window.PACK={"book":{"id":"tabaqat-shuara","title":"طبقات فحول الشعراء","type":"adabbook","author":"محمد بن سلام الجمحي (ت ٢٣١هـ)","source":"المكتبة الشاملة عبر مشروع OpenITI","edition":"دار المدني - جدة","optional":true,"packVersion":"877bf45835b5"},"items":[{"id":"tabaqat-shuara:1","bookId":"tabaqat-shuara","type":"section","seq":1,"chapter":"طبقات فحول الشعراء","title":"طبقات فحول الشعراء","page":"ص0","text":"المؤلف: محمد بن سلام الجمحي (المتوفى: 232ه)\nالمحقق: محمود محمد شاكر\nالناشر: دار المدني - جدة\nعدد الأجزاء: 2\n[ترقيم الكتاب موافق للمطبوع]"},{"id":"tabaqat-shuara:2","bookId":"tabaqat-shuara","type":"section","seq":2,"chapter":"طبقات فحول الشعراء","title":"بسم الله الرحمن الرحيم","page":"ج1 ص1","text":"وأخبرنا أبو القاسم سليمان ابن أحمد بن أيوب الطبرانى قال قرئ على الفضل بن الحباب وأنا أسمع\n... أبو نصر أخبرك أبو سعد إذنا أنبا أبو نعيم"},{"id":"tabaqat-shuara:3","bookId":"tabaqat-shuara","type":"section","seq":3,"chapter":"طبقات فحول الشعراء","title":"1- أبو عبد الله محمد بن عبد الله بن أسيد قال قرئ على القاضى —","page":"ج1 ص1","text":"أبو عبد الله محمد بن عبد الله بن أسيد قال قرئ على القاضى\n... . . قرأه عليه ... سنة إحدى وسبعين وثلثمائة ... قال القاضى\nوهو الفضل بن الحباب الجمحى أبو خليفة قال محمد بن سلام الجمحى"},{"id":"tabaqat-shuara:4","bookId":"tabaqat-shuara","type":"section","seq":4,"chapter":"طبقات فحول الشعراء","title":"2- ذكرنا العرب وأشعارها والمشهورين المعروفين من شعرائها وفرسانها وأشرافها وأيامها إذ كان لا ي","page":"ج1 ص1","text":"ذكرنا العرب وأشعارها والمشهورين المعروفين من شعرائها وفرسانها وأشرافها وأيامها إذ كان لا يحاط بشعر قبيلة واحدة من قبائل العرب وكذلك فرسانها وساداتها وأيامها فاقتصرنا من ذلك على ما لا يجهله عالم ولا يستغنى عن علمه ناظر فى أمر العرب فبدأنا بالشعر"},{"id":"tabaqat-shuara:5","bookId":"tabaqat-shuara","type":"section","seq":5,"chapter":"طبقات فحول الشعراء","title":"3- وفى الشعر مصنوع مفتعل موضوع كثير لا خير فيه ولا حجة فى عربية ولا أدب يستفاد ولا معنى يستخر","page":"ص0","text":"وفى الشعر مصنوع مفتعل موضوع كثير لا خير فيه ولا حجة فى عربية ولا أدب يستفاد ولا معنى يستخرج ولا مثل يضرب ولا مديح رائع ولا هجاء مقذع ولا فخر معجب ولا نسيب مستطرف\nوقد تداوله قوم من كتاب إلى كتاب لم يأخذوه عن أهل البادية ولم يعرضوه على العلماء\nوليس لأحد إذا أجمع أهل العلم والرواية الصحيحة على إبطال شئ منه أن يقبل من صحيفة ولا يروى عن صحفى\nوقد اختلف العلماء بعد في بعض الشعر كما اختلفت في سائر الأشياء فأما ما اتفقوا عليه فليس لأحد أن يخرج منه"},{"id":"tabaqat-shuara:6","bookId":"tabaqat-shuara","type":"section","seq":6,"chapter":"طبقات فحول الشعراء","title":"4- وللشعر صناعة وثقافة يعرفها أهل العلم كسائر أصناف العلم والصناعات منها ما تثقفه العين ومنها","page":"ص0","text":"وللشعر صناعة وثقافة يعرفها أهل العلم كسائر أصناف العلم والصناعات منها ما تثقفه العين ومنها ما تثقفه الأذن ومنها ما تثقفه اليد ومنها ما يثقفه اللسان\nمن ذلك اللؤلؤ والياقوت لا تعرفه بصفة ولا وزن دون المعاينة ممن يبصره\nومن ذلك الجهبذة بالدينار والدرهم لا تعرف جودتهما بلون ولا مس ولا طراز ولا وسم ولا صفة ويعرفه الناقد عند المعاينة فيعرف بهرجها وزائفها وستوقها ومفرغها ومنه البصر بغريب النخل والبصر بأنواع المتاع وضروبه واختلاف بلاده\nمع تشابه لونه ومسه وذرعه حتى يضاف كل صنف إلى بلده الذي خرج منه\nوكذلك بصر الرقيق فتوصف الجارية فيقال ناصعة اللون جيدة الشطب نقية الثغر حسنة العين والأنف جيدة النهود ظريفة اللسان واردة الشعر فتكون في هذه الصفة بمئة دينار وبمئتى دينار وتكون أخرى بألف دينار وأكثر ولا يجد واصفها مزيدا على هذه الصفة وتوصف الدابة فيقال خفيف العنان لين الظهر شديد الحافر فتى السن نقى من العيوب فيكون بخمسين دينارا أو نحوها وتكون أخرى بمئتى دينار وأكثر وتكون هذه صفتها\nويقال للرجل والمرأة فى القراءة والغناء إنه لندى الحلق طل الصوت طويل النفس مصيب للحن ويوصف الآخر بهذه الصفة وبينهما بون بعيد يعرف ذلك العلماء عند المعاينة والاستماع له بلا صفة ينتهى إليها ولا علم يوقف عليه\nوأن كثرة\nالمدارسة لتعدي علي العلم به\nفكذلك الشعر يعلمه أهل العلم به"},{"id":"tabaqat-shuara:7","bookId":"tabaqat-shuara","type":"section","seq":7,"chapter":"طبقات فحول الشعراء","title":"5- قال محمد قال خلاد بن يزيد الباهلى لخلف بن حيان أبى محرز وكان خلاد حسن العلم بالشعر يرويه و","page":"ج1 ص6","text":"قال محمد قال خلاد بن يزيد الباهلى لخلف بن حيان أبى محرز وكان خلاد حسن العلم بالشعر يرويه ويقوله بأى شئ ترد هذه الاشعار التي تروى قال له هل فيها ما تعلم أنت أنه مصنوع لا خير فيه قال نعم\nقال أفتعلم في الناس من هو أعلم بالشعر منك قال نعم\nقال فلا تنكر أن يعلموا من ذلك أكثر مما تعلمه أنت"},{"id":"tabaqat-shuara:8","bookId":"tabaqat-shuara","type":"section","seq":8,"chapter":"طبقات فحول الشعراء","title":"6- وقال قائل لخلف إذا سمعت أنا بالشعر أستحسنه فما أبالى ما قلت أنت فيه وأصحابك — قال إذا أخذت د","page":"ج1 ص6","text":"وقال قائل لخلف إذا سمعت أنا بالشعر أستحسنه فما أبالى ما قلت أنت فيه وأصحابك\nقال إذا أخذت درهما فاستحسنته فقال لك الصراف إنه ردئ فهل ينفعك استحسانك إياه"},{"id":"tabaqat-shuara:9","bookId":"tabaqat-shuara","type":"section","seq":9,"chapter":"طبقات فحول الشعراء","title":"7- وكان ممن أفسد الشعر وهجنه وحمل كل غثاء منه محمد بن — إسحاق بن يسار مولى آل مخرمة بن المطلب ب","page":"ج1 ص6","text":"وكان ممن أفسد الشعر وهجنه وحمل كل غثاء منه محمد بن\nإسحاق بن يسار مولى آل مخرمة بن المطلب بن عبد مناف وكان من علماء الناس بالسير\nقال الزهرى لا يزال فى الناس علم ما بقى مولى آل مخرمة وكان أكثر علمه بالمغازي والسير وغير ذلك فقبل الناس عنه الأشعار وكان يعتذر منها ويقول لا علم لى بالشعر أتينا به فأحمله\nولم يكن ذلك له عذرا فكتب في السير أشعار الرجال الذين لم يقولوا شعرا قط وأشعار النساء فضلا عن الرجال ثم جاوز ذلك إلى عاد وثمود فكتب لهم أشعارا كثيرة وليس بشعر إنما هو كلام مؤلف معقود بقواف\nأفلا يرجع إلى نفسه فيقول من حمل هذا الشعر ومن أداه منذ آلاف من السنين والله تبارك وتعالى يقول {فقطع دابر القوم الذين ظلموا} أى لا بقية لهم وقال أيضا {وأنه أهلك عادا الأولى وثمود فما أبقى} وقال فى عاد {فهل ترى لهم من باقية} وقال {وقرونا بين ذلك كثيرا} وقال {ألم يأتكم نبأ الذين من قبلكم قوم نوح وعاد وثمود}\nوالذين من بعدهم لا يعلمهم إلا الله)"},{"id":"tabaqat-shuara:10","bookId":"tabaqat-shuara","type":"section","seq":10,"chapter":"طبقات فحول الشعراء","title":"8- وقال يونس بن حبيب أول من تكلم بالعربية ونسى لسان أبيه إسماعيل بن إبراهيم صلوات الله عليهما","page":"ج1 ص8","text":"وقال يونس بن حبيب أول من تكلم بالعربية ونسى لسان أبيه إسماعيل بن إبراهيم صلوات الله عليهما"},{"id":"tabaqat-shuara:11","bookId":"tabaqat-shuara","type":"section","seq":11,"chapter":"طبقات فحول الشعراء","title":"9- أخبرنى مسمع بن عبد الملك أنه سمع محمد بن علي يقول قال أبو عبد الله بن سلام لا أدري أرفعه أ","page":"ج1 ص8","text":"أخبرنى مسمع بن عبد الملك أنه سمع محمد بن علي يقول قال أبو عبد الله بن سلام لا أدري أرفعه أم لا وأظنه قد رفعه أول من تكلم بالعربية ونسى لسان أبيه إسماعيل ابن إبراهيم صلوات الله عليهما"},{"id":"tabaqat-shuara:12","bookId":"tabaqat-shuara","type":"section","seq":12,"chapter":"طبقات فحول الشعراء","title":"10- وأخبرنى يونس عن أبى عمرو بن العلاء قال العرب كلها ولد إسماعيل إلا حمير وبقايا جرهم — وكذلك ي","page":"ج1 ص8","text":"وأخبرنى يونس عن أبى عمرو بن العلاء قال العرب كلها ولد إسماعيل إلا حمير وبقايا جرهم\nوكذلك يروى أن إسماعيل ابن إبراهيم جاورهم وأصهر إليهم"},{"id":"tabaqat-shuara:13","bookId":"tabaqat-shuara","type":"section","seq":13,"chapter":"طبقات فحول الشعراء","title":"11- ولكن العربية التي عنى محمد بن علي اللسان الذى نزل به القرآن وما تكلمت به العرب على عهد الن","page":"ص0","text":"ولكن العربية التي عنى محمد بن علي اللسان الذى نزل به القرآن وما تكلمت به العرب على عهد النبى صلى الله عليه وسلم وتلك عربية أخرى غير كلامنا هذا"},{"id":"tabaqat-shuara:14","bookId":"tabaqat-shuara","type":"section","seq":14,"chapter":"طبقات فحول الشعراء","title":"12- لم يجاوز أبناء نزار فى أنسابهم وأشعارهم عدنان اقتصروا على معد — ولم يذكر عدنان جاهلى قط غير","page":"ص0","text":"لم يجاوز أبناء نزار فى أنسابهم وأشعارهم عدنان اقتصروا على معد\nولم يذكر عدنان جاهلى قط غير لبيد بن ربيعة الكلابى في بيت واحد قاله قال\n(فإن لم تجد من دون عدنان والدا ... ودون معد فلتزعك العواذل)\nوقد روى لعباس بن مرداس السلمى بيت في عدنان قال\n(وعك بن عدنان الذين تلعبوا ... بمذحج حتى طردوا كل مطرد)\nوالبيت مريب عند أبى عبد الله فما فوق عدنان أسماء لم تؤخذ إلا عن الكتب والله أعلم بها لم يذكرها عربى قط\nوإنما كان معد بإزاء موسى بن عمران صلي الله عليه أو قبله قليلا وبين موسى وعاد وثمود الدهر الطويل والأمد البعيد\nفنحن لا نقيم في النسب ما فوق عدنان ولا نجد لأولية العرب المعروفين شعرا فكيف بعاد وثمود فهذا الكلام الواهن الخبيث ولم يرو قط عربى منها بيتا واحدا ولا راوية للشعر مع ضعف أسره وقلة طلاوته"},{"id":"tabaqat-shuara:15","bookId":"tabaqat-shuara","type":"section","seq":15,"chapter":"طبقات فحول الشعراء","title":"13- وقال أبو عمرو بن العلاء في ذلك ما لسان حمير وأقاصى اليمن اليوم بلساننا ولا عربيتهم بعربيتن","page":"ص0","text":"وقال أبو عمرو بن العلاء في ذلك ما لسان حمير وأقاصى اليمن اليوم بلساننا ولا عربيتهم بعربيتنا فكيف بما علي عهد عاد وثمود مع تداعيه ووهيه فلو كان الشعر مثل ما وضع لابن إسحاق ومثل ما روى الصحفيون ما كانت إليه حاجة ولا فيه دليل على علم"},{"id":"tabaqat-shuara:16","bookId":"tabaqat-shuara","type":"section","seq":16,"chapter":"طبقات فحول الشعراء","title":"14- وكان لأهل البصرة في العربية قدمة وبالنحو ولغات العرب والغريب عناية — وكان أول من أسس العربية","page":"ص0","text":"وكان لأهل البصرة في العربية قدمة وبالنحو ولغات العرب والغريب عناية\nوكان أول من أسس العربية وفتح بابها وأنهج سبيلها ووضع قياسها أبو الأسود الدؤلى وهو ظالم بن عمرو بن سفيان ابن عمرو بن جندل بن يعمر بن نفاثة بن حلس بن ثعلبة بن عدى بن الدئل وكان رجل أهل البصرة وكان علوى الرأى وكان يونس يقول هم ثلاثة الدول من حنيفة ساكنة الواو والديل في عبد القيس والدئل في كنانة رهط أبى الأسود وإنما قال ذلك حين اضطرب كلام العرب فغلبت السليقية ولم تكن نحوية فكان سراه الناس يلحنون ووجوه الناس فوضع باب الفاعل والمفعول به والمضاف وحروف الرفع والنصب والجر والجزم"},{"id":"tabaqat-shuara:17","bookId":"tabaqat-shuara","type":"section","seq":17,"chapter":"طبقات فحول الشعراء","title":"15- وكان ممن أخذ عنه يحيى بن يعمر وهو رجل من عدوان وعداده في بنى ليث وكان مأمونا عالما يروى عن","page":"ص0","text":"وكان ممن أخذ عنه يحيى بن يعمر وهو رجل من عدوان وعداده في بنى ليث وكان مأمونا عالما يروى عنه الفقه\nروى عن ابن عمر وابن عباس وروى عنه قتادة وإسحاق بن سويد وغيرهما من العلماء وأخذ ذلك عنه أيضا ميمون الأقرن وعنبسة الفيل ونصر بن عاصم الليثى وغيرهم"},{"id":"tabaqat-shuara:18","bookId":"tabaqat-shuara","type":"section","seq":18,"chapter":"طبقات فحول الشعراء","title":"16- قال ابن سلام أخبرنى يونس بن حبيب قال الحجاج لابن يعمر أتسمعني ألحن قال الأمير أفصح الناس ق","page":"ص0","text":"قال ابن سلام أخبرنى يونس بن حبيب قال الحجاج لابن يعمر أتسمعني ألحن قال الأمير أفصح الناس قال يونس وكذلك كان ولم يكن صاحب شعر قال تسمعنى ألحن قال حرفا\nقال أين قال في القرآن\nقال ذلك أشنع له فما هو قال تقول {قل إن كان آباؤكم وأبناؤكم وإخوانكم وأزواجكم وعشيرتكم وأموال اقترفتموها وتجارة تخشون كسادها ومساكن ترضونها أحب إليكم من الله ورسوله} قرأها بالرفع كأنه لما طال عليه الكلام نسى ما ابتدأ به\nوالوجه أن يقرأ أحب إليكم بالنصب على خبر كان وفعلها\nقال وأخبرنى يونس قال قال له لا جرم لا تسمع لى لحنا أبدا\nقال يونس فألحقه بخراسان وعليها يزيد بن المهلب\nفأخبرني أبى قال كتب يزيد بن المهلب إلى الحجاج إنا لقينا العدو ففعلنا واضطررناهم إلى عرعرة الجبل\nفقال الحجاج ما لابن المهلب ولهذا الكلام فقيل له إن ابن يعمر هناك فقال فذاك إذا"},{"id":"tabaqat-shuara:19","bookId":"tabaqat-shuara","type":"section","seq":19,"chapter":"طبقات فحول الشعراء","title":"17- ثم كان من بعدهم عبد الله بن أبى إسحاق الحضرمى وكان أول من بعج النحو ومد القياس والعلل — وكان","page":"ص0","text":"ثم كان من بعدهم عبد الله بن أبى إسحاق الحضرمى وكان أول من بعج النحو ومد القياس والعلل\nوكان معه أبو عمرو ابن العلاء وبقى بعده بقاء طويلا\nوكان ابن أبى إسحاق أشد تجريدا للقياس وكان أبو عمرو أوسع علما بكلام العرب ولغاتها وغريبها\nوكان بلال بن أبى بردة جمع بينهما بالبصرة وهو يومئذ وال عليها ولاه خالد بن عبد الله القسرى زمان هشام بن عبد الملك قال أبو عبد الله قال يونس قال أبو عمرو فغلبنى ابن أبى إسحاق بالهمز يومئذ فنظرت فيه بعد ذلك وبالغت فيه\nوكان عيسى بن عمر أخذ عن ابن أبى إسحاق وأخذ يونس عن أبى عمرو بن العلاء وكان معهما مسلمة بن عبد الله بن سعد بن محارب الفهرى وكان ابن أبى إسحاق خاله وكان حماد بن الزبرقان ويونس يفضلانه\nوسمعت أبى يسأل يونس عن ابن أبى إسحاق وعلمه قال هو والنحو سواء أى هو الغاية\nقال فأين علمه من علم الناس اليوم قال لو كان فى الناس اليوم من لا يعلم إلا علمه يومئذ لضحك به ولو كان فيهم من له ذهنه ونفاذه ونظر نظرهم كان أعلم الناس"},{"id":"tabaqat-shuara:20","bookId":"tabaqat-shuara","type":"section","seq":20,"chapter":"طبقات فحول الشعراء","title":"18- قال وقلت ليونس هل سمعت من ابن أبى إسحاق شيئا قال قلت له هل يقول أحد الصويق يعنى السويق — قال","page":"ص0","text":"قال وقلت ليونس هل سمعت من ابن أبى إسحاق شيئا قال قلت له هل يقول أحد الصويق يعنى السويق\nقال نعم عمرو بن تميم تقولها وما تريد إلى هذا عليك بباب من النحو يطرد وينقاس"},{"id":"tabaqat-shuara:21","bookId":"tabaqat-shuara","type":"section","seq":21,"chapter":"طبقات فحول الشعراء","title":"19- وسمعت يونس يقول لو كان أحد ينبغى أن يؤخذ بقوله كله فى شئ واحد كان ينبغى لقول أبى عمرو بن ا","page":"ص0","text":"وسمعت يونس يقول لو كان أحد ينبغى أن يؤخذ بقوله كله فى شئ واحد كان ينبغى لقول أبى عمرو بن العلاء فى العربية أن يؤخذ كله ولكن ليس أحد إلا وأنت آخذ من قوله وتارك"},{"id":"tabaqat-shuara:22","bookId":"tabaqat-shuara","type":"section","seq":22,"chapter":"طبقات فحول الشعراء","title":"20- قال فأخذ على الفرزدق شئ فى شعره فقال أين هذا الذى يجر فى المسجد خصييه ولا يصلحه يعنى ابن أ","page":"ص0","text":"قال فأخذ على الفرزدق شئ فى شعره فقال أين هذا الذى يجر فى المسجد خصييه ولا يصلحه يعنى ابن أبى إسحاق"},{"id":"tabaqat-shuara:23","bookId":"tabaqat-shuara","type":"section","seq":23,"chapter":"طبقات فحول الشعراء","title":"21- أخبرنى يونس أن أبا عمرو كان أشد تسليما للعرب وكان ابن أبى إسحاق وعيسى بن عمر يطعنان عليهم —","page":"ص0","text":"أخبرنى يونس أن أبا عمرو كان أشد تسليما للعرب وكان ابن أبى إسحاق وعيسى بن عمر يطعنان عليهم\nكان عيسى يقول أساء النابغة فى قوله حيث يقول\n(فبت كأنى ساورتنى ضئيلة ... من الرقش فى أنيابها السم ناقع)\nيقول موضعها ناقعا\nوكان يختار السم والشهد وهى علوية"},{"id":"tabaqat-shuara:24","bookId":"tabaqat-shuara","type":"section","seq":24,"chapter":"طبقات فحول الشعراء","title":"22- وأخبرني يونس أن ابن أبى إسحاق قال للفرزدق فى مديحه يزيد بن عبد الملك —","page":"ص0","text":"وأخبرني يونس أن ابن أبى إسحاق قال للفرزدق فى مديحه يزيد بن عبد الملك\n(مستقبلين شمال الشأم تضربنا ... بحاصب كنديف القطن منثور)\n(على عمائمنا يلقى وأرحلنا ... على زواحف تزجى مخها رير)\nقال ابن أبى إسحاق أسأت إنما هى رير وكذلك قياس النحو فى هذا الموضع\nوقال يونس والذي قال حسن جائز\nفلما ألحوا على الفرزدق قال على زواحف نزجيها محاسير\nقال ثم ترك الناس هذا ورجعوا إلى القول الأول"},{"id":"tabaqat-shuara:25","bookId":"tabaqat-shuara","type":"section","seq":25,"chapter":"طبقات فحول الشعراء","title":"23- وكان يكثر الرد على الفرزدق فقال فيه الفرزدق —","page":"ص0","text":"وكان يكثر الرد على الفرزدق فقال فيه الفرزدق\n(فلو كان عبد الله مولى هجوته ... ولكن عبد الله مولى مواليا)\nرد الياء على الأصل\nوهى أبيات ولو كان هذا البيت وحده تركه ساكنا"},{"id":"tabaqat-shuara:26","bookId":"tabaqat-shuara","type":"section","seq":26,"chapter":"طبقات فحول الشعراء","title":"24- وكان مولى آل الحضرمى وهم حلفاء بنى عبد شمس بن عبد مناف — والحليف عند العرب مولى من ذلك قول ا","page":"ص0","text":"وكان مولى آل الحضرمى وهم حلفاء بنى عبد شمس بن عبد مناف\nوالحليف عند العرب مولى من ذلك قول الراعى يريد به غنيا وهم حلفاؤهم\n(جزى الله مولانا غنيا ملامة ... شرار موالى عامر في العزائم)\nوقال الأخطل\n(أتشتم قوما أثلوك بنهشل ... ولولاهم كنتم كعكل مواليا)\nيعنى حلف الرباب لسعد وإنما قالها لجرير\nوقال الكلبى يحضض عذره على فزارة\n(وأشجع إن لاقيتموهم فإنهم ... لذبيان مولى فى الحروب وناصر)"},{"id":"tabaqat-shuara:27","bookId":"tabaqat-shuara","type":"section","seq":27,"chapter":"طبقات فحول الشعراء","title":"25- وكان عيسى بن عمر إذا اختلفت العرب نزع إلى النصب — كان عيسى بن عمر وابن أبى إسحاق يقرآن {يا ل","page":"ص0","text":"وكان عيسى بن عمر إذا اختلفت العرب نزع إلى النصب\nكان عيسى بن عمر وابن أبى إسحاق يقرآن {يا ليتنا نرد ولا نكذب بآيات ربنا ونكون من المؤمنين}\nوكان الحسن وأبو عمرو بن العلاء ويونس يرفعون نرد ونكذب\nونكون\nقلت لسيبويه كيف الوجه عندك قال الرفع\nقلت فالذين قرأوا بالنصب قال سمعوا قراءة ابن أبى إسحاق فاتبعوه\nوكان عيسى بن عمر يقرأ {الزانية والزاني} {والسارق والسارقة} وكان ينشد\n(ياعديا لقلبك المهتاج ... )\nوكان يقرأ {هؤلاء بناتي هن أطهر لكم} فقال له أبو عمرو بن العلاء هؤلاء بنى هم ماذا فقال عشرين رجلا فأنكرها أبو عمرو\nوكان أبو عمرو وعيسى يقرآن {يا جبال أوبي معه والطير} ويختلفان فى التأويل\nكان عيسى يقول على النداء كقولك يا زيد والحارث لما لم يمكنه يا زيد يا الحارث\nوكان أبو عمرو يقول لو كانت على النداء لكانت رفعا ولكنها على إضمار وسخرنا الطير كقوله على أثر هذا {ولسليمان الريح} أى سخرنا الريح"},{"id":"tabaqat-shuara:28","bookId":"tabaqat-shuara","type":"section","seq":28,"chapter":"طبقات فحول الشعراء","title":"26- وقال يونس قال ابن أبى إسحق فى بيت الفرزدق —","page":"ج1 ص20","text":"وقال يونس قال ابن أبى إسحق فى بيت الفرزدق\n(وعض زمان يا بن مروان لم يدع ... من المال إلا مسحتا أو مجرف)\nويروى أيضا مجلف المجرف الذى تجر فته السنة وقشرته والمجلف الذى صيرته جلفا للرفع وجه\nقال أبو عمرو ولا أعرف لها وجها\nوكان يونس لا يعرف لها وجها\nقلت ليونس لعل الفرزدق قالها على النصب ولم يأبه فقال لا كان ينشدها على الرفع\nوأنشدنيها رؤبة على الرفع\nوتقول العرب سحته وأسحته يقرأ بهما فى القرآن جميعا فمن قرأ {فيسحتكم بعذاب} فهو من أسحت يسحت فهو مسحت وهى التى قال الفرزدق\nومن قرأ فيسحتكم فهو من سحت يسحت فهو مسحوت"},{"id":"tabaqat-shuara:29","bookId":"tabaqat-shuara","type":"section","seq":29,"chapter":"طبقات فحول الشعراء","title":"27- وأخبرنى الحارث البنانى أخو أبى الجحاف أنه سمع الفرزدق ينشد —","page":"ص0","text":"وأخبرنى الحارث البنانى أخو أبى الجحاف أنه سمع الفرزدق ينشد\n(فيا عجبا حتى كليب تسبنى ... كأن أباها نهشل أو مجاشع)\nكأنه جعله غاية فخفض"},{"id":"tabaqat-shuara:30","bookId":"tabaqat-shuara","type":"section","seq":30,"chapter":"طبقات فحول الشعراء","title":"28- ثم كان الخليل بن أحمد وهو رجل من الأزد من فراهيد يقال هذا رجل فراهيدى ويونس يقول فرهودى مث","page":"ص0","text":"ثم كان الخليل بن أحمد وهو رجل من الأزد من فراهيد يقال هذا رجل فراهيدى ويونس يقول فرهودى مثل قردوسى فاستخرج من العروض واستنبط منه ومن علله ما لم يستخرج أحد ولم يسبقه إلى مثله سابق من العلماء كلهم"},{"id":"tabaqat-shuara:31","bookId":"tabaqat-shuara","type":"section","seq":31,"chapter":"طبقات فحول الشعراء","title":"29- رجع إلى قول الشعراء وإلى قول العلماء فيه ولكل من ذكرنا قول فيه — قال فنقلنا ذلك إلى خلف بن ح","page":"ص0","text":"رجع إلى قول الشعراء وإلى قول العلماء فيه ولكل من ذكرنا قول فيه\nقال فنقلنا ذلك إلى خلف بن حيان أبى محرز وهو خلف الأحمر اجتمع أصحابنا أنه كان أفرس الناس ببيت شعر وأصدقه لسانا\nكنا لا نبالى إذا أخذنا عنه خبرا أو أنشدنا شعرا أن لا نسمعه من صاحبه"},{"id":"tabaqat-shuara:32","bookId":"tabaqat-shuara","type":"section","seq":32,"chapter":"طبقات فحول الشعراء","title":"30- وكان الأصمعى وأبو عبيدة من أهل العلم — وأعلم من ورد علينا من غير أهل البصرة المفضل بن محمد ا","page":"ص0","text":"وكان الأصمعى وأبو عبيدة من أهل العلم\nوأعلم من ورد علينا من غير أهل البصرة المفضل بن محمد الضبى الكوفى"},{"id":"tabaqat-shuara:33","bookId":"tabaqat-shuara","type":"section","seq":33,"chapter":"طبقات فحول الشعراء","title":"31- ففصلنا الشعراء من أهل الجاهلية والإسلام — والمخضرمين الذين كانوا فى الجاهلية وأدركوا الإسلام","page":"ص0","text":"ففصلنا الشعراء من أهل الجاهلية والإسلام\nوالمخضرمين الذين كانوا فى الجاهلية وأدركوا الإسلام فنزلناهم منازلهم واحتججنا لكل شاعر بما وجدنا له من حجة وما قال فيه العلماء\nوقد اختلف الناس والرواة فيهم\nفنظر قوم من أهل العلم بالشعر والنفاذ فى كلام العرب والعلم بالعربية إذا اختلفت الرواة فقالوا بآرائهم وقالت العشائر بأهوائها ولا يقنع الناس مع ذلك إلا الرواية عمن تقدم\nفاقتصرنا من الفحول المشهورين على أربعين شاعرا فألفنا من تشابه شعره منهم إلى نظرائه فوجدناهم عشر طبقات أربعة رهط كل طبقة متكافئين معتدلين"},{"id":"tabaqat-shuara:34","bookId":"tabaqat-shuara","type":"section","seq":34,"chapter":"طبقات فحول الشعراء","title":"32- وكان الشعر فى الجاهلية عند العرب ديوان علمهم ومنتهى حكمهم به يأخذون وإليه يصيرون — قال ابن س","page":"ص0","text":"وكان الشعر فى الجاهلية عند العرب ديوان علمهم ومنتهى حكمهم به يأخذون وإليه يصيرون\nقال ابن سلام قال ابن عون عن ابن سيرين قال قال عمر بن الخطاب كان الشعر علم قوم لم يكن لهم علم أصح منه\nفجاء الإسلام فتشاغلت عنه العرب وتشاغلوا بالجهاد وغزو فارس والروم ولهت عن الشعر وروايته\nفلما كثر الإسلام وجاءت الفتوح واطمأنت العرب بالامصار راجعوا رواية الشعر فلم يؤولوا إلى ديوان مدون ولا كتاب مكتوب وألفوا ذلك وقد هلك من العرب من هلك بالموت والقتل فحفظوا أقل ذلك وذهب عليهم منه كثير\nوقد كان عند النعمان بن المنذر منه ديوان فيه أشعار الفحول وما مدح هو وأهل بيته به صار ذلك إلى بنى مروان أو صار منه"},{"id":"tabaqat-shuara:35","bookId":"tabaqat-shuara","type":"section","seq":35,"chapter":"طبقات فحول الشعراء","title":"33- قال يونس بن حبيب قال أبو عمرو بن العلاء ما انتهى إليكم مما قالت العرب إلا أقله ولو جاءكم و","page":"ص0","text":"قال يونس بن حبيب قال أبو عمرو بن العلاء ما انتهى إليكم مما قالت العرب إلا أقله ولو جاءكم وافرا لجاءكم علم وشعر كثير"},{"id":"tabaqat-shuara:36","bookId":"tabaqat-shuara","type":"section","seq":36,"chapter":"طبقات فحول الشعراء","title":"34- ومما يدل على ذهاب الشعر وسقوطه قلة ما بقى بأيدى الرواة المصححين لطرفة وعبيد اللذين صح لهما","page":"ص0","text":"ومما يدل على ذهاب الشعر وسقوطه قلة ما بقى بأيدى الرواة المصححين لطرفة وعبيد اللذين صح لهما قصائد بقدر عشر\nوإن لم يكن لهما غيرهن فليس موضعهما حيث وضعا من الشهرة والتقدمه وإن كان ما يروى من الغثاء لهما فليس يستحقان مكانهما على أفواه الرواة\nونرى أن غيرهما قد سقط من كلامه كلام كثير غير أن الذى نالهما من ذلك أكثر\nوكانا أقدم الفحول فلعل ذلك لذاك\nفلما قل كلامهما حمل عليهما حمل كثير"},{"id":"tabaqat-shuara:37","bookId":"tabaqat-shuara","type":"section","seq":37,"chapter":"طبقات فحول الشعراء","title":"35- ولم يكن لأوائل العرب من الشعر إلا الأبيات يقولها الرجل فى حاجته وإنما قصدت القصائد وطول ال","page":"ص0","text":"ولم يكن لأوائل العرب من الشعر إلا الأبيات يقولها الرجل فى حاجته وإنما قصدت القصائد وطول الشعر على عهد عبد المطلب وهاشم بن عبد مناف\nوذلك يدل على إسقاط شعر عاد وثمود وحمير وتبع"},{"id":"tabaqat-shuara:38","bookId":"tabaqat-shuara","type":"section","seq":38,"chapter":"طبقات فحول الشعراء","title":"36- فمن قديم الشعر الصحيح قول العنبر بن عمرو بن تميم وكان — جاور في بهراء فرابه ريب فقال —","page":"ص0","text":"فمن قديم الشعر الصحيح قول العنبر بن عمرو بن تميم وكان\nجاور في بهراء فرابه ريب فقال\n(قد رابني من دلوى اضطرابها ... والنأى فى بهراء واغترابها)\n(إن لا تجئ ملأى يجئ قرابها ... )\nوقد قال قوم إنه كان من بهراء فجاور عمرو بن تميم وأنه قال\n(قد رابنى من دلوى اضطرابها ... والنأى عن بهراء واغترابها)\nولا نرى ذلك كما قالوا بل هو كما ذكر العنبر بن عمرو بن تميم\nوكان على عائشة محرر من ولد إسماعيل فلما قدم سبى العنبر أمرها رسول الله صلى الله عليه وسلم أن تعتق منهم وهم أصحاب الحجرات"},{"id":"tabaqat-shuara:39","bookId":"tabaqat-shuara","type":"section","seq":39,"chapter":"طبقات فحول الشعراء","title":"37- أخبرنى أبو محرز واصل بن شبيب المنافى قال كان سعد ومالك ابنى زيد مناة بن تميم فكان سعد أسود","page":"ج1 ص27","text":"أخبرنى أبو محرز واصل بن شبيب المنافى قال كان سعد ومالك ابنى زيد مناة بن تميم فكان سعد أسودهما وكان مالك ترعية يعزب في الإبل وأمهما مفداة بنت ثعلبة بن دودان بن أسد وخالتهما ممناة بنت ثعلبة أم ثعلبة بن عكابة بن صعب بن على\nابن بكر بن وائل أبى شيبان وقيس وذهل وتيم وهو الحصن\nوقال أبو محرز زار ثعلبة ابنته وهى حامل بسعد فمخضت ليلا فاستحيت من أبيها وزوجها فخرجت فأعجلها الولاد فطرقت على قرية نمل\nفأدركها أبوها وزجر فقال لئن صدقت الطير ليملأن ابنك هذا الأرض من ولده\nقال أبو محرز فتزوج مالك بن زيد مناة النوار بنت جل بن عدى بن عبد مناة بن أد وهم عدى وتيم ويقال لتيم تيم عدى وهما من الرباب وكانت امرأة زولة جزلة\nفلما اهتداها\nمالك خرج سعد في الإبل فعزب فيها ثم أوردها لظمئها ومالك في صفرة وكان عروسا فأراد القيام فمنعته امرأته من القيام فجعل سعد وهو مشتمل يزاول سقيها ولا يرفق فقال\n(يظل يوم وردها مزعفرا ... وهى خناطيل تجوس الخضرا)\nفقالت النوار لمالك ألا تسمع ما يقول أخوك أجبه\nقال وما أقول قالت قل\n(أوردها سعد وسعد مشتمل ... ما هكذا تورد يا سعد الإبل)\nفولدت حنظلة الأغر وفيه بيت تميم وشرفها\nوقال حنظلة ولدت لمالك وولد لى مالك\nوقال جرير لعمر بن لجأ\n(فلم تلدوا النوار ولم تلد كم ... مفداة المباركة الولود)"},{"id":"tabaqat-shuara:40","bookId":"tabaqat-shuara","type":"section","seq":40,"chapter":"طبقات فحول الشعراء","title":"38- ومما يروى من قديم الشعر قول دوبد بن زيد بن نهد قال حين حضره الموت —","page":"ج1 ص30","text":"ومما يروى من قديم الشعر قول دوبد بن زيد بن نهد قال حين حضره الموت\n(اليوم يبنى لدويد بيته ... لو كان للدهر بلى أبليته)\n(أو كان قرنى واحدا كفيته ... يا رب نهب صالح حويته)\n(ورب غيل حسن لويته ... ومعصم مخضب ثنيته)\nوقال أيضا\n(ألقى على الدهر رجلا ويدا ... )\n(والدهر ما أصلح يوما أفسدا ... )\n(يصلحه اليوم ويفسده غدا ... )\nقال وأوصى بنيه عند موته فقال أوصيكم بالناس شرا لا تقبلوا\nلهم معذرة ولا تقيلوهم عثرة"},{"id":"tabaqat-shuara:41","bookId":"tabaqat-shuara","type":"section","seq":41,"chapter":"طبقات فحول الشعراء","title":"39- وقال أعصر بن سعد بن قيس بن عيلان وهو منبه أبو باهلة وغنى والطفاوة —","page":"ج1 ص32","text":"وقال أعصر بن سعد بن قيس بن عيلان وهو منبه أبو باهلة وغنى والطفاوة\n(قالت عميرة ما لرأسك بعدما ... نفد الزمان أتى بلون منكر)\n(أعمير إن أباك شيب رأسه ... كر الليالى واختلاف الأعصر)\nفبهذا البيت سمى أعصر وقد يقول قوم يعصر وليس بشئ"},{"id":"tabaqat-shuara:42","bookId":"tabaqat-shuara","type":"section","seq":42,"chapter":"طبقات فحول الشعراء","title":"40- ومنهم المستوغر بن ربيعة بن كعب بن سعد بن زيد مناة ابن تميم كان قديما وبقى بقاء طويلا حتى ق","page":"ج1 ص32","text":"ومنهم المستوغر بن ربيعة بن كعب بن سعد بن زيد مناة ابن تميم كان قديما وبقى بقاء طويلا حتى قال\n(ولقد سئمت من الحياة وطولها ... وازددت من عدد السنين مئينا)\n(مئة أتت من بعدها مئتان لى ... وازددت من عدد الشهور سنينا)\n(هل ما بقا إلا كما قد فاتنا ... يوم يكر وليلة تحدونا)\nقوله بقا يريد بقى وفنا يريد فنى وهما لغتان لطيئ\nوقد تكلمت بهما العرب وهما في لغة طيئ أكثر قال زهير بن أبى سلمى\n(تربع صارة حتى إذا ما ... فنا الدحلان عنه والإضاء)\nأنشدينها يونس\nوأنشدنى له عبد الله بن ميمون المرى\n(إذا ما المرء صم فلم يناجى ... وأودى سمعه إلا ندايا)\n(ولاعب بالعشى بنى بنيه ... كفعل الهر يحنرش العظايا)\n(يلاعبهم وودوا لو سقوه ... من الذيفان مترعة ملايا)\n(فلا ذاق النعيم ولا شرابا ... ولا يسقى من المرض الشفايا)"},{"id":"tabaqat-shuara:43","bookId":"tabaqat-shuara","type":"section","seq":43,"chapter":"طبقات فحول الشعراء","title":"41- ومنهم زهير بن جناب الكلبى كان قديما شريف الولد وطال عمره فقال —","page":"ج1 ص34","text":"ومنهم زهير بن جناب الكلبى كان قديما شريف الولد وطال عمره فقال\n(أبنى إن أهلك فإنى ... قد بنيت لكم بنيه)\n(وجعلتكم أبناء سادات ... زنادكم وريه)\n(من كل ما نال الفتى ... قد نلته إلا التحية)\n(كم من محيى لا يوازينى ... ولا يهب الرعيه)\n(ولقد رأيت النار للسلاف ... توقد فى طميه)\n(ولقد رحلت البازل ... الوجناء ليس لها وليه)\n(ولقد غدوت بمشرف الطرفين لم يغمز شظيه ... )\n(فأصبت من حمر القنان ... معا ومن حمر القفيه)\n(ونطقت خطبة ماجد ... غير الضعيف ولا العييه)\n(والموت خير للفتى ... وليهلكن وبه بقيه)\n(من أن يرى الشيخ البجال ... وقد يهادى بالعشيه)"},{"id":"tabaqat-shuara:44","bookId":"tabaqat-shuara","type":"section","seq":44,"chapter":"طبقات فحول الشعراء","title":"42- وقال جذيمة الأبرش — ص —","page":"ج1 ص36","text":"وقال جذيمة الأبرش\nص\n(ربما أوفيت فى علم ... ترفعن ثوبى شمالات)\n(فى فتو أنا رابئهم ... من كلال غزوة ماتوا)\n(ليت شعرى ما أماتهم ... نحن أدلجنا وهم باتوا)"},{"id":"tabaqat-shuara:45","bookId":"tabaqat-shuara","type":"section","seq":45,"chapter":"طبقات فحول الشعراء","title":"43- وقال امرؤ القيس —","page":"ج1 ص38","text":"وقال امرؤ القيس\n(عوجا على الطلل المحيل لعلنا ... نبكى الدياركما بكى ابن حذام)\nوهو رجل من طيئ لم نسمع شعره الذى بكى فيه ولا شعرا غير هذا البيت الذى ذكره امرؤ القيس"},{"id":"tabaqat-shuara:46","bookId":"tabaqat-shuara","type":"section","seq":46,"chapter":"طبقات فحول الشعراء","title":"44- وكان أول من قصد القصائد وذكر الوقائع المهلهل بن ربيعة التغلبى في قتل أخيه كليب وائل قتلته","page":"ج1 ص38","text":"وكان أول من قصد القصائد وذكر الوقائع المهلهل بن ربيعة التغلبى في قتل أخيه كليب وائل قتلته بنو شيبان وكان اسم المهلهل عديا وإنما سمى مهلهلا لهلهلة شعره كهلهلة الثوب وهو اضطرابه واختلافه ومن ذلك قول النابغة\n(أتاك بقول هلهل النسج كاذب ... ولم يأت بالحق الذى هو ناصع)\nوزعمت العرب أنه كان يدعى في شعره ويتكثر في قوله بأكثر من فعله"},{"id":"tabaqat-shuara:47","bookId":"tabaqat-shuara","type":"section","seq":47,"chapter":"طبقات فحول الشعراء","title":"45- وكان شعراء الجاهلية في ربيعة أولهم المهلهل والمرقشان وسعد بن مالك وطرفة بن العبد وعمرو بن","page":"ص0","text":"وكان شعراء الجاهلية في ربيعة أولهم المهلهل والمرقشان وسعد بن مالك وطرفة بن العبد وعمرو بن قميئة والحارث بن حلزة والمتلمس والأعشى والمسيب بن علس\nثم تحول الشعر فى قيس فمنهم النابغة الذيبانى وهم يعدون زهير بن أبى سلمى من عبد الله بن غطفان وابنه كعبا ولبيد والنابغة الجعدى والحطيئة والشماخ وأخوه مزرد وخداش بن زهير ثم آل ذلك إلى تميم فلم يزل فيهم إلى اليوم\nكان امرؤ القيس بن حجر بعد مهلهل ومهلهل خاله وطرفة وعبيد وعمرو بن قميئة والمتلمس في عصر واحد"},{"id":"tabaqat-shuara:48","bookId":"tabaqat-shuara","type":"section","seq":48,"chapter":"طبقات فحول الشعراء","title":"46- فكان من الشعراء من يتأله فى جاهليته ويتعفف في شعره ولا يستبهر بالفواحش ولا يتهكم في الهجاء","page":"ص0","text":"فكان من الشعراء من يتأله فى جاهليته ويتعفف في شعره ولا يستبهر بالفواحش ولا يتهكم في الهجاء يقال يتهكم ويتكهم\nقال الفضل ويقال ليلة بهرة إذا كان قمرها مضيئا ومنهم من كان ينعى على نفسه ويتعهر\nمنهم امرؤ القيس وقال\n(ومثلك حبلى قد طرقت ومرضع ... فألهيتها عن ذى تمائم محول)\nوقال\n(دخلت وقد ألقت لنوم ثيابها ... لدى الستر إلا لبسة المتفضل)\nوقال\n(سموت إليها بعد ما نام أهلها ... سمو حباب الماء حالا على حال)"},{"id":"tabaqat-shuara:49","bookId":"tabaqat-shuara","type":"section","seq":49,"chapter":"طبقات فحول الشعراء","title":"47- ومنهم الأعشى قال —","page":"ص0","text":"ومنهم الأعشى قال\n(فظللت أرعاها وظل يحوطها ... حتى دنوت إذ الظلام دنالها)\nوقال\n(وأقررت عينى من العانيات ... إما نكاحا وإما أزن)\nوقال\n(وقد أخرج الكاعب المستراة ... من خدرها وأشيع القمارا)\nوقال\n(ورادعة بالطيب صفراء عندنا ... لجس الندامى فى يد الدرع مفتق)\nوقال\n(وقد أخالس رب البيت غفلته ... وقد يحاذر منى ثم ما يئل)"},{"id":"tabaqat-shuara:50","bookId":"tabaqat-shuara","type":"section","seq":50,"chapter":"طبقات فحول الشعراء","title":"48- وكان الفرزدق أقول أهل الإسلام فى هذا الفن قال —","page":"ج1 ص43","text":"وكان الفرزدق أقول أهل الإسلام فى هذا الفن قال\n(هما دلتانى من ثمانين قامة ... كما انقض باز أقتم الريش كاسره)\n(فلما استوت رجلاى فى الأرض نادتا ... أحيا يرجى أم قتيلا نحاذره)\n(فقلت ارفعوا الأسباب لا يقطنوا بنا ... ووليت فى أعجاز ليل أبادره)\n(وأصبحت فى القوم الجلوس وأصبحت ... مغلقة دونى عليها دسا كره)\nقالها وهو بالمدينة فأنكرت ذلك قريش وأزعجه مروان بن الحكم وهو وال على المدينة فأجله ثلاثا ثم أخرجه عنها\nقال وقال يونس كان للفرزدق غلامان أحدهما اسمه وقاع والآخر نقطة ولوقاع يقول للفرزدق\n(تغلغل وقاع إليها فأصبحت ... تخوض خداريا من الليل أخضرا)\n(لطيف إذا ما أنغل أدرك ما ابتغى ... إذا هو للظبى الغرير تقترا)\nوقال أيضا\n(فأبلغهن وحى القول عنى ... وأدخل رأسه تحت القرام)\n(أسيد ذو خريطة نهارا ... من المتلقطى قرد القمام)\n(فقلن له نواعدك الثرايا ... وذاك إليه مجتمع الزحام)\n(ثلاث واثنتان فهن خمس ... وسادسة تميل إلى الشمام)\nالشمام المشامة\n(فبتن بجانبى مصرعات ... وبت أفض أغلاق الختام)\nوكان جرير مع إفراطه فى الهجاء يعف عن ذكر النساء كان لا يشبب إلا بامرأة يملكها"},{"id":"tabaqat-shuara:51","bookId":"tabaqat-shuara","type":"section","seq":51,"chapter":"طبقات فحول الشعراء","title":"49- قال ابن سلام فلما راجعت العرب رواية الشعر وذكر أيامها ومآثرها استقل بعض العشائر شعر شعرائه","page":"ج1 ص45","text":"قال ابن سلام فلما راجعت العرب رواية الشعر وذكر أيامها ومآثرها استقل بعض العشائر شعر شعرائهم وما ذهب من ذكر وقائعهم\nوكان قوم قلت وقائعهم وأشعارهم فأرادوا أن يلحقوا بمن له الوقائع والأشعار فقالوا على ألسنة شعرائهم\nثم كانت الرواة بعد فزادوا فى الأشعار التى قيلت\nوليس يشكل على أهل العلم زيادة الرواة ولا ما وضعوا ولا ما وضع المولدون وإنما عضل بهم\nأن يقول الرجل من أهل البادية من ولد الشعراء أو الرجل ليس من ولدهم فيشكل ذلك بعض الإشكال"},{"id":"tabaqat-shuara:52","bookId":"tabaqat-shuara","type":"section","seq":52,"chapter":"طبقات فحول الشعراء","title":"50- قال ابن سلام أخبرنى أبو عبيدة أن ابن داوود بن متمم بم نويرة قدم البصرة فى بعض ما يقدم له ا","page":"ص0","text":"قال ابن سلام أخبرنى أبو عبيدة أن ابن داوود بن متمم بم نويرة قدم البصرة فى بعض ما يقدم له البدوى من الجلب والميرة فنزل النحيت فأتيته أنا وابن نوح العطاردى فسألناه عن شعر أبيه متمم وقمنا له بحاجته وكفيناه ضيعته فلما نفد شعر أبيه\nجعل يزيد فى الأشعار ويصنعها لنا وإذا كلام دون كلام متمم وإذا هو يحتذى على كلامه فيذكر المواضع التى ذكرها متمم والوقائع التى شهدها\nفلما توالى ذلك علمنا أنه يفتعله"},{"id":"tabaqat-shuara:53","bookId":"tabaqat-shuara","type":"section","seq":53,"chapter":"طبقات فحول الشعراء","title":"51- وكان أول من جمع أشعار العرب وساق أحاديثها حماد الراوية وكان غير موثوق به وكان ينحل شعر الر","page":"ص0","text":"وكان أول من جمع أشعار العرب وساق أحاديثها حماد الراوية وكان غير موثوق به وكان ينحل شعر الرجل غيره وينحله غير شعره ويزيد في الأشعار"},{"id":"tabaqat-shuara:54","bookId":"tabaqat-shuara","type":"section","seq":54,"chapter":"طبقات فحول الشعراء","title":"52- قال ابن سلام أخبرنى أبو عبيدة عن يونس قال قدم حماد البصرة على بلال بن أبى بردة وهو عليها ف","page":"ص0","text":"قال ابن سلام أخبرنى أبو عبيدة عن يونس قال قدم حماد البصرة على بلال بن أبى بردة وهو عليها فقال أما أطرفتنى شيئا فعاد إليه فأنشده القصيدة التى في شعر الحطيئة مديح أبى موسى قال ويحك يمدح الحطئية أبا موسى لا أعلم به وأنا أروى شعر الحطيئة ولكن دعها تذهب في الناس"},{"id":"tabaqat-shuara:55","bookId":"tabaqat-shuara","type":"section","seq":55,"chapter":"طبقات فحول الشعراء","title":"53- قال ابن سلام أخبرنى أبو عبيدة عن عمر بن سعيد بن وهب الثقفى قال كان حماد لى صديقا ملطفا فعر","page":"ص0","text":"قال ابن سلام أخبرنى أبو عبيدة عن عمر بن سعيد بن وهب الثقفى قال كان حماد لى صديقا ملطفا فعرض على ما قبله يوما\nفقلت له أمل على قصيدة لأخوالى بنى سعد بن مالك لطرفة فأملى على\n(إن الخليط أجد منتقله ... ولذاك زمت غدوة إبله)\n(عهدى بهم فى النقب قد سندوا ... تهدى صعاب مطيهم ذلله)\nوهي لأعشى همدان"},{"id":"tabaqat-shuara:56","bookId":"tabaqat-shuara","type":"section","seq":56,"chapter":"طبقات فحول الشعراء","title":"54- وسمعت يونس يقول العجب ممن يأخذ عن حماد وكان يكذب ويلحن ويكسر","page":"ص0","text":"وسمعت يونس يقول العجب ممن يأخذ عن حماد وكان يكذب ويلحن ويكسر"},{"id":"tabaqat-shuara:57","bookId":"tabaqat-shuara","type":"section","seq":57,"chapter":"طبقات فحول الشعراء","title":"55- ثم إنا اقتصرنا بعد الفحص والنظر والرواية عمن مضى — من أهل العلم إلى رهط أربعة اجتمعوا على أن","page":"ص0","text":"ثم إنا اقتصرنا بعد الفحص والنظر والرواية عمن مضى\nمن أهل العلم إلى رهط أربعة اجتمعوا على أنهم أشعر العرب طبقة ثم اختلفوا فيهم بعد\nوسنسوق اختلافهم واتفاقهم ونسمى الأربعة ونذكر الحجة لكل واحد منهم وليس تبدئتنا أحدهم في الكتاب نحكم له ولا بد من مبتدأ ونذكر من شعرهم الأبيات التى تكون فى الحديث والمعنى"},{"id":"tabaqat-shuara:58","bookId":"tabaqat-shuara","type":"section","seq":58,"chapter":"طبقات فحول الشعراء","title":"56- امرؤ القيس بن حجر بن الحارث بن عمرو بن حجر آكل المرار بن عمرو بن معاوية بن يعرب بن ثور بن","page":"ج1 ص50","text":"امرؤ القيس بن حجر بن الحارث بن عمرو بن حجر آكل المرار بن عمرو بن معاوية بن يعرب بن ثور بن مرتع بن معاوية ابن كنده"},{"id":"tabaqat-shuara:59","bookId":"tabaqat-shuara","type":"section","seq":59,"chapter":"طبقات فحول الشعراء","title":"57- ونابغة بنى ذبيان واسمه زياد بن معاوية بن ضباب بن جابر ابن يربوع بن غيظ بن مرة بن عوف بن سع","page":"ج1 ص50","text":"ونابغة بنى ذبيان واسمه زياد بن معاوية بن ضباب بن جابر ابن يربوع بن غيظ بن مرة بن عوف بن سعد بن ذبيان ويكنى أبا أمامة"},{"id":"tabaqat-shuara:60","bookId":"tabaqat-shuara","type":"section","seq":60,"chapter":"طبقات فحول الشعراء","title":"58- وزهير بن أبى سلمى واسم أبى سلمى ربيعة بن رياح ابن قرط بن الحارث بن مازن بن ثعلبة بن ثور بن","page":"ج1 ص50","text":"وزهير بن أبى سلمى واسم أبى سلمى ربيعة بن رياح ابن قرط بن الحارث بن مازن بن ثعلبة بن ثور بن هذمة بن لاطم بن عثمان ابن مزينة"},{"id":"tabaqat-shuara:61","bookId":"tabaqat-shuara","type":"section","seq":61,"chapter":"طبقات فحول الشعراء","title":"59- والأعشى وهو ميمون بن قيس بن جندل بن شراحيل بن عوف بن سعد بن ضبيعة بن قيس بن ثعلبة ويكنى أب","page":"ص0","text":"والأعشى وهو ميمون بن قيس بن جندل بن شراحيل بن عوف بن سعد بن ضبيعة بن قيس بن ثعلبة ويكنى أبا بصير"},{"id":"tabaqat-shuara:62","bookId":"tabaqat-shuara","type":"section","seq":62,"chapter":"طبقات فحول الشعراء","title":"60- أخبرنى يونس بن حبيب أن علماء البصرة كانوا يقدمون امرأ القيس بن حجر وأهل الكوفة كانوا يقدمو","page":"ص0","text":"أخبرنى يونس بن حبيب أن علماء البصرة كانوا يقدمون امرأ القيس بن حجر وأهل الكوفة كانوا يقدمون الأعشى وأن أهل الحجاز والبادية كانوا يقدمون زهيرا والنابغة"},{"id":"tabaqat-shuara:63","bookId":"tabaqat-shuara","type":"section","seq":63,"chapter":"طبقات فحول الشعراء","title":"61- وأخبرنى يونس كالمتعجب أن ابن أبى إسحاق كان يقول أشعر أهل الجاهلية مرقش وأشعر أهل الإسلام ك","page":"ص0","text":"وأخبرنى يونس كالمتعجب أن ابن أبى إسحاق كان يقول أشعر أهل الجاهلية مرقش وأشعر أهل الإسلام كثير\nولم يقبل هذا القول ولم يشيع"},{"id":"tabaqat-shuara:64","bookId":"tabaqat-shuara","type":"section","seq":64,"chapter":"طبقات فحول الشعراء","title":"62- وأخبرنى شعيب بن صخر عن هارون بن إبراهيم قال سمعت قائلا يقول للفرزدق من أشعر الناس يا أبا ف","page":"ص0","text":"وأخبرنى شعيب بن صخر عن هارون بن إبراهيم قال سمعت قائلا يقول للفرزدق من أشعر الناس يا أبا فراس قال\nذو القروح يعنى امرأ القيس\nقال حين يقول ماذا قال حين يقول\n(وقاهم جدهم ببنى أبيهم ... وبالأشقين ما كان العقاب)\n(وأفلتهن علباء جريضا ... ولو أدركنه صفر الوطاب)"},{"id":"tabaqat-shuara:65","bookId":"tabaqat-shuara","type":"section","seq":65,"chapter":"طبقات فحول الشعراء","title":"63- أخبرنى أبو خليفة عن محمد بن سلام قال سمعت رجلا يسأل يونس عن قوله صفر الوطاب فقال سألنا رؤب","page":"ص0","text":"أخبرنى أبو خليفة عن محمد بن سلام قال سمعت رجلا يسأل يونس عن قوله صفر الوطاب فقال سألنا رؤبة عنه فقال لو أدركوه قتلوه وساقوا إبله فصفرت وطابه من اللبن\nوقال غيره صفر الوطاب أى أنه كان يقتل فيكون جسمه صفرا من دمه كما يكون الوطاب صفرا من اللبن"},{"id":"tabaqat-shuara:66","bookId":"tabaqat-shuara","type":"section","seq":66,"chapter":"طبقات فحول الشعراء","title":"64- وأخبرنى شعيب بن صخر قال سمعت عيسى بن عمر ينشد عامر بن عبد الملك لزهير أو النابغة فقال يا أ","page":"ص0","text":"وأخبرنى شعيب بن صخر قال سمعت عيسى بن عمر ينشد عامر بن عبد الملك لزهير أو النابغة فقال يا أبا عبد الله هذا والله لا قول الأعشى\n(لسنا نقاتل بالعصى ... ولا نرامى بالحجارة)"},{"id":"tabaqat-shuara:67","bookId":"tabaqat-shuara","type":"section","seq":67,"chapter":"طبقات فحول الشعراء","title":"65- وأخبرنى أبان بن عثمان البجلى قال مر لبيد بالكوفة فى بنى نهد فأتبعوه رسولا سؤولا يسئله من أ","page":"ص0","text":"وأخبرنى أبان بن عثمان البجلى قال مر لبيد بالكوفة فى بنى نهد فأتبعوه رسولا سؤولا يسئله من أشعر الناس قال الملك الضليل\nفأعادوه إليه قال ثم من قال الغلام القتيل وقال غير أبان ابن العشرين يعنى طرفة قال ثم من قال الشيخ أبو عقيل يعنى نفسه\nفهذان امرؤ القيس وطرفة\nقال يونس كل شئ فى القرآن فأتبعه أى طالبه\nوأتبعه يتلوه"},{"id":"tabaqat-shuara:68","bookId":"tabaqat-shuara","type":"section","seq":68,"chapter":"طبقات فحول الشعراء","title":"66- فاحتج لامرئ القيس من يقدمه قال ما قال ما لم يقولوا ولكنه سبق العرب إلى أشياء ابتدعها واستح","page":"ص0","text":"فاحتج لامرئ القيس من يقدمه قال ما قال ما لم يقولوا ولكنه سبق العرب إلى أشياء ابتدعها واستحسنتها العرب واتبعته فيها الشعراء استيقاف صحبه والتبكاء فى الديار ورقة النسيب وقرب المأخذ وشبه النساء بالظباء والبيض وشبه الخيل بالعقبان والعصى وقيد الأوابد وأجاد في التشبيه وفصل بين النسيب وبين المعنى\nكان أحسن أهل طبقته تشبيها وأحسن الإسلاميين تشبيها ذو الرمة"},{"id":"tabaqat-shuara:69","bookId":"tabaqat-shuara","type":"section","seq":69,"chapter":"طبقات فحول الشعراء","title":"67- وقال من احتج للنابغة كان أحسنهم ديباجة شعر وأكثرهم رونق كلام وأجزلهم بيتا كأن شعره كلام لي","page":"ص0","text":"وقال من احتج للنابغة كان أحسنهم ديباجة شعر وأكثرهم رونق كلام وأجزلهم بيتا كأن شعره كلام ليس فيه تكلف\nوالمنطق على المتكلم أوسع منه على الشاعر والشعر يحتاج إلى البناء والعروض والقوافى والمتكلم مطلق يتخير الكلام\nوإنما نبغ بالشعر بعد ما أسن واحتنك وهلك قبل أن يهتر"},{"id":"tabaqat-shuara:70","bookId":"tabaqat-shuara","type":"section","seq":70,"chapter":"طبقات فحول الشعراء","title":"68- ويروى أن عمر بن الخطاب قال أى شعرائكم يقول —","page":"ص0","text":"ويروى أن عمر بن الخطاب قال أى شعرائكم يقول\n(فلست بمستبق أخا لا تلمه ... إلى شعث أى الرجال المهذب)\nقالوا النابغة\nقال هو أشعرهم وبنو سعد بن زيد مناة تدعى هذا البيت لرجل من بنى مالك بن سعد يقال له شقة أنشدناه له\nحلابس العطاردى\nوأخبرنى خلف الأحمر أنه سمع من أعراب بنى سعد لهذا الرجل"},{"id":"tabaqat-shuara:71","bookId":"tabaqat-shuara","type":"section","seq":71,"chapter":"طبقات فحول الشعراء","title":"69- وأخبرنى خلف أنه سمع أهل البادية من بنى سعد يروون بيت النابغة للزبرقان بن بدر فمن رواه للنا","page":"ص0","text":"وأخبرنى خلف أنه سمع أهل البادية من بنى سعد يروون بيت النابغة للزبرقان بن بدر فمن رواه للنابغة قال\n(تعدو الذئاب على من لا كلاب له ... وتتقى مربض المستثفر الحامى)\nوهى الكلمة التى أولها\n(قالت بنو عامر خالوا بنى أسد ... يا بؤس للجهل ضرارا الأقوام)\nومن رواه للزبرقان بن بدر قال\n(إن الذئاب ترى من لا كلاب له ... وتحتمى مربض المستثفر الحامى)\nويروى وتتقى هذا البيت فى قوله\n(أبلغ سراة بنى عوف مغلغلة ... )\nوسألت يونس عن البيت فقال هو للنابغة أظن الزبرقان استزاده في شعره كالمثل حين جاء موضعه لا مجتلبا له"},{"id":"tabaqat-shuara:72","bookId":"tabaqat-shuara","type":"section","seq":72,"chapter":"طبقات فحول الشعراء","title":"70- وقد تفعل ذلك العرب لا يريدون به السرقة قال أبو الصلت بن ربيعة الثقفى —","page":"ص0","text":"وقد تفعل ذلك العرب لا يريدون به السرقة قال أبو الصلت بن ربيعة الثقفى\n(تلك المكارم لاقعبان من لبن ... شيبا بماء فعادا بعد أبوالا)\nوقال النابغة الجعدى في كلمة فخر بها ورد فيها على القشيرى\n(فإن يكن حاجب ممن فخرت به ... فلم يكن حاجب عما ولا خالا)\n(هلا فخرت بيومى رحرحان وقد ... ظنت هوازن أن العز قد زالا)\n(تلك المكارم لا قعبان من لبن ... شيبا بماء فعادا بعد أبوالا)\nترويه عامر للنابغة الرواة مجمعون أن أبا الصلت بن أبى ربيعة قاله"},{"id":"tabaqat-shuara:73","bookId":"tabaqat-shuara","type":"section","seq":73,"chapter":"طبقات فحول الشعراء","title":"71- وقال غير واحد من الرجاز —","page":"ص0","text":"وقال غير واحد من الرجاز\n(عند الصباح يحمد القوم السرى ... )\nإذا جاء موضعه جعلوه مثلا وقال امرؤ القيس\n(وقوفا بها صحبى على مطيهم ... يقولون لا تهلك أسى وتجمل)\nوقال طرفة\n(وقوفا بها صحبى على مطيهم ... يقولون لا تهلك أسى وتجلد)"},{"id":"tabaqat-shuara:74","bookId":"tabaqat-shuara","type":"section","seq":74,"chapter":"طبقات فحول الشعراء","title":"72- ويروى عن الشعبى عن ربعى بن حراش أن عمر — ابن الخطاب قال أى شعرائكم الذى يقول —","page":"ص0","text":"ويروى عن الشعبى عن ربعى بن حراش أن عمر\nابن الخطاب قال أى شعرائكم الذى يقول\n(فألفيت الأمانة لم تخنها ... كذلك كان نوح لا يخون)\nوهذا غلط على الشعبى أو من الشعبى أو من ابن حراش\nأجمع أهل العلم أن النابغة لم يقل هذا ولم يسمعه عمر ولكنهم غلطوا بغيره من شعر النابغة فإنه قد ذكر لى أن عمر بن الخطاب سأل عن بيت النابغة\n(حلفت فلم أترك لنفسك ريبة ... وليس وراء الله للمرء مذهب)\nوحرى أن يكون هذا البيت أو البيت الأول"},{"id":"tabaqat-shuara:75","bookId":"tabaqat-shuara","type":"section","seq":75,"chapter":"طبقات فحول الشعراء","title":"73- وجدنا رواة العلم يغلطون فى الشعر ولا يضبط الشعر إلا أهله — وقد تروى العامة أن الشعبى كان ذا","page":"ص0","text":"وجدنا رواة العلم يغلطون فى الشعر ولا يضبط الشعر إلا أهله\nوقد تروى العامة أن الشعبى كان ذا علم بالشعر وأيام العرب وقد روى عنه هذا البيت وهو فاسد\nوروى عنه شيء يحمل على لبيد\n(باتت تشكى إلى النفس مجهشة ... وقد حملتك سبعا بعد سبعين)\n(فإن تعيشى ثلاثا تبلغى أملا ... وفى الثلاث وفاء للثمانين)\nولا اختلاف فى أن هذا مصنوع تكثر به الأحاديث ويستعان به على السهر عند الملوك والملوك لا تستقصى"},{"id":"tabaqat-shuara:76","bookId":"tabaqat-shuara","type":"section","seq":76,"chapter":"طبقات فحول الشعراء","title":"74- وكان قتادة بن دعامة السدوسى من رواة الفقه عالما بالعرب وبأنسابها ولم يأتنا عن أحد من رواة","page":"ص0","text":"وكان قتادة بن دعامة السدوسى من رواة الفقه عالما بالعرب وبأنسابها ولم يأتنا عن أحد من رواة الفقه من علم العرب أصح من شئ أتانا عن قتادة"},{"id":"tabaqat-shuara:77","bookId":"tabaqat-shuara","type":"section","seq":77,"chapter":"طبقات فحول الشعراء","title":"75- أخبرنا عامر بن عبد الملك قال كان الرجلان من بنى مروان يختلفان فى الشعر فيرسلان راكبا فينيخ","page":"ص0","text":"أخبرنا عامر بن عبد الملك قال كان الرجلان من بنى مروان يختلفان فى الشعر فيرسلان راكبا فينيخ ببابه يعنى قتادة بن دعامة فيسأله عنه ثم يشخص"},{"id":"tabaqat-shuara:78","bookId":"tabaqat-shuara","type":"section","seq":78,"chapter":"طبقات فحول الشعراء","title":"76- أخبرنى سعيد بن عبيد عن أبى عوانه أنه قال شهدت عامر بن عبد الملك يسأل قتادة عن أيام العرب و","page":"ص0","text":"أخبرنى سعيد بن عبيد عن أبى عوانه أنه قال شهدت عامر بن عبد الملك يسأل قتادة عن أيام العرب وأنسابها وأحاديثها فاستحسنته\nفعدت إليه فجعلت أسأله عن ذلك فقال مالك ولهذا دع هذا العلم لعامر وعد إلى شأنك"},{"id":"tabaqat-shuara:79","bookId":"tabaqat-shuara","type":"section","seq":79,"chapter":"طبقات فحول الشعراء","title":"77- ويروى عن بعض أصحابنا قال رأيت راكبا قدم من الشأم فأناخ على باب قتادة فسأله من قتل عمرا وعا","page":"ص0","text":"ويروى عن بعض أصحابنا قال رأيت راكبا قدم من الشأم فأناخ على باب قتادة فسأله من قتل عمرا وعامرا التغلبيين يوم قضة قال جحدر فأعادوا إليه الرسول كيف قتلهما جميعا قال اعتوراه فطعن هذا بالسنان وهذا بالزج فعادى بينهما\nثم رحل مكانه"},{"id":"tabaqat-shuara:80","bookId":"tabaqat-shuara","type":"section","seq":80,"chapter":"طبقات فحول الشعراء","title":"78- وكان أبو المعتمر الشيبانى كثير الحديث عن العرب وعن — معاوية وعمرو بن العاص وزياد وطبقتهم وكا","page":"ص0","text":"وكان أبو المعتمر الشيبانى كثير الحديث عن العرب وعن\nمعاوية وعمرو بن العاص وزياد وطبقتهم وكان يقول أخذته عن قتادة وكان أبو بكر الهذلى يروى هذا العلم عن قتادة"},{"id":"tabaqat-shuara:81","bookId":"tabaqat-shuara","type":"section","seq":81,"chapter":"طبقات فحول الشعراء","title":"79- أخبرنى عيسى بن يزيد بن دأب بإسناد له عن ابن عباس قال قال لى عمر أنشدنى لأشعر شعرائكم — قلت م","page":"ص0","text":"أخبرنى عيسى بن يزيد بن دأب بإسناد له عن ابن عباس قال قال لى عمر أنشدنى لأشعر شعرائكم\nقلت من هو يا أمير المؤمنين قال زهير\nقلت وكان كذلك قال كان لا يعاظل بين الكلام ولا يتبع وحشيه ولا يمدح الرجل إلا بما فيه"},{"id":"tabaqat-shuara:82","bookId":"tabaqat-shuara","type":"section","seq":82,"chapter":"طبقات فحول الشعراء","title":"80- وأخبرنى عمر بن موسى الجمحى عن أخيه قدامة ابن موسى وكأن من علماء أهل المدينة أنه كان يقدم ز","page":"ص0","text":"وأخبرنى عمر بن موسى الجمحى عن أخيه قدامة ابن موسى وكأن من علماء أهل المدينة أنه كان يقدم زهيرا\nقلنا فأى شعره كان أعجب إليه قال التى يقول فيها\n(قد جعل المبتغون الخير فى هرم ... والسائلون إلى أبوابه طرقا)\n(من يلق يوما على علاته هرما ... يلق السماحة منه والندى خلقا)"},{"id":"tabaqat-shuara:83","bookId":"tabaqat-shuara","type":"section","seq":83,"chapter":"طبقات فحول الشعراء","title":"81- وقال أهل النظر كان زهيرا أحصفهم شعرا وأبعدهم من سخف وأجمعهم لكثير من المعنى فى قليل من الم","page":"ص0","text":"وقال أهل النظر كان زهيرا أحصفهم شعرا وأبعدهم من سخف وأجمعهم لكثير من المعنى فى قليل من المنطق وأشدهم مبالغة في المدح وأكثرهم أمثالا فى شعره"},{"id":"tabaqat-shuara:84","bookId":"tabaqat-shuara","type":"section","seq":84,"chapter":"طبقات فحول الشعراء","title":"82- وأخبرنى أبو قيس العنبرى ولم أر بدويا يزيد عليه عن عكرمة بن جرير قال قلت لأبى يا أبه من أشع","page":"ص0","text":"وأخبرنى أبو قيس العنبرى ولم أر بدويا يزيد عليه عن عكرمة بن جرير قال قلت لأبى يا أبه من أشعر الناس قال أعن أهل الجاهلية تسألنى أم أهل الإسلام قلت ما أردت إلا الإسلام فإذ ذكرت أهل الجاهلية فأخبرنى عن أهلها\nقال زهير\nشاعرها\nقال قلت فالإسلام قال الفرزدق نبعة الشعر\nقلت فالأخطل قال يجيد مدح الملوك ويصيب صفة الخمر\nقلت فما تركت لنفسك قال دعنى فإنى أنا نحرت الشعر نحرا"},{"id":"tabaqat-shuara:85","bookId":"tabaqat-shuara","type":"section","seq":85,"chapter":"طبقات فحول الشعراء","title":"83- وقال أصحاب الأعشى هو أكثرهم عروضا وأذهبهم فى فنون الشعر وأكثرهم طويلة جيدة وأكثرهم مدحا وه","page":"ص0","text":"وقال أصحاب الأعشى هو أكثرهم عروضا وأذهبهم فى فنون الشعر وأكثرهم طويلة جيدة وأكثرهم مدحا وهجاء وفخرا ووصفا كل ذلك عنده"},{"id":"tabaqat-shuara:86","bookId":"tabaqat-shuara","type":"section","seq":86,"chapter":"طبقات فحول الشعراء","title":"84- وكان أول من سأل بشعره ولم يكن له مع ذلك بيت نادر على أفواه الناس كأبيات أصحابه","page":"ص0","text":"وكان أول من سأل بشعره ولم يكن له مع ذلك بيت نادر على أفواه الناس كأبيات أصحابه"},{"id":"tabaqat-shuara:87","bookId":"tabaqat-shuara","type":"section","seq":87,"chapter":"طبقات فحول الشعراء","title":"85- وشهدت خلفا فقيل له من أشعر الناس فقال ما ننتهى — إلى واحد يجتمع عليه كما لا يجتمع على اشجع ا","page":"ص0","text":"وشهدت خلفا فقيل له من أشعر الناس فقال ما ننتهى\nإلى واحد يجتمع عليه كما لا يجتمع على اشجع الناس وأخطب الناس وأجمل الناس\nقلت فأيهم أعجب إليك يا أبا محرز قال الأعشى\nقال أظنه قال كان أجمعهم"},{"id":"tabaqat-shuara:88","bookId":"tabaqat-shuara","type":"section","seq":88,"chapter":"طبقات فحول الشعراء","title":"86- وكان أبو الخطاب الأخفش مستهترا به يقدمه — وكان أبو عمرو بن العلاء يقول مثله مثل البازى يضرب","page":"ص0","text":"وكان أبو الخطاب الأخفش مستهترا به يقدمه\nوكان أبو عمرو بن العلاء يقول مثله مثل البازى يضرب كبير الطير وصغيرة\nويقول نظيرة فى الإسلام جرير ونظير النابغة الأخطل ونظير زهير الفرزدق"},{"id":"tabaqat-shuara:89","bookId":"tabaqat-shuara","type":"section","seq":89,"chapter":"طبقات فحول الشعراء","title":"87- وروى سليمان بن إسحق الربالى عن يونس أنه قال الشعر كالسراء والشجاعة والجمال لا ينتهى منه إل","page":"ص0","text":"وروى سليمان بن إسحق الربالى عن يونس أنه قال الشعر كالسراء والشجاعة والجمال لا ينتهى منه إلى غاية"},{"id":"tabaqat-shuara:90","bookId":"tabaqat-shuara","type":"section","seq":90,"chapter":"طبقات فحول الشعراء","title":"88- أخبرنى المسيب بن سعيد عن هشام بن القاسم مولى بنى — غبر وقد رأيته وكان من عليه أهل البصرة وكا","page":"ص0","text":"أخبرنى المسيب بن سعيد عن هشام بن القاسم مولى بنى\nغبر وقد رأيته وكان من عليه أهل البصرة وكان يصلى على جنائز بنى غبر قال أول من سأل بشعره الأعشى"},{"id":"tabaqat-shuara:91","bookId":"tabaqat-shuara","type":"section","seq":91,"chapter":"طبقات فحول الشعراء","title":"89- ولم يقو من هذه الطبقة ولا من أشباههم إلا النابغة فى بيتين قوله —","page":"ص0","text":"ولم يقو من هذه الطبقة ولا من أشباههم إلا النابغة فى بيتين قوله\n(أمن آل مية رائح أو مغتدى ... عجلان ذا زاد وغير مزود)\n(زعم البوارح أن رحلتنا غدا ... وبذاك خبرنا الغداف الأسود)\nوقوله\n(سقط النصيف ولم ترد إسقاطه ... فتناولته واتقتنا باليد)\n(بمخضب رخص كأن بنانه ... عنم يكاد من اللطافة يعقد)\nالعنم نبت أحمر يصبغ به فقدم المدينة فعيب ذلك عليه فلم يأبه لهما حتى أسمعوه إياه فى غناء وأهل القرى ألطف نظرا من أهل البدو وكانوا يكتبون لجوارهم أهل الكتاب فقالوا للجارية إذا صرت إلى القافية فرتلى\nفلما قالت الغداف الأسود ويعقد وباليد علم وانتبه فلم يعد فيه\nوقال قدمت الحجاز وفى شعرى صنعة ورحلت عنها وأنا أشعر الناس"},{"id":"tabaqat-shuara:92","bookId":"tabaqat-shuara","type":"section","seq":92,"chapter":"طبقات فحول الشعراء","title":"90- قال يونس عيوب الشعر أربعة الزحاف والسناد والإقواء والإيطاء والإكفاء وهو الإقواء — والزحاف أه","page":"ص0","text":"قال يونس عيوب الشعر أربعة الزحاف والسناد والإقواء والإيطاء والإكفاء وهو الإقواء\nوالزحاف أهونها وهو أن ينقص الجزء عن سائر الأجزاء فينكره السمع ويثقل على اللسان\nوهو في ذلك جائز\nوالأجزاء\nمختلفة فمنها ما نقصانه أخفى ومنها ما نقصانه أشنع\nقال الهذلى\n(لعلك إما أم عمرو تبدلت ... سواك خليلا شاتمى تستخيرها)\nفهذا مزاحف في كاف سواك وهو خفى ومن أنشده\n(لعلك إما أم عمرو تبدلت ... خليلا خليلا سواك شاتمى تستخيرها)\nفهذا أفظع وهو جائز والاستخارة الاستعطاف ويقال تبغمت الظبية تستخير ولدها أى تستدعيه\nومنه قيل أستخير الله أى أستعطفه\nوهو نحو قول الفرزدق\n(فإن كان لهذا الأمر فى جاهلية ... علمت من المولى القليل حلائبه)\n(ولو كان هذا غير دين محمد ... لأديته أو غص بالماء شاربه)\nمزاحف خفى ومن قال لأدين أو لغص بالماء شاربه فهو أفظع\nوهو أكثر من أن يعد"},{"id":"tabaqat-shuara:93","bookId":"tabaqat-shuara","type":"section","seq":93,"chapter":"طبقات فحول الشعراء","title":"91- وكان الخليل بن أحمد يستحسنه في الشعر إذا قل فى البيت والبيتين فإذا توالى وكثر فى القصيدة س","page":"ج1 ص69","text":"وكان الخليل بن أحمد يستحسنه في الشعر إذا قل فى البيت والبيتين فإذا توالى وكثر فى القصيدة سمج\nفإن قيل كيف يستحسن منه شئ وقد قيل هو عيب قال يكون هذا مثل القبل والحول واللثغ فى الجارية قد يشتهى القليل منه الخفيف وهو إن كثر عند رجل فى جوار أو اشتد فى جارية هجن وسمج\nوالوضح في الخيل يستطرف ويشتهى خفيفه مثل الغرة والتحجيل فإذا كثر وفشا كانت هجنة ووهنا\nوخفيف البلق يحتمل فى الخيل ولم أر أبلق قط ولم أسمع به سابقا"},{"id":"tabaqat-shuara:94","bookId":"tabaqat-shuara","type":"section","seq":94,"chapter":"طبقات فحول الشعراء","title":"92- والإقواء هو الإكفاء مهموز — وهو أن يختلف إعراب القوافى فتكون قافية مرفوعة وأخرى مخفوضة أو من","page":"ص0","text":"والإقواء هو الإكفاء مهموز\nوهو أن يختلف إعراب القوافى فتكون قافية مرفوعة وأخرى مخفوضة أو منصوبة وهو فى شعر الأعراب كثير ودون الفحول من الشعراء ولا يجوز لمولد لأنهم قد عرفوا عيبه والبدوى لا يأبه له فهو أعذر"},{"id":"tabaqat-shuara:95","bookId":"tabaqat-shuara","type":"section","seq":95,"chapter":"طبقات فحول الشعراء","title":"93- فقلت ليونس أكان عبيد الله بن الحر يقوى قال الإقواء خير منه يعنى من فوقه من الشعراء يقوى غي","page":"ص0","text":"فقلت ليونس أكان عبيد الله بن الحر يقوى قال الإقواء خير منه يعنى من فوقه من الشعراء يقوى غير أن الفحول قد استجاوزا فى موضع نحو قول جرير\n(عرين من عرينة ليس منا ... برئت إلى عرينة من عرين)\n(عرفنا جعفرا وبنى عبيد ... وأنكرنا زعانف آخرين)\nوقال سحيم بن وثيل\n(عذرت البزل إن هى خاطرتنى ... فما بالى وبال ابن اللبون)\n(وماذا يدرى الشعراء منى ... وقد جاوزت رأس الأربعين)\nفموضع هذه الأبيات التى له ولجرير النصب ولكنه كأنه سكت عند القافية"},{"id":"tabaqat-shuara:96","bookId":"tabaqat-shuara","type":"section","seq":96,"chapter":"طبقات فحول الشعراء","title":"94- ومنه الإيطاء وهو أن تتفق القافيتان فى قصيدة واحدة فإن كان أكثر من قافيتين فهو أسمج له وقد","page":"ص0","text":"ومنه الإيطاء وهو أن تتفق القافيتان فى قصيدة واحدة فإن كان أكثر من قافيتين فهو أسمج له وقد يكون\nولا يجوز لمولد إذ كان عنده عيبا\nفإذا اتفق اللفظ واختلف المعنى فهو جائز نحو قولك محمد تريد الاسم وجواد محمد تريد الفعل\nوتقول خيار تريد خيار من الله وتقول خيار أى خيار من قوم\nفيجوز\nونحو هذا كثير وأهل البادية لا ينكرونه\nوأنشد سلمة ابن عياش أباحية النميرى كلمة طويلة جدا يقول فيها\n(طربت وما هذا بحين تطرب ... ورأسك مبيض العذارين أشيب)\nقال له النميرى أرى فيها عيبا\nقال ما هو قال لم أرك أعدت قافية بعد قافية عده عيبا\nأظنه عابه إذا رأى أنه هرب منه"},{"id":"tabaqat-shuara:97","bookId":"tabaqat-shuara","type":"section","seq":97,"chapter":"طبقات فحول الشعراء","title":"95- والمواطأة فى الأمر يقال منه واطأته على كذا وكذا ومنه {ليواطئوا عدة ما حرم الله} أى ليوافقو","page":"ص0","text":"والمواطأة فى الأمر يقال منه واطأته على كذا وكذا ومنه {ليواطئوا عدة ما حرم الله} أى ليوافقوا\nكانت العرب تحرم أربعة أشهر من السنة كما كان بأيديهم من إرث إسماعيل بن إبراهيم عليهما السلام وكانت توالى عليهم ثلاثة أشهر ذو القعدة وذو الحجة والمحرم فيطول عليهم أن لا يغزوا ولا يحاربوا وكان لهم نسأة من بنى كنانة تؤخر المحرم عاما وترده\nعاما وذلك قول الله عز وجل {إنما النسيء زيادة في الكفر} وهى فى الذين يريدون أن يجعلوا أربعة حرما ...\n... . . المحرم عام حجة الوداع من النبى صلى الله عليه وسلم الشهر الذى حرمه الله بعينه فقال إن الزمان قد استدار كهيئته يوم خلق الله السموات والأرض\nوكان الذي يسمع الناس عنه صلى الله عليه وسلم ربيعة بن أمية ابن خلف الجمحى وكان فى صوته رفاع\nفأصاب بعد ذلك فى عهد عمر بن الخطاب حدا بالشأم فضرب فأدركته الحمية فلحق بالروم فهلك فيهم فكره الناس بعد ذلك أن يقيموا حدا بأرض العدو\nوكانت العرب تسمى رجبا الأصم ويسمونه منصل الأسنة وكانوا ينصلون أسنتهم فيه لموضع الحرب قال دريد بن الصمة\n(تداركه فى منصل الأل بعدما ... مضى غير دأداة وقد كاد يعطب)\nوالدأداة الليلة التى تكون فى آخر الشهر يشك فيها"},{"id":"tabaqat-shuara:98","bookId":"tabaqat-shuara","type":"section","seq":98,"chapter":"طبقات فحول الشعراء","title":"96- والسناد وهو أن تختلف القوافى نحو نقيب وعيب وقريب وشيب منه قول الفضل بن العباس اللهبى —","page":"ج1 ص74","text":"والسناد وهو أن تختلف القوافى نحو نقيب وعيب وقريب وشيب منه قول الفضل بن العباس اللهبى\n(عبد شمس أبى فإن كنت غضبى ... فاملئى وجهك الجميل خموشا)\nوقال\n(وبنا سميت قريش قريشا ... )\nوقال\n( ... . . ولا تمليت عيشا ... )\nوقال عدى بن زيد\n(فناجاها وقد جمعت فيوجا ... على أبواب حصن مصلتينا)\n(فقدمت الأديم لراهشيه ... وألفى قولها كذبا ومينا)\nقال المفضل كذابا مبينا فر من السناد والرواية هى الأولى على قوله ومينا"},{"id":"tabaqat-shuara:99","bookId":"tabaqat-shuara","type":"section","seq":99,"chapter":"طبقات فحول الشعراء","title":"97- وقال الفضل بن عبد الرحمن بن عباس فى مرثية زيد ابن علي بن الحسين رضى الله عنهم —","page":"ص0","text":"وقال الفضل بن عبد الرحمن بن عباس فى مرثية زيد ابن علي بن الحسين رضى الله عنهم\n( ... . . ليس ذا حين الجمود ... )\nثم قال\n( ... ... ... فوق العمود ... )\nثم قال\n(وكيف جمود دمعك بعد زيد ... )"},{"id":"tabaqat-shuara:100","bookId":"tabaqat-shuara","type":"section","seq":100,"chapter":"طبقات فحول الشعراء","title":"98- ومنه قول العرب خرج القوم برأسين متساندين أى هذا على حياله وهذا على حياله وهو من قولهم كانت","page":"ص0","text":"ومنه قول العرب خرج القوم برأسين متساندين أى هذا على حياله وهذا على حياله وهو من قولهم كانت قريش يوم الفجار متساندين أى لا يقودهم رجل واحد"},{"id":"tabaqat-shuara:101","bookId":"tabaqat-shuara","type":"section","seq":101,"chapter":"طبقات فحول الشعراء","title":"99- وقال العجاج فأفرط وجاوز السناد مع حذفه —","page":"ص0","text":"وقال العجاج فأفرط وجاوز السناد مع حذفه\n(ثم رأى أهل الدسيع الأعظم ... خندف والجد الخضم المخضم)\n(وعلية الناس وأهل الحكم ... ومستقر المصحف المرقم)\n(عند كريم منهم مكرم ... معلم آى الهدى معلم)\n(مبارك للأنبياء خاتم ... وخندف هامة هذا العالم)\nفساند فى بيتين سنادا فاحشا أخذه الناس عليه"},{"id":"tabaqat-shuara:102","bookId":"tabaqat-shuara","type":"section","seq":102,"chapter":"طبقات فحول الشعراء","title":"100- وأخبرنى سلمة بن عياش قال قلت لرؤبة أبوك أشعر منك — قال أنا أشعر منه — هو يقول —","page":"ص0","text":"وأخبرنى سلمة بن عياش قال قلت لرؤبة أبوك أشعر منك\nقال أنا أشعر منه\nهو يقول\n(وخندف هامة هذا العالم ... )"},{"id":"tabaqat-shuara:103","bookId":"tabaqat-shuara","type":"section","seq":103,"chapter":"طبقات فحول الشعراء","title":"101- وقال العجاج —","page":"ص0","text":"وقال العجاج\n(يا ليت أيام الصبا رواجعا ... )\nوهى لغة لهم سمعت أبا عون الحرمازى يقول ليت أباك\nمنطلقا وليت زيدا قاعدا\nوأخبرنى أبو يعلى أن منشأه بلاد العجاج فأخذها عنهم"},{"id":"tabaqat-shuara:104","bookId":"tabaqat-shuara","type":"section","seq":104,"chapter":"طبقات فحول الشعراء","title":"102- وقد تغلط مقاحيم الشعراء وثنيانهم والمقحم الذى يقتحم سنا إلى أخرى ليس بالبازل ولا المستحكم —","page":"ص0","text":"وقد تغلط مقاحيم الشعراء وثنيانهم والمقحم الذى يقتحم سنا إلى أخرى ليس بالبازل ولا المستحكم\nوالثنيان العاجز الواهن قال أوس بن حجر\n(وقد رام بحرى قبل ذلك طاميا ... من الشعراء كل عود ومقحم)\nوقال أوس بن مغراء\n(ثنياننا إن أتاهم كان بدأهم ... وبدؤهم إن أتانا كان ثنيانا)\nفيغلطون فى السين والصاد والميم والنون والدال والطاء وأحرف\nيتقارب مخرجها من اللسان تشتبه عليهم\nأنشدنى أبو العطاف\n(أرمى بها مطالع النجوم ... رمى سليمان بذى غضون)\nوقال زغيب بن نسير العنبرى\n(نظرت بأعلى الصوق والباب دونه ... إلى نعم ترعى قوافي مسرد)\nالصوق السوق\nثم قال كحيل مخلط فقلت له قل معقد فيصح لك المعنى وتستقيم القوافى\nقال أجل فاستعدته فعاد إلى قوله الأول\nوقال أبو الدهماء العنبرى\n(فلا عيب فيها غير أن جنينها ... جهيض وفى العينين منها التخاوص)\nثم قال بالثياب الطيالس ثم قال والماء جامس\nوكان يقول الصويق وبر مكيول وثوب مخيوط\nوقال أبو الدهماء يهجو شويعرا من عكل وكان أبو الدهماء أفصح الناس فقال يذكر جردانه\n(ويل الحبالى إذ أصاب الركبا ... يستخرج الصبيان منه خذما)"},{"id":"tabaqat-shuara:105","bookId":"tabaqat-shuara","type":"section","seq":105,"chapter":"طبقات فحول الشعراء","title":"103- واستحسن الناس من تشبيه امرئ القيس —","page":"ج1 ص80","text":"واستحسن الناس من تشبيه امرئ القيس\n(كأن قلوب الطير رطبا ويابسا ... لدى وكرها العناب والحشف البالى)\nوقوله\n(كأنى بفتخاء الجناحين لقوة ... دفوف من العقبان طأطأت شملال)\nوقوله\n(بعجلزة قد أترز الجرى لحمها ... كميت كأنها هراوة منوال)\n(وصم حوام ما يقين من الوجى ... كأن مكان الردف منها على رال)\nوقوله\n(نظرت إليها والنجوم كأنها ... مصابيح رهبان تشب لقفال)\n(كأن الصوار إذ تجاهدن غدوة ... على جمزى خيل تجول بأجلال)\nوقوله\n(أيقتلنى والمشرفى مضاجعى ... ومسنونة زرق كأنياب أغوال)"},{"id":"tabaqat-shuara:106","bookId":"tabaqat-shuara","type":"section","seq":106,"chapter":"طبقات فحول الشعراء","title":"104- وقوله —","page":"ج1 ص82","text":"وقوله\n(كأنى غداة البين حين تحملوا ... لدى سمرات الحى ناقف حنظل)\nوقوله\n(مكر مفر مقبل مدبر معا ... كجلمود صخر حطه السيل من عل)\nوقوله\n(له أيطلا ظبى وساقا نعامة ... وإرخاء سرحان وتقريب تتفل)\nوقوله\n(درير كخذروف الوليد أدره ... تتابع كفيه بخيط موصل)\nوقوله\n(كميت يزل اللبد عن حال متنه ... كما زلت الصفواء بالمتنزل)\nوقوله\n(كأن دماء الهاديات بنحره ... عصارة حناء بشيب مرجل)\nوقوله\n(وليل كموج البحر أرخى سدوله ... على بأنواع الهموم ليبتلى)\nوقوله\n(فيالك من ليل كأن نجومه ... بأمراس كتان إلى صم جندل)\nخيروا بينه وبين قول النابغة\n(فإنك كالليل الذى هو مدركى ... وإن خلت أن المنتأى عنك واسع)\nفزعم بعض الأشياخ أن بيت النابغة أحكمها\nوقوله\n( ... ... ... ... ... ... ترائبها مصقولة كالسجنجل)\nهى المرآة بالرومية\nوقوله\n(إذا ما الثريا فى السماء تعرضت ... تعرض أثناء الوشاح المفصل)\nقال فأنكر قوم قوله إذا ما الثريا فى السماء تعرضت وقالوا الثريا لا تعرض\nوقال بعض العلماء عنى الجوزاء\nوقد تفعل العرب بعض ذلك قال زهير\n(فتنج لكم غلمان أشأم كلهم ... كأحمر عاد ثم ترضع فتفطم)\nيعنى أحمر ثمود\nوقوله\n(يظل العذارى يرتمين بلحمها ... وشحم كهداب الدمقس المفتل)"},{"id":"tabaqat-shuara:107","bookId":"tabaqat-shuara","type":"section","seq":107,"chapter":"طبقات فحول الشعراء","title":"105- وقال يصف فرسا —","page":"ج1 ص88","text":"وقال يصف فرسا\n(بذى ميعة كأن أدنى سقاطه ... وتقريبه هونا دآليل ثعلب)\n(عظيم طويل مطمئن كأنه ... بأسفل ذى مأوان سرحة مرقب)\n(له أيطلا ظبى وساقا نعامة ... وصهوة عير قائم فوق مرقب)\n(له جؤجؤ حشر كأن لجامه ... يعالى به فى رأس جذع مشذب)\n(وعينان كالماويتين ومحجر ... إلى سند مثل الرتاج المضبب)\n(إذا ما جرى شأوين وابتل عطفه ... نقول هزيز الريح مرت بأثأب)\n(كأن دماء الهاديات بنحره ... عصارة حناء بشيب مخضب)"},{"id":"tabaqat-shuara:108","bookId":"tabaqat-shuara","type":"section","seq":108,"chapter":"طبقات فحول الشعراء","title":"106- وقال أيضا —","page":"ج1 ص90","text":"وقال أيضا\n(تروح كأنها مما أصابت ... معلقة بأحقيها الدلى)\n(إذا ما قام حالبها أرنت ... كأن الحى صبحهم نعى)"},{"id":"tabaqat-shuara:109","bookId":"tabaqat-shuara","type":"section","seq":109,"chapter":"طبقات فحول الشعراء","title":"107- أخبرنى يونس بن حبيب قال قال ذو الرمة من أحسن الناس وصفا للمطر فذكروا قول عبيد —","page":"ص0","text":"أخبرنى يونس بن حبيب قال قال ذو الرمة من أحسن الناس وصفا للمطر فذكروا قول عبيد\n(دان مسف فويق الأرض هيدبه ... يكاد يدفعه من قام بالراح)\n(فمن بنجوته كمن بمحلفه ... والمستكن كمن يمشى بقرواح)\nفجعلها يونس لعبيد وعلى ذلك كان إجماعنا فلما قدم المفضل صرفها إلى أوس بن حجر\nوذكروا قول عبد بنى الحسحاس\n(نعمت به ظنا وأيقنت أنه ... يحط الوعول والصخور الرواسيا)\n(وما حركته الريح حتى ظننته ... بحرة ليلى أو بنخلة ثاويا)\n(فدر على الأنهاء أول مزنه ... فعن طويلا يسكب الماء ساحيا)\n(ركام يسح الماء عن كل فيقة ... ويغدر فى القيعان رنقا وصافيا)\n(ومر على الأجبال أجبال طيىء ... كما سقت منكوب الدوابر حافيا)\n(أجش هزيم سيله مع ودقه ... ترى خشب الغلان فيه طوافيا)\n(بكى شجوه واغتاظ حتى حسبته ... من البعد لما جلجل الوعد حاديا)\nفقال ذو الرمة بل قول امرئ القيس أجود حيث يقول\n(ديمة هطلاء فيها وطف ... طبق الأرض تحرى وتدر)\n(تخرج الود إذا ما أشجذت ... وتواريه إذا ما تشتكر)\n(وترى الضب خفيفا ماهرا ... ثانيا برثنه ما ينعفر)\n(وترى الشجراء فى ريقها ... كرءوس قطعت فيها الخمر)\n(ساعة ثم انتحاها وابل ... ساقط الأكناف واه منهمر)\n(راح تمريه الصبا ثم انتحى ... فيه شؤبوب جنوب منفجر)\n(ثج حتى ضاق عن آذيه ... عرض خيم فخفاف فيسر)\n(قد غدا يحملنى فى أنفه ... لاحق ألأيطل محبوك ممر)"},{"id":"tabaqat-shuara:110","bookId":"tabaqat-shuara","type":"section","seq":110,"chapter":"طبقات فحول الشعراء","title":"180- أوس بن حجر بن عتاب بن عبد الله بن عدى بن نمير بن أسيد بن عمرو بن تميم وهو المقدم عليهم","page":"ج1 ص96","text":"أوس بن حجر بن عتاب بن عبد الله بن عدى بن نمير بن أسيد بن عمرو بن تميم وهو المقدم عليهم"},{"id":"tabaqat-shuara:111","bookId":"tabaqat-shuara","type":"section","seq":111,"chapter":"طبقات فحول الشعراء","title":"109- وبشر بن أبى خازم الأسدى","page":"ج1 ص96","text":"وبشر بن أبى خازم الأسدى"},{"id":"tabaqat-shuara:112","bookId":"tabaqat-shuara","type":"section","seq":112,"chapter":"طبقات فحول الشعراء","title":"110- وكعب بن زهير بن أبى سلمى","page":"ج1 ص96","text":"وكعب بن زهير بن أبى سلمى"},{"id":"tabaqat-shuara:113","bookId":"tabaqat-shuara","type":"section","seq":113,"chapter":"طبقات فحول الشعراء","title":"111- والحطيئة أبو مليكة جرول بن أوس بن مالك بن جوية بن مخزوم بن مالك بن غالب بن قطيعة بن عبس بن","page":"ج1 ص96","text":"والحطيئة أبو مليكة جرول بن أوس بن مالك بن جوية بن مخزوم بن مالك بن غالب بن قطيعة بن عبس بن بغيض بن ريث بن غطفان"},{"id":"tabaqat-shuara:114","bookId":"tabaqat-shuara","type":"section","seq":114,"chapter":"طبقات فحول الشعراء","title":"112- وأوس نظير الأربعة المتقدمين إلا أنا اقتصرنا فى الطبقات على أربعة رهط","page":"ج1 ص96","text":"وأوس نظير الأربعة المتقدمين إلا أنا اقتصرنا فى الطبقات على أربعة رهط"},{"id":"tabaqat-shuara:115","bookId":"tabaqat-shuara","type":"section","seq":115,"chapter":"طبقات فحول الشعراء","title":"113- وقال يونس قال أبو عمرو بن العلاء كان أوس فحل مضر حتى نشأ النابغة وزهير فأخملاه — وكان زهير ر","page":"ج1 ص96","text":"وقال يونس قال أبو عمرو بن العلاء كان أوس فحل مضر حتى نشأ النابغة وزهير فأخملاه\nوكان زهير راويته"},{"id":"tabaqat-shuara:116","bookId":"tabaqat-shuara","type":"section","seq":116,"chapter":"طبقات فحول الشعراء","title":"114- وقال أبو على الحرمازى كان أوس زوج أم زهير","page":"ج1 ص97","text":"وقال أبو على الحرمازى كان أوس زوج أم زهير"},{"id":"tabaqat-shuara:117","bookId":"tabaqat-shuara","type":"section","seq":117,"chapter":"طبقات فحول الشعراء","title":"115- قلت لعمرو بن معاذ التيمى وكان بصيرا بالشعر من أشعر الناس قال أوس قلت ثم من قال أبو ذؤيب","page":"ج1 ص97","text":"قلت لعمرو بن معاذ التيمى وكان بصيرا بالشعر من أشعر الناس قال أوس قلت ثم من قال أبو ذؤيب"},{"id":"tabaqat-shuara:118","bookId":"tabaqat-shuara","type":"section","seq":118,"chapter":"طبقات فحول الشعراء","title":"116- قال فأوس شاعر مضر والأعشى شاعر ربيعة —","page":"ج1 ص97","text":"قال فأوس شاعر مضر والأعشى شاعر ربيعة\n... ... ... ... ... ... ... ... ... ... ... ... ... ... ... ... . ."},{"id":"tabaqat-shuara:119","bookId":"tabaqat-shuara","type":"section","seq":119,"chapter":"طبقات فحول الشعراء","title":"117-","page":"ص0","text":"... وكان أخوه بجير بن زهير أسلم وشهد مع النبى صلى الله عليه وسلم فتح مكة وحنينا فأرسل إليه كعب أبياتا ينهاه عن الإسلام وذكره للنبى صلى الله عليه وسلم فأوعده فأرسل بجير إليه ويلك إن النبى أوعدك وقد أوعد رجالا بمكة فقتلهم وهو والله قاتلك أو تأتيه فتسلم فاستطير ولفظته الأرض"},{"id":"tabaqat-shuara:120","bookId":"tabaqat-shuara","type":"section","seq":120,"chapter":"طبقات فحول الشعراء","title":"118- أنا أبو خليفة نا ابن سلام قال وأخبرنى محمد بن سليمان عن يحيى بن سعيد الأنصارى عن سعيد بن ا","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال وأخبرنى محمد بن سليمان عن يحيى بن سعيد الأنصارى عن سعيد بن المسيب قال\nقدم كعب متنكرا حين بلغه عن النبى ما بلغه فأتى أبا بكر\nفلما صلى الصبح أتى به وهو متلثم بعمامته فقال يا رسول الله رجل يبايعك على الإسلام\nوبسط يده وحسر عن وجهه وقال بأبى أنت وأمى يا رسول الله هذا مكان العائذ بك أنا كعب بن زهير\nفتجهمته الأنصار وغلظت عليه لما ذكر به رسول الله ولانت له قريش وأحبوا إسلامه وإيمانه\nفأمنه رسول الله فأنشد مدحته التى يقول فيها\n(بانت سعاد فقلبى اليوم متبول ... متيم إثرها لم يشف مكبول)\nحتى انتهى إلى قوله\n(وقال كل خليل كنت آمله ... لا ألفينك إنى عنك مشغول)\n(فقلت خلوا سبيلى لا أبالكم ... فكل ما وعد الرحمن مفعول)\n(كل ابن أنثى وإن طالت سلامته ... يوما على آلة حدباء محمول)\n(نبئت أن رسول الله أوعدنى ... والعفو عند رسول الله مأمول)\nإلى قوله\n(إن الرسول لسيف يستضاء به ... مهند من سيوف الله مسلول)\n(فى فتية من قريش قال قائلهم ... ببطن مكة لما أسلموا زولوا)\n(زالوا فما زال أنكاس ولا كشف ... يوم اللقاء ولا سود معازيل)\n(لا يقع الطعن إلا فى نحورهم ... وما بهم عن حياض الموت تهليل)\nفنظر النبى صلى الله عليه وسلم إلى من عنده من قريش أى اسمعوا حتى قال\n(يمشون مشى الجمال الزهر يعصمهم ... ضرب إذا عرد السود التنابيل)\nيعرض بالأنصار لغلظتهم كانت عليه\nفأنكرت قريش ما قال وقالوا لم تمدحنا إذ هجوتهم ولم يقبلوا ذلك حتى قال\n(من سره كرم الحياة فلا يزل ... فى مقنب من صالح الأنصار)\n(الباذلين نفوسهم لنبيهم ... يوم الهياج وسطوة الجبار)\n(يتطهرون كأنه نسك لهم ... بدماء من علقوا من الكفار)\n(صدموا عليا يوم بدر صدمة ... ذلت لوقعتها جميع نزار)\nيعنى بنى على بن مسعود وهم بنو كنانة\nفكساه النبى صلى الله عليه وسلم بردة اشتراها معاوية من آل كعب بن زهير بمال كثير قد سمي\nفهى البردة التى تلبسها الخلفاء فى العيدين\nزعم ذلك أبان"},{"id":"tabaqat-shuara:121","bookId":"tabaqat-shuara","type":"section","seq":121,"chapter":"طبقات فحول الشعراء","title":"119- وكان الحطيئة متين الشعر شرود القافية وكان راوية لزهير وآل زهير واستفرغ شعره فى بنى قريع","page":"ج1 ص103","text":"وكان الحطيئة متين الشعر شرود القافية وكان راوية لزهير وآل زهير واستفرغ شعره فى بنى قريع"},{"id":"tabaqat-shuara:122","bookId":"tabaqat-shuara","type":"section","seq":122,"chapter":"طبقات فحول الشعراء","title":"120- وقال لكعب بن زهير قد علمت روايتى شعر أهل البيت وانقطاعى وقد ذهب الفحول غيرى وغيرك فلو قلت","page":"ج1 ص103","text":"وقال لكعب بن زهير قد علمت روايتى شعر أهل البيت وانقطاعى وقد ذهب الفحول غيرى وغيرك فلو قلت شعرا تذكر فيه نفسك وتضعنى موضعا فإن الناس لأشعاركم أروى وإليها أسرع\nفقال كعب\n(فمن للقوافى شانها من يحوكها ... إذا ما ثوى كعب وفوز جرول)\n(يقول فلا يعي بشيء يقوله ... ومن قائلها من يسئ ويعمل)\n(كفيتك لا تلقى من الناس واحدا ... تنخل منها مثل ما يتنخل)\n(يثقفها حتى تلين متونها ... فيقصر عنها كل ما يتمثل)"},{"id":"tabaqat-shuara:123","bookId":"tabaqat-shuara","type":"section","seq":123,"chapter":"طبقات فحول الشعراء","title":"121- فاعترضه مزرد بن ضرار واسمه يزيد وهو أخو الشماخ وكان عريضا أى شديد العارضة كثيرها فقال —","page":"ص0","text":"فاعترضه مزرد بن ضرار واسمه يزيد وهو أخو الشماخ وكان عريضا أى شديد العارضة كثيرها فقال\n(وباستك إذ خلفتنى خلف شاعر ... من الناس لم أكفئ ولم أتنحل)\n(فأن تجشبا أجشب وإن تتنخلا ... وإن كنت أفتى منكما أتنخل)\n(ولست كحسان الحسام بن ثابت ... ولست كشماخ ولا كالمخبل)\n(وأنت امرؤ من أهل قدس أوارة ... أحلتك عبد الله أكناف مبهل)\nمبهل جبل لعبد الله بن غطفان\nوقدس أوارة جبل لمزينة\nفعزاه إلى مزينة"},{"id":"tabaqat-shuara:124","bookId":"tabaqat-shuara","type":"section","seq":124,"chapter":"طبقات فحول الشعراء","title":"122- وكان أبو سلمى وأهل بيته فى بنى عبد الله بن غطفان فبهم يعرفون وإليهم ينسبون فقال كعب بن زهي","page":"ص0","text":"وكان أبو سلمى وأهل بيته فى بنى عبد الله بن غطفان فبهم يعرفون وإليهم ينسبون فقال كعب بن زهير يثبت أنه من مزينة\n(ألا أبلغا هذا المعرض آية ... أيقظان قال القول إذ قال أو حلم)\nيقال حلم فى المنام وحلم من الحلم إلى قوله\n(أعيرتنى عزا عزيزا ومعشرا ... كراما بنوا لى المجد فى باذخ أشم)\n(هم الأصل منى حيث كنت وإننى ... من المزنين المصفين بالكرم)\nوقد كانت العرب تفعل ذلك لا يعزى الرجل إلى قبيلة غير التى هو منها إلا قال أنا من الذين عبت"},{"id":"tabaqat-shuara:125","bookId":"tabaqat-shuara","type":"section","seq":125,"chapter":"طبقات فحول الشعراء","title":"123- كان أبو ضمرة يزيد بن سنان بن أبى حارثة لاحى النابغة فنماه إلى قضاعة فقال النابغة —","page":"ص0","text":"كان أبو ضمرة يزيد بن سنان بن أبى حارثة لاحى النابغة فنماه إلى قضاعة فقال النابغة\n(جمع محاشك يا يزيد فإننى ... أعددت يربوعا لكم وتميما)\n(ولحقت بالنسب الذى عيرتنى ... ووجدت نصرك يا يزيد ذميما)\n(حدبت على بطون ضنة كلها ... إن ظالما فيهم وإن مظلوما)\n(لولا بنو نهد بن عوف أصبحت ... بالنعف أمك يا يزيد عقيما)\nضنه بن كبير بن عذرة"},{"id":"tabaqat-shuara:126","bookId":"tabaqat-shuara","type":"section","seq":126,"chapter":"طبقات فحول الشعراء","title":"124- وكان رهط الزبرقان بن بدر يخلجون إلى بنى كعب بن يشكر إلى ذى المجاسد عامر بن جشم بن كعب فقال","page":"ج1 ص108","text":"وكان رهط الزبرقان بن بدر يخلجون إلى بنى كعب بن يشكر إلى ذى المجاسد عامر بن جشم بن كعب فقال الزبرقان\n(فإن أك من كعب بن سعد فإننى ... رضيت بهم من حى صدق ووالد)\n(وإن يك من كعب بن يشكر منصبى ... فإن أبانا عامر ذو المجاسد)"},{"id":"tabaqat-shuara:127","bookId":"tabaqat-shuara","type":"section","seq":127,"chapter":"طبقات فحول الشعراء","title":"125- قال ابن سلام ولقد أخبرنى بعض أهل العلم من غطفان أنهم من بنى عبد الله بن غطفان وأن اعتزاءه","page":"ج1 ص108","text":"قال ابن سلام ولقد أخبرنى بعض أهل العلم من غطفان أنهم من بنى عبد الله بن غطفان وأن اعتزاءه إلى مزينة كقول هؤلاء\nوأما العامة فهو عندهم مزنى وليس لزهير ولا لبنيه صليبة شعر يعتزون فيه إلى غطفان ولا مزينة إلا بيت كعب ذاك وقول بجير\n(صبحناهم بسبع من سليم ... وألف من بنى عثمان واف)\nوقد يجوز أن يكون يعنى غير قومه من المزنيين فذكرهم كما ذكر سليما"},{"id":"tabaqat-shuara:128","bookId":"tabaqat-shuara","type":"section","seq":128,"chapter":"طبقات فحول الشعراء","title":"126- ولم يزل فى ولد زهير شعر — ولم يتصل فى ولد أحد من فحول الجاهلية ما اتصل فى ولد زهير ولا فى ول","page":"ص0","text":"ولم يزل فى ولد زهير شعر\nولم يتصل فى ولد أحد من فحول الجاهلية ما اتصل فى ولد زهير ولا فى ولد أحد من الإسلاميين ما اتصل فى ولد جرير"},{"id":"tabaqat-shuara:129","bookId":"tabaqat-shuara","type":"section","seq":129,"chapter":"طبقات فحول الشعراء","title":"127- وكان الحطيئة قد عمر دهرا فى الجاهلية وبقى فى الإسلام — حينا وكان جشعا سؤولا","page":"ص0","text":"وكان الحطيئة قد عمر دهرا فى الجاهلية وبقى فى الإسلام\nحينا وكان جشعا سؤولا"},{"id":"tabaqat-shuara:130","bookId":"tabaqat-shuara","type":"section","seq":130,"chapter":"طبقات فحول الشعراء","title":"128- وكان مع علقمة بن علاثة حين نافر عامر بن الطفيل فقال يفضل علقمة —","page":"ص0","text":"وكان مع علقمة بن علاثة حين نافر عامر بن الطفيل فقال يفضل علقمة\n(يا عام قد كنت ذا باع ومكرمة ... لو أن مسعاة من جاريته أمم)\n(جاريت فرعا أجاد الأحوصان به ... ضخم الدسيعة فى عرنينه شمم)\n(لا يصعب الأمر إلا ريث يركبه ... ولا يبيت على مال له قسم)\nوكان الأعشى مع عامر بن الطفيل ولبيد بن ربيعة"},{"id":"tabaqat-shuara:131","bookId":"tabaqat-shuara","type":"section","seq":131,"chapter":"طبقات فحول الشعراء","title":"129- وشهد الحطيئة نفار عيينة بن حصن بن حذيفة بن بدر أحد بنى عدى بن فزارة وزبان بن سيار بن عمرو","page":"ص0","text":"وشهد الحطيئة نفار عيينة بن حصن بن حذيفة بن بدر أحد بنى عدى بن فزارة وزبان بن سيار بن عمرو بن جابر أحد بنى مازن بن فزاره فقال يفضل عيينه على زبان\n(أبى لك آباء أبى لك مجدهم ... سوى المجد فانظر صاغرا من قنافره)\n(قبور أصابتها السيوف ثلاثة ... نجوم هوت فى كل نجم مرائره)\n(فقبر بأجبال وقبر بحاجر ... وقبر القليب أسعر الحرب ساعره)\n(وشر المنايا هالك وسط أهله ... كهلك الفتاة أيقظ الحى حاضره)\nقبر بأجبال يريد قبر بدر بن عمرو قتيل بنى أسد بن خزيمة\nوقبر القليب وهو الهباءة قبر حذيفة بن بدر بن عمرو قتيل بني عبس\nوقبر بحاجر يعنى قبر حصن بن حذيفة بن بدر قتيل بنى عقيل بن كعب ونمير بن عامر"},{"id":"tabaqat-shuara:132","bookId":"tabaqat-shuara","type":"section","seq":132,"chapter":"طبقات فحول الشعراء","title":"130- قال كان الحطيئة سؤولا جشعا فقدم المدينة وقد أرصدت له قريش العطايا والناس فى سنة مجدبة وسخط","page":"ص0","text":"قال كان الحطيئة سؤولا جشعا فقدم المدينة وقد أرصدت له قريش العطايا والناس فى سنة مجدبة وسخطة من خليفة\nفمشى أشراف أهل المدينة بعضهم إلى بعض فقالوا قد قدم علينا هذا الرجل وهو شاعر والشاعر يظن فيحقق وهو يأتى الرجل من أشرافكم يسأله فإن أعطاه جهد نفسه بهرها وإن حرمه هجاه\nفأجمع رأيهم على أن يجعلوا له شيئا معدا يجمعونه بينهم له فكان أهل البيت من قريش والأنصار يجمعون له العشرة والعشرين والثلاثين دينارا حتى جمعوا له أربعمئة دينار وظنوا أنهم قد أغنوه فأتوه فقالوا له هذه صلة آل فلان وهذه صلة آل فلان\nفأخذها\nفظنوا أنهم قد كفوه عن المسئلة فإذا هو يوم الجمعة قد استقبل الإمام ماثلا ينادى بعد الصلاة فقال من يحملنى على نعلين وقاه الله كبة جهنم"},{"id":"tabaqat-shuara:133","bookId":"tabaqat-shuara","type":"section","seq":133,"chapter":"طبقات فحول الشعراء","title":"131- أنا أبو خليفة نا ابن سلام قال وأخبرنى يونس النحوى قال خرج الحطيئة مع ابنته مليكة وامرأته أ","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال وأخبرنى يونس النحوى قال خرج الحطيئة مع ابنته مليكة وامرأته أمامة على ذود له ثلاث فنزل منزلا وسرح ذوده\nفلما قام للرواح فقد إحداهن فقال\n(أذئب القفر أم ذئب أنيس ... أصاب البكر أم حدث الليالي)\n(ونحن ثلاثة وثلاث ذود ... لقد جار الزمان على عيالي)"},{"id":"tabaqat-shuara:134","bookId":"tabaqat-shuara","type":"section","seq":134,"chapter":"طبقات فحول الشعراء","title":"132- وكان سبب هجائه الزبرقان أنه صادفه بالمدينة وكان قدمها على عمر رضى الله عنه فقال الحطيئة ود","page":"ص0","text":"وكان سبب هجائه الزبرقان أنه صادفه بالمدينة وكان قدمها على عمر رضى الله عنه فقال الحطيئة وددت أنى أصبت رجلا\nيحملنى وأصفيه مديحي وأقتصر عليه\nقال الزبرقان قد أصبته تقدم على أهلى فإنى على إثرك\nفقدم فنزل بحراه وأرسل الزبرقان إلى امرأته أن أكرمى مثواه\nوكانت ابنته مليكة جميلة فكرهت امرأته مكانها فظهرت لهم منها جفوة وبغيض بن عامر بن لأى بن شماس أحد بنى قريع بن عوف ينازع يومئذ الزبرقان الشرف والزبرقان أحد بنى بهدلة بن عوف وبغيض أرسخ فى الشرف من الزبرقان وقد ناوأه الزبرقان ببدنه حتى ساواه بل اعتلاه فاغتنم بغيض وأخواه علقمة وهوذة ما فيه الحطيئة من الجفوة فدعواه إلى ما عندهما فأسرع\nفبنوا عليه قبة ونحروا له وأكرموه كل الإكرام وشدوا بكل طنب من أطناب خبائه جلة من برنى هجر قال والمخبل شاعر مفلق وهو ابن عمهم\nيلقاهم إلى أنف الناقة وهو جعفر بن قريع\nقال وقدم الزبرقان أسيفا عاتبا على امرأته فمدح بنى قريع وذم الزبرقان فاستعدى عليه الزبرقان عمر فأقدمه عمر وقال للزبرقان ما قال لك فقال قال لى\n(دع المكارم لا ترحل لبغيتها ... واقعد فإنك أنت الطاعم الكاسى)\nفقال عمر لحسان ما تقول أهجاه وعمر يعلم من ذلك ما يعلم حسان ولكنه أراد الحجة على الحطيئة قال ذرق عليه فألقاه عمر فى حفرة اتخذها محبسا فقال الحطيئة\n(ماذا تقول لأفراخ بذى مرخ ... حمر الحواصل لا ماء ولا شجر)\n(ألقيت كاسبهم فى قعر مظلمة ... فاغفر عليك سلام الله يا عمر)\n(أنت الإمام الذى من بعد صاحبه ... ألقى إليك مقاليد النهى البشر)\n(ما آثروك بها إذ بايعوك لها ... لكن لأنفسهم كانت بك الإثر)"},{"id":"tabaqat-shuara:135","bookId":"tabaqat-shuara","type":"section","seq":135,"chapter":"طبقات فحول الشعراء","title":"133- وكان الزبرقان شاعرا مفلقا وكان يعاتبهم ولم يكن يهجوهم وكان حليما — وكانا فى عداوتهما مجملين","page":"ج1 ص116","text":"وكان الزبرقان شاعرا مفلقا وكان يعاتبهم ولم يكن يهجوهم وكان حليما\nوكانا فى عداوتهما مجملين وقد تقدم عليه المخبل بالهجاء فقال\n(لعمرك إن الزبرقان لدائب ... على الناس يعدو نوكه ومجاهله)\n(ولما رأيت العز فى دار أهله ... تمنيت بعد الشيب أنك ناقلة)\n(ولما نر الأخفاف تمشى على الذرى ... ولما يكن أعلى العضاه أسافله)\n(ولما يزل عن رأس صهوة عصمها ... ولما يدع ورد العراق مناهله)\n(وينفس فى ما أورثتنى أوائلى ... ويرغب عما أورثته أوائله)\n(فإن كنت لا تمسى بحظك راضيا ... فدع عنك حظى إننى اليوم شاغله)\nأتيت امرءا أحمى على الناس عرضه ... فمازلت حتى أنت مقع تناضله)\n(فأقع كما أقعى أبوك على استه ... رأى أن ريما فوقه لا يعادله)"},{"id":"tabaqat-shuara:136","bookId":"tabaqat-shuara","type":"section","seq":136,"chapter":"طبقات فحول الشعراء","title":"134- ومدح سعيد بن العاص وكان سعيد لا تأخذه العين كان يقال له عكه العسل فقال —","page":"ج1 ص118","text":"ومدح سعيد بن العاص وكان سعيد لا تأخذه العين كان يقال له عكه العسل فقال\n(خفيف المعى لا يملأ الهم صدره ... إذا سمته الزاد الخبيث عيوف)"},{"id":"tabaqat-shuara:137","bookId":"tabaqat-shuara","type":"section","seq":137,"chapter":"طبقات فحول الشعراء","title":"135- وقال له أيضا —","page":"ج1 ص118","text":"وقال له أيضا\n(سعيد فلا يغررك خفة لحمه ... تخدد عنه اللحم وهو صليب)\nوهو أحد من اتصل به الشرف من خمسة آباء وابنه عمرو ابن سعيد"},{"id":"tabaqat-shuara:138","bookId":"tabaqat-shuara","type":"section","seq":138,"chapter":"طبقات فحول الشعراء","title":"136- أخبرنى الفضل بن الحباب الجمحى أبو خليفة فى كتابه إلى بإجازته لى يذكر عن محمد بن سلام أن ال","page":"ص0","text":"أخبرنى الفضل بن الحباب الجمحى أبو خليفة فى كتابه إلى بإجازته لى يذكر عن محمد بن سلام أن الحطيئة كان ينتمى إلى بنى ذهل بن ثعلبة فقال\n(إن اليمامة خير ساكنها ... أهل القرية من بنى ذهل)\nقال والقرية منازلهم ولم ينبت الحطيئة فى هؤلاء"},{"id":"tabaqat-shuara:139","bookId":"tabaqat-shuara","type":"section","seq":139,"chapter":"طبقات فحول الشعراء","title":"137- قال محمد بن سلام فى كتاب طبقات الشعراء دخل الحطيئة على سعيد بن العاص متنكرا فلما قام الناس","page":"ص0","text":"قال محمد بن سلام فى كتاب طبقات الشعراء دخل الحطيئة على سعيد بن العاص متنكرا فلما قام الناس وبقى الخواص أراد\nالحاجب أن يقيمه فأبى أن يقوم فقال سعيد دعه\nوتذاكروا أيام العرب وأشعارها فلما أسهبوا قال الحطيئة ما صنعتم شيئا\nفقال سعيد فهل عندك علم من ذلك قال نعم\nقال فمن أشعر العرب قال الذى يقول\n(قد جعل المبتغون الخير فى هرم ... والسائلون إلى أبوابه طرقا)\nقال ثم من قال الذى يقول\n(فإنك شمس والملوك كواكب ... إذا طلعت لم يبد منهن كوكب)\nيعنى زهيرا والنابغة ثم قال وحسبك بى إذا وضعت إحدى رجلى على الأخرى ثم عويت فى إثر القوافى كما يعوى الفصيل فى إثر أمه قال فمن أنت قال أنا الحطيئة\nفرحب به سعيد وأمر له بألف دينار"},{"id":"tabaqat-shuara:140","bookId":"tabaqat-shuara","type":"section","seq":140,"chapter":"طبقات فحول الشعراء","title":"138- أبو ليلى نابغة بنى جعدة وهو قيس بن عبد الله بن عدس بن ربيعة بن جعدة بن كعب بن ربيعة بن عام","page":"ج1 ص121","text":"أبو ليلى نابغة بنى جعدة وهو قيس بن عبد الله بن عدس بن ربيعة بن جعدة بن كعب بن ربيعة بن عامر بن صعصعة"},{"id":"tabaqat-shuara:141","bookId":"tabaqat-shuara","type":"section","seq":141,"chapter":"طبقات فحول الشعراء","title":"139- وأبو ذؤيب الهذلى وهو خويلد بن خالد بن محرث بن زبيد بن مخزوم بن صاهلة بن كاهل بن الحارث بن","page":"ج1 ص121","text":"وأبو ذؤيب الهذلى وهو خويلد بن خالد بن محرث بن زبيد بن مخزوم بن صاهلة بن كاهل بن الحارث بن تميم بن سعد ابن هذيل"},{"id":"tabaqat-shuara:142","bookId":"tabaqat-shuara","type":"section","seq":142,"chapter":"طبقات فحول الشعراء","title":"140- والشماخ بن ضرار بن سنان بن أمامة أحد بنى سعد ابن ذيبان","page":"ج1 ص121","text":"والشماخ بن ضرار بن سنان بن أمامة أحد بنى سعد ابن ذيبان"},{"id":"tabaqat-shuara:143","bookId":"tabaqat-shuara","type":"section","seq":143,"chapter":"طبقات فحول الشعراء","title":"141- ولبيد بن ربيعة بن مالك بن جعفر بن كلاب بن ربيعة ابن عامر","page":"ج1 ص121","text":"ولبيد بن ربيعة بن مالك بن جعفر بن كلاب بن ربيعة ابن عامر"},{"id":"tabaqat-shuara:144","bookId":"tabaqat-shuara","type":"section","seq":144,"chapter":"طبقات فحول الشعراء","title":"142- وكان النابغة قديما شاعرا مفلقا طويل البقاء فى الجاهلية والإسلام وكان أكبر من النابغة الذبي","page":"ج1 ص121","text":"وكان النابغة قديما شاعرا مفلقا طويل البقاء فى الجاهلية والإسلام وكان أكبر من النابغة الذبيانى ويدل على ذلك قوله\n(فمن يك سائلا عنى فإنى ... من الفتيان أيام الخنان)\n(أتت مئة لعام ولدت فيه ... وعشر بعد ذاك وحجتان)\n(وقد أبقت خطوب الدهر منى ... كما تبقى من السيف اليمانى)\n(تفلل وهو مأثور جراز ... إذا اجتمعت بقائمه اليدان)\nوقوله\n(نداماى عند المنذر بن محرق ... فأصبح منهم ظاهر الأرض مقفرا)\nوكان الذبيانى مع النعمان وفى عصره ولم يكن له قدم"},{"id":"tabaqat-shuara:145","bookId":"tabaqat-shuara","type":"section","seq":145,"chapter":"طبقات فحول الشعراء","title":"143- وكان الجعدى مختلف الشعر مغلبا فقال الفرزدق مثله — مثل صاحب الخلقان ترى عنده ثوب عصب وثوب خز","page":"ص0","text":"وكان الجعدى مختلف الشعر مغلبا فقال الفرزدق مثله\nمثل صاحب الخلقان ترى عنده ثوب عصب وثوب خز وإلى جنبه سمل كساء\nوكان الأصمعى يمدحه بهذا وينسبه إلى قلة التكلف فيقول عنده خمار بواف ومطرف بآلاف\nبواف يعنى بدرهم وثلث\nوإذا قالت العرب مغلب فهو مغلوب\nوإذا قالوا غلب فهو غالب"},{"id":"tabaqat-shuara:146","bookId":"tabaqat-shuara","type":"section","seq":146,"chapter":"طبقات فحول الشعراء","title":"144- وغلبت عليه ليلى الأخيلية وأوس بن مغراء القريعى ولم يكن إليه ولا قريبا منه — وغلب عليه عقال ب","page":"ص0","text":"وغلبت عليه ليلى الأخيلية وأوس بن مغراء القريعى ولم يكن إليه ولا قريبا منه\nوغلب عليه عقال بن خالد العقيلى وكان مفحما بكلام لا بشعر"},{"id":"tabaqat-shuara:147","bookId":"tabaqat-shuara","type":"section","seq":147,"chapter":"طبقات فحول الشعراء","title":"145- وهجاه سوار بن أوفى القشيرى وفاخره وهجاه الأخطل بأخرة","page":"ص0","text":"وهجاه سوار بن أوفى القشيرى وفاخره وهجاه الأخطل بأخرة"},{"id":"tabaqat-shuara:148","bookId":"tabaqat-shuara","type":"section","seq":148,"chapter":"طبقات فحول الشعراء","title":"146- حدثنى إبراهيم بن شهاب قال حدثنا الفضل بن الحباب قال حدثنى أبو الغراف قال قال النابغة الجعد","page":"ص0","text":"حدثنى إبراهيم بن شهاب قال حدثنا الفضل بن الحباب قال حدثنى أبو الغراف قال قال النابغة الجعدى إنى وأوس بن مغراء لنبتدر بيتا ما قلناه بعد لو قاله أحدنا لقد غلب على صاحبه\nقال ابن\nسلام وكانا يتهاجيان ولم يكن أوس إلى النابغة فى قريحة الشعر وكان النابغة فوقه فقال أوس بن مغراء\n(فلست بعاف عن شتيمة عامر ... ولا حابسى عما أقول وعيدها)\n(ترى اللؤم ما عاشوا جديدا عليهم ... وأبقى ثياب اللابسين جديدها)\n(لعمرك ما تبلى سرابيل عامر ... من اللؤم ما دامت عليها جلودها)\nفقال النابغة هذا البيت الذى كنا نبتدر وغلب الناس أوسا عليه"},{"id":"tabaqat-shuara:149","bookId":"tabaqat-shuara","type":"section","seq":149,"chapter":"طبقات فحول الشعراء","title":"147- نا ابن سلام قال قلت ليونس كيف تقرأ {وجئتك من سبإ بنبإ يقين} فقال قال الجعدى وهو أفصح العرب","page":"ص0","text":"نا ابن سلام قال قلت ليونس كيف تقرأ {وجئتك من سبإ بنبإ يقين} فقال قال الجعدى وهو أفصح العرب\n(من سبأ الحاضرين مأرب إذ ... يبنون من دون سيله العرما)\nوهو على قراءة أبى عمرو ويونس فجعل يونس القصيدة\nللجعدى\nوسمعت أبا الورد الكلابى سأل عنها أبا عبيدة فقال لأمية ثم أتينا خلفا الأحمر فسألناه فقال للنابغة وقد يقال لأمية"},{"id":"tabaqat-shuara:150","bookId":"tabaqat-shuara","type":"section","seq":150,"chapter":"طبقات فحول الشعراء","title":"148- نا ابن سلام قال ذكر مسلمة بن محارب عن أبيه قال دخل النابغة على عثمان بن عفان فقال أستودعك","page":"ص0","text":"نا ابن سلام قال ذكر مسلمة بن محارب عن أبيه قال دخل النابغة على عثمان بن عفان فقال أستودعك الله يا أمير المؤمنين وأقرأ عليك السلام\nقال لمه قال أنكرت نفسى فأردت أن أخرج إلى إبلى فأشرب من ألبانها وأشم من شيح البادية\nوذكر بلده\nفقال يا أبا ليلى أما علمت أن التعرب بعد الهجرة لا يصلح قال لا والله ما علمت وما كنت لأخرج حتى أستأذنك\nفأذن له وضرب له أجلا\nفخرج من عنده فدخل على الحسن بن على فودعه فقال له الحسن أنشدنا من بعض شعرك\nفانشده\n(الحمد لله لا شريك له ... من لم يقلها فنفسه ظلما)\nفقال له يا أبا ليلى ما كنا نروى هذه الأبيات إلا لأمية بن أبى الصلت قال يا بن رسول الله والله إنى لأول الناس قالها وإن السروق من سرق أمية شعره"},{"id":"tabaqat-shuara:151","bookId":"tabaqat-shuara","type":"section","seq":151,"chapter":"طبقات فحول الشعراء","title":"149- وقال يونس كان الجعدى أوصف الناس لفرس أنشدت قوله رؤبة —","page":"ص0","text":"وقال يونس كان الجعدى أوصف الناس لفرس أنشدت قوله رؤبة\n(فإن صدقوا قالوا جواد مجرب ... ضليع ومن خير الجياد ضليعها)\nقال رؤبة ما كنت أرى المرهف منها إلا أسرع\nولم يكن رؤبة والعجاج صاحبى خيل ولكن كانا صاحبى إبل ونعتها"},{"id":"tabaqat-shuara:152","bookId":"tabaqat-shuara","type":"section","seq":152,"chapter":"طبقات فحول الشعراء","title":"150- نا ابن سلام قال أخبرنى ابن دأب قال تزوج النابغة امرأة من بنى المجنون وهم عدد بنى جعدة وشرف","page":"ص0","text":"نا ابن سلام قال أخبرنى ابن دأب قال تزوج النابغة امرأة من بنى المجنون وهم عدد بنى جعدة وشرفهم فنازعته وادعت الطلاق فكان يراها فى منامه فقال\n(مالى وما لابنة المجنون تطرقنى ... بالليل إن نهارى منك يكفينى)\n(لا أجذع البو بو الزعم أرأمه ... ولا أقيم بدار العجز والهون)\n(وشر حشو خباء أنت مولجه ... مجنونة هنباء بنت مجنون)\n(تستخنث الوطب لم تنقض مريرته ... وتأكل الحب صرفا غير مطحون)"},{"id":"tabaqat-shuara:153","bookId":"tabaqat-shuara","type":"section","seq":153,"chapter":"طبقات فحول الشعراء","title":"151- قال ابن دأب وكان النابغة علوى الرأى وأخذ مروان — ابنه وإبله بالمدينة فخرج ومدح مروان بن الحك","page":"ص0","text":"قال ابن دأب وكان النابغة علوى الرأى وأخذ مروان\nابنه وإبله بالمدينة فخرج ومدح مروان بن الحكم بأبيات\nقال ابن سلام وأنا منها فى شك ولكنه قال مالا أشك فيه\n(فمن راكب يأتى ابن هند بحاجتى ... ومروان والأنباء تنمى وتجلب)\n(ويخبر عنى ما أقول ابن عامر ... فنعم الفتى يأوى إليه المعصب)\n(فإن تأخذوا مالى وأهلى بظنة ... فإنى لحراب الرجال محرب)\n(صبور على ما يكره المرء كله ... سوى الظلم إنى إن ظلمت سأغضب)\n(أصيب ابن عفان الإمام فلم يكن ... لذى حسب بعد ابن عفان مغضب)"},{"id":"tabaqat-shuara:154","bookId":"tabaqat-shuara","type":"section","seq":154,"chapter":"طبقات فحول الشعراء","title":"152- وكان أبو ذؤيب شاعرا فحلا لا غميزة فيه ولا وهن","page":"ج1 ص130","text":"وكان أبو ذؤيب شاعرا فحلا لا غميزة فيه ولا وهن"},{"id":"tabaqat-shuara:155","bookId":"tabaqat-shuara","type":"section","seq":155,"chapter":"طبقات فحول الشعراء","title":"153- قال أبو عمرو بن العلاء سئل حسان من أشعر الناس قال حيا أو رجلا قال حيا — قال أشعر الناس حيا ه","page":"ج1 ص130","text":"قال أبو عمرو بن العلاء سئل حسان من أشعر الناس قال حيا أو رجلا قال حيا\nقال أشعر الناس حيا هذيل وأشعر هذيل غير مدافع أبو ذؤيب\nقال ابن سلام هذا ليس من قول أبى عمرو ونحن نقوله"},{"id":"tabaqat-shuara:156","bookId":"tabaqat-shuara","type":"section","seq":156,"chapter":"طبقات فحول الشعراء","title":"154- أخبرنى أبو خليفة قال حدثنا محمد بن سلام قال أخبرنى — عمرو بن معاذ المعمرى قال فى التوراة أبو","page":"ج1 ص130","text":"أخبرنى أبو خليفة قال حدثنا محمد بن سلام قال أخبرنى\nعمرو بن معاذ المعمرى قال فى التوراة أبو ذؤيب مؤلف زورا\nوكان اسم لشاعر بالسريانية مؤلف زورا\nفأخبرت بذلك بعض أصحاب العربية وهو كثير بن اسحق فأعجب منه وقال قد بلغنى ذاك وكان فصيحا كثير الغريب متمكنا فى الشعر"},{"id":"tabaqat-shuara:157","bookId":"tabaqat-shuara","type":"section","seq":157,"chapter":"طبقات فحول الشعراء","title":"155- فأما الشماخ فكان شديد متون الشعر أشد أسر كلام من لبيد وفيه كزازة ولبيد أسهل منه منطقا","page":"ص0","text":"فأما الشماخ فكان شديد متون الشعر أشد أسر كلام من لبيد وفيه كزازة ولبيد أسهل منه منطقا"},{"id":"tabaqat-shuara:158","bookId":"tabaqat-shuara","type":"section","seq":158,"chapter":"طبقات فحول الشعراء","title":"156- وكان للشماخ أخوان وهو أفحلهم مزرد وهو — أشبههما به وله أشعار وشهرة وجزء وهو الذى يقول يرثى ع","page":"ص0","text":"وكان للشماخ أخوان وهو أفحلهم مزرد وهو\nأشبههما به وله أشعار وشهرة وجزء وهو الذى يقول يرثى عمر بن الخطاب\n(جزى الله خيرا من أمير وباركت ... يد الله فى ذاك الأديم الممزق)\n(فمن يسع أو يركب جناحى نعامة ... ليدرك ما حاولت بالأمس يسبق)\n(قضيت أمورا ثم غادرت بعدها ... بوائق فى أكمامها لم تفتق)\n(وما كنت أخشى أن تكون وفاته ... بكفى سبنتى أزرق العين مطرق)"},{"id":"tabaqat-shuara:159","bookId":"tabaqat-shuara","type":"section","seq":159,"chapter":"طبقات فحول الشعراء","title":"157- أنا ابن سلام قال أخبرنى شعيب بن صخر قال كانت عند الشماخ امرأة من بنى سليم إحدى بنى حرام بن","page":"ج1 ص133","text":"أنا ابن سلام قال أخبرنى شعيب بن صخر قال كانت عند الشماخ امرأة من بنى سليم إحدى بنى حرام بن سمال فنازعته وادعت عليه طلاقا وحضر معها قومها فأعانوها واختصموا إلى كثير بن الصلت وكان عثمان أقعده للنظر بين الناس وهو رجل من كندة عداده فى بنى جمح ثم تحولوا إلى بنى العباس فهم فيهم اليوم فرأى كثير عليه يمينا فالتوى الشماخ باليمين يحرضهم عليها ثم حلف\nوقال\n(أتتنى سليم قضها وقضيضها ... تمسح حولي بالبقيع سبالها)\n(يقولون لى يا احلف ولست بحالف ... أخاتلهم عنها لكيما أنالها)\n(ففرجت هم النفس عنى بحلفة ... كما شقت الشقراء عنها جلالها)"},{"id":"tabaqat-shuara:160","bookId":"tabaqat-shuara","type":"section","seq":160,"chapter":"طبقات فحول الشعراء","title":"158- وكان لبيد بن ربيعة أبو عقيل فارسا شاعرا شجاعا وكان عذب المنطق رقيق حواشى الكلام وكان مسلما","page":"ص0","text":"وكان لبيد بن ربيعة أبو عقيل فارسا شاعرا شجاعا وكان عذب المنطق رقيق حواشى الكلام وكان مسلما رجل صدق"},{"id":"tabaqat-shuara:161","bookId":"tabaqat-shuara","type":"section","seq":161,"chapter":"طبقات فحول الشعراء","title":"159- قال وكتب عمر إلى عاملة أن سل لبيدا والأغلب ما أحدثا من الشعر فى الإسلام فقال الأغلب —","page":"ص0","text":"قال وكتب عمر إلى عاملة أن سل لبيدا والأغلب ما أحدثا من الشعر فى الإسلام فقال الأغلب\n(أرجزا سألت أم قصيدا ... فقد سألت هينا موجودا)\nوقال لبيد قد أبدلنى الله بالشعر سورة البقرة وآل عمران\nفزاد\nعمر فى عطائه فبلغ به ألفين\nفلما ولى معاوية قال يا أبا عقيل عطائى وعطاؤك سواء لا أرانى إلا سأحطك قال أو تدعنى قليلا ثم تضم عطائى إلى عطائك فتأخذه أجمع"},{"id":"tabaqat-shuara:162","bookId":"tabaqat-shuara","type":"section","seq":162,"chapter":"طبقات فحول الشعراء","title":"160- قال وعمر عمرا طويلا — وكان فى الجاهلية خير شاعر لقومه يمدحهم ويرثيهم ويعد أيامهم ووقائعهم وف","page":"ص0","text":"قال وعمر عمرا طويلا\nوكان فى الجاهلية خير شاعر لقومه يمدحهم ويرثيهم ويعد أيامهم ووقائعهم وفرسانهم\nوكان يطعم ما هبت الصبا وكان المغيرة بن شعبة إذا هبت الصبا قال أعينوا أبا عقيل على مروءته"},{"id":"tabaqat-shuara:163","bookId":"tabaqat-shuara","type":"section","seq":163,"chapter":"طبقات فحول الشعراء","title":"161- وهم أربعة رهط فحول شعراء موضعهم مع الأوائل وإنما أخل بهم قلة شعرهم بأيدى الرواة","page":"ص0","text":"وهم أربعة رهط فحول شعراء موضعهم مع الأوائل وإنما أخل بهم قلة شعرهم بأيدى الرواة"},{"id":"tabaqat-shuara:164","bookId":"tabaqat-shuara","type":"section","seq":164,"chapter":"طبقات فحول الشعراء","title":"162- طرفة بن العبد بن سفيان بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبه","page":"ص0","text":"طرفة بن العبد بن سفيان بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبه"},{"id":"tabaqat-shuara:165","bookId":"tabaqat-shuara","type":"section","seq":165,"chapter":"طبقات فحول الشعراء","title":"163- وعبيد بن الأبرص بن جشم بن عامر أحد بنى دودان بن أسد بن خزيمة","page":"ص0","text":"وعبيد بن الأبرص بن جشم بن عامر أحد بنى دودان بن أسد بن خزيمة"},{"id":"tabaqat-shuara:166","bookId":"tabaqat-shuara","type":"section","seq":166,"chapter":"طبقات فحول الشعراء","title":"164- وعلقمة بن عبدة بن ناشرة بن قيس بن عبيد بن ربيعة بن مالك بن زيد مناة بن تميم","page":"ص0","text":"وعلقمة بن عبدة بن ناشرة بن قيس بن عبيد بن ربيعة بن مالك بن زيد مناة بن تميم"},{"id":"tabaqat-shuara:167","bookId":"tabaqat-shuara","type":"section","seq":167,"chapter":"طبقات فحول الشعراء","title":"165- وعدى بن زيد بن حمار بن زيد بن أيوب أحد بنى امرئ القيس بن زيد مناة بن تميم","page":"ص0","text":"وعدى بن زيد بن حمار بن زيد بن أيوب أحد بنى امرئ القيس بن زيد مناة بن تميم"},{"id":"tabaqat-shuara:168","bookId":"tabaqat-shuara","type":"section","seq":168,"chapter":"طبقات فحول الشعراء","title":"166- فأما طرفة فأشعر الناس واحدة وهى قوله —","page":"ص0","text":"فأما طرفة فأشعر الناس واحدة وهى قوله\n(لخولة أطلال ببرقة ثهمد ... وقفت بها أبكى وأبكى إلى الغد)\nوتليها أخرى مثلها وهى\n(أصحوت اليوم أم شاقتك هر ... ومن الحب جنون مستقر)\nومن بعد له قصائد حسان جياد"},{"id":"tabaqat-shuara:169","bookId":"tabaqat-shuara","type":"section","seq":169,"chapter":"طبقات فحول الشعراء","title":"167- وعبيد بن الأبرص قديم عظيم الذكر عظيم الشهرة وشعره مضطرب ذاهب لا أعرف له إلا قوله —","page":"ص0","text":"وعبيد بن الأبرص قديم عظيم الذكر عظيم الشهرة وشعره مضطرب ذاهب لا أعرف له إلا قوله\n(أقفر من أهله ملحوب ... فالقطبيات فالذنوب)\nولا أدرى ما بعد ذلك"},{"id":"tabaqat-shuara:170","bookId":"tabaqat-shuara","type":"section","seq":170,"chapter":"طبقات فحول الشعراء","title":"168- وعلقمة بن عبده وهو علقمة الفحل وعلقمة الخصى من رهط علقمة الفحل ولابن عبدة ثلاث روائع جياد","page":"ص0","text":"وعلقمة بن عبده وهو علقمة الفحل وعلقمة الخصى من رهط علقمة الفحل ولابن عبدة ثلاث روائع جياد لا يفوقهن شعر\n(ذهبت من الهجران فى كل مذهب ... ولم يك حقا كل هذا التجنب)\nوالثانية\n(طحا بك قلب فى الحسان طروب بعيد الشباب عصرحان مشيب)\nوالثالثة\n(هل ما علمت وما استودعت مكتوم ... أم حبلها إذ نأتك اليوم مصروم)\nولا شئ بعدهن يذكر"},{"id":"tabaqat-shuara:171","bookId":"tabaqat-shuara","type":"section","seq":171,"chapter":"طبقات فحول الشعراء","title":"169- نا أبو خليفة نا أبو عثمان المازنى عن الأصمعى عن نافع بن أبى نعيم قال مر رجل من مزينة بباب","page":"ص0","text":"نا أبو خليفة نا أبو عثمان المازنى عن الأصمعى عن نافع بن أبى نعيم قال مر رجل من مزينة بباب رجل من الأنصار وقد كان يتهم بامرأته فتمثل\n(هل ما علمت وما استودعت مكتوم ... )\nفاستعدى رب البيت عليه عمر فقال له عمر ما أردت قال وما على فى أن أنشدت شعرا قال قد كان له موضع غير هذا ثم أمر به فحد"},{"id":"tabaqat-shuara:172","bookId":"tabaqat-shuara","type":"section","seq":172,"chapter":"طبقات فحول الشعراء","title":"170- وعدى بن زيد كان يسكن الحيرة ويرا كن الريف فلان لسانه وسهل منطقه فحمل عليه شئ كثير وتخليصه","page":"ص0","text":"وعدى بن زيد كان يسكن الحيرة ويرا كن الريف فلان لسانه وسهل منطقه فحمل عليه شئ كثير وتخليصه شديد\nواضطرب فيه خلف الأحمر وخلط فيه المفضل فأكثر"},{"id":"tabaqat-shuara:173","bookId":"tabaqat-shuara","type":"section","seq":173,"chapter":"طبقات فحول الشعراء","title":"171- وله أربع قصائد غرر روائع مبرزات وله بعدهن شعر حسن أولهن —","page":"ص0","text":"وله أربع قصائد غرر روائع مبرزات وله بعدهن شعر حسن أولهن\n(أرواح مودع أم بكور ... أنت فاعلم لأى حال تصير)\nنا أبو خليفة نا ابن سلام قال سمعت يونس وقد تمثل بهذا البيت\n(أيها الشامت المعير بالدهر ... أأنت المبرأ الموفور)\n(أم لديك العهد الوثيق من الأيام ... بل أنت جاهل مغرور)\nفقال لو تمنيت أن أقول شعرا ما تمنيت إلا هذه أو قال مثل هذه\nوقوله\n(أتعرف رسم الدار من أم معبد ... نعم فرماك الشوق قبل التجلد)\nوقوله\n(ليس شئ على المنون بباق ... غير وجه المسبح الخلاق)\nوقوله\n(لم أر مثل الفتيان فى غبر الأيام ... ينسون ما عواقبها)"},{"id":"tabaqat-shuara:174","bookId":"tabaqat-shuara","type":"section","seq":174,"chapter":"طبقات فحول الشعراء","title":"الطبقة الخامسة","page":"ج1 ص142","text":"وهم أربعة رهط"},{"id":"tabaqat-shuara:175","bookId":"tabaqat-shuara","type":"section","seq":175,"chapter":"طبقات فحول الشعراء","title":"172- خداش بن زهير بن ربيعة ذى الشامة بن عمرو وهو فارس الضحياء بن عامر بن ربيعة بن عامر بن صعصعة","page":"ج1 ص142","text":"خداش بن زهير بن ربيعة ذى الشامة بن عمرو وهو فارس الضحياء بن عامر بن ربيعة بن عامر بن صعصعة"},{"id":"tabaqat-shuara:176","bookId":"tabaqat-shuara","type":"section","seq":176,"chapter":"طبقات فحول الشعراء","title":"173- والأسود بن يعفر بن عبد الأسود بن جندل بن نهشل ابن دارم","page":"ج1 ص142","text":"والأسود بن يعفر بن عبد الأسود بن جندل بن نهشل ابن دارم"},{"id":"tabaqat-shuara:177","bookId":"tabaqat-shuara","type":"section","seq":177,"chapter":"طبقات فحول الشعراء","title":"174- وأبو يزيد المخبل بن ربيعة بن عوف قتال بن أنف الناقة بن قريع","page":"ج1 ص142","text":"وأبو يزيد المخبل بن ربيعة بن عوف قتال بن أنف الناقة بن قريع"},{"id":"tabaqat-shuara:178","bookId":"tabaqat-shuara","type":"section","seq":178,"chapter":"طبقات فحول الشعراء","title":"175- وتميم بن أبى بن مقبل بن عوف بن حنيف بن قتيبة بن العجلان بن عبد الله بن ربيعة بن كعب بن عام","page":"ج1 ص142","text":"وتميم بن أبى بن مقبل بن عوف بن حنيف بن قتيبة بن العجلان بن عبد الله بن ربيعة بن كعب بن عامر بن صعصعة"},{"id":"tabaqat-shuara:179","bookId":"tabaqat-shuara","type":"section","seq":179,"chapter":"طبقات فحول الشعراء","title":"176- فخداش شاعر — قال أبو عمرو بن العلاء هو أشعر فى قريحة الشعر من لبيد وأبى الناس إلا تقدمة لبيد","page":"ص0","text":"فخداش شاعر\nقال أبو عمرو بن العلاء هو أشعر فى قريحة الشعر من لبيد وأبى الناس إلا تقدمة لبيد"},{"id":"tabaqat-shuara:180","bookId":"tabaqat-shuara","type":"section","seq":180,"chapter":"طبقات فحول الشعراء","title":"177- وكان يهجو قريشا ويقال إن أباه قتلته قريش أيام الفجار وهو الذى يقول —","page":"ص0","text":"وكان يهجو قريشا ويقال إن أباه قتلته قريش أيام الفجار وهو الذى يقول\n(أبى فارس الضحياء عمرو بن عامر ... أبى الذم واختار الوفاء على الغدر)\n(فيا أخوينا من أبينا وأمنا ... إليكم إليكم لا سبيل إلى جسر)\nوهو الذى يقول\n(ياشدة ما شددنا غير كاذبة ... على سخينة لولا الليل والحرم)\n(إذ يتقينا هشام بالوليد ولو ... أنا ثقفنا هشاما شالت الجذم)\nسخينة شئ تعير به قريش فجعله اسما لها\nهشام والوليد ابنا المغيرة المخزوميان"},{"id":"tabaqat-shuara:181","bookId":"tabaqat-shuara","type":"section","seq":181,"chapter":"طبقات فحول الشعراء","title":"179- وقال القصيدة المنصفة —","page":"ص0","text":"وقال القصيدة المنصفة\n(فأبلغ إن عرضت بنا هشاما ... وعبد الله ابلغ والوليدا)\n(أولئك إن يكن فى الناس خير ... فإن لديهم حسبا وجودا)\n(هم خير المعاشر من قريش ... وأوراها إذا قدحت زنودا)\n(بأنا يوم شمطة قد أقمنا ... عمود المجد إن له عمودا)\n(فجاؤوا عارضا بردا وجئنا ... كما أضرمت فى الغاب الوفودا)\n(فعانقنا الكماة وعانقونا ... عراك النمر واجهت الأسودا)\n(فلم أر مثلهم هزموا وفلوا ... ولا كذبادنا عنقا مجودا)\nهشام والوليد أبنا المغيرة وعبد الله ابن جدعان\nوكان يعتمد على ابن جدعان بالهجاء فزعموا أنه لما رآه ورأى جماله وجهارته وسيماه قال والله لا أهجوه أبدا"},{"id":"tabaqat-shuara:182","bookId":"tabaqat-shuara","type":"section","seq":182,"chapter":"طبقات فحول الشعراء","title":"180- والأسود بن يعفر يكنى أبا الجراح أخبرنى يونس أن رؤبة كان يقول يعفر بضم الياء والفاء فقال يو","page":"ج1 ص146","text":"والأسود بن يعفر يكنى أبا الجراح أخبرنى يونس أن رؤبة كان يقول يعفر بضم الياء والفاء فقال يونس يقال يونس ويونس ويوسف ويوسف"},{"id":"tabaqat-shuara:183","bookId":"tabaqat-shuara","type":"section","seq":183,"chapter":"طبقات فحول الشعراء","title":"181- وكان الأسود شاعرا فحلا وكان يكثر التنقل فى العرب يجاورهم فيذم ويحمد وله فى ذلك أشعار — وله و","page":"ج1 ص146","text":"وكان الأسود شاعرا فحلا وكان يكثر التنقل فى العرب يجاورهم فيذم ويحمد وله فى ذلك أشعار\nوله واحدة رائعة طويلة لاحقة بأجود الشعر لو كان شفعها بمثلها قدمناه على مرتبته وهى\n(نام الخلى وما أحس رقادى ... والهم محتضر لدى وسادى)\nوله شعر جيد ولا كهذه"},{"id":"tabaqat-shuara:184","bookId":"tabaqat-shuara","type":"section","seq":184,"chapter":"طبقات فحول الشعراء","title":"181- وذكر بعض أصحابنا أنه سمع المفضل يقول له ثلاثون ومئة قصيدة — ونحن لا نعرف له ذلك ولا قريبا من","page":"ص0","text":"وذكر بعض أصحابنا أنه سمع المفضل يقول له ثلاثون ومئة قصيدة\nونحن لا نعرف له ذلك ولا قريبا منه\nوقد علمت أن أهل الكوفة يروون له أكثر مما نروى ويتجوزون فى ذلك بأكثر من تجوزنا"},{"id":"tabaqat-shuara:185","bookId":"tabaqat-shuara","type":"section","seq":185,"chapter":"طبقات فحول الشعراء","title":"182- وأسمعنى بعض أهل الكوفة شعرا زعم أنه أخذه عن خالد بن كلثوم يرثى به حاجب بن زرارة — فقلت له كي","page":"ص0","text":"وأسمعنى بعض أهل الكوفة شعرا زعم أنه أخذه عن خالد بن كلثوم يرثى به حاجب بن زرارة\nفقلت له كيف يروى خالد مثل هذا وهو من أهل العلم وهذا شعر متداع خبيث فقال أخذناه من الثقات ونحن لا نعرف هذا ولا نقبله"},{"id":"tabaqat-shuara:186","bookId":"tabaqat-shuara","type":"section","seq":186,"chapter":"طبقات فحول الشعراء","title":"183- وقال يمدح الحارث بن هشام بن المغيرة وكانت أسماء بنت مخربة النهشلية عند هشام بن المغيرة فول","page":"ص0","text":"وقال يمدح الحارث بن هشام بن المغيرة وكانت أسماء بنت مخربة النهشلية عند هشام بن المغيرة فولدت له أبا جهل والحارث ثم تزوجها أبو ربيعة بن المغيرة فأولدها عبد الله وعياشا وكان الحارث بن هشام قام بغزوة أحد وكان له فيها أثر\nفقال\n(إن الأكارم من قريش كلها ... قاموا فراموا الأمر كل مرام)\n(حتى إذا كثر التحاول بينهم ... فصل الأمور الحارث بن هشام)\n(وسما ليثرب لا يريد طعامها ... إلا ليصلح أهلها بسوام)\n(وغزا اليهود فأسلموا أبناءهم ... صمى لما لقيت يهود صمام)"},{"id":"tabaqat-shuara:187","bookId":"tabaqat-shuara","type":"section","seq":187,"chapter":"طبقات فحول الشعراء","title":"184- والمخبل شاعر فحل وهو أبو يزيد وله يقول الفرزدق —","page":"ص0","text":"والمخبل شاعر فحل وهو أبو يزيد وله يقول الفرزدق\n(وهب القصائد لى النوابغ إذ مضوا ... وأبو يزيد وذو القروح وجرول)\nوللمخبل شعر كثير جيد هجابه الزبرقان وغيره وكان يمدح بنى قريع ويذكر أيام سعد\nوشعره كثير"},{"id":"tabaqat-shuara:188","bookId":"tabaqat-shuara","type":"section","seq":188,"chapter":"طبقات فحول الشعراء","title":"185- وتميم بن أبى بن مقبل شاعر مجيد مغلب غلب عليه النجاشى ولم يكن إليه فى الشعر وقد قهره فى اله","page":"ص0","text":"وتميم بن أبى بن مقبل شاعر مجيد مغلب غلب عليه النجاشى ولم يكن إليه فى الشعر وقد قهره فى الهجاء فقال\n(إذا الله عادى أهل لؤم ودقة ... فعادى بنى العجلان رهط ابن مقبل)\nثم هاجى النجاشى عبد الرحمن بن حسان بن ثابت فغلبه عبد الرحمن بن حسان بن ثابت"},{"id":"tabaqat-shuara:189","bookId":"tabaqat-shuara","type":"section","seq":189,"chapter":"طبقات فحول الشعراء","title":"186- وكان ابن مقبل جافيا فى الدين وكان الإسلام يبكى أهل الجاهلية ويذكرها فقيل له تبكى أهل الجاه","page":"ص0","text":"وكان ابن مقبل جافيا فى الدين وكان الإسلام يبكى أهل الجاهلية ويذكرها فقيل له تبكى أهل الجاهلية وأنت مسلم فقال\n(وما لى لا أبكى الديار وأهلها ... وقد زارها زوار عك وحميرا)\n(وجاء قطا الأجباب من كل جانب ... فوقع فى أعطاننا ثم طيرا)"},{"id":"tabaqat-shuara:190","bookId":"tabaqat-shuara","type":"section","seq":190,"chapter":"طبقات فحول الشعراء","title":"187- أربعة رهط لكل واحد منهم واحدة","page":"ص0","text":"أربعة رهط لكل واحد منهم واحدة"},{"id":"tabaqat-shuara:191","bookId":"tabaqat-shuara","type":"section","seq":191,"chapter":"طبقات فحول الشعراء","title":"188- أولهم عمرو بن كلثوم بن مالك بن عتاب بن سعد بن زهير بن جشم بن بكر بن حبيب بن عمرو بن غنم بن","page":"ص0","text":"أولهم عمرو بن كلثوم بن مالك بن عتاب بن سعد بن زهير بن جشم بن بكر بن حبيب بن عمرو بن غنم بن تغلب\nوله قصيدة التى أولها\n(ألاهبى بصحنك فاصبحينا ... ولا تبقى خمور الأندرينا)"},{"id":"tabaqat-shuara:192","bookId":"tabaqat-shuara","type":"section","seq":192,"chapter":"طبقات فحول الشعراء","title":"189- والحارث بن حلزة بن مكروه بن بديد بن عبد الله بن مالك بن عبد سعد بن خشم بن ذبيان بن كنانه ب","page":"ص0","text":"والحارث بن حلزة بن مكروه بن بديد بن عبد الله بن مالك بن عبد سعد بن خشم بن ذبيان بن كنانه بن يشكر بن بكر ابن وائل\nوله قصيدة التى أولها\n(آذنتنا ببينها أسماء ... رب ثاو يمل منه الثواء)\nوله شعر سوى هذا وهو الذى يقول فى شعره\n(لا تكسع الشول بأغبارها ... إنك لا تدرى من الناتج)"},{"id":"tabaqat-shuara:193","bookId":"tabaqat-shuara","type":"section","seq":193,"chapter":"طبقات فحول الشعراء","title":"190- وعنترة بن شداد بن معاوية بن قراد بن مخزوم بن مالك ابن غالب بن قطيعة بن عبس — وله قصيدة وهى —","page":"ص0","text":"وعنترة بن شداد بن معاوية بن قراد بن مخزوم بن مالك ابن غالب بن قطيعة بن عبس\nوله قصيدة وهى\n(يا دار عبلة بالجواء تكلمى ... وعمى صباحا دار عبلة واسلمى)\nوله شعر كثير إلا أن هذه نادرة فألحقوها مع أصحاب الواحدة"},{"id":"tabaqat-shuara:194","bookId":"tabaqat-shuara","type":"section","seq":194,"chapter":"طبقات فحول الشعراء","title":"191- وسويد بن أبى كاهل بن حارثه بن حسل بن مالك بن عبد سعد بن جشم بن ذبيان بن كنانه بن يشكر بن ب","page":"ص0","text":"وسويد بن أبى كاهل بن حارثه بن حسل بن مالك بن عبد سعد بن جشم بن ذبيان بن كنانه بن يشكر بن بكر بن وائل\nوله قصيدة أولها\n(بسطت رابعة الحبل لنا ... فمددنا الحبل منها ما اتسع)\nوله شعر كثير ولكن برزت هذه على شعره\nوهو الذى يقول\n(جررت على راجى الهوادة منهم ... وقد تلحق المولى العنود الجرائر)"},{"id":"tabaqat-shuara:195","bookId":"tabaqat-shuara","type":"section","seq":195,"chapter":"طبقات فحول الشعراء","title":"192- قال وحدثنى أبو بكر عبد الله بن مصعب قال لما خلع ابن الزبير يزيد بن معاوية والمنذر بن الزبي","page":"ص0","text":"قال وحدثنى أبو بكر عبد الله بن مصعب قال لما خلع ابن الزبير يزيد بن معاوية والمنذر بن الزبير يومئذ بالبصرة وعروة بن الزبير بمصر شخصا إليه ومسافتهما يومئذ غير متقاربة فلما رآهما تمثل ببيت سويد\n(جررت على راجى الهوادة منهم ... وقد تلحق المولى العنود الجرائر)"},{"id":"tabaqat-shuara:196","bookId":"tabaqat-shuara","type":"section","seq":196,"chapter":"طبقات فحول الشعراء","title":"193- أربعة رهط محكمون مقلون وفى أشعارهم قلة فذاك الذى أخرهم","page":"ص0","text":"أربعة رهط محكمون مقلون وفى أشعارهم قلة فذاك الذى أخرهم"},{"id":"tabaqat-shuara:197","bookId":"tabaqat-shuara","type":"section","seq":197,"chapter":"طبقات فحول الشعراء","title":"194- منهم سلامة بن جندل بن عبد الرحمن بن عبد عمرو بن الحارث وهو مقاعس بن عمرو بن كعب بن سعد","page":"ص0","text":"منهم سلامة بن جندل بن عبد الرحمن بن عبد عمرو بن الحارث وهو مقاعس بن عمرو بن كعب بن سعد"},{"id":"tabaqat-shuara:198","bookId":"tabaqat-shuara","type":"section","seq":198,"chapter":"طبقات فحول الشعراء","title":"195- وحصين بن الحمام المرى بن ربيعة بن مساب بن حرام بن وائلة بن سهم بن مرة وهو فارس شاعر شريف","page":"ص0","text":"وحصين بن الحمام المرى بن ربيعة بن مساب بن حرام بن وائلة بن سهم بن مرة وهو فارس شاعر شريف"},{"id":"tabaqat-shuara:199","bookId":"tabaqat-shuara","type":"section","seq":199,"chapter":"طبقات فحول الشعراء","title":"196- والمتلمس وهو جرير بن عبد المسيح بن عبد الله — ابن زيد بن دوفن بن حرب بن وهب بن جلى بن أحمس ب","page":"ص0","text":"والمتلمس وهو جرير بن عبد المسيح بن عبد الله\nابن زيد بن دوفن بن حرب بن وهب بن جلى بن أحمس بن ضبيعة بن ربيعة ويقال ضبيعة أضجم والأضجم الحارث الخير بن عبد الله بن ربيعة بن دوفن وبه ضجمت ربيعة وكان سيدا\nوالمتلمس خال طرفة بن العبد وإنما سمى المتلمس لقوله\n(فهذا أوان العرض حى ذبابه ... زنابيره والأزرق المتلمس)"},{"id":"tabaqat-shuara:200","bookId":"tabaqat-shuara","type":"section","seq":200,"chapter":"طبقات فحول الشعراء","title":"197- والمسيب بن علس بن عمرو بن قمامة بن زيد بن ثعلبة بن عمرو بن مالك بن جشم بن بلال بن خماعة بن","page":"ص0","text":"والمسيب بن علس بن عمرو بن قمامة بن زيد بن ثعلبة بن عمرو بن مالك بن جشم بن بلال بن خماعة بن جلى بن أحمس بن ضبيعة\nواسم المسيب زهير وإنما سمى المسيب حين أوعد بنى عامر بن ذهل فقالت بنو ضبيعة قد سيبناك والقوم\nوهو خال الأعشى وهو الذى يقول فى القعقاع بن معبد بن زرارة\n(فلأهدين مع الرياح قصيدة ... منى مغلغلة إلى القعقاع)\n(أنت الذى زعمت معد أنه ... أهل التكرم والندى والباع)"},{"id":"tabaqat-shuara:201","bookId":"tabaqat-shuara","type":"section","seq":201,"chapter":"طبقات فحول الشعراء","title":"الطبقة الثامنة","page":"ج1 ص157","text":"أربعة رهط"},{"id":"tabaqat-shuara:202","bookId":"tabaqat-shuara","type":"section","seq":202,"chapter":"طبقات فحول الشعراء","title":"198- عمرو بن قميئة بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة","page":"ج1 ص157","text":"عمرو بن قميئة بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة"},{"id":"tabaqat-shuara:203","bookId":"tabaqat-shuara","type":"section","seq":203,"chapter":"طبقات فحول الشعراء","title":"199- والنمر بن تولب بن أقيش بن عبد الله بن كعب بن عوف بن الحارث بن عدى بن عوف بن عبد مناة بن أد","page":"ج1 ص157","text":"والنمر بن تولب بن أقيش بن عبد الله بن كعب بن عوف بن الحارث بن عدى بن عوف بن عبد مناة بن أد وهو عكل"},{"id":"tabaqat-shuara:204","bookId":"tabaqat-shuara","type":"section","seq":204,"chapter":"طبقات فحول الشعراء","title":"200- وأوس بن غلفاء الهجيمى","page":"ج1 ص157","text":"وأوس بن غلفاء الهجيمى"},{"id":"tabaqat-shuara:205","bookId":"tabaqat-shuara","type":"section","seq":205,"chapter":"طبقات فحول الشعراء","title":"201- وعوف بن عطية بن الخرع والخرع يقال له عمرو بن عيش بن وديعة بن عبد الله بن لؤى بن عمرو بن ال","page":"ج1 ص157","text":"وعوف بن عطية بن الخرع والخرع يقال له عمرو بن عيش بن وديعة بن عبد الله بن لؤى بن عمرو بن الحارث بن تيم ابن عبد مناة بن أد"},{"id":"tabaqat-shuara:206","bookId":"tabaqat-shuara","type":"section","seq":206,"chapter":"طبقات فحول الشعراء","title":"202- حدثنى مسمع بن عبد الملك وهو كردين قال قول امرئ القيس —","page":"ص0","text":"حدثنى مسمع بن عبد الملك وهو كردين قال قول امرئ القيس\n(بكى صاحبى لما رأى الدرب دونه ... وأيقن أنا لاحقان بقيصرا)\nقال صاحبه الذى ذكر عمرو بن قميئة\nوبنو قيس تدعى بعض شعر امرئ القيس لعمرو بن قميئة وليس ذلك بشئ"},{"id":"tabaqat-shuara:207","bookId":"tabaqat-shuara","type":"section","seq":207,"chapter":"طبقات فحول الشعراء","title":"203- والنمر بن تولب جواد لا يليق شيئا وكان شاعرا فصيحا جريئا على المنطق — وكان أبو عمرو بن العلاء","page":"ص0","text":"والنمر بن تولب جواد لا يليق شيئا وكان شاعرا فصيحا جريئا على المنطق\nوكان أبو عمرو بن العلاء يسميه الكيس لحسن شعره"},{"id":"tabaqat-shuara:208","bookId":"tabaqat-shuara","type":"section","seq":208,"chapter":"طبقات فحول الشعراء","title":"204- وهو الذى يقول —","page":"ص0","text":"وهو الذى يقول\n(لا تغضبن على امرئ فى ماله ... وعلى كرائم صلب مالك فاغضب)\n(وإذا تصبك خصاصة فارج الغنى ... وإلى الذى يعطى الرغائب فارغب)"},{"id":"tabaqat-shuara:209","bookId":"tabaqat-shuara","type":"section","seq":209,"chapter":"طبقات فحول الشعراء","title":"205- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(عليهن يوم الورد حق وحرمة ... وهن غداة الغب عندك حفل)"},{"id":"tabaqat-shuara:210","bookId":"tabaqat-shuara","type":"section","seq":210,"chapter":"طبقات فحول الشعراء","title":"206- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(أقى حسبى به ويعز عرضى ... على إذا الحفيظة أدركتنى)\n(وأعلم أن ستدركنى المنايا ... فإلا أتبعها تتبعنى)"},{"id":"tabaqat-shuara:211","bookId":"tabaqat-shuara","type":"section","seq":211,"chapter":"طبقات فحول الشعراء","title":"207- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(أعاذل إن يصبح صداى بقفرة ... بعيد نآنى صاحبى وقريبى)\n(ترى أن ما أنفقت لم يك ضرنى ... وأن الذى أفنيت كان نصيبى)"},{"id":"tabaqat-shuara:212","bookId":"tabaqat-shuara","type":"section","seq":212,"chapter":"طبقات فحول الشعراء","title":"208- وعمر عمرا طويلا فكان هجيراه اصبحوا الراكب اغبقوا الراكب لعادته التى كان عليها","page":"ص0","text":"وعمر عمرا طويلا فكان هجيراه اصبحوا الراكب اغبقوا الراكب لعادته التى كان عليها"},{"id":"tabaqat-shuara:213","bookId":"tabaqat-shuara","type":"section","seq":213,"chapter":"طبقات فحول الشعراء","title":"209- قال وخرفت امرأة من العرب عرب كرام لا أبالى أن لا أسميهم وكانت تقول زوجونى — فقال عمر ما لهج","page":"ص0","text":"قال وخرفت امرأة من العرب عرب كرام لا أبالى أن لا أسميهم وكانت تقول زوجونى\nفقال عمر ما لهج به أخو عكل أسرى مما لهجت به صاحبتكم"},{"id":"tabaqat-shuara:214","bookId":"tabaqat-shuara","type":"section","seq":214,"chapter":"طبقات فحول الشعراء","title":"210- وذكر خلاد بن قرة بن خالد السدوسى عن أبيه وعن سعيد بن إياس الجريرى عن أبى العلاء يزيد بن عب","page":"ص0","text":"وذكر خلاد بن قرة بن خالد السدوسى عن أبيه وعن سعيد بن إياس الجريرى عن أبى العلاء يزيد بن عبد الله بن الشخير أخى مطرف بن عبد الله قال\nبينما نحن بهذا المربد جلوس إذ أتى علينا أعرابى أشعث\nالرأس فوقف علينا\nفقلنا والله لكأن هذا ليس من أهل هذا البلد قال أجل والله وإذا معه قطعة من جراب أو أديم فقال هذا كتاب كتبه لى محمد رسول الله صلى الله عليه وسلم\nفأخذناه فقرأناه فإذا فيه\nبسم الله الرحمن الرحيم\nهذا كتاب من محمد رسول الله صلى الله عليه وسلم لبنى زهير بن أقيش قال الجريرى هو حى من عكل إنكم إن شهدتم أن لا إله إلا الله وأنى رسول الله وأقمتم الصلاة وآتيتم الزكاة وفارقتم المشركين وأعطيتم الخمس من الغنائم وسهم ذى القربى والصفى وربما قال وصفيه فأنتم آمنون بأمان الله وأمان رسوله\nفقال لهم القوم حدثنا أصلحك الله بما سمعت من رسول الله صلى الله عليه وسلم\nقال سمعت رسول الله صلى الله عليه وسلم يقول صوم شهر الصبر وصوم ثلاثة أيام من كل شهر يذهبن وحر الصدر\nفقال له القوم أأنت سمعت هذا من رسول الله صلى الله عليه وسلم قال\nألا أراكم تخافون أن أكذب على رسول الله صلى الله عليه وسلم لاحدثتكم حديثا ثم أومأ بيده إلى صحيفته ثم انصاع مدبرا\nففى حديث قرة عن يزيد فقيل لى لما ولى هذا النمر بن تولب العكلى الشاعر"},{"id":"tabaqat-shuara:215","bookId":"tabaqat-shuara","type":"section","seq":215,"chapter":"طبقات فحول الشعراء","title":"211- وعوف بن الخرع جيد الشعر وهو الذى يرد على لقيط ابن زرارة قيلة —","page":"ج1 ص163","text":"وعوف بن الخرع جيد الشعر وهو الذى يرد على لقيط ابن زرارة قيلة\n(أحق مال فكلوه بأكل ... أموال تيم وعدى وعكل)\n(يا ضب كن عما كريما واعتزل ... ذرنا وتيما وعديا ننتضل)"},{"id":"tabaqat-shuara:216","bookId":"tabaqat-shuara","type":"section","seq":216,"chapter":"طبقات فحول الشعراء","title":"212- وقال —","page":"ج1 ص163","text":"وقال\n(فأما الألأمان بنو عدى ... وتيم حين تزدحم الأمور)\n(فلا تشهد بهم فتيان حرب ... ولكن أدن من حلب وغير)\n(إذا دهنوا رماحهم بزبد ... فإن رماح تيم لا تضير)"},{"id":"tabaqat-shuara:217","bookId":"tabaqat-shuara","type":"section","seq":217,"chapter":"طبقات فحول الشعراء","title":"213- فقال عوف بن الخرع —","page":"ص0","text":"فقال عوف بن الخرع\n(هلا غضبت على ابن أمك معبد ... والعامرى يقوده بصفاد)\n(أذكرت من لبن المحلق شربة ... والخيل تعدو فى الصعيد بداد)\n(هلا فوارس رحرحان هجوتم ... عشر تناوح فى سرارة واد)\n(لا تأكل الإبل الغراث نباته ... كلا وليس عماده بعماد)"},{"id":"tabaqat-shuara:218","bookId":"tabaqat-shuara","type":"section","seq":218,"chapter":"طبقات فحول الشعراء","title":"214- وعوف يقول أيضا —","page":"ص0","text":"وعوف يقول أيضا\n(يا قرة بن هبيرة ابن أقيشر ... يا سيد السلمات إنك تظلم)"},{"id":"tabaqat-shuara:219","bookId":"tabaqat-shuara","type":"section","seq":219,"chapter":"طبقات فحول الشعراء","title":"215- وأوس بن غلفاء الذى يقول —","page":"ص0","text":"وأوس بن غلفاء الذى يقول\n(ألا قالت أمامة يوم غول ... تقطع بابن غلفاء الجبال)\n(ذرينى إنما خطإى وصوبى ... على وإن ما أهلكت مال)"},{"id":"tabaqat-shuara:220","bookId":"tabaqat-shuara","type":"section","seq":220,"chapter":"طبقات فحول الشعراء","title":"216- وهو الذى يرد على يزيد بن الصعق قوله —","page":"ص0","text":"وهو الذى يرد على يزيد بن الصعق قوله\n(إذا ما مات ميت من تميم ... فسرك أن يعيش فجئ بزاد)"},{"id":"tabaqat-shuara:221","bookId":"tabaqat-shuara","type":"section","seq":221,"chapter":"طبقات فحول الشعراء","title":"217- وقوله —","page":"ص0","text":"وقوله\n(ألا أبلغ لديك بنى تميم ... بآية ما يحبون الطعاما)"},{"id":"tabaqat-shuara:222","bookId":"tabaqat-shuara","type":"section","seq":222,"chapter":"طبقات فحول الشعراء","title":"218- فقال أوس بن غلفاء —","page":"ص0","text":"فقال أوس بن غلفاء\n(فإنك من هجاء بنى تميم ... كمزداد الغرام إلى الغرام)\n(هم ضربوك أم الرأس حتى ... بدت أم الشؤون عن العظام)\n(إذا يأسونها نشزت عليهم ... شرنبثه الأصابع أم هام)\n(وهم تركوك أسلح من حبارى ... وهم تركوك أشرد من نعام)"},{"id":"tabaqat-shuara:223","bookId":"tabaqat-shuara","type":"section","seq":223,"chapter":"طبقات فحول الشعراء","title":"219- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(هم قتلوا أباك فلم تبين ... لحق ما الأغر من البهيم)\n(وهم منوا عليك فلم تثبهم ... ثواب المرء ذى الحسب الكريم)"},{"id":"tabaqat-shuara:224","bookId":"tabaqat-shuara","type":"section","seq":224,"chapter":"طبقات فحول الشعراء","title":"الطبقة التاسعة","page":"ج1 ص170","text":"أربعة رهط"},{"id":"tabaqat-shuara:225","bookId":"tabaqat-shuara","type":"section","seq":225,"chapter":"طبقات فحول الشعراء","title":"220- ضابئ بن الحارث بن أرطاة بن شهاب بن عبيد بن خاذل ابن قيس القبيلة بن حنظلة بن مالك من البراج","page":"ج1 ص170","text":"ضابئ بن الحارث بن أرطاة بن شهاب بن عبيد بن خاذل ابن قيس القبيلة بن حنظلة بن مالك من البراجم"},{"id":"tabaqat-shuara:226","bookId":"tabaqat-shuara","type":"section","seq":226,"chapter":"طبقات فحول الشعراء","title":"221- وسويد بن كراع العكلى","page":"ج1 ص170","text":"وسويد بن كراع العكلى"},{"id":"tabaqat-shuara:227","bookId":"tabaqat-shuara","type":"section","seq":227,"chapter":"طبقات فحول الشعراء","title":"222- والحويدرة واسمه قطبة بن محصن بن جرول بن حبيب — الأعظم بن عبد العزى بن حزيمة بن رزام بن مازن","page":"ج1 ص170","text":"والحويدرة واسمه قطبة بن محصن بن جرول بن حبيب\nالأعظم بن عبد العزى بن حزيمة بن رزام بن مازن بن ثعلبة بن سعد بن ذبيان"},{"id":"tabaqat-shuara:228","bookId":"tabaqat-shuara","type":"section","seq":228,"chapter":"طبقات فحول الشعراء","title":"223- وسحيم عبد بنى الحسحاس بن هند بن سفيان بن غضاب بن كعب بن سعد بن ثعلبة بن دودان بن أسد بن خز","page":"ص0","text":"وسحيم عبد بنى الحسحاس بن هند بن سفيان بن غضاب بن كعب بن سعد بن ثعلبة بن دودان بن أسد بن خزيمة"},{"id":"tabaqat-shuara:229","bookId":"tabaqat-shuara","type":"section","seq":229,"chapter":"طبقات فحول الشعراء","title":"224- قال وكان ضابئ بن الحارث رجلا بذيا كثير الشر وكان بالمدينة وكان صاحب صيد وصاحب خيل فركب فرس","page":"ص0","text":"قال وكان ضابئ بن الحارث رجلا بذيا كثير الشر وكان بالمدينة وكان صاحب صيد وصاحب خيل فركب فرسا له يقال له قيار وكان ضعيف البصر ولقيار يقول\n(فمن يك أمسى بالمدينة رحله ... فإنى وقيارا بها لغريب)\nيقول إنى بها لغريب وقيارا أيضا"},{"id":"tabaqat-shuara:230","bookId":"tabaqat-shuara","type":"section","seq":230,"chapter":"طبقات فحول الشعراء","title":"225- ثم إنه وطئ صبيا دابته فقتله فرفع إلى عثمان بن عفان فاعتذر بضعف بصره وقال لم أره ولم أعمده —","page":"ص0","text":"ثم إنه وطئ صبيا دابته فقتله فرفع إلى عثمان بن عفان فاعتذر بضعف بصره وقال لم أره ولم أعمده\nفحبسه عثمان ما حبسه\nثم تخلص"},{"id":"tabaqat-shuara:231","bookId":"tabaqat-shuara","type":"section","seq":231,"chapter":"طبقات فحول الشعراء","title":"226- وكان استعار كلب صيد من قوم من بنى نهشل يقال له قرحان فحبسه حولا ثم جاؤوا يطلبونه وألحوا عل","page":"ص0","text":"وكان استعار كلب صيد من قوم من بنى نهشل يقال له قرحان فحبسه حولا ثم جاؤوا يطلبونه وألحوا عليه حتى أخذوه فقال ضابئ\n(تجشم دونى وفد قرحان خطة ... تظل بها الوجناء وهى حسير)\n(فأردفتهم كلبا فراحوا كأنما ... حباهم بتاج المرزبان أمير)\n(فأمكم لا تتركوها وكلبكم ... فإن عقوق الأمهات كبير)\n(إذا عثنت من آخر الليل دخنة ... يظل لها فوق الفراش هرير)\nفاستعدوا عليه عند عثمان\nفقال ويلك ما سمعت أحدا رمى امرأة من المسلمين بكلب غيرك وإنى لأراك لو كنت على عهد رسول الله\nصلى الله عليه وسلم لأنزل الله فيك قرآنا ولو كان أحد قبلى قطع لسان شاعر فى هجاء لقطعت لسانك\nفحبسه فى السجن"},{"id":"tabaqat-shuara:232","bookId":"tabaqat-shuara","type":"section","seq":232,"chapter":"طبقات فحول الشعراء","title":"227- فعرض أهل السجن يوما فإذا هو قد أعد حديدة يريد أن يغتال عثمان بها فأهانه وركسه فى السجن فقا","page":"ص0","text":"فعرض أهل السجن يوما فإذا هو قد أعد حديدة يريد أن يغتال عثمان بها فأهانه وركسه فى السجن فقال\n(لا يعطين بعدى امرؤ ضيم خطة ... حذار لقاء الموت والموت نائلة)\n(فلا تتبعنى إن هلكت ملامة ... فليس بعار قتل من لا تقاتله)\n(هممت ولم أفعل وكدت وليتنى ... تركت على عثمان تبكى حلائله)\n(وما الفتك ما آمرت فيه ولا الذى ... تخبر من لاقيت أنك فاعله)\n(وقائلة لا يبعد الله ضابئا ... إذا القرن لم يوجد لم من ينازله)\n(وقائلة إن مات فى السجن ضابئ ... لنعم الفتى تخلو به وتداخله)\n(وقائلة لا يبعد الله ضابئا ... إذا احمر من حس الشتاء أصائله)\nولم يزل ضابئ فى السجن حتى مات"},{"id":"tabaqat-shuara:233","bookId":"tabaqat-shuara","type":"section","seq":233,"chapter":"طبقات فحول الشعراء","title":"228- فلما قتل عثمان وثب عمير ابنه على عثمان بعد أن قتل فيقال إنه كسر صلبه أو كسر ضلعا له","page":"ص0","text":"فلما قتل عثمان وثب عمير ابنه على عثمان بعد أن قتل فيقال إنه كسر صلبه أو كسر ضلعا له"},{"id":"tabaqat-shuara:234","bookId":"tabaqat-shuara","type":"section","seq":234,"chapter":"طبقات فحول الشعراء","title":"229- فلما قدم الحجاج العراق والمهلب بإزاء الأزارقة قد أرفض عنه أصحابه فنادى الحجاج فى بعث المهل","page":"ص0","text":"فلما قدم الحجاج العراق والمهلب بإزاء الأزارقة قد أرفض عنه أصحابه فنادى الحجاج فى بعث المهلب وأجلهم ثلاثا\nفجاء عمير بن ضابئ وقد كبر يومئذ بابن له شاب إلى الحجاج فقال أيها الأمير إنى قد كبرت وهذا ابنى شاب جلد يقوم مقامى\nفهم بقبوله فقال له عنبسة بن سعيد بن العاص أيها الأمير هذا عمير صاحب أمير المؤمنين عثمان فقدمه فضرب عنقه\nفذعر الناس فخرجوا إلى المهلب\nفلما تساقطوا عليه قال لقد قدم العراق أمير ذكر"},{"id":"tabaqat-shuara:235","bookId":"tabaqat-shuara","type":"section","seq":235,"chapter":"طبقات فحول الشعراء","title":"230- وقال فى ذلك عبد الله بن زبير الأسدى —","page":"ص0","text":"وقال فى ذلك عبد الله بن زبير الأسدى\n(تجهز فإما أن تزور ابن ضابئ ... عميرا وإما أن تزور المهلبا)\n(هما خطنا خسف نجاؤك منهما ... ركوبك حوليا من الثلج أشهبا)"},{"id":"tabaqat-shuara:236","bookId":"tabaqat-shuara","type":"section","seq":236,"chapter":"طبقات فحول الشعراء","title":"231- وسويد بن كراع العكلى وكان شاعرا محكما وكان رجل بنى عكل وذا الرأي والتقدم فيهم","page":"ص0","text":"وسويد بن كراع العكلى وكان شاعرا محكما وكان رجل بنى عكل وذا الرأي والتقدم فيهم"},{"id":"tabaqat-shuara:237","bookId":"tabaqat-shuara","type":"section","seq":237,"chapter":"طبقات فحول الشعراء","title":"232- قال وكان بعض بنى عدى تيم ضرب رجلا من بنى ضبة ثم من بنى السيد وهم قوم نكد شرس وهم أخوال الف","page":"ص0","text":"قال وكان بعض بنى عدى تيم ضرب رجلا من بنى ضبة ثم من بنى السيد وهم قوم نكد شرس وهم أخوال الفرزدق فتجمعوا حتى ألم أن يكون بينهم قتال\nفجاء رجل من بنى عدى فأعطاه يده رهينة لينظر ما يصنع المضروب فقال خالد بن علقمة ابن الطيفان أحد أحلاف بنى عبد الله بن دارم\n(أسالم إنى لا إخالك سالما ... أتيت بنى السيد الغواة الأشائما)\n(أسالم إن أفلت من شر هذه ... فنح فرارا إنما كنت حالما)\n(أسالم ما أعطى ابن مامة مثلها ... ولا حاتم فيما بلا الناس حاتما)"},{"id":"tabaqat-shuara:238","bookId":"tabaqat-shuara","type":"section","seq":238,"chapter":"طبقات فحول الشعراء","title":"233- فقال سويد بن كراع وعكل وتيم وعدى وضبة — إخوة وهم الرباب يرد على ابن الطيفان دخوله بينهم —","page":"ص0","text":"فقال سويد بن كراع وعكل وتيم وعدى وضبة\nإخوة وهم الرباب يرد على ابن الطيفان دخوله بينهم\n(أشاعر عبد الله إن كنت لأئما ... فإنى لما تأتى من الأمر لائم)\n(تحضض أفناء الرباب سفاهة ... وعرضك موتور وليلك نائم)\n(وهل عجب أن تدرك السيد وترها ... وتصبر للحق السراة الأكارم)\n(رأيتك لم تمنع طهية حكمها ... وأعطيت يربوعا وأنفك راغم)\n(وأنت امرؤ لا تقبل الصلح طائعا ... ولكن متى تظأر فإنك رائم)"},{"id":"tabaqat-shuara:239","bookId":"tabaqat-shuara","type":"section","seq":239,"chapter":"طبقات فحول الشعراء","title":"234- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(خليلى قوما فى عطالة فانظرا ... أنارا ترى من ذى أبا نين أم برقا)\n(فإن يك برق فهو برق سحابة ... تغادر ماء لا قليلا ولا رنقا)\n(وإن تك نار فهى نار بملتقى ... من الريح تزهاها وتعفقها عفقا)\n(لأم على أوقدتها طماعة ... بأوبة سفر أن تكون لها وفقا)"},{"id":"tabaqat-shuara:240","bookId":"tabaqat-shuara","type":"section","seq":240,"chapter":"طبقات فحول الشعراء","title":"235- وهو الذى يقول —","page":"ص0","text":"وهو الذى يقول\n(فإن تزجرانى يا ابن عفان أزدجر ... وإن تتركانى أحم عرضا ممنعا)"},{"id":"tabaqat-shuara:241","bookId":"tabaqat-shuara","type":"section","seq":241,"chapter":"طبقات فحول الشعراء","title":"235- وقوله تزجرانى وتتركانى وإنما يريد واحدا وقد تفعل هذا العرب قال الفرزدق —","page":"ص0","text":"وقوله تزجرانى وتتركانى وإنما يريد واحدا وقد تفعل هذا العرب قال الفرزدق\n(عشية سال المربدان كلاهما ... عجاجة موت بالسيوف الصوارم)\nوقال أيضا\n(أخذنا بآفاق السماء عليكم ... لنا قمراها والنجوم الطوالع)\nوقال أبو ذؤيب\n(وحتى يؤوب القارظان كلاهما ... وينشر فى القتلى كليب لوائل)\nوهو رجل واحد من عنزة ذهب أن يجتنى القرظ فلم يثبت أنه رجع\nوقول بشر بن أبى خازم يدل على أنه واحد\n(فرجى الخير وانتظرى إيابى ... إذا ما القارظ العنزى آبا)\nوقال العجاج\n(لا تحسبن الخندقين والحفر ... )\nوهو خندق واحد"},{"id":"tabaqat-shuara:242","bookId":"tabaqat-shuara","type":"section","seq":242,"chapter":"طبقات فحول الشعراء","title":"236- أخبرنى يونس بن حبيب أن رجلا من بنى السيد قتل رجلا من قومه فأتاهم الفرزدق وهم أخواله فعرض ع","page":"ج1 ص180","text":"أخبرنى يونس بن حبيب أن رجلا من بنى السيد قتل رجلا من قومه فأتاهم الفرزدق وهم أخواله فعرض عليهم الدية وأن يرهنهم ابنه بذلك فخافوا شره وأن لا يستطيعوا الإقدام عليه فأبوا\nفقال الفرزدق\n(ألم ترنى أزمعت وثبة حازم ... لأفدى بابنى من ردى الموت خاليا)\n(وكنت ابن اشياخ يجيرون من جنى ... ويحيون كالغيث العظام البواليا)\n(ولما دعانى وهو يرسف لم أكن ... بطيئا عن الداعى ولا متوانيا)\n(شددت على نصفى إزارى وربما ... شددت لأحناء الأمور إزاريا)\n(وقلت أشطوا يا بنى السيد حكمكم ... على فإنى لا تضيق ذراعيا)\n(عرضت على السيد الأشائم موفيا ... بمقتولهم عند المقادة غاليا)\n(غلاما أبوه المستجار بقبره ... وصعصعة الفكاك من كان عانيا)\n(إذا خير السيدى بين غواية ... ورشد أتى السيدى ما كان غاويا)\n(فإن تنج منها تنج من ذى عظيمة ... وإلا فإنى لا إخالك ناجيا)"},{"id":"tabaqat-shuara:243","bookId":"tabaqat-shuara","type":"section","seq":243,"chapter":"طبقات فحول الشعراء","title":"237- وقال بعد ذلك يفتخر بهم —","page":"ص0","text":"وقال بعد ذلك يفتخر بهم\n(بنو السيد الأشائم للأعادى ... نمونى للعلى وبنو ضرار)"},{"id":"tabaqat-shuara:244","bookId":"tabaqat-shuara","type":"section","seq":244,"chapter":"طبقات فحول الشعراء","title":"238- حدثنى حاجب بن يزيد عن أبيه قال إن جريرا كان ينشد هذه الأبيات وشيخ من ثعلبه بن يربوع يقال ل","page":"ص0","text":"حدثنى حاجب بن يزيد عن أبيه قال إن جريرا كان ينشد هذه الأبيات وشيخ من ثعلبه بن يربوع يقال له العقار بن\nالنحار أو النحار بن العقار قاعد بالماء قد شد له حاجباه من الكبر حين قال جرير وضبة كلها ثعلبة وبكر ابنا سعد بن ضبة فذكر أخوال الفرزدق\n(أثعلب أولى حلفة ما ذكرتكم ... بسوء ولكنى عتبت على بكر)\n(أثعلب إنى لم أزل مذ عرفتكم ... أرى لكم سترا فلا تهتكوا سترى)\n(فلا توبسوا بينى وبينكم الثرى ... فإن الذى بينى وبينكم مثرى)\n(فما شهدت يوم النقا خيل هاجر ... ولا السيد إذ ينحطن فى الأسل السمر)\n(وما شهدت يوم الغبيط مجاشع ... ولا نقلان الخيل من قنتى يسر)\nويوم النقا يوم قتل فيه بسطام بن قيس بن مسعود بن قيس بن خالد بن ذى الجدين قتلته ثعلبة بن سعد بن ضبة دون بكر والغبيط أسرت فيه يربوع بسطاما\nقال حاجب فى حديثه فلما أنشد جرير\n(وما شهدت يوم الغبيط مجاشع ... )\nقال الشيخ الثغلبى من المنشد قالوا أحد بنى الخطفى\nقال الشيخ ولا كليب والأجل ما شهدت ما كنا إلا سبعة فوارس من ثعلبة ابن يربوع"},{"id":"tabaqat-shuara:245","bookId":"tabaqat-shuara","type":"section","seq":245,"chapter":"طبقات فحول الشعراء","title":"239- وقال معاوية الضبى —","page":"ج1 ص183","text":"وقال معاوية الضبى\n(فهذا مكانى أو أرى القار مغربا ... وحتى أرى صم الجبال تكلم)\nيريد أنه لا يبرحها أبدا كما أن القار لا يكون مغربا والجبال لا تكلم\nوقد تقول العرب حتى يكون كذا وكذا لما لا يكون\nأبدا فيقولون حتى تطلع الشمس من مغربها وحتى تقع السماء على الأرض وحتى يرجع الدر في الضرع\nوهذا كله عندهم مما لا يكون\nوقال الله عز وجل {حتى يلج الجمل في سم الخياط} لما لا يكون وقال النابغة الذبيانى لعامر بن طفيل\n(وإنك سوف تحلم أو تناهى ... إذا ما شبت أو شاب الغراب)\nوقال النمر بن تولب\n(وقولى إذا ما أطلقوا عن بعيرهم ... يلاقونه حتى يؤوب المنخل)\nأى لا يلاقونه ابدا وكذلك قول أبى ذؤيب\n(وحتى يؤوب القارظان كلاهما ... وينشر فى القتلى كليب لوائل)\nوقال بشر بن أبى خازم\n(فرجى الخير وانتظرى إيابى ... إذا ما القارظ العنزى آبا)\nفهذا عندهم مما لا يكون لأن الغراب لا يشيب ومن مات عندهم لم يرجع"},{"id":"tabaqat-shuara:246","bookId":"tabaqat-shuara","type":"section","seq":246,"chapter":"طبقات فحول الشعراء","title":"240- والثالث الحويدرة وهو شاعر وهو يقول فى كلمة له طويلة —","page":"ج1 ص185","text":"والثالث الحويدرة وهو شاعر وهو يقول فى كلمة له طويلة\n(رحلت سمية غدوة فتمتع ... وغدت غدو مفارق لم يربع)\n(وتزودت عينى غداة لقيتها ... بلوى عنيزة نظرة لم تنقع)\n(وتصدفت حتى استبتك بواضح ... صلت كمنتصب الغزال الأتلع)\n(وبمقلة حوراء تحسب طرفها ... وسنان حرة مستهل الأدمع)"},{"id":"tabaqat-shuara:247","bookId":"tabaqat-shuara","type":"section","seq":247,"chapter":"طبقات فحول الشعراء","title":"241- والرابع عبد بنى الحسحاس — وهو حلو الشعر رقيق حواشى الكلام","page":"ص0","text":"والرابع عبد بنى الحسحاس\nوهو حلو الشعر رقيق حواشى الكلام"},{"id":"tabaqat-shuara:248","bookId":"tabaqat-shuara","type":"section","seq":248,"chapter":"طبقات فحول الشعراء","title":"242- ذكروا عن عثمان بن عفان أنه أتى بعبد من عبيد العرب نافذ فأراد شراءه فقيل له إنه شاعر — قال لا","page":"ص0","text":"ذكروا عن عثمان بن عفان أنه أتى بعبد من عبيد العرب نافذ فأراد شراءه فقيل له إنه شاعر\nقال لا حاجة لى به إن الشاعر لا حريم له\nويقال إنه عبد بنى الحسحاس وذلك قبل خلافة عثمان"},{"id":"tabaqat-shuara:249","bookId":"tabaqat-shuara","type":"section","seq":249,"chapter":"طبقات فحول الشعراء","title":"243- وأنشد عمر بن الخطاب قوله —","page":"ص0","text":"وأنشد عمر بن الخطاب قوله\n(عميرة ودع إن تجهزت غاديا ... كفى الشيب والإسلام للمرء ناهيا)\nفقال لو قلت شعرك مثل هذا أعطيتك عليه\nفلما قال\n(فبات وسادانا إلي علجانة ... وحقف تهاداه الرياح تهاديا)\n(وهبت شمال آخر الليل قرة ... ولا ثوب إلا درعها وردائيا)\n(فما زال بردى طيبا من ثيابها ... إلى الحول حتى أنهج الثوب باليا)\nفقال له عمر ويلك إنك مقتول"},{"id":"tabaqat-shuara:250","bookId":"tabaqat-shuara","type":"section","seq":250,"chapter":"طبقات فحول الشعراء","title":"244- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(ولقد تحدر من كريمة بعضهم ... عرق على متن الفراش وطيب)\nفأخذوه شاربا ثملا فعرضوا عليه نسوة حتى مرت عليه التى يظنونها به فأهوى لها فأخذوه فقتلوه لما تحقق عندهم"},{"id":"tabaqat-shuara:251","bookId":"tabaqat-shuara","type":"section","seq":251,"chapter":"طبقات فحول الشعراء","title":"الطبقة العاشرة","page":"ص0","text":"وهى آخر الطبقات وهم أربعة رهط"},{"id":"tabaqat-shuara:252","bookId":"tabaqat-shuara","type":"section","seq":252,"chapter":"طبقات فحول الشعراء","title":"245- أولهم أمية بن حرثان بن الأسكر بن عبد الله سرابيل الموت كان شاعرا سيدا بن زهرة بن زبينة بن","page":"ص0","text":"أولهم أمية بن حرثان بن الأسكر بن عبد الله سرابيل الموت كان شاعرا سيدا بن زهرة بن زبينة بن جندع بن ليث بن بكرعبد مناة بن كنانة"},{"id":"tabaqat-shuara:253","bookId":"tabaqat-shuara","type":"section","seq":253,"chapter":"طبقات فحول الشعراء","title":"246- وحريث بن محفظ","page":"ص0","text":"وحريث بن محفظ"},{"id":"tabaqat-shuara:254","bookId":"tabaqat-shuara","type":"section","seq":254,"chapter":"طبقات فحول الشعراء","title":"247- والكميت بن معروف بن الكميت بن ثعلبة بن نوفل — ابن نضلة بن الأشتر بن جحوان بن فقعس بن طريف بن","page":"ص0","text":"والكميت بن معروف بن الكميت بن ثعلبة بن نوفل\nابن نضلة بن الأشتر بن جحوان بن فقعس بن طريف بن عمرو بن قعين بن الحارث بن ثعلبة بن دودان بن أسد بن خزيمة"},{"id":"tabaqat-shuara:255","bookId":"tabaqat-shuara","type":"section","seq":255,"chapter":"طبقات فحول الشعراء","title":"248- وعمرو بن شأس بن أبى بلى واسمه عبيد بن ثعلبة بن ذويبة بن مالك بن الحارث بن سعد بن ثعلبة بن","page":"ص0","text":"وعمرو بن شأس بن أبى بلى واسمه عبيد بن ثعلبة بن ذويبة بن مالك بن الحارث بن سعد بن ثعلبة بن دودان بن أسد ابن خزيمة"},{"id":"tabaqat-shuara:256","bookId":"tabaqat-shuara","type":"section","seq":256,"chapter":"طبقات فحول الشعراء","title":"249- وكان أمية بن حرثان بن الأسكر قديما وعمر فى الجاهلية عمرا طويلا وألفاه الإسلام هرما — وله شعر","page":"ص0","text":"وكان أمية بن حرثان بن الأسكر قديما وعمر فى الجاهلية عمرا طويلا وألفاه الإسلام هرما\nوله شعر فى الجاهلية وشعر في الإسلام"},{"id":"tabaqat-shuara:257","bookId":"tabaqat-shuara","type":"section","seq":257,"chapter":"طبقات فحول الشعراء","title":"250- وكان ابناه كلاب وأخوه هاجرا إلى البصرة أيام عمر بعدما كبر الشيخ وكف بصره فقال —","page":"ص0","text":"وكان ابناه كلاب وأخوه هاجرا إلى البصرة أيام عمر بعدما كبر الشيخ وكف بصره فقال\n(لمن شيخان قد نشدا كلابا ... كتاب الله إن حفظ الكتابا)\n(إذا هتفت حمامة بطن وج ... على بيضاتها ذكرا كلابا)\n(تركت أباك مرعشة يداه ... وأمك ما تسيغ لها شرابا)"},{"id":"tabaqat-shuara:258","bookId":"tabaqat-shuara","type":"section","seq":258,"chapter":"طبقات فحول الشعراء","title":"251- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(سأستأدى على الفاروق ربا ... له عمد الحجيج إلى بصاق)\n(إن الفاروق لم يردد كلابا ... إلى شيخين هامهما زواقى)\nفكتب عمر إلى أبى موسى بإشخاصه فلم يرع أمية إلا ببابه يقرع فقال إن كان كلاب فى الناس حيا إنه لهو"},{"id":"tabaqat-shuara:259","bookId":"tabaqat-shuara","type":"section","seq":259,"chapter":"طبقات فحول الشعراء","title":"252- وخطة كلاب بالبصرة فى بنى سليم يقال لها مربعة كلاب وتقول لها العامة مربعة الكلاب بلا علم","page":"ص0","text":"وخطة كلاب بالبصرة فى بنى سليم يقال لها مربعة كلاب وتقول لها العامة مربعة الكلاب بلا علم"},{"id":"tabaqat-shuara:260","bookId":"tabaqat-shuara","type":"section","seq":260,"chapter":"طبقات فحول الشعراء","title":"253- ومر بأمية غلام له وهو يحثو التراب على رأسه هرما ودلها فقام ينظر إليه فأفاق إفاقة فرآه قائم","page":"ص0","text":"ومر بأمية غلام له وهو يحثو التراب على رأسه هرما ودلها فقام ينظر إليه فأفاق إفاقة فرآه قائما ينظر إليه فقال\n(أصبحت فنا لراعى الضأن أعجبه ... ماذا يريبك منى راعى الضان)\n(إن ترع ضأنا فإنى قد رزئتهم ... بيض الوجوه بنى عم وإخوانى)\n(يا ابنى أمية إنى عنكما غانى ... وما غنائى إلا أننى فانى)\n(يا ابنى أمية إلا تشهدا كبرى ... فإن نأيكما والموت سيان)"},{"id":"tabaqat-shuara:261","bookId":"tabaqat-shuara","type":"section","seq":261,"chapter":"طبقات فحول الشعراء","title":"254- الثانى حريث بن محفظ المازنى وهو جاهلى إسلامى له فى الجاهلية أشعار — وهو الذى يقول —","page":"ص0","text":"الثانى حريث بن محفظ المازنى وهو جاهلى إسلامى له فى الجاهلية أشعار\nوهو الذى يقول\n(ونحن طردنا الحى بكر بن وائل ... إلى سنة مثل السنان ونار)\n(وموم وطاعون وحصبة قاتل ... وذى لبد يغشى المهجهج ضارى)\n(وحكم عدو لا هوادة عنده ... ومنزل ذل فى الحياة وعار)\nيعنى محل بكر بن وائل وهو السواد والسواد أوبأ البلاد على الرجال والإبل من البر\nوقوله وحكم عدو يعنى حكما للعجم على بكر بن وائل فذلك قوله وحكم عدو لا هوادة عنده"},{"id":"tabaqat-shuara:262","bookId":"tabaqat-shuara","type":"section","seq":262,"chapter":"طبقات فحول الشعراء","title":"255- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(تقول ابنة الضبى يوم لقيتها ... تغيرت حتى كدت منك أهال)\n(فإن تعجبى منى عمير فقد أتت ... ليال وأيام على طوال)\n(وإنى لمن قوم تشيب سراتهم ... كذاك وفيهم نائل وفعال)"},{"id":"tabaqat-shuara:263","bookId":"tabaqat-shuara","type":"section","seq":263,"chapter":"طبقات فحول الشعراء","title":"256- وقال —","page":"ص0","text":"وقال\n(ألم تر قومى إن دعاهم أخوهم ... أجابوا وإن يغضب على القوم يغضبوا)\n(هم حفظوا غيبى كما كنت حافظا ... لقومى أخرى مثلها إن تغيبوا)\n(بنو المجد لم تقعد بهم أمهاتهم ... وآباؤهم آباء صدق فأنجبوا)"},{"id":"tabaqat-shuara:264","bookId":"tabaqat-shuara","type":"section","seq":264,"chapter":"طبقات فحول الشعراء","title":"257- قال ابن دأب أدخل الحارث بن نوفل بن الحارث ابن عبد المطلب على معاوية فتيانا من فتيان بنى عب","page":"ص0","text":"قال ابن دأب أدخل الحارث بن نوفل بن الحارث ابن عبد المطلب على معاوية فتيانا من فتيان بنى عبد مناف فقال معاوية هؤلاء كما قال أخو بنى مازن\n(بنو المجد لم تقعد بهم أمهاتهم ... وآباؤهم أباء صدق فأنجبوا)"},{"id":"tabaqat-shuara:265","bookId":"tabaqat-shuara","type":"section","seq":265,"chapter":"طبقات فحول الشعراء","title":"258- قال أبو عبد الله قال الحجاج وهو على المنبر أنتم والله يا أهل الشأم كما قال القائل —","page":"ص0","text":"قال أبو عبد الله قال الحجاج وهو على المنبر أنتم والله يا أهل الشأم كما قال القائل\n(بنو المجد لم تقعد بهم أمهاتهم ... وآباؤهم آباء صدق فأنجبوا)\nوحريث تحت منبره فقال أنا قائله أيها الأمير\nفقال كذبت ذاك حريث بن محفظ\nقال أنا حريث قال فما حملك\nعلى الرد على هكذا قال ما ملكت حين تمثل الأمير بشعرى أن أخبرته بمكانى"},{"id":"tabaqat-shuara:266","bookId":"tabaqat-shuara","type":"section","seq":266,"chapter":"طبقات فحول الشعراء","title":"259- والثالث الكميت بن معروف وهو شاعر وجده الكميت بن ثعلبة شاعر وكميت بن زيد الآخر شاعر — والكميت","page":"ص0","text":"والثالث الكميت بن معروف وهو شاعر وجده الكميت بن ثعلبة شاعر وكميت بن زيد الآخر شاعر\nوالكميت ابن معروف الأوسط أشعرهم قريحة والكميت بن زيد أكثرهم شعرا"},{"id":"tabaqat-shuara:267","bookId":"tabaqat-shuara","type":"section","seq":267,"chapter":"طبقات فحول الشعراء","title":"260- قال الكميت بن معروف —","page":"ص0","text":"قال الكميت بن معروف\n(أقول لندمانى والحزن بيننا ... وغبر الأعالى من خفاف فوارع)\n(أنار بدت بين المسناة والحمى ... لعينيك أم برق من الليل لامع)\n(فإن يك برقا فهو برق مخيلة ... لها ريق لم يخلف الشيم رائع)\n(وإن تك نار فهى نار تشبها ... قلوص وتزها ها الرياح الزعازع)\n(وما مغزل أدماء مرتع طفلها ... أراك وسدر بالمراضين يانع)\n(بأحسن منها يوم قالت لتربها ... سليه يخبرنا متى هو راجع)\n(فقلت لها والله ما من مسافر ... يحيط له علم بما الله صانع)"},{"id":"tabaqat-shuara:268","bookId":"tabaqat-shuara","type":"section","seq":268,"chapter":"طبقات فحول الشعراء","title":"261- والرابع عمرو بن شأس كثير الشعر فى الجاهلية والإسلام أكثر أهل طبقته شعرا — وكان ذا قدر وشرف و","page":"ص0","text":"والرابع عمرو بن شأس كثير الشعر فى الجاهلية والإسلام أكثر أهل طبقته شعرا\nوكان ذا قدر وشرف ومنزلة فى قومه"},{"id":"tabaqat-shuara:269","bookId":"tabaqat-shuara","type":"section","seq":269,"chapter":"طبقات فحول الشعراء","title":"262- جاوره رجل من بنى عامر بن صعصعة ومع العامرى بنت له جميلة فخطبها فقال له العامرى أما ما دمت","page":"ص0","text":"جاوره رجل من بنى عامر بن صعصعة ومع العامرى بنت له جميلة فخطبها فقال له العامرى أما ما دمت في جوارك فلا تنزل منى على الاقتسار والقهر ولكن إذا رجعت إلى قومى فاخطبها\nفغضب عمرو وآلى يمينا أن لا يتزوجها أبدا إلا أن يصيبها سباء\nفلما رجع الرجل إلى قومه أراد عمرو غزوهم ثم قال قد كان بينى وبين الرجل عهد وميثاق وجوار فاستحي وتذمم أن يفعل وقال\n(إذا نحن أدلجنا وأنت أمامنا ... كفى لمطايانا برياك هاديا)\n(ولولا اتقاء الله والعهد قد رأى ... مبينة منا تثر النواديا)\n(ونحن بنو خير السباع أكيلة ... وأجحرة لما تحفظ عاديا)\n(لنا حاضر لم يحضر الناس مثله ... وباد إذا عدوا فأكرم باديا)"},{"id":"tabaqat-shuara:270","bookId":"tabaqat-shuara","type":"section","seq":270,"chapter":"طبقات فحول الشعراء","title":"263- قال ونزل رجل من بنى حنظلة بإبل له عظيمة فى جوار بنى سعد بن ثعلبة دودان بن اسد بن خزيمة رهط","page":"ج1 ص198","text":"قال ونزل رجل من بنى حنظلة بإبل له عظيمة فى جوار بنى سعد بن ثعلبة دودان بن اسد بن خزيمة رهط عمرو بن شأس فأقام فيهم سنوات ثم رحل عنهم\nفأغارت طيئ على إبله فذهبوا بها فرجع إلى بنى سعد بن ثعلبة فقال قد برئت ذمتكم ولكنى أصبت وقد عدت على طيئ فركب معه بنو سعد إلى طيئ فأخذوا أكثر إبله وأدوه إلى مأمنه فقال عمرو بن شأس\n(أبأنا لقاح الحنظلى بمثلها ... لقاحا وقلنا دونك ابن مكدم)\n(وفاء ولم تشرف عليه نفوسنا ... حناجرها كأنها صوغ حنتم)"},{"id":"tabaqat-shuara:271","bookId":"tabaqat-shuara","type":"section","seq":271,"chapter":"طبقات فحول الشعراء","title":"264- وكان لعمرو ابن يقال له عرار من أمه سوداء وكانت امرأته تؤذيه وتستخف به فقال عمرو فى كلمة له","page":"ج1 ص198","text":"وكان لعمرو ابن يقال له عرار من أمه سوداء وكانت امرأته تؤذيه وتستخف به فقال عمرو فى كلمة له\n(أرادت عرارا بالهوان ومن يرد ... عرارا لعمرى بالهوان فقد ظلم)\n(وإن عرارا إن يكن غير واضح ... فإنى أحب الجون ذا المنكب العمم)\n(وإن عرارا إن يكن ذا شكيمة ... تلقيتها منه فما أملك الشيم)\n(فإن كنت منى أو تريدين صحبتى ... فكونى له كالسمن ربت له الأدم)\n(وإلا فسيرى مثل ما سار راكب ... تعجل خمسا ليس فى سيره أمم)"},{"id":"tabaqat-shuara:272","bookId":"tabaqat-shuara","type":"section","seq":272,"chapter":"طبقات فحول الشعراء","title":"265- وقال عمرو فى كلمة له طويلة —","page":"ج1 ص200","text":"وقال عمرو فى كلمة له طويلة\n(متى تعرف العينان أطلال دمنة ... لليلى بأعلى ذى معارك تدمعا)\n(على النحر والسربال حتى تبله ... رشاشا ولم تجزع إلى الدار مجزعا)\n(خليلى عوجا اليوم نقض لبانة ... وإلا تعوجا اليوم لا ننطلق معا)\n(وإن تنظرانى اليوم أتبعكماغدا ... أذل قيادا من جنيب وأطوعا)\n(وقد زعما أن قد أمل عليهما ... ثوائى وقولى كلما ارتحلا اربعا)\n(وما لبث فى الحى يوما وليلة ... بزائد ما قد فات صيفا ومربعا)\n(فجودا لهند فى الكرامة منكما ... وإن شئتما أن تمنعا بعد فامنعا)"},{"id":"tabaqat-shuara:273","bookId":"tabaqat-shuara","type":"section","seq":273,"chapter":"طبقات فحول الشعراء","title":"266- انقضى خبر العشر الطبقات","page":"ص0","text":"انقضى خبر العشر الطبقات"},{"id":"tabaqat-shuara:274","bookId":"tabaqat-shuara","type":"section","seq":274,"chapter":"طبقات فحول الشعراء","title":"267- قال وصيرنا أصحاب المراثى طبقة بعد العشر الطبقات","page":"ص0","text":"قال وصيرنا أصحاب المراثى طبقة بعد العشر الطبقات"},{"id":"tabaqat-shuara:275","bookId":"tabaqat-shuara","type":"section","seq":275,"chapter":"طبقات فحول الشعراء","title":"268- أولهم متمم بن نويرة بن جمرة بن شداد بن عبيد بن ثعلبة بن يربوع رثى أخاه مالكا","page":"ص0","text":"أولهم متمم بن نويرة بن جمرة بن شداد بن عبيد بن ثعلبة بن يربوع رثى أخاه مالكا"},{"id":"tabaqat-shuara:276","bookId":"tabaqat-shuara","type":"section","seq":276,"chapter":"طبقات فحول الشعراء","title":"269- والخنساء بنت عمرو بن الحارث بن الشريد بن رياح بن يقظة بن عصية بن خفاف بن امرئ القيس بن بهث","page":"ص0","text":"والخنساء بنت عمرو بن الحارث بن الشريد بن رياح بن يقظة بن عصية بن خفاف بن امرئ القيس بن بهثة رثت أخويها صخرا ومعاوية"},{"id":"tabaqat-shuara:277","bookId":"tabaqat-shuara","type":"section","seq":277,"chapter":"طبقات فحول الشعراء","title":"270- وأعشى باهله واسمه عامر بن الحارث بن رياح بن عبد الله بن زيد بن عمرو بن سلامة بن ثعلبة بن و","page":"ص0","text":"وأعشى باهله واسمه عامر بن الحارث بن رياح بن عبد الله بن زيد بن عمرو بن سلامة بن ثعلبة بن وائل بن معن رثى المنتشر بن وهب بن عجلان بن سلمة بن كراثة بن هلال بن عمرو\nابن سلامة بن ثعلبة بن وائل بن معن"},{"id":"tabaqat-shuara:278","bookId":"tabaqat-shuara","type":"section","seq":278,"chapter":"طبقات فحول الشعراء","title":"271- وكعب بن سعد بن عمرو بن عقبة أو علقمة بن عوف بن رفاعة أحد بنى سالم بن عبيد بن سعد بن جلان ب","page":"ص0","text":"وكعب بن سعد بن عمرو بن عقبة أو علقمة بن عوف بن رفاعة أحد بنى سالم بن عبيد بن سعد بن جلان بن غنم بن غنى بن أعصر رثى أخاه أبا المغوار"},{"id":"tabaqat-shuara:279","bookId":"tabaqat-shuara","type":"section","seq":279,"chapter":"طبقات فحول الشعراء","title":"272- والمقدم عندنا متمم بن نويرة ويكنى أبا نهشل رثى أخاه مالك بن نويرة وكان قتله خالد بن الوليد","page":"ص0","text":"والمقدم عندنا متمم بن نويرة ويكنى أبا نهشل رثى أخاه مالك بن نويرة وكان قتله خالد بن الوليد بن المغيرة حين وجهه أبو بكر رضى الله عنه إلى أهل الردة\nفمن الحديث ما جاء على وجهه ومنه ما ذهب معناه علينا للاختلاف فيه\nوحديث مالك مما اختلف فيه فلم نقف منه على ما نريد\nوقد سمعت فيه أقاويل شتى غير أن الذى استقر عندنا أن عمر أنكر قتله وقام على خالد فيه وأغلط له وأن أبا بكر صفح عن خالد وقبل تأوله"},{"id":"tabaqat-shuara:280","bookId":"tabaqat-shuara","type":"section","seq":280,"chapter":"طبقات فحول الشعراء","title":"273- وكان مالك رجلا شريفا فارسا شاعرا وكانت فيه خيلاء وتقدم وكان ذا لمة كبيرة وكان يقال له الجف","page":"ص0","text":"وكان مالك رجلا شريفا فارسا شاعرا وكانت فيه خيلاء وتقدم وكان ذا لمة كبيرة وكان يقال له الجفول\nوقدم على النبى صلى الله عليه وسلم فيمن قدم من أمثاله من العرب فولاه صدقات قومه بنى يربوع\nفلما قبض النبى صلى الله عليه وسلم اضطرب فيها فلم يحمد أمره وفرق ما فى يديه من إبل الصدقة فكلمة الأقرع ابن حابس المجاشعى والقعقاع بن معبد بن زرارة الدارمى فقالا له إن لهذا الأمر قائما وطالبا فلا تعجل بتفرقة ما فى يديك\nفقال\n(أرانى الله بالنعم المندى ... ببرقة رحرحان وقد أرانى)\n(تمشى يا ابن عوذة فى تميم ... وصاحبك الأقيرع تلحيانى)\n(حميت جميعها بالسيف صلتا ... ولم ترعش يداى ولا بنانى)\nعوذة يعنى أم القعقاع وهى معاذة بنت ضرار بن عمرو"},{"id":"tabaqat-shuara:281","bookId":"tabaqat-shuara","type":"section","seq":281,"chapter":"طبقات فحول الشعراء","title":"274- وقال —","page":"ص0","text":"وقال\n(وقلت خذوا أموالكم غير خائف ... ولا ناظر فيما يجئ من الغد)\n(فإن قام بالأمر المخوف قائم ... منعنا وقلنا الدين دين محمد)"},{"id":"tabaqat-shuara:282","bookId":"tabaqat-shuara","type":"section","seq":282,"chapter":"طبقات فحول الشعراء","title":"275- فطرق خالد مالكا وقومه وهم على ماء لهم يقال له البعوضة تحت الليل فذعرهم وأخذوا السلاح — فكان","page":"ص0","text":"فطرق خالد مالكا وقومه وهم على ماء لهم يقال له البعوضة تحت الليل فذعرهم وأخذوا السلاح\nفكان فى حجة خالد عليهم أنه أنظرهم إلى وقت الأذان فلم يسمع أذانا\nوتقول بنو تميم\nإنه لما هجم عليهم خالد قال من أنتم قالوا المسلمون قال ونحن المسلمون فما بال السلاح قالوا ذعرتمونا قال فضعوا السلاح"},{"id":"tabaqat-shuara:283","bookId":"tabaqat-shuara","type":"section","seq":283,"chapter":"طبقات فحول الشعراء","title":"276- والمجتمع عليه أن خالدا حاوره وراده وأن مالكا سمح بالصلاة والتوى بالزكاة — فقال خالد أما علمت","page":"ص0","text":"والمجتمع عليه أن خالدا حاوره وراده وأن مالكا سمح بالصلاة والتوى بالزكاة\nفقال خالد أما علمت أن الصلاة والزكاة معا لا تقبل واحدة دون الأخرى قال قد كان يقول ذلك صاحبكم قال وما تراه لك صاحبا والله لقد هممت أن أضرب عنقك\nثم تحاولا فقال له خالد إنى قاتلك\nقال وبذا أمرك صاحبك قال وهذه بعد والله لا أقيلك"},{"id":"tabaqat-shuara:284","bookId":"tabaqat-shuara","type":"section","seq":284,"chapter":"طبقات فحول الشعراء","title":"277- فيقول من عذر مالكا أنه أراد بقوله صاحبك أنه أراد القرشية وتأول خالد غير ذلك فقال إنه إنكار","page":"ص0","text":"فيقول من عذر مالكا أنه أراد بقوله صاحبك أنه أراد القرشية وتأول خالد غير ذلك فقال إنه إنكار منه للنبوة\nوتقول بنو مخزوم إن عمرو بن العاص قال لخالد وقد كان لقيه وهو منصرف من عمان وكان النبى صلى الله عليه وسلم وجهه إلى ابن الجلندى فقال لخالد يا أبا سليمان إن رأت عينك مالكا فلا تزايله حتى تقتله"},{"id":"tabaqat-shuara:285","bookId":"tabaqat-shuara","type":"section","seq":285,"chapter":"طبقات فحول الشعراء","title":"278- وكان خالد يحتج على مالك بأشعاره التى كتبنا — وكلم أبو قتادة الأنصارى خالدا فى ذلك كلاما شديد","page":"ص0","text":"وكان خالد يحتج على مالك بأشعاره التى كتبنا\nوكلم أبو قتادة الأنصارى خالدا فى ذلك كلاما شديدا فلم يقبله فآلى يمينا أن لا يسير تحت راية أميرها خالد أبدا\nوقال له عبد الله بن عمر وهو فى القوم يومئذ يا خالد أبعد شهادة أبى قتادة فأعرض عنه\nثم عاوده فقال يا أبا عبد الرحمن اسكت عن هذا فإنى أعلم ما لا تعلم\nفأمر ضرار بن الأزور الأسدى بضرب عنقه ففعل"},{"id":"tabaqat-shuara:286","bookId":"tabaqat-shuara","type":"section","seq":286,"chapter":"طبقات فحول الشعراء","title":"279- قال ابن سلام سمعنى يونس يوما أراد التميمية فى خالد وأعذره فقال يا أبا عبد الله أما سمعت بس","page":"ص0","text":"قال ابن سلام سمعنى يونس يوما أراد التميمية فى خالد وأعذره فقال يا أبا عبد الله أما سمعت بساقى أم تميم وصارت أم تميم إلى خالد بنكاح أو سباء وعابه عليه عمر ابن الخطاب قال قتلت امرأ مسلما ووثبت على امرأته بعقرباء يوم بنى حنيفة"},{"id":"tabaqat-shuara:287","bookId":"tabaqat-shuara","type":"section","seq":287,"chapter":"طبقات فحول الشعراء","title":"280- قال ومن أحسن ما سمعت من عذر خالد ما ذكروا أن عمر قال لمتمم بن نويرة ما بلغ من جزعك على أخي","page":"ص0","text":"قال ومن أحسن ما سمعت من عذر خالد ما ذكروا أن عمر قال لمتمم بن نويرة ما بلغ من جزعك على أخيك وكان متمم\nأعور قال بكيت عليه بعينى الصحيحة حتى نفد ماؤها فأسعدتها أختها الذاهبة فقال عمر لو كنت شاعرا لقلت فى أخى أجود مما قلت\nقال يا أمير المؤمنين لو كان أخى أصيب مصاب أخيك ما بكيته\nفقال عمر ما عزانى أحد عنه بأحسن مما عزيتنى"},{"id":"tabaqat-shuara:288","bookId":"tabaqat-shuara","type":"section","seq":288,"chapter":"طبقات فحول الشعراء","title":"281- وبكى متمم مالكا فأكثر وأجاد والمقدمة منهن قوله —","page":"ص0","text":"وبكى متمم مالكا فأكثر وأجاد والمقدمة منهن قوله\n(لعمرى وما دهرى بتأبين هالك ... ولا جزع مما أصاب وأوجعا)\nقال ابن سلام وأخبرنى يونس بن حبيب أن التأبين مدح الميت والثناء عليه قال رؤبة\n(فامدح بلالا غير مامؤبن ... )\nوالمدح للحى"},{"id":"tabaqat-shuara:289","bookId":"tabaqat-shuara","type":"section","seq":289,"chapter":"طبقات فحول الشعراء","title":"282- وبكت الخنساء أخويها صخرا ومعاوية — فأما صخر فقتلته بنو أسد وأما معاوية فقتلته بنو مرة غطفان —","page":"ص0","text":"وبكت الخنساء أخويها صخرا ومعاوية\nفأما صخر فقتلته بنو أسد وأما معاوية فقتلته بنو مرة غطفان\nفقالت فى صخر كلمتها التى تقول فيها\n(وإن صخرا لتأتم الهداة به ... كأنه علم فى رأسه نار)\nوقالت فى معاوية\n(ألا ما لعينك أم مالها ... لقد أخضل الدمع سربالها)\nوقالت فى صخر الكلمة الأخرى\n(أمن حدث الأيام عينك تهمل ... وتبكى على صخر وفى الدهر مذهل)"},{"id":"tabaqat-shuara:290","bookId":"tabaqat-shuara","type":"section","seq":290,"chapter":"طبقات فحول الشعراء","title":"283- وأعشى باهله رثى المنتشر بن وهب الباهلى قتيل بنى الحارث بن كعب فقال فى كلمته —","page":"ص0","text":"وأعشى باهله رثى المنتشر بن وهب الباهلى قتيل بنى الحارث بن كعب فقال فى كلمته\n(لا يأمن الناس ممساه ومصبحه ... من كل أوب وإن لم يغز ينتظر)\n(لا يغمز الساق من أين ولا وجع ... ولا يزال أمام القوم يقتفر)\n(إنى أشد حزيمى ثم يدركنى ... منك البلاء ومن آلائك الذكر)\n(فإن جزعنا فمثل الشر أجزعنا ... وإن صبرنا فإنا معشر صبر)\n(إما سلكت سبيلا كنت سالكها ... فاذهب فلا يبعدنك الله منتشر)\n(لا يصعب الأمر إلا ريث يركبه ... وكل أمر سوى الفحشاء يأتمر)"},{"id":"tabaqat-shuara:291","bookId":"tabaqat-shuara","type":"section","seq":291,"chapter":"طبقات فحول الشعراء","title":"284- والرابع كعب بن سعد الغنوى رثى أخاه أبا المغوار بكلمة قال فيها —","page":"ج1 ص211","text":"والرابع كعب بن سعد الغنوى رثى أخاه أبا المغوار بكلمة قال فيها\n(فخبر تمانى أنما الموت بالقرى ... فكيف وهذى روضة وكثيب)\n(وماء سماء كان غير محمة ... بداوية تجرى عليه جنوب)\n(ومنزلة فى دار صدق وغبطة ... وما اقتال فى حكم على طبيب)\n(فلو كانت الموتى تباع اشتريته ... بما لم تكن عنه النفوس تطيب)\n(بعينى أو كلتا يدى وقيل لى ... هو الغانم الجذلان حين يؤوب)\n(وداع دعا يا من يجيب إلى الندى ... فلم يستجبه عند ذاك مجيب)\n(فقلت ادع أخرى وارفع الصوت دعوة ... لعل أبا المغوار منك قريب)"},{"id":"tabaqat-shuara:292","bookId":"tabaqat-shuara","type":"section","seq":292,"chapter":"طبقات فحول الشعراء","title":"285- وهى خمس المدينة ومكة والطائف واليمامة والبحرين — وأشعرهن قرية المدينة — شعراؤها الفحول خمسة ثل","page":"ج1 ص213","text":"وهى خمس المدينة ومكة والطائف واليمامة والبحرين\nوأشعرهن قرية المدينة\nشعراؤها الفحول خمسة ثلاثة من الخزرج واثنان من الأوس"},{"id":"tabaqat-shuara:293","bookId":"tabaqat-shuara","type":"section","seq":293,"chapter":"طبقات فحول الشعراء","title":"286- فمن الخزرج من بنى النجار حسان بن ثابت","page":"ج1 ص213","text":"فمن الخزرج من بنى النجار حسان بن ثابت"},{"id":"tabaqat-shuara:294","bookId":"tabaqat-shuara","type":"section","seq":294,"chapter":"طبقات فحول الشعراء","title":"287- ومن بنى سلمة كعب بن مالك","page":"ج1 ص213","text":"ومن بنى سلمة كعب بن مالك"},{"id":"tabaqat-shuara:295","bookId":"tabaqat-shuara","type":"section","seq":295,"chapter":"طبقات فحول الشعراء","title":"288- ومن بلحارث بن الخزرج عبد الله بن رواحة","page":"ج1 ص213","text":"ومن بلحارث بن الخزرج عبد الله بن رواحة"},{"id":"tabaqat-shuara:296","bookId":"tabaqat-shuara","type":"section","seq":296,"chapter":"طبقات فحول الشعراء","title":"289- ومن الأوس قيس بن الخطيم من بنى ظفر","page":"ج1 ص213","text":"ومن الأوس قيس بن الخطيم من بنى ظفر"},{"id":"tabaqat-shuara:297","bookId":"tabaqat-shuara","type":"section","seq":297,"chapter":"طبقات فحول الشعراء","title":"290- وأبو قيس بن الأسلت من بنى عمرو بن عوف","page":"ج1 ص213","text":"وأبو قيس بن الأسلت من بنى عمرو بن عوف"},{"id":"tabaqat-shuara:298","bookId":"tabaqat-shuara","type":"section","seq":298,"chapter":"طبقات فحول الشعراء","title":"291- أشعرهم حسان بن ثابت — وهو كثير الشعر جيدة وقد حمل عليه ما لم يحمل على أحد — لما تعاضهت قريش وا","page":"ج1 ص213","text":"أشعرهم حسان بن ثابت\nوهو كثير الشعر جيدة وقد حمل عليه ما لم يحمل على أحد\nلما تعاضهت قريش واستبت وضعوا عليه أشعارا كثيرة لا تنقى"},{"id":"tabaqat-shuara:299","bookId":"tabaqat-shuara","type":"section","seq":299,"chapter":"طبقات فحول الشعراء","title":"292- وكان أبوه ثابت بن المنذر بن حرام من سادة قومه وأشرافهم — والمنذر الحاكم بين الأوس والخزرج فى","page":"ص0","text":"وكان أبوه ثابت بن المنذر بن حرام من سادة قومه وأشرافهم\nوالمنذر الحاكم بين الأوس والخزرج فى يوم سميحة وهو يوم من أيامهم مشهور وكانوا حكموا فى دمائهم يومئذ مالك بن العجلان بن سالم بن عوف فتعدى فى مولى له قتل يومئذ وقال لا آخذ فيه إلا دية الصريح\nفأبوا أن يرضوا بحكمه فحكموا المنذر بن حرام فحكم بأن هدر دماء قومه الخزرج واحتمل دماء الأوس فذكره حسان فى شعره فى قصيدته التى قال فيها\n(منع النوم بالعشاء الهموم ... )"},{"id":"tabaqat-shuara:300","bookId":"tabaqat-shuara","type":"section","seq":300,"chapter":"طبقات فحول الشعراء","title":"293- وأسرت مزينة ثابتا أبا حسان فعرض عليهم الفداء فقالوا لا نفاديك إلا بتيس ومزينة تسب بالتيوس","page":"ص0","text":"وأسرت مزينة ثابتا أبا حسان فعرض عليهم الفداء فقالوا لا نفاديك إلا بتيس ومزينة تسب بالتيوس فأبى وأبوا\nفلما طال مكثه أرسل إلى قومه أن أعطوهم أخاهم وخذوا أخاكم"},{"id":"tabaqat-shuara:301","bookId":"tabaqat-shuara","type":"section","seq":301,"chapter":"طبقات فحول الشعراء","title":"294- وحدثنى يزيد بن عياض بن جعدبه أن النبى صلى الله عليه وسلم — لما قدم المدينة تناولته قريش باله","page":"ص0","text":"وحدثنى يزيد بن عياض بن جعدبه أن النبى صلى الله عليه وسلم\nلما قدم المدينة تناولته قريش بالهجاء فقال لعبد الله بن رواحة رد عنى\nفذهب فى قديمهم وأولهم فلم يصنع فى الهجاء شيئا\nفأمر كعب ابن مالك فذكر الحرب كقوله\n(نصل السيوف إذا قصرن بخطونا ... قدما ونلحقها إذا لم تلحق)\nفلم يصنع فى الهجاء شيئا\nفدعا حسان بن ثابت فقال اهجهم وائت أبا بكر يخبرك أى بمعائب القوم\nوكان أبو بكر علامة قريش وكان جبير بن مطعم أخذ العلم عن أبى بكر"},{"id":"tabaqat-shuara:302","bookId":"tabaqat-shuara","type":"section","seq":302,"chapter":"طبقات فحول الشعراء","title":"295- شعبة عن عدى بن ثابت الأنصارى أنه سمع البراء بن عازب الأنصارى يقول قال رسول الله صلى الله ع","page":"ص0","text":"شعبة عن عدى بن ثابت الأنصارى أنه سمع البراء بن عازب الأنصارى يقول قال رسول الله صلى الله عليه وسلم اهجهم أو هاجهم وجبريل معك"},{"id":"tabaqat-shuara:303","bookId":"tabaqat-shuara","type":"section","seq":303,"chapter":"طبقات فحول الشعراء","title":"296- قال ابن جعدبه فى حديثه وأخرج حسان لسانه حتى ضرب به على صدره وقال والله يا رسول الله ما أحب","page":"ص0","text":"قال ابن جعدبه فى حديثه وأخرج حسان لسانه حتى ضرب به على صدره وقال والله يا رسول الله ما أحب أن لى به مقولا فى العرب\nفصب على قريش منه شآبيب شر فقال رسول الله صلى الله عليه وسلم اهجهم كأنك تنضحهم بالنبل"},{"id":"tabaqat-shuara:304","bookId":"tabaqat-shuara","type":"section","seq":304,"chapter":"طبقات فحول الشعراء","title":"297- ومن شعره الرائع الجيد ما مدح به بنى جفنة من غسان ملوك الشام فى كلمة —","page":"ص0","text":"ومن شعره الرائع الجيد ما مدح به بنى جفنة من غسان ملوك الشام فى كلمة\n(لله در عصابة نادمتهم ... يوما بجلق فى الزمان الأول)\n(يسقون من ورد البريص عليهم ... بردى يصفق بالرحيق السلسل)\n(يغشون حتى ما تهر كلابهم ... لا يسألون عن السواد المقبل)\n(أولاد جفنة عند قبر أبيهم ... قبر ابن مارية الكريم المفضل)"},{"id":"tabaqat-shuara:305","bookId":"tabaqat-shuara","type":"section","seq":305,"chapter":"طبقات فحول الشعراء","title":"298- وقال فى الكلمة الأخرى الطويلة —","page":"ص0","text":"وقال فى الكلمة الأخرى الطويلة\n(لنا الجفنات الغر يلمعن بالضحى ... وأسيافنا يقطرن من نجدة دما)\n(أبى فعلنا المعروف أن ننطق الخنا ... وقائلنا بالعرف إلا تكلما)"},{"id":"tabaqat-shuara:306","bookId":"tabaqat-shuara","type":"section","seq":306,"chapter":"طبقات فحول الشعراء","title":"299- وقوله —","page":"ص0","text":"وقوله\n(وإن امرء أمسى وأصبح سالما ... من الناس إلا ما جنى لسعيد)"},{"id":"tabaqat-shuara:307","bookId":"tabaqat-shuara","type":"section","seq":307,"chapter":"طبقات فحول الشعراء","title":"300- ولما قال للحارث بن عوف بن أبى حارثة المرى —","page":"ص0","text":"ولما قال للحارث بن عوف بن أبى حارثة المرى\n(وأمانة المرى حيث لقيته ... مثل الزجاجة صدعها لم يجبر)\nقال الحارث يا محمد أجرنى من شعر حسان فوالله لو مزج به ماء البحر مزجه"},{"id":"tabaqat-shuara:308","bookId":"tabaqat-shuara","type":"section","seq":308,"chapter":"طبقات فحول الشعراء","title":"301- وأشعار حسان وأحاديثه كثيرة","page":"ص0","text":"وأشعار حسان وأحاديثه كثيرة"},{"id":"tabaqat-shuara:309","bookId":"tabaqat-shuara","type":"section","seq":309,"chapter":"طبقات فحول الشعراء","title":"302- وكعب بن مالك شاعر مجيد — قال يوم أحد فى كلمة —","page":"ص0","text":"وكعب بن مالك شاعر مجيد\nقال يوم أحد فى كلمة\n(فجئنا إلى موج من البحر وسطه ... أحابيش منهم حاسر ومقنع)\n(ثلاثة آلاف ونحن نصية ... ثلاث مئين إن كثرنا وأربع)\nوكانوا سبعمئة\n(فراحوا سراعا موجفين كأنهم ... جهام هراقت ماءه الريح مقلع)\n(ورحنا وأخرانا تطانا كأننا ... أسود على لحم ببيشة ظلع)"},{"id":"tabaqat-shuara:310","bookId":"tabaqat-shuara","type":"section","seq":310,"chapter":"طبقات فحول الشعراء","title":"303- وقال كعب فى أيام الخندق —","page":"ص0","text":"وقال كعب فى أيام الخندق\n(من سرة ضرب يرعبل بعضه ... بعضا كمعمعة الأباء المحرق)\n(فليأت مأسدة تسل سيوفها ... بين المذاد وبين جزع الخندق)"},{"id":"tabaqat-shuara:311","bookId":"tabaqat-shuara","type":"section","seq":311,"chapter":"طبقات فحول الشعراء","title":"304- وقال بعد ذلك فى كلمة أيضا —","page":"ص0","text":"وقال بعد ذلك فى كلمة أيضا\n(قضينا من تهامة كل ريب ... وخيبر ثم أجممنا السيوفا)\n(نخيرها ولو نطقت لقالت ... قواطعن دوسا أو ثقيفا)\n(فلست لحاصن إن لم تروها ... بساحة داركم منا ألوفا)\n(فننتزع العروش ببطن وج ... ونترك داركم منا خلوفا)\n(ونردى اللات والعزى وودا ... ونسلبها القلائد والشنوفا)"},{"id":"tabaqat-shuara:312","bookId":"tabaqat-shuara","type":"section","seq":312,"chapter":"طبقات فحول الشعراء","title":"305- حدثنى عمر بن معاذ التيمى المعمرى وغيره قال قال رسول الله صلى الله عليه وسلم لكعب بن مالك أ","page":"ص0","text":"حدثنى عمر بن معاذ التيمى المعمرى وغيره قال قال رسول الله صلى الله عليه وسلم لكعب بن مالك أترى الله نسى لك قولك\n(زعمت سخينة أن ستغلب ربها ... وليغلبن مغالب الغلاب)"},{"id":"tabaqat-shuara:313","bookId":"tabaqat-shuara","type":"section","seq":313,"chapter":"طبقات فحول الشعراء","title":"306- وكان أحد الثلاثة الذين تخلفوا عن تبوك هو وهلال ابن أمية ومرارة بن الربيع فتاب الله عليهم ك","page":"ص0","text":"وكان أحد الثلاثة الذين تخلفوا عن تبوك هو وهلال ابن أمية ومرارة بن الربيع فتاب الله عليهم كما قص فى سورة براءة\nيروى أن قومه قالوا فى ذلك لو اعتذرت إلى رسول الله\nصلى الله عليه وسلم ما يعتذر به الناس عذرك\nقال إنى لأصنعهم لسانا وأقدرهم على ذلك ولكن والله لا أعتذر إليه بكذب وإن عذرنى فيطلعه الله عليه\nفيقال إن الله عز وجل أنزل فيه {يا أيها الذين آمنوا اتقوا الله وكونوا مع الصادقين} وشهد العقبة ولم يشهد بدرا"},{"id":"tabaqat-shuara:314","bookId":"tabaqat-shuara","type":"section","seq":314,"chapter":"طبقات فحول الشعراء","title":"307- وعبد الله بن رواحة عظيم القدر فى قومه سيد فى الجاهلية ليس فى طبقته التى ذكرنا أسود منه — شهد","page":"ص0","text":"وعبد الله بن رواحة عظيم القدر فى قومه سيد فى الجاهلية ليس فى طبقته التى ذكرنا أسود منه\nشهد بدرا\nوكان فى حروبهم فى الجاهلية يناقض قيس بن الخطيم\nوكان فى الإسلام عظيم القدر والمكانة عند رسول الله صلى الله عليه وسلم"},{"id":"tabaqat-shuara:315","bookId":"tabaqat-shuara","type":"section","seq":315,"chapter":"طبقات فحول الشعراء","title":"308- وقال عبد الله بن رواحة وهو آخذ بزمام ناقة رسول الله صلى الله عليه وسلم فى عمرة القضاء يقود","page":"ص0","text":"وقال عبد الله بن رواحة وهو آخذ بزمام ناقة رسول الله صلى الله عليه وسلم فى عمرة القضاء يقودها وقد اجتمع أهل مكة وغلمانهم ينظرون إليه وهو يقول\n(خلوا بنى الكفار عن سبيله ... خلوا فكل الخير مع رسوله)\n(نحن ضربنا كم على تأويله ... كما ضربنا كم على تنزيله)\n(ضربا يزيل الهام عن مقيله ... ويذهل الخليل عن خليله)"},{"id":"tabaqat-shuara:316","bookId":"tabaqat-shuara","type":"section","seq":316,"chapter":"طبقات فحول الشعراء","title":"309- وأرسل رسول الله صلى الله عليه وسلم عبد الله بن رواحة منصرفه من العمرة فخرص على أهل خيبر فق","page":"ص0","text":"وأرسل رسول الله صلى الله عليه وسلم عبد الله بن رواحة منصرفه من العمرة فخرص على أهل خيبر فقال لهم لما شكوا الخرص فنحن نأخذها بذلك\nقالوا بهذا قامت السموات والأرض"},{"id":"tabaqat-shuara:317","bookId":"tabaqat-shuara","type":"section","seq":317,"chapter":"طبقات فحول الشعراء","title":"310- وقد روى عمر بن أبى زائدة قال سمعت مدرك بن عمارة ابن عقبة بن أبى معيط يقول قال عبد الله بن","page":"ص0","text":"وقد روى عمر بن أبى زائدة قال سمعت مدرك بن عمارة ابن عقبة بن أبى معيط يقول قال عبد الله بن رواحة مررت بمسجد رسول الله صلى الله عليه وسلم وهو فى نفر من أصحابه فأضب القوم يا عبد الله بن رواجة يا عبد الله بن رواحة فعرفت أن رسول الله صلى الله عليه وسلم دعانى فانطلقت إليهم مسرعا فسلمت فقال ههنا\nفجلست بين يديه فقال كأنه يتعجب من شعري كيف تقول الشعر إذا قلته قلت أنظر فى ذلك ثم أقول\nقال فعليك بالمشركين\nقال فلم أكن أعددت شيئا فأنشدته فلما قلت\n(فخبرونى أثمان العباء متى ... كنتم بطاريق أودانت لكم مضر)\nقال فكأنى عرفت فى وجه رسول الله صلى الله عليه وسلم الكراهة إذ جعلت قومه أثمان العباء فقلت\n(نجالد الناس عن عرض فنأسرهم ... فينا النبى وفينا تنزل السور)\n(وقد علمتم بأنا ليس غالبنا ... حى من الناس إن عزوا وإن كثروا)\n(يا هاشم الخير إن الله فضلكم ... على البرية فضلا ماله غير)\n(إنى تفرست فيك الخير أعرفه ... فراسة خالفتهم فى الذى نظروا)\n(ولو سألت أو استنصرت بعضهم ... فى جل أمرك ما آوو وما نصروا)\n(فثبت الله ما آتاك من حسن ... تثبيت موسى ونصرا كالذى نصروا)\nفأقبل على بوجهه مبتسما\nثم قال وإياك فثبت الله"},{"id":"tabaqat-shuara:318","bookId":"tabaqat-shuara","type":"section","seq":318,"chapter":"طبقات فحول الشعراء","title":"311- وأرسله رسول الله صلى الله عليه وسلم إلى مؤتة ثالث ثلاثة أمراء زيد بن حارثة وجعفر بن أبى طا","page":"ص0","text":"وأرسله رسول الله صلى الله عليه وسلم إلى مؤتة ثالث ثلاثة أمراء زيد بن حارثة وجعفر بن أبى طالب وابن رواحة\nفلما قتل صاحباه كأنه تكره الإقدام فقال\n(أقسمت يا نفس لتنزلنه ... طائعة أو لا لتكرهنه)\n(وطالما قد كنت مطمئنة ... مالى أراك تكرهين الجنة)\nفقتل يومئذ"},{"id":"tabaqat-shuara:319","bookId":"tabaqat-shuara","type":"section","seq":319,"chapter":"طبقات فحول الشعراء","title":"312- وأبو قيس بن الأسلت وهو شاعر مجيد وهو الذى يقول فى حرب بينهم وبين الخزرج —","page":"ص0","text":"وأبو قيس بن الأسلت وهو شاعر مجيد وهو الذى يقول فى حرب بينهم وبين الخزرج\n(قد حصت البيضة رأسى فما ... أطعم نوما غير تهجاع)\n(أسعى على جل بنى مالك ... كل امرئ فى شأنه ساع)"},{"id":"tabaqat-shuara:320","bookId":"tabaqat-shuara","type":"section","seq":320,"chapter":"طبقات فحول الشعراء","title":"313- وهو يقول في قصيدة —","page":"ص0","text":"وهو يقول في قصيدة\n(فلست لحاصن إن لم ترونا ... نجالد كم كأنا شرب خمر)\n(ملكنا الناس قد علمت معد ... فلم نغلب ولم نسبق بوتر)\n(هممنا بالإقامة ثم سرنا ... مسير حذيفة الخير بن بدر)"},{"id":"tabaqat-shuara:321","bookId":"tabaqat-shuara","type":"section","seq":321,"chapter":"طبقات فحول الشعراء","title":"314- وذكروا أنه أقبل يريد النبى صلى الله عليه وسلم فقال له عبد الله ابن أبى خفت والله سيوف الخز","page":"ص0","text":"وذكروا أنه أقبل يريد النبى صلى الله عليه وسلم فقال له عبد الله ابن أبى خفت والله سيوف الخزرج قال لا جرم والله لا أسلم حولا\nفمات فى الحول"},{"id":"tabaqat-shuara:322","bookId":"tabaqat-shuara","type":"section","seq":322,"chapter":"طبقات فحول الشعراء","title":"315- قيس بن الخطيم شاعر فمن الناس من يفضله على حسان شعرا ولا أقول ذلك","page":"ص0","text":"قيس بن الخطيم شاعر فمن الناس من يفضله على حسان شعرا ولا أقول ذلك"},{"id":"tabaqat-shuara:323","bookId":"tabaqat-shuara","type":"section","seq":323,"chapter":"طبقات فحول الشعراء","title":"316- وهو الذى يقول يوم بعاث —","page":"ص0","text":"وهو الذى يقول يوم بعاث\n(أتعرف رسما كاطراد المذاهب ... لعمرة قفرا غير موقف راكب)\nعمرة بنت رواحة أخت عبد الله بن رواحة وهى أم النعمان ابن بشير الأنصارى\n(ديار التى كادت ونحن على منى ... تحل بنا لولا نجاء الركائب)\n(تراءت لنا كالشمس تحت غمامة ... بدا حاجب منها وضنت بحاجب)\n(ولم أرها إلا ثلاثا على منى ... وعهدى بها عذراء ذات ذوائب)\n(ومثلك قد أصبيت ليست بكنة ... ولا جارة ولا حليلة صاحب)\n(أربت بدفع الحرب حتى رأيتها ... على الدفع لا تزداد غير تقارب)\n(فلما رأيت الحرب حربا تجردت ... لبست مع البردين ثوب المحارب)\n(مضاعفة يغشى الأنامل ريعها ... كأن قتيرها عيون الجنادب)\n(إذا ما فررنا كان أسوأ فرنا ... صدود الخدود وازورار المناكب)"},{"id":"tabaqat-shuara:324","bookId":"tabaqat-shuara","type":"section","seq":324,"chapter":"طبقات فحول الشعراء","title":"317- وهو الذى يقول —","page":"ص0","text":"وهو الذى يقول\n(تراءت لنا يوم الرحيل بمقلتى ... غرير بملتف من السدر مفرد)\n(وجيد كجيد الرئم حال يزينه ... على النحر منظوم وفصل زبرجد)\n(كأن الثريا فوق ثغرة نحرها ... توقد فى الظلماء أى توقد)\n(وإنى لأغنى الناس عن متكلف ... يرى الناس ضلالا وليس بمهتدى)\n(أكثر أهلى من عيال سواهم ... وأطوى على الماء القراح المبرد)"},{"id":"tabaqat-shuara:325","bookId":"tabaqat-shuara","type":"section","seq":325,"chapter":"طبقات فحول الشعراء","title":"318- وقال —","page":"ص0","text":"وقال\n(طعنت ابن عبد القيس طعنة ثائر ... لها نفذ لولا الشعاع أضاءها)"},{"id":"tabaqat-shuara:326","bookId":"tabaqat-shuara","type":"section","seq":326,"chapter":"طبقات فحول الشعراء","title":"319- وكان قيس مقيما على شركه وأسلمت امرأته وكان يقال لها حواء فكان يصدها عن الإسلام ويعبث بها ي","page":"ص0","text":"وكان قيس مقيما على شركه وأسلمت امرأته وكان يقال لها حواء فكان يصدها عن الإسلام ويعبث بها يأتيها وهى ساجدة فيقلبها على رأسها\nوكان رسول الله صلى الله عليه وسلم وهو بمكة قبل\nالهجرة يسأل عن أمر الأنصار وعن حالهم فأخبر بإسلامها وما تلقى من قيس\nفلما كان الموسم أتاه صلى الله عليه وسلم فى مضربه فلما رأى النبى صلى الله عليه وسلم رحب به وأعظمه\nفقال النبى صلى الله عليه وسلم إن امرأتك قد أسلمت وإنك تؤذيها فأحب أن لا تعرض لها\nقال نعم وكرامة يا أبا القاسم لست بعائد فى شئ تكرهه\nفلما قدم المدينة قال لها إن صاحبك قد لقينى فطلب إلى أن لا أعرض لك فشأنك وأمرك"},{"id":"tabaqat-shuara:327","bookId":"tabaqat-shuara","type":"section","seq":327,"chapter":"طبقات فحول الشعراء","title":"320- وبمكة شعراء فأبرعهم شعرا","page":"ج1 ص231","text":"وبمكة شعراء فأبرعهم شعرا"},{"id":"tabaqat-shuara:328","bookId":"tabaqat-shuara","type":"section","seq":328,"chapter":"طبقات فحول الشعراء","title":"321- عبد الله بن الزبعرى بن قيس بن عدى بن سعد بن سهم","page":"ج1 ص231","text":"عبد الله بن الزبعرى بن قيس بن عدى بن سعد بن سهم"},{"id":"tabaqat-shuara:329","bookId":"tabaqat-shuara","type":"section","seq":329,"chapter":"طبقات فحول الشعراء","title":"322- وأبو طالب بن عبد المطلب شاعر","page":"ج1 ص231","text":"وأبو طالب بن عبد المطلب شاعر"},{"id":"tabaqat-shuara:330","bookId":"tabaqat-shuara","type":"section","seq":330,"chapter":"طبقات فحول الشعراء","title":"323- والزبير بن عبد المطلب شاعر","page":"ج1 ص231","text":"والزبير بن عبد المطلب شاعر"},{"id":"tabaqat-shuara:331","bookId":"tabaqat-shuara","type":"section","seq":331,"chapter":"طبقات فحول الشعراء","title":"324- وأبو سفيان بن الحارث شاعر","page":"ج1 ص231","text":"وأبو سفيان بن الحارث شاعر"},{"id":"tabaqat-shuara:332","bookId":"tabaqat-shuara","type":"section","seq":332,"chapter":"طبقات فحول الشعراء","title":"325- ومسافر بن أبى عمرو بن أمية شاعر","page":"ج1 ص231","text":"ومسافر بن أبى عمرو بن أمية شاعر"},{"id":"tabaqat-shuara:333","bookId":"tabaqat-shuara","type":"section","seq":333,"chapter":"طبقات فحول الشعراء","title":"326- وضرار بن الخطاب الفهرى شاعر","page":"ج1 ص231","text":"وضرار بن الخطاب الفهرى شاعر"},{"id":"tabaqat-shuara:334","bookId":"tabaqat-shuara","type":"section","seq":334,"chapter":"طبقات فحول الشعراء","title":"327- وأبو عزة الجمحى شاعر واسمه عمرو بن عبد الله","page":"ص0","text":"وأبو عزة الجمحى شاعر واسمه عمرو بن عبد الله"},{"id":"tabaqat-shuara:335","bookId":"tabaqat-shuara","type":"section","seq":335,"chapter":"طبقات فحول الشعراء","title":"328- وعبد الله بن حذافة السهمى الممزق","page":"ص0","text":"وعبد الله بن حذافة السهمى الممزق"},{"id":"tabaqat-shuara:336","bookId":"tabaqat-shuara","type":"section","seq":336,"chapter":"طبقات فحول الشعراء","title":"329- وهبيرة بن أبى وهب بن عامر بن عائذ بن عمران بن مخزوم","page":"ص0","text":"وهبيرة بن أبى وهب بن عامر بن عائذ بن عمران بن مخزوم"},{"id":"tabaqat-shuara:337","bookId":"tabaqat-shuara","type":"section","seq":337,"chapter":"طبقات فحول الشعراء","title":"330- قال حدثنى شعيب بن صخر وأبو بكر الزبيرى المصعبى قال أصبح الناس يوما بمكة وعلى دار الندوة مك","page":"ص0","text":"قال حدثنى شعيب بن صخر وأبو بكر الزبيرى المصعبى قال أصبح الناس يوما بمكة وعلى دار الندوة مكتوب\n(ألهى قصيا عن المجد الأساطير ... ورشوة مثل ما ترشى السفاسير)\n(وأكلها اللحم بحتا لا خليط له ... وقولها رحلت عير مضت عير)\nفأنكر الناس ذلك وقالوا ما قالها إلا ابن الزبعرى أجمع على ذلك رأيهم فمشوا إلى بنى سهم وكان مما تنكر قريش وتعاقب عليه أن يهجو بعضها بعضا فقالوا لبنى سهم ادفعوه إلينا نحكم فيه بحكمنا\nقالوا وما الحكم فيه قالوا نقطع لسانه قالوا فشأنكم واعلموا والله أنه لا يهجونا رجل منكم إلا فعلنا به مثل ذلك\nوالزبير\nابن عبد المطلب يومئذ غائب نحو اليمن فانتجت بنو قصى بينهم فقالوا لا نأمن الزبير إن بلغه ما قال هذا أن يقول شيئا فيؤتى إليه مثل ما نأتى إلى هذا وكانوا أهل تناصف فأجمعوا على تخليته فخلوه\nفقال له الناس وحملوه على قومه أسلمك قومك ولم يمنعوك ولو شاؤوا منعوك فقال\n(لعمرك ما جاءت بنكر عشيرتى ... وإن صالحت إخوانها لا ألومها)\n(بود جناة الغى أن سيوفنا ... بأيماننا مسلولة لا نشيمها)"},{"id":"tabaqat-shuara:338","bookId":"tabaqat-shuara","type":"section","seq":338,"chapter":"طبقات فحول الشعراء","title":"331- وقال فى يوم أحد قصيدة يقول فيها —","page":"ج1 ص236","text":"وقال فى يوم أحد قصيدة يقول فيها\n(كل بؤس ونعيم زائل ... وبنات الدهر يلعبن بكل)\n(والعطيات خساس بيننا ... وسواء رمس مثر ومقل)\n(ليت أشياخى ببدر شهدوا ... ضجر الخزرج من وقع الأسل)\n(حين ألقت بقناة بركها ... واستحر القتل فى عبد الأشل)\n(فقبلنا النصف من سادتهم ... وعدلنا ميل بدر فاعتدل)\nوزعم ابن جعدبة أنه سمع هشام بن عروة ينشد هذا الشعر وسمعته قال عنه رويته"},{"id":"tabaqat-shuara:339","bookId":"tabaqat-shuara","type":"section","seq":339,"chapter":"طبقات فحول الشعراء","title":"332- وقال ابن الزبعرى لبنى المغيرة بن عبد الله المخزوميين وكان لهم بلاء فى الفجار وأمهم ريطة بن","page":"ج1 ص239","text":"وقال ابن الزبعرى لبنى المغيرة بن عبد الله المخزوميين وكان لهم بلاء فى الفجار وأمهم ريطة بنت سعيد بن سعد ابن سهم فقال\n(ألا لله قوم ولدت أخت بنى سهم ... )\n(هشام وأبو عبد مناف مدره الخصم ... )\n(وذو الرمحين أشباك من القوة والحزم ... )\n(فهذان يذودان وذا من كثب يرمى ... )\n(وإن احلف وبيت الله لا أحلف على إثم ... )\n(لما إن إخوة بين ... دروب الروم والردم)\n(بأزكى من بنى ريطة أو أوزن فى حلم ... )\n(هم يوم عكاظ ... منعوا الناس من الهزم)\nوقال كان الفزارى ينشدها هشاما وأبا عبد مناف أى ولدت\nوأبو عبد مناف هاشم بن المغيرة جد عمر بن الخطاب لأمة أمه حنتمة بنت هاشم بن المغيرة\nوذو الرمحين أبو ربيعة بن المغيرة أبو عبد الله وعياش ابنى أبى ربيعة"},{"id":"tabaqat-shuara:340","bookId":"tabaqat-shuara","type":"section","seq":340,"chapter":"طبقات فحول الشعراء","title":"333- ثم أسلم ابن الزبعرى ومدح النبى صلى الله عليه وسلم واعتذر إليه فأحسن فقال —","page":"ج1 ص241","text":"ثم أسلم ابن الزبعرى ومدح النبى صلى الله عليه وسلم واعتذر إليه فأحسن فقال\n(يا رسول المليك إن لسانى ... راتق مافتقت إذ أنا بور)\n(إذ أجارى الشيطان فى سنن الغى ... ومن مال ميلة مثبور)\n(آمن اللحم والعظام بما قلت فنفسى الفدى وأنت النذير ... )"},{"id":"tabaqat-shuara:341","bookId":"tabaqat-shuara","type":"section","seq":341,"chapter":"طبقات فحول الشعراء","title":"334- وقال أيضا —","page":"ج1 ص241","text":"وقال أيضا\n(منع الرقاد بلابل وهموم ... والليل معتلج الرواق بهيم)\n(مم أتانى أن أحمد لامنى ... فيه فبت كأننى محموم)\n(يا خير من حملت على أوصالها ... عيرانة سرح اليدين رسوم)\n(إنى لمعتذر إليك من الذى ... أسديت إذا أنا نافى الضلال أهيم)\n(أيام تأمرنى بأغوى خطة ... سهم وتأمرنى بها مخزوم)\n(فاغفر فدى لك والداى كلاهما ... ذنبى فإنك راحم مرحوم)\n(وعليك من أثر المليك علامة ... نور أضاء وخاتم مختوم)\n(مضت العداوة فانقضت أسبابها ... ودعت أواصر بيننا وحلوم)"},{"id":"tabaqat-shuara:342","bookId":"tabaqat-shuara","type":"section","seq":342,"chapter":"طبقات فحول الشعراء","title":"335- وحدثنى ابن جعدبه قال قدم ضرار بن الخطاب الفهرى وعبد الله بن الزبعرى المدينة أيام عمر بن ال","page":"ص0","text":"وحدثنى ابن جعدبه قال قدم ضرار بن الخطاب الفهرى وعبد الله بن الزبعرى المدينة أيام عمر بن الخطاب فأتيا أبا أحمد بن جحش الأسدى وكان مكفوفا وكان مألفا يجتمع إليه ويتحدث عنده ويقول الشعر فقالا له أتيناك لترسل إلى حسان بن ثابت فنناشده ونذاكره فإنه كان يقول فى الإسلام ويقول فى الكفر\nفأرسل إليه فجاء فقال يا أبا الوليد أخواك تطربا إليك ابن\nالزبعرى وضرار يذاكراك ويناشداك\nقال نعم إن شئتما بدأت وإن شئتما فابديا قالا نبدأ فأنشداه حتى إذا صار كالمرجل يفور قعدا على رواحلهما\nفخرج حسان حتى تلقى عمر بن الخطاب وتمثل ببيت ذكره ابن جعدبة لا أذكره فقال عمر وما ذاك فأخبره خبرهما قال لا جرم لا يفوتانك\nفأرسل فى إثرهما فردا\nوقال لحسان أنشدهما\nفأنشد حاجته قال أكتفيت قال نعم قال شأنكما الآن إن شئتما فارحلا وإن شئتما فأقيما"},{"id":"tabaqat-shuara:343","bookId":"tabaqat-shuara","type":"section","seq":343,"chapter":"طبقات فحول الشعراء","title":"336- وكان أبو طالب شاعرا جيد الكلام أبرع ما قال قصيدته التى صح فيها النبى صلى الله عليه وسلم) — و","page":"ص0","text":"وكان أبو طالب شاعرا جيد الكلام أبرع ما قال قصيدته التى صح فيها النبى صلى الله عليه وسلم)\nوأبيض يستسقى الغمام بوجهه ... ربيع اليتامى عصمة للأرامل)\nوقد زيد فيها وطولت\nورأيت فى كتاب يوسف بن سعد صاحبنا منذ أكثر من مئة سنة وقد علمت أن قد زاد الناس فيها ولا أدرى\nأين منتهاها\nوسألنى الأصمعى عنها فقلت صحيحة جيدة قال أتدرى أين منتهاها قلت لا\nوأشعار قريش أشعار فيها لين فتشكل بعض الإشكال"},{"id":"tabaqat-shuara:344","bookId":"tabaqat-shuara","type":"section","seq":344,"chapter":"طبقات فحول الشعراء","title":"337- وأجمع الناس على أن الزبير بن عبد المطلب شاعر — والحاصل من شعره قليل ومما صح عنه قوله —","page":"ص0","text":"وأجمع الناس على أن الزبير بن عبد المطلب شاعر\nوالحاصل من شعره قليل ومما صح عنه قوله\n(ولولا الحبش لم تلبس رجال ... ثياب أعزة حتى يموتوا)\nوقال قوم ولولا الحمس وليس هذا بشئ إنما هى الحبش يعنى أنهم أخذوا ثيابهم ومتاعهم وذاك حين جاؤوا يريدون هدم البيت فرماهم الله وكانت أم أيمن منهم غنمتها قريش وهى أم أسامة بن زيد\nوهذه أبيات للزبير بن عبد المطلب"},{"id":"tabaqat-shuara:345","bookId":"tabaqat-shuara","type":"section","seq":345,"chapter":"طبقات فحول الشعراء","title":"338- وقلت لخلف من يقول —","page":"ص0","text":"وقلت لخلف من يقول\n(إذا كنت فى حاجة مرسلا ... فأرسل حكيما ولا توصه)\nقال يقال للزبير بن عبد المطلب\nفقلت فالخليل يقول هذا خطأ فى بناء القوافى حين يقول\n(وإن باب أمر عليك التوى ... فشاور لبيبا ولا تعصه)\nلقوله ولا توصه كان يقول لا يتفق هذا\nفقال خلف أخطأ الخليل نراها جائزة"},{"id":"tabaqat-shuara:346","bookId":"tabaqat-shuara","type":"section","seq":346,"chapter":"طبقات فحول الشعراء","title":"339- ولأبى سفيان بن الحارث شعر كان يقوله فى الجاهلية فسقط ولم يصل إلينا منه إلا القليل","page":"ص0","text":"ولأبى سفيان بن الحارث شعر كان يقوله فى الجاهلية فسقط ولم يصل إلينا منه إلا القليل"},{"id":"tabaqat-shuara:347","bookId":"tabaqat-shuara","type":"section","seq":347,"chapter":"طبقات فحول الشعراء","title":"340- ولسنا نعد ما يروى ابن اسحاق له ولا لغيره شعرا ولأن لا يكون لهم شعر أحسن من أن يكون ذاك لهم","page":"ص0","text":"ولسنا نعد ما يروى ابن اسحاق له ولا لغيره شعرا ولأن لا يكون لهم شعر أحسن من أن يكون ذاك لهم"},{"id":"tabaqat-shuara:348","bookId":"tabaqat-shuara","type":"section","seq":348,"chapter":"طبقات فحول الشعراء","title":"341- قال أبو سفيان —","page":"ص0","text":"قال أبو سفيان\n(لعمرك إنى يوم أحمل راية ... لتغلب خيل اللات خيل محمد)\n(لكالمدلج الحيران أظلم ليله ... فهذا أوان حين أهدى وأهتدى)\n(هدانى هاد غير نفسى وقادنى ... إلى الله من طردت كل مطرد)\nقال فبلغنى أن رسول الله صلى الله عليه وسلم قال له أنت طردتنى كل مطرد كأنه ينكرها يردد ذلك"},{"id":"tabaqat-shuara:349","bookId":"tabaqat-shuara","type":"section","seq":349,"chapter":"طبقات فحول الشعراء","title":"342- وقال أبو سفيان فى يوم أحد يرد على حسان بن ثابت وكان أصحاب رسول الله صلى الله عليه وسلم أصا","page":"ص0","text":"وقال أبو سفيان فى يوم أحد يرد على حسان بن ثابت وكان أصحاب رسول الله صلى الله عليه وسلم أصابوا فى عقب بدر عيرا لقريش فيها فضة فكانوا تنكبوا بعد طريق الشام وأخذوا طريق\nالعراق فقال حسان\n(دعوا فلجات الشام قد حال دونها ... جلاد كأفواه المخاض الأوارك)\n(بأيدى رجال هاجروا نحو ربهم ... وأنصاره حقا وأيدى الملائك)\n(إذا سلكت حوران من أرض عالج ... فقولا لها إن الطريق هنالك)\nفلما كان يوم أحد قال أبو سفيان بن الحارث يرد عليه\n(شقيتم بها وغيركم أهل ذكرها ... فوارس من أبناء فهر بن مالك)\n(حسبتم جلاد البيض حول بيوتكم ... كأخذكم فى العير أرطال آنك)\nفقال أبو سفيان بن حرب لأبى سفيان بن الحارث يا ابن أخى لم جعلتها آنك إن كانت لفضة بيضاء جيدة"},{"id":"tabaqat-shuara:350","bookId":"tabaqat-shuara","type":"section","seq":350,"chapter":"طبقات فحول الشعراء","title":"333- ويروى الناس لأبى سفيان بن الحارث يقول لحسان —","page":"ج1 ص248","text":"ويروى الناس لأبى سفيان بن الحارث يقول لحسان\n(أبوك أبو سوء وخالك مثله ... ولست بخير من أبيك وخالكا)\n(وإن أحق الناس أن لا تلومه ... على اللؤم من ألفى أباه كذلكا)\nفأخبرنى أهل العلم من أهل المدينة أن قدامة بن موسى ابن عمر بن قدامة بن مظعون الجمحى قالها ونحلها أبا سفيان\nوقريش تروية فى أشعارها تريد بذلك الأنصار والرد على حسان"},{"id":"tabaqat-shuara:351","bookId":"tabaqat-shuara","type":"section","seq":351,"chapter":"طبقات فحول الشعراء","title":"344- وكان ضرار بن الخطاب بن مرداس من محارب بن فهر من ظواهر قريش وكان لا يكون بالبطحاء إلا قليلا","page":"ج1 ص249","text":"وكان ضرار بن الخطاب بن مرداس من محارب بن فهر من ظواهر قريش وكان لا يكون بالبطحاء إلا قليلا\nوكان جمع من\nحلفاء قريش ومراق كنانة ناسا وكان يأكل بهم ويغير ويسبى ويأخذ المال\nوالحارث بن فهر بطحاوية"},{"id":"tabaqat-shuara:352","bookId":"tabaqat-shuara","type":"section","seq":352,"chapter":"طبقات فحول الشعراء","title":"345 - وكان ضرار خرج فى الجاهلية فى ركب من قريش فمروا ببلاد دوس وهم يطالبون قريشا بدم أبى أزيهر قتله هشام بن الوليد ابن المغيرة فثاروا بهم وق","page":"ص0","text":"ودوس تدعى شيئا كثيرا من القتلى وليس ذلك بمعلوم\nفقاتلهم ضرار ثم لجأ إلى امرأة منهم يقال لها أم غيلان مقينة تقين العرائس يقال إنها مولاة لهم فأدخلته بين درعها وجلدها ودافعت عنه هى وبناتها وصرخت\nببينها فجاءوا فخرج معهم ضرار فجالد أشد الجلاد فقالت أم غيلان ما رأيت شدة أفكل أقرب إلى حسن جلاد منه\nوقال ضرار\n(جزى الله عنا أم غيلان صالحا ... ونسوتها إذهن شعت عواطل)\n(فهن دفعن الموت بعد اقترابه ... وقد ظهرت للثائرين مقاتل)\n(فجردت سيفى ثم قمت بنصله ... وعن أى نفس بعد نفسى أقاتل)"},{"id":"tabaqat-shuara:353","bookId":"tabaqat-shuara","type":"section","seq":353,"chapter":"طبقات فحول الشعراء","title":"346- ولقى ضرار بن الخطاب يوم أحد عمر بن الخطاب فى الجولة التى جالها المسلمون وكان قد آلى يومئذ","page":"ص0","text":"ولقى ضرار بن الخطاب يوم أحد عمر بن الخطاب فى الجولة التى جالها المسلمون وكان قد آلى يومئذ أن لا يقتل قرشيا فضربه بعارضة سيفه وقال انج يا ابن الخطاب فضرب الدهر ما ضرب وولى عمر بن الخطاب فسمعت أم غيلان بذكر ابن الخطاب فظنته ضرارا فقدمت عليه فقال لها قوم قدمت وهو غائب فأتت عمر فأخبرته بالذى جاءت له فأثابها"},{"id":"tabaqat-shuara:354","bookId":"tabaqat-shuara","type":"section","seq":354,"chapter":"طبقات فحول الشعراء","title":"347- وحدثنى أبان الأعرج بحديثها فقال جاءت فلقيت ضرارا فقالت قد عرفت بلائى ويدى وقد وليت ما وليت","page":"ص0","text":"وحدثنى أبان الأعرج بحديثها فقال جاءت فلقيت ضرارا فقالت قد عرفت بلائى ويدى وقد وليت ما وليت\nقال ما اعرفنى بذلك ولست أنا بالذى تولى ما توهمت ذاك عمر بن الخطاب ولئن كان لك عندى يد وبلاء إن لى عنده ليدا وبلاء يعنى بلاءه يوم أحد فاذهبى بنا إليه\nفأتاه فقال يا أمير المؤمنين هذه أم غيلان وقد عرفت ما كان من أمرها سمعت بولايتك فظنتنى الوالى فأتتنى تطلب النوال\nقال فتريد ماذا قال تعجل عطائى فأكافئها به\nفأعطاها نصف عطائه ونصف عطاء عمر"},{"id":"tabaqat-shuara:355","bookId":"tabaqat-shuara","type":"section","seq":355,"chapter":"طبقات فحول الشعراء","title":"348- وكان ضرار على بنى محارب يوم الفجار","page":"ص0","text":"وكان ضرار على بنى محارب يوم الفجار"},{"id":"tabaqat-shuara:356","bookId":"tabaqat-shuara","type":"section","seq":356,"chapter":"طبقات فحول الشعراء","title":"349- وكان أبو عزة شاعرا وكان مملقا ذا عيال فأسر يوم بدر كافرا فقال يا رسول الله إنى ذو عيال وحا","page":"ص0","text":"وكان أبو عزة شاعرا وكان مملقا ذا عيال فأسر يوم بدر كافرا فقال يا رسول الله إنى ذو عيال وحاجة قد عرفتها فامنن على صلى الله عليك\nفقال على أن لا تعين على يريد شعره قال نعم\nفعاهده وأطلقه فقال\n(ألا أبلغا عنى النبى محمدا ... بأنك حق والمليك حميد)\n(وأنت امرؤ تدعو إلى الرشد والتقى ... عليك من الله الكريم شهيد)\n(وأنت امرء بوئت فينا مباءة ... لها درجات سهلة وصعود)\n(وإنك من حاربته لمحارب ... شقى ومن سالمته لسعيد)\n(ولكن إذا ذكرت بدرا وأهلها ... تأوب ما بى حسرة وتعود)\nفلما كان يوم أحد دعاه صفوان بن أمية بن خلف الجمحى وهو سيدهم يومئذ إلى الخروج فقال إن محمدا قد من على وعاهدته أن لا أعين عليه\nفلم يزل به وكان محتاجا فأطعمه والمحتاج يطمع\nفخرج فسار فى بنى كنانة فحرضهم فقال\n(يا بنى عبد مناة الرزام ... أنتم حماة وأبوكم حام)\n(لا تعدونى نصركم بعد العام ... لا تسلمونى لا يحل إسلام)"},{"id":"tabaqat-shuara:357","bookId":"tabaqat-shuara","type":"section","seq":357,"chapter":"طبقات فحول الشعراء","title":"350- أنا أبو خليفة نا أبن سلام قال حدثنى أبان بن عثمان وهو قول ابن إسحاق أن أبا عزة أسر يوم أحد","page":"ج1 ص254","text":"أنا أبو خليفة نا أبن سلام قال حدثنى أبان بن عثمان وهو قول ابن إسحاق أن أبا عزة أسر يوم أحد فقال يا رسول الله من على فقال النبى صلى الله عليه وسلم (لا يلسع المؤمن من جحر مرتين)\nوقال أبان قال رسول الله) صلى الله عليه وسلم (لا تمسح عارضيك بمكة) تقول خدعت محمدا مرتين فقتله\nفذكرت ذلك لابن جعدبه فقال ما أسر يوم أحد هو ولا غيره ولقد كان المسلمون يومئذ فى شغل عن الأسر ولم ينكر قتله وكان ينكر قتل النضر بن الحارث فى يوم بدر صبرا فقال أصابته جراحة فارتث منها وكان شديد العداوة فقال لا أطعم طعاما ولا أشرب شرابا ما دمت فى أيديهم فمات\nفأخبرت أبى سلاما بقول ابن جعدبة فى أبى عزة فقال\nقد قيل أن النبى صلى الله عليه وسلم لم يقتل أحدا صبرا إلا عقبة بن أبى معيط يوم بدر"},{"id":"tabaqat-shuara:358","bookId":"tabaqat-shuara","type":"section","seq":358,"chapter":"طبقات فحول الشعراء","title":"351- قال ابن جعدبة برص أبو عزة بعد ما أسن وكانت قريش تكره الأبرص وتخاف العدوى فكانوا لا يؤاكلون","page":"ص0","text":"قال ابن جعدبة برص أبو عزة بعد ما أسن وكانت قريش تكره الأبرص وتخاف العدوى فكانوا لا يؤاكلونه ولا يشاربونه ولا يجالسونه فكبر ذلك عليه فقال الموت خير من هذا فأخذ حديدة وصعد إلى جبل حراء يريد قتل نفسه فطعن بها فى بطنه فضعفت يده لما وجد مسها فمارت الحديدة بن الصفاق والجلد فسال ماء أصفر وذهب ما كان به فقال\n(لا هم رب وائل ونهد ... والتهمات والجبال الجرد)\n(ورب من يرمى بياض نجد ... أصبحت عبدا لك وابن عبد)\n(أبرأتنى من وضح بجلدى ... من بعد ما طعنت فى معدى)\nوالمعد موضع رجلى الراكب من الفرس"},{"id":"tabaqat-shuara:359","bookId":"tabaqat-shuara","type":"section","seq":359,"chapter":"طبقات فحول الشعراء","title":"352- وكان هبيرة بن أبى وهب شاعرا من رجال قريش المعدودين وكان شديد العداوة لله ولرسوله فأخمله ال","page":"ص0","text":"وكان هبيرة بن أبى وهب شاعرا من رجال قريش المعدودين وكان شديد العداوة لله ولرسوله فأخمله الله ودحقه وهو الذى يقول فى يوم أحد\n(قدنا كنانة من أكناف ذى يمن ... عرض البلاد على ما كان يزجيها)\n(قالت كنانة أنى تذهبون بنا ... قلنا النخيل فأموها وما فيها)\nوله شعر كثير وحديث"},{"id":"tabaqat-shuara:360","bookId":"tabaqat-shuara","type":"section","seq":360,"chapter":"طبقات فحول الشعراء","title":"353- قال ابن سلام وبالطائف شعر وليس بالكثير وإنما كان يكثر الشعر بالحروب التى تكون بين الأحياء","page":"ص0","text":"قال ابن سلام وبالطائف شعر وليس بالكثير وإنما كان يكثر الشعر بالحروب التى تكون بين الأحياء نحو حرب الأوس والخزرج أو قوم يغيرون ويغار عليهم\nوالذى قلل شعر قريش أنه لم يكن بينهم نائرة ولم يحاربوا\nوذلك الذى قلل شعر عمان وأهل الطائف فى طرف ومع ذلك كان فيهم"},{"id":"tabaqat-shuara:361","bookId":"tabaqat-shuara","type":"section","seq":361,"chapter":"طبقات فحول الشعراء","title":"354- أبو الصلت بن أبى ربيعة","page":"ص0","text":"أبو الصلت بن أبى ربيعة"},{"id":"tabaqat-shuara:362","bookId":"tabaqat-shuara","type":"section","seq":362,"chapter":"طبقات فحول الشعراء","title":"355- وابنه أمية بن أبى الصلت وهو أشعرهم","page":"ص0","text":"وابنه أمية بن أبى الصلت وهو أشعرهم"},{"id":"tabaqat-shuara:363","bookId":"tabaqat-shuara","type":"section","seq":363,"chapter":"طبقات فحول الشعراء","title":"356- وأبو محجن عمرو بن حبيب بن عمرو بن عمير الثقفى","page":"ص0","text":"وأبو محجن عمرو بن حبيب بن عمرو بن عمير الثقفى"},{"id":"tabaqat-shuara:364","bookId":"tabaqat-shuara","type":"section","seq":364,"chapter":"طبقات فحول الشعراء","title":"357- وغيلان بن سلمة بن معتب بن مالك بن كعب بن عمرو بن سعد بن عوف","page":"ص0","text":"وغيلان بن سلمة بن معتب بن مالك بن كعب بن عمرو بن سعد بن عوف"},{"id":"tabaqat-shuara:365","bookId":"tabaqat-shuara","type":"section","seq":365,"chapter":"طبقات فحول الشعراء","title":"358- وكنانة بن عبد يا ليل","page":"ص0","text":"وكنانة بن عبد يا ليل"},{"id":"tabaqat-shuara:366","bookId":"tabaqat-shuara","type":"section","seq":366,"chapter":"طبقات فحول الشعراء","title":"359- وكان أبو الصلت يمدح أهل فارس حين قتلوا الحبشة فى كلمة قال فيها —","page":"ص0","text":"وكان أبو الصلت يمدح أهل فارس حين قتلوا الحبشة فى كلمة قال فيها\n(لله درهم من عصبة خرجوا ... ما إن ترى لهم فى الناس أمثالا)\n(بيضا مرازبة غرا جحاجحة ... أسدا تربب فى الغيضات أشبالا)\n(لا يرمضون إذا حرت مغافرهم ... ولا ترى منهم فى الطعن ميالا)\n(من مثل كسرى وسابور الجنود له ... أو مثل وهرز يوم الجيش إذ صالا)\n(فاشرب هنيئا عليك التاج مرتفقا ... فى رأس غمدان دارا منك محلالا)\n(واضطم بالمسك إذ شالت نعامتهم ... وأسبل اليوم فى برديك إسبالا)\n(تلك المكارم لا قعبان من لبن ... شيبا بماء فعادا بعد أبوالا)"},{"id":"tabaqat-shuara:367","bookId":"tabaqat-shuara","type":"section","seq":367,"chapter":"طبقات فحول الشعراء","title":"360- وكان أمية بن أبى الصلت كثير العجائب يذكر فى شعره خلق السموات والأرض ويذكر الملائكة ويذكر م","page":"ج1 ص261","text":"وكان أمية بن أبى الصلت كثير العجائب يذكر فى شعره خلق السموات والأرض ويذكر الملائكة ويذكر من ذلك\nما لم يذكره أحد من الشعراء وكان قد شام أهل الكتاب"},{"id":"tabaqat-shuara:368","bookId":"tabaqat-shuara","type":"section","seq":368,"chapter":"طبقات فحول الشعراء","title":"361- نا ابن سلام قال فحدث سفيان وابن دأب أن أمية مر بزيد بن عمرو بن نفيل أخى عدى بن كعب وكان قد","page":"ص0","text":"نا ابن سلام قال فحدث سفيان وابن دأب أن أمية مر بزيد بن عمرو بن نفيل أخى عدى بن كعب وكان قد طلب الدين فى الجاهلية هو وورقة بن نوفل\nفقال له أمية يا باغى الخير هل وجدت قال لا\nقال ولم أوت من طلب\nقال أبى علماء أهل الكتاب إلا أنه منا أو منكم أو من أهل فلسطين"},{"id":"tabaqat-shuara:369","bookId":"tabaqat-shuara","type":"section","seq":369,"chapter":"طبقات فحول الشعراء","title":"362- وناح أمية على قتلى بدر فقال —","page":"ص0","text":"وناح أمية على قتلى بدر فقال\n(ماذا ببدر فالعقنقل من مرازبة جحاجح ... )\n(هلا بكيت على الكرام ... بنى الكرام أولى الممادح)"},{"id":"tabaqat-shuara:370","bookId":"tabaqat-shuara","type":"section","seq":370,"chapter":"طبقات فحول الشعراء","title":"363- وقال أمية —","page":"ص0","text":"وقال أمية\n(وما يبقى على الحدثان غفر ... بشاهقة له أم رؤوم)\n(تبيت الليل حانية عليه ... كما يخرمس الأرخ الأطوم)\n(تصدى كلما طلعت لنشر ... وودت أنها منه عقيم)\nالغفر ولد الوعل\nوالأرخ ولد البقرة\nويخرمس أى يتصمت\nوالأطوم الضمام بين شفتيه"},{"id":"tabaqat-shuara:371","bookId":"tabaqat-shuara","type":"section","seq":371,"chapter":"طبقات فحول الشعراء","title":"364- ومدح أمية عبد الله بن جدعان التيمى فقال —","page":"ص0","text":"ومدح أمية عبد الله بن جدعان التيمى فقال\n(أأذكر حاجتى أم قد كفانى ... حياؤك إن شمتك الحياء)\n(كريم لا يغيره صباح ... عن الخلق الكريم ولا مساء)\n(وأرضك كل مكرمة بنتها ... بنو تيم وأنت لهم سماء)\nقال ابن سلام وأنشدينها أبو بكر بن محمد بن واسع السلمى وأنشدنيها أيضا أبو بكر وذكرتها لخلف فعرفها"},{"id":"tabaqat-shuara:372","bookId":"tabaqat-shuara","type":"section","seq":372,"chapter":"طبقات فحول الشعراء","title":"365- وقال أمية —","page":"ص0","text":"وقال أمية\n(عطاؤك زين لامرئ بذل وجهه ... بخير وما كل العطاء يزين)\n(وليس بشين لامرئ بذل وجهه ... إليك كما بعض السؤال يشين)"},{"id":"tabaqat-shuara:373","bookId":"tabaqat-shuara","type":"section","seq":373,"chapter":"طبقات فحول الشعراء","title":"366- نا ابن سلام قال وذكر عيسى بن عمر عن بعض أهل — الطائف عن أخت أمية بن أبى الصلت قالت إنى لفى ب","page":"ص0","text":"نا ابن سلام قال وذكر عيسى بن عمر عن بعض أهل\nالطائف عن أخت أمية بن أبى الصلت قالت إنى لفى بيت فيه أمية نائم إذ أقبل طائران أبيضان فسقطا على السقف ففرج السقف فسقط أحدهما عليه فشق بطنه وثبت الآخر مكانه\nفقال الأعلى للأسفل أوعى قال وعى\nقال أقبل قال أبى ويقال قال زكا\nقال خسا فرد عليه قلبه وطار والتأم السقف\nقالت فلما استيقظ قلت له يا أخى أحسست شيئا\nقال لا وإنى لأجد توصيبا فما ذاك فأخبرته\nقال يا أخية أنا رجل أراد الله بى خيرا فلم أقبله\nقالت فلما مرض مرضته التى مات فيها قالت فإنى عنده إذ نظر إلى السماء وشق بصره ثم قال\n(لبيكما لبيكما ... ها أنا ذا لديكما)\nلا ذو براءة فأعتذر ولا ذو قوة فأنتصر\nثم أغمى عليه ثم شق بصره ونظر وقال\n(لبيكما لبيكما ... ها أنا ذا لديكما)\nوقال لا ذو عشيرة تحمينى ولا ذو مال يفدينى\nثم أغمى عليه فقلنا قد أودى ثم شق بصره ونظر إلى السماء فقال\n(لبيكما لبيكما ... ها أنا ذا لديكما)\nبالنعم محفود من الذنب مخضود\nثم أغمى عليه ثم شق بصره وقال\n(إن تغفر اللهم تغفر جما ... وأى عبد لك لا ألما)\nثم أغمى عليه ثم أفاق فقال\n(ليتنى كنت قبل ما قد بدالى ... فى قلال الجبال أرعى الوعولا)\n(كل عيش وإن تطاول دهرا ... قصره مرة إلى أن يزولا)\nثم خفت فمات"},{"id":"tabaqat-shuara:374","bookId":"tabaqat-shuara","type":"section","seq":374,"chapter":"طبقات فحول الشعراء","title":"367- قال ابن سلام وأبو محجن رجل شاعر شريف — وكان قد غلب عليه الشراب فضرب فيه مرارا ثم حبسه سعد با","page":"ج1 ص267","text":"قال ابن سلام وأبو محجن رجل شاعر شريف\nوكان قد غلب عليه الشراب فضرب فيه مرارا ثم حبسه سعد بالقادسية فى القصر معه والناس يقتتلون فجال المسلمون جولة وهو ينظر فقال\n(كفى حزنا أن تطرد الخيل بالقنا ... وأترك مشدودا على وثاقيا)\n(إذا قمت غنانى الحديد وأغلقت ... مصاريع من دونى تصم المناديا)\n(وقد كنت ذا مال كثيروإخوة ... فقد تركونى واحدا لا أخا ليا)\n(أرينى سلاحى لا أبا لك إننى ... أرى الحرب ما تزداد إلا تماديا)\nوكان مقيدا يومئذ عند زبراء أم ولد سعد بن أبى وقاص فقال لها\nأطلقينى فلك الله لئن فتح الله على المسلمين وسلمت لأرجعن حتى أضع رجلى فى القيد\nفأطلقته وحملته على فرس لسعد فأخذ الرمح فخرج فقاتل فحطم المشركين وكان سبب الهزيمة\nفقال سعد لولا أن أبا محجن محبوس لقلت الفارس أبو محجن فلما فتح الله على المسلمين رجع إلى محبسه فقال له سعد لاضربتك فى الخمر أبدا\nقال أبو محجن وأنا والله لا أشربها أبدا"},{"id":"tabaqat-shuara:375","bookId":"tabaqat-shuara","type":"section","seq":375,"chapter":"طبقات فحول الشعراء","title":"368- قال ابن سلام ولغيلان بن سلمة شعر وهو شريف — وكان قسم ما له كله بين ولده وطلق نساءه — فقال له ع","page":"ص0","text":"قال ابن سلام ولغيلان بن سلمة شعر وهو شريف\nوكان قسم ما له كله بين ولده وطلق نساءه\nفقال له عمر إن الشيطان قد نفث فى روعك أنك ميت ولا أراه إلا كذلك لترجعن فى مالك ولتراجعن نساءك أو لآمرن بقبرك أن يرجم كما يرجم قبر أبى رغال\nففعل"},{"id":"tabaqat-shuara:376","bookId":"tabaqat-shuara","type":"section","seq":376,"chapter":"طبقات فحول الشعراء","title":"369- قال ابن سلام وفى البحرين شعر كثير جيد وفصاحة منهم","page":"ج1 ص270","text":"قال ابن سلام وفى البحرين شعر كثير جيد وفصاحة منهم"},{"id":"tabaqat-shuara:377","bookId":"tabaqat-shuara","type":"section","seq":377,"chapter":"طبقات فحول الشعراء","title":"370- المثقب وهو عائذ بن محصن بن ثعلبة بن واثلة بن عدى بن عوف بن دهن بن عذرة بن منبة بن نكرة وهى","page":"ج1 ص270","text":"المثقب وهو عائذ بن محصن بن ثعلبة بن واثلة بن عدى بن عوف بن دهن بن عذرة بن منبة بن نكرة وهى القبيلة ابن لكيز بن أفصى بن عبد القيس\nوإنما سمى المثقب لبيت قاله\n(رددن تحية وكنن أخرى ... وثقبن الوصاوص للعيون)"},{"id":"tabaqat-shuara:378","bookId":"tabaqat-shuara","type":"section","seq":378,"chapter":"طبقات فحول الشعراء","title":"371- وقال أيضا —","page":"ج1 ص270","text":"وقال أيضا\n(ظعائن لا توفى بهن ظعائن ... ولا الثاقبات من لؤى بن غالب)\n(ولا ثعلبيات حللن عباعبا ... لا أسرة القعقاع من رهط حاجب)\nوتميم تنشد\n(ولا نهشليات أبوهن دارم ... ولا أسرة القعقاع من رهط حاجب)"},{"id":"tabaqat-shuara:379","bookId":"tabaqat-shuara","type":"section","seq":379,"chapter":"طبقات فحول الشعراء","title":"372- والمثقب العبدى هو الذى يقول —","page":"ص0","text":"والمثقب العبدى هو الذى يقول\n(أفاطم قبل بينك متعينى ... ومنعك ما سألتك أن تبينى)\n(ولا تعدى مواعد كاذبات ... تمر بها رياح الصيف دونى)\n(فإنى لو تخالفنى شمالى ... عنادك ما وصلت بها يمينى)\n(إذا لقطعتها ولقلت بينى ... كذلك أجتوى من يجتوينى)\n(إذا ماقمت أرحلها بليل ... تأوه آهة الرجل الحزين)\n(تقول إذا درأت لها وضينى ... أهذا دينه أبدا ودينى)\n(أكل الدهر حلا وارتحالا ... أما يبقى على ولا يقينى)\n(فأبقى باطلى والجد منها ... كد كان الدرابنة المطين)\nوهذه الأبيات بعض القصيدة وإنما انتخبنا أجودها أبياتا"},{"id":"tabaqat-shuara:380","bookId":"tabaqat-shuara","type":"section","seq":380,"chapter":"طبقات فحول الشعراء","title":"373- ومنهم الممزق العبدى واسمه شأس بن نهار بن أسود وإنما سمى الممزق ببيت قاله —","page":"ج1 ص273","text":"ومنهم الممزق العبدى واسمه شأس بن نهار بن أسود وإنما سمى الممزق ببيت قاله\n(فإن كنت مأكولا فكن خير آكل ... وإلا فأدركنى ولما أمزق)\nقال وبلغنى أن عثمان بن عفان بعث به إلى على بن أبي طالب رحمه الله عليهما ورضى عنهما حين بلغ منه وألح عليه"},{"id":"tabaqat-shuara:381","bookId":"tabaqat-shuara","type":"section","seq":381,"chapter":"طبقات فحول الشعراء","title":"374- ومنهم المفضل بن معشر بن أسحم بن عدى بن شيبان بن — سود بن عذرة بن منبه بن نكرة — فضلته قصيدته ا","page":"ج1 ص273","text":"ومنهم المفضل بن معشر بن أسحم بن عدى بن شيبان بن\nسود بن عذرة بن منبه بن نكرة\nفضلته قصيدته التى يقال لها المنصفة وأولها\n(ألم تر أن جيرتنا استقلوا ... فنيتنا ونيتهم فريق)"},{"id":"tabaqat-shuara:382","bookId":"tabaqat-shuara","type":"section","seq":382,"chapter":"طبقات فحول الشعراء","title":"375- وقد اختلف فى القائل —","page":"ص0","text":"وقد اختلف فى القائل\n(هل للفتى من بنات الدهر من واقى ... أم هل له من حتى الموت من راقى)\n(ورجلونى وما رجلت من شعث ... وألبسونى ثيابا غير أخلاق)\n(ورفعونى وقالوا أيما رجل ... وأدرجونى كأنى طى مخراق)\n(وأرسلوا فتية من خيرهم حسبا ... ليسندوا فى ضريح الترب أطباقى)\n(خفض عليك ولا تولع بإشفاق ... فإنما مالنا للوارث الباقى)"},{"id":"tabaqat-shuara:383","bookId":"tabaqat-shuara","type":"section","seq":383,"chapter":"طبقات فحول الشعراء","title":"376- ولا أعرف باليمامة شاعرا مذكورا","page":"ج1 ص276","text":"ولا أعرف باليمامة شاعرا مذكورا"},{"id":"tabaqat-shuara:384","bookId":"tabaqat-shuara","type":"section","seq":384,"chapter":"طبقات فحول الشعراء","title":"377- وفى يهود المدينة وأكنافها شعر جيد منهم","page":"ص0","text":"وفى يهود المدينة وأكنافها شعر جيد منهم"},{"id":"tabaqat-shuara:385","bookId":"tabaqat-shuara","type":"section","seq":385,"chapter":"طبقات فحول الشعراء","title":"378- السموأل بن عادياء من أهل تيماء وهو الذى كان امرؤ القيس استودعه سلاحة فسار إليه الحارث بن أ","page":"ص0","text":"السموأل بن عادياء من أهل تيماء وهو الذى كان امرؤ القيس استودعه سلاحة فسار إليه الحارث بن أبى شمر الغسانى فطلبه فأغلق الحصن دونه\nفأخذ ابنا له خارجا من القصر وقال إما أن تؤدى إلى السلاح وإما أن أقتله\nقال اقتله فلن أؤديها\nووفى فضرب به الأعشى المثل فقال\n(كن كالسموأل إذ طاف الهمام به ... فى جحفل كسواد الليل جرار)\n(بالأبلق الفرد من تيماء منزله ... حصن حصين وجار غير غدار)\n(إذ سامه خطتى خسف فقال له ... قل ما تشاء فإنى سامع حار)\n(فقال ثكل وغدر أنت بينهما ... فاختر وما فيهما حظ لمختار)\n(فشك غير طويل ثم قال له ... اقتل أسيرك إنى مانع جارى)"},{"id":"tabaqat-shuara:386","bookId":"tabaqat-shuara","type":"section","seq":386,"chapter":"طبقات فحول الشعراء","title":"379- والسموأل بن عادياء يقول فى كلمة له طويلة —","page":"ص0","text":"والسموأل بن عادياء يقول فى كلمة له طويلة\n(إن حلمى إذا تغيب عنى ... فاعلمى أننى عظيما رزيت)\n(ضيق الصدر بالخيانة لا ... ينقض فقرى أمانتى ماحييت)\n(كم فظيع سمعته فتصاممت ... وغى تركته فكفيت)\n(ليت شعرى وأشعرن إذا ما ... قربوها منشورة فقريت)\n(ألى الفضل أم على إذا حوسبت ... إنى على الحساب مقيت)\n(ميت دهر قد كنت ثم حييت ... وحياتى رهن بأن سأموت)"},{"id":"tabaqat-shuara:387","bookId":"tabaqat-shuara","type":"section","seq":387,"chapter":"طبقات فحول الشعراء","title":"380- ومنهم الربيع بن أبى الحقيق من بنى النضير وهو الذى يقول —","page":"ص0","text":"ومنهم الربيع بن أبى الحقيق من بنى النضير وهو الذى يقول\n(سائل بنا خابر أكفائنا ... والعلم قد يلفى لدى السائل)\n(لسنا إذا جارت دواعى الهوى ... واستمع المنصت للقائل)\n(واعتلج القوم بألبابهم ... بقابل الجور ولا الفاعل)\n(إنا إذا نحكم فى ديننا ... نرضى بحكم العادل الفاصل)\n(لا نجعل الباطل حقا ولا ... نلط دون الحق بالباطل)\n(نخاف أن نسفه أحلامنا ... فنخمل الدهر مع الخامل)\nويروى فنحمل الذم مع الحامل"},{"id":"tabaqat-shuara:388","bookId":"tabaqat-shuara","type":"section","seq":388,"chapter":"طبقات فحول الشعراء","title":"381- وكعب بن الأشرف وهو من طيئ وأمه من بنى النضير — وكان فى أخواله سيدا وبكى قتلى بدر وشبب بنساء","page":"ص0","text":"وكعب بن الأشرف وهو من طيئ وأمه من بنى النضير\nوكان فى أخواله سيدا وبكى قتلى بدر وشبب بنساء رسول الله صلى الله عليه وسلم ونساء المسلمين فأمر رسول الله صلى الله عليه وسلم\nمحمد بن مسلمة ورهطا معه من الأنصار بقتله فقتلوه\nوهو يقول فى كلمة\n(رب خال لى لو أبصرته ... سبط المشية أباءأنف)\n(لين الجانب فى أقربه ... وعلى الأعداء سم كالذعف)\n(ولنا بئر رواء جمة ... من يردها بإناء يغترف)\n(ونخيل فى تلاع جمة ... تخرج التمر كأمثال الأكف)\n(وصرير فى محال خلته ... آخر الليل أهازيج بدف)"},{"id":"tabaqat-shuara:389","bookId":"tabaqat-shuara","type":"section","seq":389,"chapter":"طبقات فحول الشعراء","title":"382- وشريح بن عمران الذى يقول فى كلمة —","page":"ج1 ص283","text":"وشريح بن عمران الذى يقول فى كلمة\n(آخ الكرام إن استطعت ... إلى إخائهم سبيلا)\n(واشرب بكأسهم وإن ... شربوا بها السم الثميلا)\n(أأسيد إن مال ملكت ... فسر به سيرا جميلا)\n(أأسيد إن المال لا ... يبكى إذا فقد الخليلا)\n(إن الكريم إذا تؤاخيه ... وجدت له فضولا)"},{"id":"tabaqat-shuara:390","bookId":"tabaqat-shuara","type":"section","seq":390,"chapter":"طبقات فحول الشعراء","title":"383- وسعية بن العريض القائل فى كلمة له —","page":"ص0","text":"وسعية بن العريض القائل فى كلمة له\n(بل ليت شعرى حين أندب هالكا ... ماذا يؤبننى به أنواحى)\n(أيقلن لا تبعد فربت كربة ... فرجتها بيسارة وسماح)\n(ومغيرة شعواء يخشى درؤها ... يوما رددت سلاحها بسلاح)\n(ولرب مشغله يشب ... وقودها ... أطفأت حد رماحها برماح)\n(وكتيبة أدنيتها لكتيبة ... ومضاغن صبحت شر صباح)\n(وإذا عمدت لصخرة أسهلتها ... أدعو بأفلح مرة ورباح)\n(لا تبعدن فكل حى هالك ... لابد من تلف فبن بفلاح)\n(إن امرأ أمن الحوادث جاهلا ... ورجا الخلود كضارب بقداح)\n(ولقد أخذت الحق غير مخاصم ... ولقد دفعت الضيم غير ملاح)"},{"id":"tabaqat-shuara:391","bookId":"tabaqat-shuara","type":"section","seq":391,"chapter":"طبقات فحول الشعراء","title":"384- وأبو قيس بن رفاعه وهو يقول فى قصيدته —","page":"ج1 ص287","text":"وأبو قيس بن رفاعه وهو يقول فى قصيدته\n(إذا ذكرت أمامة فرط حول ... ولو بعدت محلتها غريت)\n(أكلفها ولو بعدت نواها ... كأنى من تذكرها خميت)\n(طليح لا يؤوب إلى جسمى ... كأنى سم عاضهة سقيت)\n(وذى ضغن كففت النفس عنه ... وكنت على مساءته مقيت)\n(وسيفى صارم لا عيب فيه ... ويمنعنى من الرهق النبيت)\n(متى ما يأت يومى لاتجدنى ... بمالى حين أتركه شقيت)\n(ألين لهم وأفديهم بنفسى ... مقارشة الرماح إذا لقيت)\n(وأرهن فى الحوادث كف بكرى ... لجارى فى العظيمة إن دهيت)\n(أراه ما أقام على حقا ... شريكى فى بلادى ما بقيت)"},{"id":"tabaqat-shuara:392","bookId":"tabaqat-shuara","type":"section","seq":392,"chapter":"طبقات فحول الشعراء","title":"385- وأبو الذيال يقول فى كلمة أولها —","page":"ج1 ص289","text":"وأبو الذيال يقول فى كلمة أولها\n(هل تعرف الدار خف ساكنها ... بالحجر فالمستوى إلى الثمد)\n(دار لبهنانة خدلجة ... تبسم عن مثل بارد البرد)\n(أثت فطالت حتى إذا اعتدلت ... ما إن يرى الناظرون من أود)\n(فيها فأما نقا فأسفلها ... والجيد منها لظبية الجرد)\n(لا الدهر فان ولا مواعدها ... تأتى فليت القتول لم تعد)\n(وعدا محاصيلة إلى خلف ... ذاك طلاب التضليل والنكد)\n(هيفاء يلتذها معانقها ... بعد علال الحديث والنجد)\n(تمشى إلى نحو بيت جارتها ... واضعة كفها على الكبد)\n(نعم شعار الفتى إذا برد الليل ... وآضت كواكب الأسد)\n(كأن ماء الغمام خالطه ... راح صفا بعد هادر الزبد)\n(والمسك والزنجبيل عل به ... أنيابها بعد غفلة الرصد)\n(دع ذا ولكن بل رب عاذلة ... لو علمت ما أريد لم تعد)\n(هبت بليل تلوم فى شرب ... الخمر وذكر الكواعب الخرد)\n(فقلت مهلا فما عليك أن ... امسيت غويا غي ولا رشدى)\n(إنى لمستيقن لئن لم امت ... مل يوم إنى إذن رهين غد)\n(هل نحن إلا كمن تقدمنا ... منا ومن تم ظمؤه يرد)\n(نحن كمن قد مضى وما إن ارى ... شحا يزيد الحريص من عدد)\n(فلا تلومننى على خلقى ... وأقنى حياء الكريم واقتصدى)"},{"id":"tabaqat-shuara:393","bookId":"tabaqat-shuara","type":"section","seq":393,"chapter":"طبقات فحول الشعراء","title":"386- ودرهم بن زيد يقول —","page":"ج1 ص293","text":"ودرهم بن زيد يقول\n(هجرت الرباب وجاراتها ... وهمك بالشوق قد يطرح)\n(يمانية نازح دارها ... تقيم بغمدان لا تبرح)\n(لعمر أبيك الذى لا أهين إنى لأعطى وأستفلح ... )\n(وأدلج بالقوم شطر الملوك ... حتى إذا خفق المجدح)\n(أمرت صحابى لكى ينزلوا ... فناموا قليلا وقد أصبحوا)\n(أجدوا سراعا فأفضى بهم ... سراب بدوية أفيح) تم السفر الأول من طبقات فحول الشعراء ويليه السفر الثانى وأوله طبقات الإسلام عشر طبقات كل طبقة أربعة رهط متكافئين معتدلين"},{"id":"tabaqat-shuara:394","bookId":"tabaqat-shuara","type":"section","seq":394,"chapter":"طبقات فحول الشعراء","title":"387- عشر طبقات كل طبقة أربعة رهط متكافئين معتدلين","page":"ج1 ص296","text":"عشر طبقات كل طبقة أربعة رهط متكافئين معتدلين"},{"id":"tabaqat-shuara:395","bookId":"tabaqat-shuara","type":"section","seq":395,"chapter":"طبقات فحول الشعراء","title":"388- جرير بن عطية بن الخطفى واسم الخطفى حذيفة بن بدر ابن سلمة بن عوف بن كليب بن يربوع خطفه بيت","page":"ج1 ص296","text":"جرير بن عطية بن الخطفى واسم الخطفى حذيفة بن بدر ابن سلمة بن عوف بن كليب بن يربوع خطفه بيت قاله\n(يرفعن لليل إذا ما أسدفا ... أعناق جنان وهاما رجفا)\n(وعنقا بعد الرسيم خيطفا ... )"},{"id":"tabaqat-shuara:396","bookId":"tabaqat-shuara","type":"section","seq":396,"chapter":"طبقات فحول الشعراء","title":"389- والفرزدق واسمه همام بن غالب بن صعصة بن ناجية بن عقال بن محمد بن سفيان بن مجاشع — وإنما سمي ا","page":"ص0","text":"والفرزدق واسمه همام بن غالب بن صعصة بن ناجية بن عقال بن محمد بن سفيان بن مجاشع\nوإنما سمي الفرزدق لأنه شبه وجهه بالخبرة وهي فرزدقة"},{"id":"tabaqat-shuara:397","bookId":"tabaqat-shuara","type":"section","seq":397,"chapter":"طبقات فحول الشعراء","title":"390- والأخطل واسمه غياث بن غوث بن الصلت بن طارقة ابن السيحان بن عمرو بن فدوكس بن عمرو بن مالك ب","page":"ص0","text":"والأخطل واسمه غياث بن غوث بن الصلت بن طارقة ابن السيحان بن عمرو بن فدوكس بن عمرو بن مالك بن جشم بن بكر ابن حبيب بن عمرو بن غنم بن تغلب\nخطله قول كعب بن جعيل له إنك لأخطل ياغلام"},{"id":"tabaqat-shuara:398","bookId":"tabaqat-shuara","type":"section","seq":398,"chapter":"طبقات فحول الشعراء","title":"391- وراعى الإبل واسمه عبيد بن حصين بن جندل بن قطن ابن ظويلم بن ربيعة بن عبد الله بن الحارث بن","page":"ص0","text":"وراعى الإبل واسمه عبيد بن حصين بن جندل بن قطن ابن ظويلم بن ربيعة بن عبد الله بن الحارث بن نمير سمى راعى\nوجرير أشعر خاصة"},{"id":"tabaqat-shuara:399","bookId":"tabaqat-shuara","type":"section","seq":399,"chapter":"طبقات فحول الشعراء","title":"397- وكان الأشهب بن رميلة يفاخر الفرزدق فكان الفرزدق يذكر فقيما مع بني نهشل فاستعدوا عليه زيادا","page":"ص0","text":"وكان الأشهب بن رميلة يفاخر الفرزدق فكان الفرزدق يذكر فقيما مع بني نهشل فاستعدوا عليه زيادا فهرب من زياد"},{"id":"tabaqat-shuara:400","bookId":"tabaqat-shuara","type":"section","seq":400,"chapter":"طبقات فحول الشعراء","title":"398- فحدثني جابر بن جندل الفزاري قال أتى الفرزدق عيسى بن خصيلة السلمي فقال يا أبا خصيلة إن هذا","page":"ص0","text":"فحدثني جابر بن جندل الفزاري قال أتى الفرزدق عيسى بن خصيلة السلمي فقال يا أبا خصيلة إن هذا الرجل قد أضافني وقد لفظني جميع من كنت أرجو قال فمرحبا يا أبا فراس فكان عنده ليالي ثم قال له إني أريد أن أخرج إلى الشام فقال له إن أقمت ففي الرحب والسعة وإن شخصت فهذه ناقة أرحبية أمتعك بها وألف درهم فركب الناقة وخرج من عنده ليلا وأرسل معه عيسى بن خصيلة من أجازه من البيوت فأصبح وقد جاوز مسيرة ثلاث فقال يمدحه\n(تخطى بى البهزى حملان من أبى ... من الناس والجانى تخاف جرائمه)\n(فتى الجود عيسى والمكارم والعلى ... إذا المال لم ترفع بخيلا كرائمه)\n(ومن كان ياعيسى يؤنب ضيفه ... فضيفك محبور هني مطاعمه)\n(وقال تعلم أنها أرحبية ... وأن لها الليل الذي أنت جاشمه)\n(فأصبحت والملقى ورائى وحنبل ... وماصدرت حتى علا النجم عاتمه)\n(تزاور عن أهل الحفير كأنها ... ظليم تبارى جنح ليل نعائمه)\n(رأت بين عينيها روية وانجلى ... لها الصبح عن صعل أسيل مخاطمه)"},{"id":"tabaqat-shuara:401","bookId":"tabaqat-shuara","type":"section","seq":401,"chapter":"طبقات فحول الشعراء","title":"399- وقال ايضا فيه —","page":"ج2 ص301","text":"وقال ايضا فيه\n(تداركنى أسباب عيسى من الردى ... ومن يك مولاه فليس بواحد)\n(نمته النواصي من سليم إلى العلى ... وأعراق صدق بين نصر وخالد)\n(سأثنى بما أوليتني وأربه ... إذا القوم عدو افضلهم في المشاهد)"},{"id":"tabaqat-shuara:402","bookId":"tabaqat-shuara","type":"section","seq":402,"chapter":"طبقات فحول الشعراء","title":"400- فلما بلغ زيادا شخوصه أتبعه علي بن زهدم الفقيمى فلم يلحقه فقال الفرزدق —","page":"ص0","text":"فلما بلغ زيادا شخوصه أتبعه علي بن زهدم الفقيمى فلم يلحقه فقال الفرزدق\n(فإنك لو لاقيتني يا ابن زهدم ... لأبت شعاعيا على شر تمثال)"},{"id":"tabaqat-shuara:403","bookId":"tabaqat-shuara","type":"section","seq":403,"chapter":"طبقات فحول الشعراء","title":"401- فأتى بكر بن وائل فأجاروه فأمن فقال —","page":"ص0","text":"فأتى بكر بن وائل فأجاروه فأمن فقال\n(وقد ميلت بين المسير فلم تجد ... لعورتها كالحي بكر بن وائل)\n(وسارت إلى الأحفار خمسا فأصبحت ... مكان الثريا من يد المتناول)\n(وما ضرها إذ جاورت في بلادها ... بني الحصن ما كان اختلاف القبائل)\nوالحصن ثعلبة بن عكابة أبو شيبان وقيس وذهل وتيم"},{"id":"tabaqat-shuara:404","bookId":"tabaqat-shuara","type":"section","seq":404,"chapter":"طبقات فحول الشعراء","title":"402- فأتى من وجهه ذلك سعيد بن العاص بالمدينة وهو واليها فمدحه وعنده الحطيئة وكعب بن جعيل فآمنه","page":"ص0","text":"فأتى من وجهه ذلك سعيد بن العاص بالمدينة وهو واليها فمدحه وعنده الحطيئة وكعب بن جعيل فآمنه سعيد فبلغه أن زيادا قال لو أتاني لآمنته واعطيته فقال في كلمة\n(دعاني زياد للعطاء ولم أكن ... لآتيه ماساق ذو حسب وفرا)\n(وعند زياد لو يريد عطاءهم ... رجال كثير قد يرى بهم فقرا)\n(قعود لدى الأبواب طالب حاجة ... عوان من الحاجات أوحاجة بكرا)\n(فلما خشينا أن يكون عطاؤه ... أداهم سودا أو محدرجة سمرا)\n(نميت إلى حرف أضر بنيها ... سرى البيد واستعراضها البلد القفرا)\n(يؤم بها الآفاق من لايرى له ... لدى ابن أبي سفيان جاها ولا عذرا)"},{"id":"tabaqat-shuara:405","bookId":"tabaqat-shuara","type":"section","seq":405,"chapter":"طبقات فحول الشعراء","title":"403- فلما اطمأن عند سعيد قال —","page":"ص0","text":"فلما اطمأن عند سعيد قال\n(ألا من مبلغ عني زيادا ... مغلغلة يخب بها بريد)\n(بأني قد فررت إلى سعيد ... ولا يسطاع مايحوي سعيد)\n(فررت إليه من ليث هزبر ... تفادى من فريسته الأسود)\n(فإن شئت انتسبت إلى النصارى ... وناسبني وناسبت اليهود)\n(وإن شئت انتسبت إلى فقيم ... وناسبني وناسبت القرود)\n(وأبغضهم إلى بنو فقيم ... ولكن سوف أفعل ما تكيد)"},{"id":"tabaqat-shuara:406","bookId":"tabaqat-shuara","type":"section","seq":406,"chapter":"طبقات فحول الشعراء","title":"404- وكان يدخل على القيان بالمدينة فقال في قينة —","page":"ص0","text":"وكان يدخل على القيان بالمدينة فقال في قينة\n(إذا شئت غناني من العاج قاصف ... على معصم ريان لم يتخدد)\n(لبيضاء من أهل المدينة لم تعش ... ببؤس ولم تتبع حمولة مجحد)\n(نعمت بها ليل التمام فلم يكد ... يروي استقائى هامة الحائم الصدي)\n(وقامت تخشينى زيادا وأجفلت ... حوالي في برد يمان ومجسد)\n(فقلت دعيني من زياد فإنني ... أرى الموت وقافا على كل مرصد)"},{"id":"tabaqat-shuara:407","bookId":"tabaqat-shuara","type":"section","seq":407,"chapter":"طبقات فحول الشعراء","title":"405- وقال —","page":"ج2 ص307","text":"وقال\n(ألم يأته أنى تخلل ناقتي ... بنعمان أطراف الأراك النواعم)\n(مقيدة ترعى الأراك ورحلها ... بمكة ملقى عائذ بالمحارم)\n(فدعني أكن ما كنت حيا حمامة ... من القاطنات البيت غير الروائم)\nفأنشدها زياد فرق له وقال عند ذلك لو أتاني لآمنته"},{"id":"tabaqat-shuara:408","bookId":"tabaqat-shuara","type":"section","seq":408,"chapter":"طبقات فحول الشعراء","title":"406- وفي ذلك يقول البكري —","page":"ص0","text":"وفي ذلك يقول البكري\n(ليالي تمنى أن تكون حمامة ... بمكة يؤويك الستار المحرم)"},{"id":"tabaqat-shuara:409","bookId":"tabaqat-shuara","type":"section","seq":409,"chapter":"طبقات فحول الشعراء","title":"407- فلما هلك زياد رثاه مسكين بن عامر بن شريح بن عمرو ابن عمرو وبن عدس الدارمي فقال —","page":"ص0","text":"فلما هلك زياد رثاه مسكين بن عامر بن شريح بن عمرو ابن عمرو وبن عدس الدارمي فقال\n(رأيت زيادة الإسلام ولت ... جهارا حين ودعها زياد)"},{"id":"tabaqat-shuara:410","bookId":"tabaqat-shuara","type":"section","seq":410,"chapter":"طبقات فحول الشعراء","title":"408- فقال الفرزدق —","page":"ص0","text":"فقال الفرزدق\n(أمسكين أبكى الله عينك إنما ... جرى في ضلال دمعها فتحدرا)\n(بكيت امرأ فظا غليظا مبغضا ... ككسرى على عدانه أو كقيصرا)\n(أقول له لما أتاني نعيه ... به لا بظبي بالصرائم أعفرا)"},{"id":"tabaqat-shuara:411","bookId":"tabaqat-shuara","type":"section","seq":411,"chapter":"طبقات فحول الشعراء","title":"409- فأجابه به مسكين فقال وهي أبيات —","page":"ص0","text":"فأجابه به مسكين فقال وهي أبيات\n(ألا أيها المرء الذي لست قائما ... ولا قاعدا في القوم إلا انبرى ليا)\n(فجئني بعم مثل عمي أو أب ... كمثل أبي أوخال صدق كخاليا)\n(كعمر وبن عمرو أوزرارة ذي الندى ... أو البشر من كل فرعت الروابيا)\nالبشر يعني خاله من النمر بن قاسط"},{"id":"tabaqat-shuara:412","bookId":"tabaqat-shuara","type":"section","seq":412,"chapter":"طبقات فحول الشعراء","title":"410- وقد مدحه مسكين فقال —","page":"ص0","text":"وقد مدحه مسكين فقال\n(شريح فارس النعمان عمى ... وخالي البشر بشر بنى هلال)\n(وقاتل خاله بأبيه منا ... سماعة لم يبع حسبا بمال)"},{"id":"tabaqat-shuara:413","bookId":"tabaqat-shuara","type":"section","seq":413,"chapter":"طبقات فحول الشعراء","title":"411- حدثني الحكم بن محمد قال كان تميم بن زيد رجلا من قضاعة من بلقين فكان على الهند وفي جيشه رجل","page":"ص0","text":"حدثني الحكم بن محمد قال كان تميم بن زيد رجلا من قضاعة من بلقين فكان على الهند وفي جيشه رجل يقال له خنيس أو حبيش طالت غيبته على أهله فأتت أمه قبر غالب بكاظمة فأقامت عليه حتى علم الفرزدق مكانها ثم أتته فطلبت إليه فكتب إلى تميم بن زيد\n(فهب لي حبيشا واتخذ فيه منة ... لغصة أم ما يسوغ شرابها)\n(أتتني فعاذت يا تميم بغالب ... وبالحفرة السافى عليه ترابها)\n(تميم بن زيد لا تكونن حاجتى ... بظهر فلا يخفى عليك جوابها)\nفلما أتاه كتابه لم يدر أخنيس أم حبيش وفي جيشه عدة خنيس وحبيش فأطلقهم جميعا له"},{"id":"tabaqat-shuara:414","bookId":"tabaqat-shuara","type":"section","seq":414,"chapter":"طبقات فحول الشعراء","title":"412- أبو يحيى الضبى قال ضرب مكاتب لبنى منقر قبة على قبر غالب فقدم الناس على الفرزدق فأخبروه أنه","page":"ص0","text":"أبو يحيى الضبى قال ضرب مكاتب لبنى منقر قبة على قبر غالب فقدم الناس على الفرزدق فأخبروه أنهم رأوا على قبر غالب بناء ثم قدم عليه وهو بالمريد فقال\n(بقبر ابن ليلى غالب عذت بعدما ... خشيت الردى أو أن أرد على قسر)\n(فأخبرني قبر ابن ليلى فقال لي ... فكاكك أن تلقى الفرزدق بالمصر)\nفقال الفرزدق صدق أبى أنخ أنخ ثم طاف له في الناس فجمع\nله مكاتبته وفضلا"},{"id":"tabaqat-shuara:415","bookId":"tabaqat-shuara","type":"section","seq":415,"chapter":"طبقات فحول الشعراء","title":"413- وكان ذو الأهدام وهو نفيع أحد بني جعفر بن كلاب توثب على الفرزدق فهجاه فجاءت أمه إلى قبر غال","page":"ص0","text":"وكان ذو الأهدام وهو نفيع أحد بني جعفر بن كلاب توثب على الفرزدق فهجاه فجاءت أمه إلى قبر غالب فعاذت به فقال الفرزدق\n(نبئت ذا الأهدام يعوي ودونه ... من الشام زراعاتها وقصورها)\n(على حين لم أترك من الأرض حية ... ولا نابحا إلا استسر عقورها)\n(كلاب نبحن الليث من كل جانب ... فعاد عواء بعد نبح هريرها)\n(عجوز تصلي الخمس عاذت بغالب ... فلا والذى عاذت به لا أضيرها)\n(لئن نافع لم يرع أرحام أمه ... وكانت كدلو لا يزال يعيرها)\n(لبئس دم المولود مس ثيابها ... عشية نادى بالغلام بشيرها)\n(وإني على إشفاقها من مخافتي ... وإن عقها بي نافع لمجيرها)\n(ولو أن أم الناس حواء حاربت ... تميم بن مر لم تجد من يجيرها)\nويقال إن هذا البيت ليس فيها"},{"id":"tabaqat-shuara:416","bookId":"tabaqat-shuara","type":"section","seq":416,"chapter":"طبقات فحول الشعراء","title":"414- قال قدم الفرزدق من اليمامة ودليله رجل من بلعنبر فضل به فقال —","page":"ص0","text":"قال قدم الفرزدق من اليمامة ودليله رجل من بلعنبر فضل به فقال\n(وما نحن إن جارت صدور ركابنا ... بأول من غرت دلالة عاصم)\n(أراد طريق العنصلين فياسرت ... به العيس في وادى الصوى المتشائم)\n(وكيف يضل العنبري ببلدة ... بها قطعت عنه سيور التمائم)\n(وجاء بجلمود له مثل رأسه ... ليشرب ماء القوم بين الصرائم)\n(فلما تصافنا الإداوة أجهشت ... إلي غضون العنبري الجراضم)\n(فآثرته لما رأيت الذي به ... من الشر أخشى لاحقات الملاوم)\n(على ساعة لو أن في القوم حاتما ... على جوده ضنت به نفس حاتم)"},{"id":"tabaqat-shuara:417","bookId":"tabaqat-shuara","type":"section","seq":417,"chapter":"طبقات فحول الشعراء","title":"415- فأجابه عاصم —","page":"ج2 ص315","text":"فأجابه عاصم\n(وكيف يضل الحنظلي ببلدة ... بها ولدته أمه غير قائم)\n(وزوراء ناء ماؤها من فلاتها ... كفينا سراها القين والقين نائم)\n(سرينا به ليل التمام فصبحت ... به العيس مروى من جمام الخضارم)"},{"id":"tabaqat-shuara:418","bookId":"tabaqat-shuara","type":"section","seq":418,"chapter":"طبقات فحول الشعراء","title":"416- وأنشد يونس للفرزدق حين طلق النوار —","page":"ص0","text":"وأنشد يونس للفرزدق حين طلق النوار\n(ندمت ندامة الكسعى لما ... مضت مني مطلقة نوار)\n(وكانت جنة فخرجت منها ... كآدم حين أخرجه الضرار)\n(وكنت كفاقئ عينيه عمدا ... فأصبح ما يضىء به النهار)\n(ولو ضنت يداي بها ونفسي ... لكان علي للقدر الخيار)\n(وما فارقتها شبعا ولكن ... رأيت الدهر يأخذ مايعار)"},{"id":"tabaqat-shuara:419","bookId":"tabaqat-shuara","type":"section","seq":419,"chapter":"طبقات فحول الشعراء","title":"417- وكان خالد بن عبد الله القسري حبس الكميت بن زيد — أبا المستهل الأسدي فحدثني سلام أبو المنذر ا","page":"ص0","text":"وكان خالد بن عبد الله القسري حبس الكميت بن زيد\nأبا المستهل الأسدي فحدثني سلام أبو المنذر القاري أن خالدا حبس الكميت بن زيد وكان قال لخالد\n(فإني وتمداحي يزيد وخالدا ... ضلالا لكالحادي وليس له إبل)\nفكانت أم المستهل تدخل عليه حتى عرف أهل السجن وبوابوه ثيابها وهيئتها\nفدخلت عند غفلة منهم فلبس ثيابها وتهيأ بهيئتها ثم خرج فقال\n(خرجت خروج القدح قدح ابن مقبل ... على الرغم من تلك النوابح والمشلى)\nعلي ثياب الغانيات وتحتها ... عزيمة أمر أشبهت سلة النصل)\nولذلك قالت القيسية لهشام حين كلموه في أمر الفرزدق حين\nحبسه خالد كلما كان في مضر ناب أو شاعر حبسه يعنون الكميت والفرزدق"},{"id":"tabaqat-shuara:420","bookId":"tabaqat-shuara","type":"section","seq":420,"chapter":"طبقات فحول الشعراء","title":"418- وأخبرنا يونس قال لما قدم المهدي أتاه ابن الكميت مدلا بطول مدح الكميت بني هاشم فقال له المه","page":"ج2 ص319","text":"وأخبرنا يونس قال لما قدم المهدي أتاه ابن الكميت مدلا بطول مدح الكميت بني هاشم فقال له المهدي أليس أبوك الذي يقول\nفالآن صرت إلى أمية والأمور لها مصائر\nآذهب فليس لك عندنا شيء"},{"id":"tabaqat-shuara:421","bookId":"tabaqat-shuara","type":"section","seq":421,"chapter":"طبقات فحول الشعراء","title":"419- وقال الفرزدق يعاتب قومه —","page":"ج2 ص319","text":"وقال الفرزدق يعاتب قومه\n(جزى الله عني في الخطوب مجاشعا ... جزاء كريم عالم كيف يصنع)\n(يرقون عظمى ما استطاعوا وإنني ... أشيد لهم بنيان مجد وأرفع)\n(وإني لتنهاني عن الجهل فيهم ... إذا كدت خلات من الحلم أربع)\n(حياء وبقيا وانتظار وأنني ... كريم فأعطي ما أشاء وأمنع)\n(فإن أعف أستبقى ذنوب مجاشع ... فإن العصا كانت لذي الحلم تقرع)"},{"id":"tabaqat-shuara:422","bookId":"tabaqat-shuara","type":"section","seq":422,"chapter":"طبقات فحول الشعراء","title":"420- اخبرني أبو يحيى الضبي قال لما هرب الفرزدق من زياد حين استعدى عليه بنو نهشل في هجائه إياهم","page":"ص0","text":"اخبرني أبو يحيى الضبي قال لما هرب الفرزدق من زياد حين استعدى عليه بنو نهشل في هجائه إياهم أتى سعيد بن العاص وهو على المدينة أيام معاوية فاستجاره فأجاره وعنده الحطيئة وكعب بن جعيل التغلبي فأنشده الفرزدق مدحته إياه التي يقول فيها\n(ترى الغر الجحاجح من قريش ... إذا ما الأمر في الحدثان عالا)\n(بني عم النبي ورهط عمرو ... وعثمان الألى غلبوا فعالا)\n(قياما ينظرون إلى سعيد ... كأنهم يرون به هلالا)\nفقال الحطيئة هذا والله هو الشعر لاما تعلل به منذ اليوم أيها الأمير فقال له كعب بن جعيل فضله على نفسك ولا تفضله على غيرك قال بل والله أفضله على نفسي وعلى غيري ياغلام أدركت من قبلك وسبقت من بعدك ثم قال له الحطيئة يا غلام لئن بقيت لتبرزن علينا يا غلام أنجدت أمك قال لا بل أبى يريد الحطيئة إن كانت أمك أنجدت فإني أصبتها فأشبهتني فألفاه لقن الجواب"},{"id":"tabaqat-shuara:423","bookId":"tabaqat-shuara","type":"section","seq":423,"chapter":"طبقات فحول الشعراء","title":"421- فنعاه عليه الطرماح حين هجاه فقال —","page":"ص0","text":"فنعاه عليه الطرماح حين هجاه فقال\n(فاسأل قفيرة بالمروت هل شهدت ... سوط الحطيئة بين السجف والنضد)\n(أم كان في غالب شعر فيشبهه ... شعر آبنها فيقال الشعر من صدد)\n(جاءت به نطفة من شر ما آتسقت ... منه إلى شر واد شق في بلد)"},{"id":"tabaqat-shuara:424","bookId":"tabaqat-shuara","type":"section","seq":424,"chapter":"طبقات فحول الشعراء","title":"422- قال وأول شعر قاله الفرزدق أن بني فقيم خرجوا يطلبون دما لهم في قوم فصالحوا منه على دية فقال","page":"ص0","text":"قال وأول شعر قاله الفرزدق أن بني فقيم خرجوا يطلبون دما لهم في قوم فصالحوا منه على دية فقال حين رجعوا\n(لقد آبت وفود بني فقيم ... بآلم ما تؤوب به الوفود)\nفشكوه إلى أبيه واستعدوه منه فقال هو أوغد من ذاك ليته يقول شعرا فقال الفرزدق\n(تعذرت من شتم العشيرة مؤليا ... ولا بد للمظنون أن يتعذرا)\nفلما سمعه أبوه قال أنت صاحب الأول"},{"id":"tabaqat-shuara:425","bookId":"tabaqat-shuara","type":"section","seq":425,"chapter":"طبقات فحول الشعراء","title":"423- وكان يرعى غنما لأهله يعني في صغره فذهب الذئب منها بكبش فقال —","page":"ص0","text":"وكان يرعى غنما لأهله يعني في صغره فذهب الذئب منها بكبش فقال\n(تلوم على أن صبح الذئب ضأنها ... فألوى بكبش وهو في الرعي راتع)\n(وقد مر حول بعد حول وأشهر ... بعوص عليه وهو ظمآن جائع)\n(فلما رأى الإقدام حزما وأنه ... أخو الموت من سدت عليه المطالع)\n(أغار على خوف وصادف غرة ... فلاقى التى كانت عليها المطامع)\n(وما كنت مضياعا ولكن همتي ... سوى الرعي مفطوما ومذأنا يافع)\n(أبيت أسوم النفس كل عظيمة ... إذا وطنت للمكثرين المضاجع)\nفكان ذلك أول ما علم به من شعره"},{"id":"tabaqat-shuara:426","bookId":"tabaqat-shuara","type":"section","seq":426,"chapter":"طبقات فحول الشعراء","title":"424- وكان راعي الإبل يفضله وفي ذلك هجاه جرير","page":"ص0","text":"وكان راعي الإبل يفضله وفي ذلك هجاه جرير"},{"id":"tabaqat-shuara:427","bookId":"tabaqat-shuara","type":"section","seq":427,"chapter":"طبقات فحول الشعراء","title":"425- وحدثني أبو بكر محمد بن واسع وعبد القاهر بن السري السليمان قالا كان منا من بني حرام بن سمال","page":"ص0","text":"وحدثني أبو بكر محمد بن واسع وعبد القاهر بن السري السليمان قالا كان منا من بني حرام بن سمال شويعر هجا الفرزدق فأخذناه فأتيناه به فقلنا هاهو ذا بين يديك فإن شئت فاضرب وإن شئت فاحلق لا عدوى عليك ولا قصاص قد برئنا إليك منه فخلى عنه وقال\n(فمن يك خائفا لأذاة شعري ... فقد أمن الهجاء بنو حرام)\n(هم قادوا سفيههم وخافوا ... قلائد مثل أطواق الحمام)"},{"id":"tabaqat-shuara:428","bookId":"tabaqat-shuara","type":"section","seq":428,"chapter":"طبقات فحول الشعراء","title":"426- وحدثني عبد القاهر السلمي قال مر الفرزدق بمجلس بني حرام ومعنا عنبسة مولى عثمان بن عفان وهو","page":"ص0","text":"وحدثني عبد القاهر السلمي قال مر الفرزدق بمجلس بني حرام ومعنا عنبسة مولى عثمان بن عفان وهو جد عبد الكريم\nابن روح فقال يا أبا فراس متى تذهب إلى الآخرة قال وما حاجتك إلى ذلك يا أخي قال أكتب معك إلى أبي قال أنا لا أذهب إلى حيث أبوك في النار اكتب إليه مع دبالويه واصطفانوس"},{"id":"tabaqat-shuara:429","bookId":"tabaqat-shuara","type":"section","seq":429,"chapter":"طبقات فحول الشعراء","title":"427- حدثني عمر بن السكن الصريمي قال مر الفرزدق ببني ربيع وهو على بغلة فوقف عليهم وفيهم ابن محكا","page":"ص0","text":"حدثني عمر بن السكن الصريمي قال مر الفرزدق ببني ربيع وهو على بغلة فوقف عليهم وفيهم ابن محكان شاعرهم وقد كان قال من الفرزدق غضبا لبني منقر حين هجاهم الفرزدق وكان قال\n(سوى أن أعراف الكوادن منقرا ... قبيلة سوء بار في الناس سوقها)"},{"id":"tabaqat-shuara:430","bookId":"tabaqat-shuara","type":"section","seq":430,"chapter":"طبقات فحول الشعراء","title":"430- فقال عمر بن سكن في حديثه فقال له بنو ربيع مرحبا بسيدنا وشاعرنا قال أير البغل في حرم سيدكم","page":"ص0","text":"فقال عمر بن سكن في حديثه فقال له بنو ربيع مرحبا بسيدنا وشاعرنا قال أير البغل في حرم سيدكم يعني ابن محكان"},{"id":"tabaqat-shuara:431","bookId":"tabaqat-shuara","type":"section","seq":431,"chapter":"طبقات فحول الشعراء","title":"431- حدثني أبو الغراف قال أتى الفرزدق عبد الله بن مسلم الباهلي فثقل عليه الكثير وخشيه في القليل","page":"ص0","text":"حدثني أبو الغراف قال أتى الفرزدق عبد الله بن مسلم الباهلي فثقل عليه الكثير وخشيه في القليل وعنده عمرو بن عفرى الضبي راوية الفرزدق وقد كان جرير هجاه لروايته للفرزدق فقال\n(ونبئت جوابا وسكنا يسبني ... وعمرو بن عفرى لا سلام على عمرو)\nفقال عمرو بن عفرى لعبد الله بن مسلم وهو الذي يلقب الفقير لا يهو لنك أمره أنا أرضيه عنك بدون ما كان هم له به فأعطاه ثلاث مئة درهم فقبلها ورضي ثم بلغه صنيع ابن عفرى فقال\n(تفوقت مال الباهلي كأنما ... تهر على المال الذي أنت كاسبه)\n(فلو كنت ضبيا صفحت ولو سرت ... على قدمي حياته وعقاربه)\n(ولكن ديافي أبوه وأمه ... بحوران يعصرن السليط أقاربه)\nفقال له ابن عفرى وأتاه في نادي قومه اجهد جهدك\nفهل هو إلا هذا فو الله لا أدع لك مساءة إلا أتيتها ولا تأمرني بشيء إلا اجتنبته ولا تنهى عن شيء إلا ركبته فقال إنك لا تدوم إنك ترجع فأكد عليه فقال فاشهدوا أنى أنهاه أن يفعل بأمه كذا وكذا"},{"id":"tabaqat-shuara:432","bookId":"tabaqat-shuara","type":"section","seq":432,"chapter":"طبقات فحول الشعراء","title":"432- حدثني شعيب بن صخر قال تزوج ذبيان بن أبى ذبيان العدوي من بلعدوية مولاة لهم فدعا الناس في ول","page":"ج2 ص329","text":"حدثني شعيب بن صخر قال تزوج ذبيان بن أبى ذبيان العدوي من بلعدوية مولاة لهم فدعا الناس في وليمته فدعا ابن أبى شيخ الفقيمي فألفى الفرزدق عنده فقال عنده فقال يا أبا فراس انهض فقال إنه لم يدعني فقال إن ذبيان يؤتى وإن لم يدع ثم قال لاتخرج من عنده إلا بجأنرة فقام معه فلما دخل على ذبيان قال\n(كم قال لي آبن ابي شيخ وقلت له ... كيف السبيل إلى معروف ذبيان)\n(إن القلوص إذا ألقت جآجئها ... بمثل بابك لم ترحل بحرمان)\nقال أجل يا أبا فراس فادخل فدخل فأعطاه ثلاث مئة درهم"},{"id":"tabaqat-shuara:433","bookId":"tabaqat-shuara","type":"section","seq":433,"chapter":"طبقات فحول الشعراء","title":"433- وحدثني أبو بكر المدني قال قدم الفرزدق المدينة — فوافق بها موت طلحة بن عبد الله بن عوف الزهري","page":"ج2 ص329","text":"وحدثني أبو بكر المدني قال قدم الفرزدق المدينة\nفوافق بها موت طلحة بن عبد الله بن عوف الزهري وكان سيدا سخيا شريفا فقال يا أهل المدينة أنتم أذل قوم قالوا وما ذاك يا أبا فراس قال غلبكم الموت على طلحة حتى أخذه من بينكم"},{"id":"tabaqat-shuara:434","bookId":"tabaqat-shuara","type":"section","seq":434,"chapter":"طبقات فحول الشعراء","title":"434- قال وأتى مكة فأتى عبد الله بن صفوان بن أمية بن خلف الجمحي وهو سيد أهل مكة يومئذ وليس عنده","page":"ص0","text":"قال وأتى مكة فأتى عبد الله بن صفوان بن أمية بن خلف الجمحي وهو سيد أهل مكة يومئذ وليس عنده نقد حاضر وهو يتوقع عطيته وعطية ولده\nفقال والله يا أبا فراس ما وافقت عندنا نقدا ولكن عروضا إن شئت فإن عندنا وصفاء فرهة فإن شئت أخذتهم قال نعم فأرسل إليه بوصفاء من بنيه وبني أخيه وقال هم لك عندنا إلى أن تشخص وجاءه العطاء فأخبره الخبر وفداهم فقال الفرزدق ونظر إلى عبد العزيز بن عبد الله بن خالد بن أسيد وكان سيدا يطوف بالبيت يتبختر\n(تمشي تبختر حول البيت منتحيا ... لو كنت عمرو بن عبد الله لم تزد)"},{"id":"tabaqat-shuara:435","bookId":"tabaqat-shuara","type":"section","seq":435,"chapter":"طبقات فحول الشعراء","title":"435- وتزوج الفرزدق النوار بنت أعين بن ضبيعة المجاشعي فادعت عليه طلاقا ونازعته — حتى قدمت على ابن","page":"ص0","text":"وتزوج الفرزدق النوار بنت أعين بن ضبيعة المجاشعي فادعت عليه طلاقا ونازعته\nحتى قدمت على ابن الزبير في خلافته وأتبعها واتهم رجالا من قومه يعينونها فقال الفرزدق\n(أطاعت بني أم النسير فأصبحت ... على قتب يعلو الفلاة دليلها)\n(تأمل أمير المؤمنين فإنها ... مولهة يوهي الحجارة قيلها)\nفلجأت إلى أم هاشم بنت منظور بن زبان الفزاري امرأة ابن الزبير ولجأ الفرزدق إلى حمزة بن عبد الله بن الزبير وأمه تماضر بنت منظور فكان حمزة إذا أصلح شيئا من أمر الفرزدق قلبت أم هاشم رأى عبد الله إلى النوار فقال الفرزدق\n(أما البنون فلم تقبل شهادتهم ... وشفعت بنت منظور بن زبانا)\n(ليس الشفيع الذي يأتيك متزرا ... مثل الشفيع الذي يأتيك عريانا)"},{"id":"tabaqat-shuara:436","bookId":"tabaqat-shuara","type":"section","seq":436,"chapter":"طبقات فحول الشعراء","title":"436- أخبرني إبراهيم بن حبيب بن الشهيد عن أبيه قال قال له ابن الزبير ما حاجتك بها وقد كرهتك كن ل","page":"ج2 ص333","text":"أخبرني إبراهيم بن حبيب بن الشهيد عن أبيه قال قال له ابن الزبير ما حاجتك بها وقد كرهتك كن لها أكره وخل سبيلها\nفخرج وهو يقول ما أمرني بطلاقها إلا ليثب عليها فبلغ ذلك ابن الزبير فخرج وقد استهل هلال ذي الحجة ولبس ثياب الإحرام يريد البيت ليحرم فألفى الفرزدق بباب المسجد عند الباعة فأخذ بعنقه فغمزها حتى جعل رأسه بين ركبتيه فقال\n(ألا أصبحت عرس الفرزدق ناشزا ... ولو رضيت رمح استه لاستقرت)\nوالبيت لجعفر بن الزبير فيما ذكر عبد الله بن مصعب"},{"id":"tabaqat-shuara:437","bookId":"tabaqat-shuara","type":"section","seq":437,"chapter":"طبقات فحول الشعراء","title":"437- وكان الفرزدق إذا أصاب دراهم أتى بها النوار فتحرز بعضها وتعطيه بعضها وكانت مسلمة تأله فكانت","page":"ج2 ص333","text":"وكان الفرزدق إذا أصاب دراهم أتى بها النوار فتحرز بعضها وتعطيه بعضها وكانت مسلمة تأله فكانت تزعم أنه طلقها ويجحدها فاحتاج يوما فقالت أعطيك كذا وكذا درهما على أن تشهد\nعلى طلاقي الحسن قال نعم فأعطته فقال أيها الشيخ إني قد طلقت النوار قال قد سمعنا ما قلت فلما حضرها الموت أوصته وهو ابن عمها أن يصلي عليها الحسن فأخبره فقال إذا فرغتم فأعلموني وأخرجت وجاء الحسن فسبقهم الناس فانتظروهما فأقبلا والناس ينظرون قد استبطؤوهم فقال الحسن ما للناس فقال الفرزدق يرون خير الناس وشر الناس قال لست بخير الناس ولست بشرهم وقال له الحسن وهو على قبرها ما أعددت لهذا المضجع قال شهادة أن لا إله إلا الله مذ سبعون سنة"},{"id":"tabaqat-shuara:438","bookId":"tabaqat-shuara","type":"section","seq":438,"chapter":"طبقات فحول الشعراء","title":"438- حدثني عامر بن أبي عامر وهو صالح بن رستم الخراز قال أخبرني أبو بكر الهذلي قال إنالجلوس عند","page":"ص0","text":"حدثني عامر بن أبي عامر وهو صالح بن رستم الخراز قال أخبرني أبو بكر الهذلي قال إنالجلوس عند الحسن إذ جاء الفرزدق يتخطى حتى جلس إلى جنبه فجاء رجل فقال يا أبا سعيد الرجل يقول في كلامه لا والله بلى والله ولا يريد\nاليمين فقال الفرزدق أو ما سمعت ما قلت في ذلك فقال الحسن ما كل ما قلت سمعوا وما قلت قال قلت\n(ولست بمأخوذ بشىء تقوله ... إذا لم تعمد عافدات العزائم)\nقال ثم لم يلبث أن جاء رجل آخر فقال يا أبا سعيد إنا نكون في هذه المغازي فنصيب المرأة لها زوج أفيحل غشيانها ولم يطلقها زوجها فقال الفرزدق أو ما سمعت ما قلت في ذلك قال الحسن ما كل ما قلت سمعوا فما قلت في ذلك قال قلت\n(وذات حليل أنكحتنا رماحنا ... حلالا لمن يبني بها لم تطلق)"},{"id":"tabaqat-shuara:439","bookId":"tabaqat-shuara","type":"section","seq":439,"chapter":"طبقات فحول الشعراء","title":"439- أخبرني محمد بن جعفر الزيبقي قال أتى الفرزدق الحسن فقال إني قد هجوت إبليس فاسمع قال لا حاجة","page":"ص0","text":"أخبرني محمد بن جعفر الزيبقي قال أتى الفرزدق الحسن فقال إني قد هجوت إبليس فاسمع قال لا حاجة لنا فيما تقول قال لتسمعن أو لأخرجن فأقول للناس الحسن ينهى عن هجاء إبليس فقال الحسن اسكت فإنك عن لسانه تنطق"},{"id":"tabaqat-shuara:440","bookId":"tabaqat-shuara","type":"section","seq":440,"chapter":"طبقات فحول الشعراء","title":"440- وقال رجل لابن سيرين وهو قائم مستقبل القبلة يريد — أن يكبر أتوضأ من الشعر فانصرف بوجهه فقال —","page":"ص0","text":"وقال رجل لابن سيرين وهو قائم مستقبل القبلة يريد\nأن يكبر أتوضأ من الشعر فانصرف بوجهه فقال\n(ألا أصبحت عرس الفرزدق ناشزا ... ولو رضيت رمح استه لاستقرت)\nثم توجه إلى القبلة وكبر"},{"id":"tabaqat-shuara:441","bookId":"tabaqat-shuara","type":"section","seq":441,"chapter":"طبقات فحول الشعراء","title":"441- أخبرني عبد الملك بن عبد العزيز الماجشوني عن يحيى ابن زيد قال دخل رجل على الحسن فسمعه يقول","page":"ص0","text":"أخبرني عبد الملك بن عبد العزيز الماجشوني عن يحيى ابن زيد قال دخل رجل على الحسن فسمعه يقول والله الذي لا إله إلا هو لتبعثن ثم قال والله الذي لا إله إلا هو لتموتن والله الذى لا إله إلا هو لتحاسبن قال فقلت هذا حلاف فخرجت من عنده فأتيت ابن سيرين فإذا عنده جرير ينشده ويحدثه قلت هذا صاحب باطل فتركتهما فندمت"},{"id":"tabaqat-shuara:442","bookId":"tabaqat-shuara","type":"section","seq":442,"chapter":"طبقات فحول الشعراء","title":"442- حدثني شعيب بن صخر عن محمد بن زياد وكان في ديماس الحجاج زمانا حتى أطلقه سليمان حين قام قال","page":"ص0","text":"حدثني شعيب بن صخر عن محمد بن زياد وكان في ديماس الحجاج زمانا حتى أطلقه سليمان حين قام قال انتهيت إلى الفرزدق وهو ينشد بمكة بالردم مديح سليمان بن عبد الملك وهو يقول\n(وكم أطلقت كفاك من قيد بائس ... ومن عقدة ما كان يرجى أنحلالها)\n(كثيرا من الأيدي التي قد تكنعت ... وفككت أعناقا عليها غلالها)\nفقلت أنا والله أحدهم قال فأخذ بيدي وقال أيها الناس سلوه فوالله ما كذبت قط"},{"id":"tabaqat-shuara:443","bookId":"tabaqat-shuara","type":"section","seq":443,"chapter":"طبقات فحول الشعراء","title":"443- وسمعت الحارث بن محمد بن زياد قال كتب يزيد بن المهلب حين فتح جرجان إلى أخيه مدركة أو مروان","page":"ص0","text":"وسمعت الحارث بن محمد بن زياد قال كتب يزيد بن المهلب حين فتح جرجان إلى أخيه مدركة أو مروان احمل الفرزدق ليقول في آثارنا فإذا شخص فأعط أهله كذا وكذا قال أحسبه قال عشة آلاف درهم فقال الفرزدق ادفعها إلي قال اشخص وأدفعها إلى أهلك فأبى وخرج وهو يقول\n(دعاني إلى جرجان والرى دونه ... لآتيه إني إذن لزؤور)\n(لآتى من آل المهلب ذائرا ... بأعراضهم والدائرات تدور)\n(سآبى وتأبى لي تميم وربما ... أبيت فلم يقدر علي أمير)"},{"id":"tabaqat-shuara:444","bookId":"tabaqat-shuara","type":"section","seq":444,"chapter":"طبقات فحول الشعراء","title":"444- أنا أبو خليفة نا ابن سلام قال سمعت سلمة بن عياش قال حبست في السجن فإذا فيه الفرزدق حبسه ما","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال سمعت سلمة بن عياش قال حبست في السجن فإذا فيه الفرزدق حبسه مالك بن المندر بن الجارود فكان يريد أن يقول البيت فيقول صدره فأسبقه إلى القافية ويجىء بالقافية فأسبقه إلى الصدر قال لي ممن أنت قلت من قريش قال كل أير حمار من قريش من أيهم أنت قلت من بني عامر قال لئام والله أذلة جاورتهم فكانوا شر جيران قلت أفلا أخبرك بأذل منهم وألأم قال بلى قلت بنو مجاشع قال ويلك ولم قلت أنت شاعرهم وسيدهم وابن سيدهم جاءك شرطي مالك حتى أدخلك السجن لم يمنعوك قال قاتلك الله"},{"id":"tabaqat-shuara:445","bookId":"tabaqat-shuara","type":"section","seq":445,"chapter":"طبقات فحول الشعراء","title":"445- أنا أبو خليفة نا ابن سلام قال فأنشدني يونس النحوي وعبد القاهر السلمي للفرزدق حين عزل يزيد","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال فأنشدني يونس النحوي وعبد القاهر السلمي للفرزدق حين عزل يزيد مسلمة عن العراق بعد قتله يزيد بن المهلب واستعمل عمر بن هبيره\n(ولت بمسلمة الركاب مودعا ... فأرعى فزارة لاهناك المرتع)\n(فسد الزمان وبدلت أعلامه ... حتى أمية عن فزارة تنزع)\n(ولقد علمت إذا فزارة أمرت ... أن سوف تطمع في الإمارة أشجع)\n(ولخلق ربك ماهم ولمثلهم ... في مثل ما نالت فزارة تطمع)\n(تزع ابن بشر وابن عمرو قبله ... وأخو هراة لمثلها يتوقع)\nابن بشر عبد الملك بن بشر بن مروان كان مسلمة أمره على البصرة\nوابن عمرو سعيد بن عمرو بن الوليد بن عقبة بن أبي معيط وكان على خراسان وأخو هراة سعيد بن عبد العزيز بن الحارث ابن الحكم بن أبي العاصي"},{"id":"tabaqat-shuara:446","bookId":"tabaqat-shuara","type":"section","seq":446,"chapter":"طبقات فحول الشعراء","title":"446- وقال إسماعيل بن عمار الأسدي حين عزل ابن هبيرة وأمر خالد القسري —","page":"ص0","text":"وقال إسماعيل بن عمار الأسدي حين عزل ابن هبيرة وأمر خالد القسري\n(عجب الفرزدق من فزارة أن رأى ... عنها أمية في المشارق تنزع)\n(فلقد رأى عجبا وأحدث بعده ... أمر تطير له القلوب وتفزع)\n(بكت المنابر من فزارة شجوها ... فاليوم من قسر تضج وتجزع)\n(وبنو أمية أضرعونا للعدى ... لله در ملوكناما تصنع)\n(كانوا كتاركة بنيها جانبا ... سفها وغيرهم تصون وترضع)\nوقال قوم إن هذا البيت للفرزدق ومن أنشده له قال\n(وملوك خندف أضرعونا للعدى ... )"},{"id":"tabaqat-shuara:447","bookId":"tabaqat-shuara","type":"section","seq":447,"chapter":"طبقات فحول الشعراء","title":"447- ويروى للفرزدق في ابن هبيرة —","page":"ص0","text":"ويروى للفرزدق في ابن هبيرة\n(أمير المؤمنينوأنت عف ... كريم لست بالطبع الحريص)\n(أوليت العراق ورافديه ... فزاريا أحذ يد القميص)\n(تفنق بالعراق أبو المثنى ... وعلم أهله أكل الخبيص)\n(ولم يك قبلها راعي مخاض ... ليأمنه على وركى قلوص)"},{"id":"tabaqat-shuara:448","bookId":"tabaqat-shuara","type":"section","seq":448,"chapter":"طبقات فحول الشعراء","title":"448- وأنشدني له يونس —","page":"ص0","text":"وأنشدني له يونس\n(جهز فإنك ممتار ومبتعث ... إلى فزارة عيرا تحمل الكمرا)\n(إن الفزارى لو يعمى فأطعمه ... أير الحمار طبيب أبرأ البصرا)\n(إن الفزارى لا يشفيه من قرم ... أطايب العير حتى ينهش الذكرا)\n(لما أتوه بما فى القدر أنكره ... وآسترجع الضيف لما أبصر الكمرا)\n(يقول لما رأى مافي إنائهم ... لله ضيف الفزاريين ما آنتظرا)"},{"id":"tabaqat-shuara:449","bookId":"tabaqat-shuara","type":"section","seq":449,"chapter":"طبقات فحول الشعراء","title":"449- فلما قدم خالد بن عبد الله القشري واليا على ابن هبيرة حبسه في السجن فنقب له سرب فخرج منه فه","page":"ص0","text":"فلما قدم خالد بن عبد الله القشري واليا على ابن هبيرة حبسه في السجن فنقب له سرب فخرج منه فهرب إلى الشام فقال فيه الفرزدق يذكر خروجه\n(لما رأيت الأرض قد سد ظهرها ... ولم تر إلا بطنها لك مخرجا)\n(دعوت الذي ناداه يونس بعدما ... ثوى في ثلاث مظلمات ففرجا)\n(فأصبحت تحت الأرض قد سرت ليلة ... وما سار سار مثلها حين أدلجا)\n(خرجت ولم يمنن عليك شفاعة ... سوى ربذ التقريب من آل أعوجا)\n(أغرمن اللحق اللهاميم إذ جرى ... جرى بك محبوك القرا غيرأفحجا)\n(جرى بك عريان الحماتين ليله ... به عنك أرخى الله ما كان أشرجا)\n(وما آحتال محتال كحيلته التي ... بها نفسه تحت الصريمة أولجا)\n(وظلماء تحت الأرض قد خضت هولها ... وليل كلون الطيلسانى أدعجا)\n(هما ظلمتا ليل وأرض تلاقتا ... على جامع من همه ما تعرجا)"},{"id":"tabaqat-shuara:450","bookId":"tabaqat-shuara","type":"section","seq":450,"chapter":"طبقات فحول الشعراء","title":"450- أنا أبو خليفة نا ابن سلام قال حدثني جابر بن جندل قال قيل لابن هبيرة من سيد أهل العراق قال","page":"ج2 ص345","text":"أنا أبو خليفة نا ابن سلام قال حدثني جابر بن جندل قال قيل لابن هبيرة من سيد أهل العراق قال الفرزدق هجاني ملكا ومدحني سوقة"},{"id":"tabaqat-shuara:451","bookId":"tabaqat-shuara","type":"section","seq":451,"chapter":"طبقات فحول الشعراء","title":"451- وقال لخالد بن عبد الله حين قدم العراق أميرا لهشام —","page":"ج2 ص345","text":"وقال لخالد بن عبد الله حين قدم العراق أميرا لهشام\n(ألا قطع الرحمن ظهر مطية ... أتتنا تخطى من دمشق بخالد)\n(وكيف يؤم الناس من كانت أمه ... تدين بأن الله ليس بواحد)\n(بنى بيعة فيها الصليب لأمه ... وهدم من كفر منار المساجد)"},{"id":"tabaqat-shuara:452","bookId":"tabaqat-shuara","type":"section","seq":452,"chapter":"طبقات فحول الشعراء","title":"452- وقال أيضا —","page":"ج2 ص345","text":"وقال أيضا\n(نزلت بجيلة واسطا فتمكنت ... ونفت فزارة عن قرار المنزل)"},{"id":"tabaqat-shuara:453","bookId":"tabaqat-shuara","type":"section","seq":453,"chapter":"طبقات فحول الشعراء","title":"453- وقال —","page":"ص0","text":"وقال\n(لعمرى لئن كانت بجيلة زانها ... جرير لقد أخزى بجيلة خالد)"},{"id":"tabaqat-shuara:454","bookId":"tabaqat-shuara","type":"section","seq":454,"chapter":"طبقات فحول الشعراء","title":"454- فلما قدم العراق أميرا أمر على شرطة البصرة مالك ابن المنذر بن الجارود فكتب إليه خالد أن احب","page":"ص0","text":"فلما قدم العراق أميرا أمر على شرطة البصرة مالك ابن المنذر بن الجارود فكتب إليه خالد أن احبس الفرزدق فإنه هجا أمير المؤمنين بأبيات قالها الفرزدق حين حفر خالد النهر الذي سماه المبارك\n(أهلكت مال الله في غير حقه ... على نهرك المشؤوم غير المبارك)\n(وتضرب أقواما براء ظهورهم ... وتترك حق الله في ظهر مالك)\n(أإنفاق مال الله في غير كنهه ... ومنعا لحق المرملات الضرائك)\nوكان عبد الأعلى بن عبد الله بن عامر يدعي على مالك فرية فأبطلها خالد"},{"id":"tabaqat-shuara:455","bookId":"tabaqat-shuara","type":"section","seq":455,"chapter":"طبقات فحول الشعراء","title":"455- أنا أبو خليفة نا محمد بن سلام قال حدثني أبو يحيى قال قال الفرزدق لابنه لبطة وهو محبوس اشخص","page":"ص0","text":"أنا أبو خليفة نا محمد بن سلام قال حدثني أبو يحيى قال قال الفرزدق لابنه لبطة وهو محبوس اشخص إلى هشام\nومدحه بقصيدة وقال لابنه استعن بالقيسية ولا يمنعك منهم هجائي لهم فإنهم سيغضبون لك وقال\n(بكت عين محزون ففاض سجامها ... وطالت ليالى حادث لا ينامها)\n(فإن نبك لا نبكي المصيبات إذ أتى ... بها الدهر والأيام جم خصامها)\n(ولكنما نبكي تنهك خالد ... محارم منا لا يحل حرامها)\n(أنقتل فيكم أن قتلنا عدوكم ... على دينكم والحرب باد قتامها)\n(فغير أمير المؤمنين فإنها ... يمانية حمقاء أنت هشامها)\nقال أنشدنيها أبو الغراف فأعانته القيسية وقالوا يا أمير\nالمؤمنين إذا ما كان في مضر ناب أو شاعر أو سيد وثب عليه خالد فحبسه"},{"id":"tabaqat-shuara:456","bookId":"tabaqat-shuara","type":"section","seq":456,"chapter":"طبقات فحول الشعراء","title":"456- وقال الفرزدق أبياتا كتب بها إلى سعيد بن الوليد الأبرش الكلبي وكلم له هشاما —","page":"ج2 ص349","text":"وقال الفرزدق أبياتا كتب بها إلى سعيد بن الوليد الأبرش الكلبي وكلم له هشاما\n(إلى الأبرش الكلبي أسندت حاجة ... تواكلها حيا تميم ووائل)\n(على حين أن زلت بي النعل زلة ... فأخلف ظني كل حاف وناعل)\n(فدونكم يا ابن الوليد فإنها ... مفضلة أصحابها في المحافل)\n(ودونكها يا ابن الوليد فقم بها ... قيام امرىء في قومه غير خامل) فكلم له هشاما فأمر بتخليته\nفقال يمدح الأبرش\n(لقد وثب الكلبي وثبة حازم ... إلى خير خلق الله نفسا وعنصرا)\n(إلى خير أبناء الخليفة لم يجد ... لحاجته من دونها متأخرا)\n(أبى حلف كلب في تميم وعقدها ... كما سنت الآباء أن يتغيرا)"},{"id":"tabaqat-shuara:457","bookId":"tabaqat-shuara","type":"section","seq":457,"chapter":"طبقات فحول الشعراء","title":"458- وكان حلف قديم بين كلب وتميم في الجاهلية وذلك قول جرير —","page":"ص0","text":"وكان حلف قديم بين كلب وتميم في الجاهلية وذلك قول جرير\n(تميم إلى كلب وكلب إليهم ... أحق وأولى من صداء وحميرا)"},{"id":"tabaqat-shuara:458","bookId":"tabaqat-shuara","type":"section","seq":458,"chapter":"طبقات فحول الشعراء","title":"459- وقال الفرزدق —","page":"ص0","text":"وقال الفرزدق\n(أشد حبال بين حيين مرة ... حبال أمرت من تميم ومن كلب)\n(وليس قضاعي لدينا بخائف ... ولو أصبحت تغلي القدور من الحرب)"},{"id":"tabaqat-shuara:459","bookId":"tabaqat-shuara","type":"section","seq":459,"chapter":"طبقات فحول الشعراء","title":"460- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(ألم تر قيسا قيس عيلان شمرت ... لنصري وحاطتني هناك قرومها)\n(فقد حالفت قيس على الناس كلهم ... تميما فهم منها ومنها تميمها)\n(وعادت عدوى إن قيسا لأسرتي ... وقومى إذا ما الناس عدصميمها)"},{"id":"tabaqat-shuara:460","bookId":"tabaqat-shuara","type":"section","seq":460,"chapter":"طبقات فحول الشعراء","title":"461- قال محمد بن سلام وحدثني عبد القاهر بن السري قال قال عمر بن يزيد بن عمير الأسيدي وسمعت يونس","page":"ص0","text":"قال محمد بن سلام وحدثني عبد القاهر بن السري قال قال عمر بن يزيد بن عمير الأسيدي وسمعت يونس يقول ما كان بالبصرة مولد مثله قال دخلت على هشام بن عبد الملك وعنده خالد بن عبد الله القسري يتكلم ويذكر اليمن وطاعتها فأكثر\nفي ذلك فصفقت تصفيقة دوى البهو منها فقلت تالله مارأيت كاليوم خطلا والله إن فتحت فتنة في الإسلام إلا باليمن لقد قتلوا أمير المؤمنين عثمان ولقد خرج ابن الأشعث على أمير المؤمنين عبد الملك بن مروان وإن سيوفنا تقطر من دماء بني المهلب فلما نهضت تبعني رجل من بني مروان حضر ذاك فقال يا أخا تميم وريت بك زنادى قد شهدت مقالتك واعلم ان أمير المؤمنين موليه العراق وإنها ليست لك بدار"},{"id":"tabaqat-shuara:461","bookId":"tabaqat-shuara","type":"section","seq":461,"chapter":"طبقات فحول الشعراء","title":"462- فلما ولي خالد استعمل على أحداث البصرة مالك بن المنذر فكان لعمر مكرما ولحوائجه قضاء إلى أن","page":"ص0","text":"فلما ولي خالد استعمل على أحداث البصرة مالك بن المنذر فكان لعمر مكرما ولحوائجه قضاء إلى أن وجد عليه وكان عمر لا يملك لسانه فخرج من عنده وقد سأله حاجة فقضاها فقال كيف رأيت الفساء سخرنا به منذ اليوم"},{"id":"tabaqat-shuara:462","bookId":"tabaqat-shuara","type":"section","seq":462,"chapter":"طبقات فحول الشعراء","title":"463- وقال قائلون إن خالد كتب إليه فيه فأخذه وشهد عليه ناس من بني تميم وغيرهم فضربه مالك حتى قتل","page":"ص0","text":"وقال قائلون إن خالد كتب إليه فيه فأخذه وشهد عليه ناس من بني تميم وغيرهم فضربه مالك حتى قتله تحت السياط"},{"id":"tabaqat-shuara:463","bookId":"tabaqat-shuara","type":"section","seq":463,"chapter":"طبقات فحول الشعراء","title":"464- وكان عمرو بن مسلم الباهلي أعان عليه وكانت حميدة بنت مسلم عند مالك بن المنذر وأعان عليه بشي","page":"ص0","text":"وكان عمرو بن مسلم الباهلي أعان عليه وكانت حميدة بنت مسلم عند مالك بن المنذر وأعان عليه بشير بن عبيد الله بن أبي بكرة وكان يخاصم هلال بن أحوز في المرغاب خصومة طويلة وكان عمر يعين على بشير فقال الفرزدق\n(لحا الله قوما شاركوا في دمائنا ... وكنا لهم عونا على العثرات)\n(فجاهرنا ذو الغش عمرو بن مسلم ... وأوقد نارا صاحب البكرات)\nيعني بشيرا"},{"id":"tabaqat-shuara:464","bookId":"tabaqat-shuara","type":"section","seq":464,"chapter":"طبقات فحول الشعراء","title":"465- أنا أبو خليفة نا ابن سلام قال حدثني خلاد بن يزيد عن سلم بن قتيبة قال رآني بشير بن عبيد الل","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني خلاد بن يزيد عن سلم بن قتيبة قال رآني بشير بن عبيد الله وأنا أخاصم بعض أهلي وأنا شاب فقال لي يا ابن أخي إني أراك ثبت المروءة فإياك والخصومات فإنها تذهب المروءة\nفرأيته بعد ذلك يخاصم هلال أبن أحوز في المرغاب خصومة طويلة فقلت له أتذكر شيئا قلته قال نعم قلت فما بالك تخاصم قال يا ابن أخي إني أخاصم في عدل الخلافة وأنت تخاصم في ضحضاح لا يواري أخمصك"},{"id":"tabaqat-shuara:465","bookId":"tabaqat-shuara","type":"section","seq":465,"chapter":"طبقات فحول الشعراء","title":"466- وكانت عاتكة بنت الفرات بن معاوية البكائي وأمها — الملاءة بنت أوفى الحرشي أخت زرارة عند عمر ب","page":"ص0","text":"وكانت عاتكة بنت الفرات بن معاوية البكائي وأمها\nالملاءة بنت أوفى الحرشي أخت زرارة عند عمر بن يزيد فخرجت إلى هشام وأعانتها القيسية على مالك فحمل مالك"},{"id":"tabaqat-shuara:466","bookId":"tabaqat-shuara","type":"section","seq":466,"chapter":"طبقات فحول الشعراء","title":"467- أنا أبو خليفة نا ابن سلام فحدثني محمد بن الحارث قال قال له هشام يا ابن اللخناء قتلت سيدك ق","page":"ص0","text":"أنا أبو خليفة نا ابن سلام فحدثني محمد بن الحارث قال قال له هشام يا ابن اللخناء قتلت سيدك قال أما إن أمي التي تلخن حملت أباك على ركائبه إلى الشام يعنى مروان وكان لجأ أيام الجمل إلى المسامعة جريحا فداووه ثم حملوه\nوأم مالك بحرية بنت مالك بن مسمع فألقي في السجن وقد مرض وبه بطن فمات في مرضه فقال الفرزدق\n(ستعلم عبد القيس إن زال ملكها ... على أي حال يستمر مريرها)"},{"id":"tabaqat-shuara:467","bookId":"tabaqat-shuara","type":"section","seq":467,"chapter":"طبقات فحول الشعراء","title":"468- فأجابه النميري بقصيدة يقول فيها —","page":"ص0","text":"فأجابه النميري بقصيدة يقول فيها\n(وكان كعنز حين قامت لحتفها ... إلى مدية مدفونة تستثيرها)\n(وكان يجير الناس من سيف مالك ... فأصبح يبغي نفسه من يجيرها)"},{"id":"tabaqat-shuara:468","bookId":"tabaqat-shuara","type":"section","seq":468,"chapter":"طبقات فحول الشعراء","title":"469- وقال الفرزدق —","page":"ص0","text":"وقال الفرزدق\n(تصرم مني ود بكر بن وائل ... وما كان مني ودهم يتصرم)\n(قوارص تأتيني ويحتقرونها ... وقد يملأ القطر الإناء فيفعم)"},{"id":"tabaqat-shuara:469","bookId":"tabaqat-shuara","type":"section","seq":469,"chapter":"طبقات فحول الشعراء","title":"470- فأجابه أبو العطاف —","page":"ص0","text":"فأجابه أبو العطاف\n(لعمري لئن كان الفرزدق عاتبا ... وأحدث صرما للفرزدق أظلم)\n(لقد وسطتك الدار بكر بن وائل ... وضمتك للأحشاء إذ أنت محرم)\n(ليالي تمنى أن تكون حمامة ... بمكة يؤويك الستار المحرم)\n(فإن تنأ عنا لا تضرنا وإن تعد ... تجد نا على العهد الذي كنت تعلم)\nيعني حين هرب الفرزدق من زياد"},{"id":"tabaqat-shuara:470","bookId":"tabaqat-shuara","type":"section","seq":470,"chapter":"طبقات فحول الشعراء","title":"471- أنا أبو خليفة نا ابن سلام قال وحدثني أبو العطاف قال لقى الفرزدق شاب من أهل البصرة فقال يا","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال وحدثني أبو العطاف قال لقى الفرزدق شاب من أهل البصرة فقال يا أبا فراس أسالك عن مسألة قال سل قال أيهما أحب إليك تسبق الخير أو يسبقك قال يا ابن أخي لم تأل أن شددت وأحببت أن لا تجعل لي مخرجا أفتجيبني أنت إن أجبتك قال نعم قال فاحلف فغلظ عليه ثم قال نكون معا لا يسبقني ولا أسبقه أسألك الآن قال نعم قال فأيما أحب إليك أن ترجع الآن إلى منزلك فتجد امراتك قابضة بكذا وكذا من رجل أو تجد رجلا قابضا بكذا وكذا منها"},{"id":"tabaqat-shuara:471","bookId":"tabaqat-shuara","type":"section","seq":471,"chapter":"طبقات فحول الشعراء","title":"472- وكان أبو العطاف شاعرا شتاما وهو القائل لعمرو ابن هداب —","page":"ص0","text":"وكان أبو العطاف شاعرا شتاما وهو القائل لعمرو ابن هداب\n(سموت إلى العلى وقصرت عنها ... فما بينى وبينك من عتاب)"},{"id":"tabaqat-shuara:472","bookId":"tabaqat-shuara","type":"section","seq":472,"chapter":"طبقات فحول الشعراء","title":"473- قال ابن سلام وأنشدني يونس للفرزدق —","page":"ص0","text":"قال ابن سلام وأنشدني يونس للفرزدق\n(من يأت عمارا ويشرب شربة ... يدع الصيام ولا تصلى الأربع)"},{"id":"tabaqat-shuara:473","bookId":"tabaqat-shuara","type":"section","seq":473,"chapter":"طبقات فحول الشعراء","title":"474- وكان الفرزدق أكثرهم بيتا مقلدا والمقلد البيت — المستغني بنفسه المشهور الذي يضرب به المثل فمن","page":"ص0","text":"وكان الفرزدق أكثرهم بيتا مقلدا والمقلد البيت\nالمستغني بنفسه المشهور الذي يضرب به المثل فمن ذلك قوله\n(فيا عجبا حتى كليب تسبني ... كأن أباها نهشل أو مجاشع)\n(وكنا إذا الجبار صعر خده ... ضربناه حتى تستقيم الأخادع)"},{"id":"tabaqat-shuara:474","bookId":"tabaqat-shuara","type":"section","seq":474,"chapter":"طبقات فحول الشعراء","title":"475- وقوله —","page":"ج2 ص361","text":"وقوله\n(ليس الكرام بما نحيك أباهم ... حتى ترد إلى عطية تعتل)"},{"id":"tabaqat-shuara:475","bookId":"tabaqat-shuara","type":"section","seq":475,"chapter":"طبقات فحول الشعراء","title":"476- وقوله —","page":"ج2 ص361","text":"وقوله\n(وكنت كذئب السوء لما رأى دما ... بصاحبه يوما أحال على الدم)"},{"id":"tabaqat-shuara:476","bookId":"tabaqat-shuara","type":"section","seq":476,"chapter":"طبقات فحول الشعراء","title":"477- وقوله —","page":"ج2 ص361","text":"وقوله\n(ترجى ربيع أن يجىء صغارها ... بخير وقد أعيى ربيعا كبارها)"},{"id":"tabaqat-shuara:477","bookId":"tabaqat-shuara","type":"section","seq":477,"chapter":"طبقات فحول الشعراء","title":"478- وقوله —","page":"ج2 ص361","text":"وقوله\n(أكلت دوابرها الإكام فمشيها ... مما وجين كمشية الأطفال)"},{"id":"tabaqat-shuara:478","bookId":"tabaqat-shuara","type":"section","seq":478,"chapter":"طبقات فحول الشعراء","title":"479- وقوله —","page":"ج2 ص361","text":"وقوله\n(قوارص تأتينى وتحتقرونها ... وقد يملأ القطر الإناء فيفعم)"},{"id":"tabaqat-shuara:479","bookId":"tabaqat-shuara","type":"section","seq":479,"chapter":"طبقات فحول الشعراء","title":"480- وقوله —","page":"ص0","text":"وقوله\n(أحلامنا تزن الجبال رزانة ... وتخالنا جنا إذا ما نجهل)"},{"id":"tabaqat-shuara:480","bookId":"tabaqat-shuara","type":"section","seq":480,"chapter":"طبقات فحول الشعراء","title":"481- وقوله —","page":"ص0","text":"وقوله\n(فإن تنج منها من ذي عظيمة ... وإلا فإني لا إخالك ناجيا)"},{"id":"tabaqat-shuara:481","bookId":"tabaqat-shuara","type":"section","seq":481,"chapter":"طبقات فحول الشعراء","title":"482- وقوله —","page":"ص0","text":"وقوله\n(وإنك إذ تسعى لتدرك دارما ... لأنت المعنى ياجرير المكلف)"},{"id":"tabaqat-shuara:482","bookId":"tabaqat-shuara","type":"section","seq":482,"chapter":"طبقات فحول الشعراء","title":"483- وقوله —","page":"ص0","text":"وقوله\n(ولو خير السيدى بين غواية ... ورشد أنى السيدى ما كان غاويا)"},{"id":"tabaqat-shuara:483","bookId":"tabaqat-shuara","type":"section","seq":483,"chapter":"طبقات فحول الشعراء","title":"484- وقوله —","page":"ص0","text":"وقوله\n(ترى كل مظلوم إلينا فراره ... ويهرب منا جهده كل ظالم)"},{"id":"tabaqat-shuara:484","bookId":"tabaqat-shuara","type":"section","seq":484,"chapter":"طبقات فحول الشعراء","title":"485- وقوله —","page":"ص0","text":"وقوله\n(ترى الناس ماسرنا يسيرون خلفنا ... وإن نحن أو مأنا إلى الناس وقفوا)"},{"id":"tabaqat-shuara:485","bookId":"tabaqat-shuara","type":"section","seq":485,"chapter":"طبقات فحول الشعراء","title":"486- وقوله —","page":"ص0","text":"وقوله\n(فسيف بني عبس وقد ضربوا به ... نبا بيدي ورقاء عن رأس خالد)\n(كذاك سيوف الهند تنبو ظباتها ... ويقطعن أحيانا مناط القلائد)"},{"id":"tabaqat-shuara:486","bookId":"tabaqat-shuara","type":"section","seq":486,"chapter":"طبقات فحول الشعراء","title":"487- وقوله —","page":"ص0","text":"وقوله\n(أقول له لما أتاني نعيه ... به لا بظبي بالصرائم أعفرا)"},{"id":"tabaqat-shuara:487","bookId":"tabaqat-shuara","type":"section","seq":487,"chapter":"طبقات فحول الشعراء","title":"488- وكان يداخل الكلام وكان ذلك يعجب أصحاب النحو من ذلك قوله يمدح إبراهيم بن هشام بن إسماعيل ال","page":"ص0","text":"وكان يداخل الكلام وكان ذلك يعجب أصحاب النحو من ذلك قوله يمدح إبراهيم بن هشام بن إسماعيل المخزومي خال هشام بن عبد الملك\n(وأصبح ما في الناس إلا مملكا ... أبو أمه حي أبوه يقاربه)"},{"id":"tabaqat-shuara:488","bookId":"tabaqat-shuara","type":"section","seq":488,"chapter":"طبقات فحول الشعراء","title":"489- وقوله —","page":"ص0","text":"وقوله\n(تالله قد سفهت أمية رأيها ... فاستجهلت سفهاؤها حلماؤها)"},{"id":"tabaqat-shuara:489","bookId":"tabaqat-shuara","type":"section","seq":489,"chapter":"طبقات فحول الشعراء","title":"490- وقوله —","page":"ص0","text":"وقوله\n(ألستم عائجين بنا لعنا ... نرى العرصات أو أثر الخيام)\n(فقالوا إن فعلت فأغن عنا ... دموعا غير راقئة السجام)"},{"id":"tabaqat-shuara:490","bookId":"tabaqat-shuara","type":"section","seq":490,"chapter":"طبقات فحول الشعراء","title":"491- وقوله —","page":"ص0","text":"وقوله\n(فهل أنت إن فاتت أتانك راحل ... إلى آل بسطام بن قيس فخاطب)"},{"id":"tabaqat-shuara:491","bookId":"tabaqat-shuara","type":"section","seq":491,"chapter":"طبقات فحول الشعراء","title":"492- وقوله —","page":"ص0","text":"وقوله\n(فنل مثلها من مثلهم ثم دلهم ... على دارمي بين ليلى وغالب)"},{"id":"tabaqat-shuara:492","bookId":"tabaqat-shuara","type":"section","seq":492,"chapter":"طبقات فحول الشعراء","title":"493- وقوله —","page":"ص0","text":"وقوله\n(تعال فإن عاهدتني لا تخونني ... نكن مثل من ياذئب يصطحبان)"},{"id":"tabaqat-shuara:493","bookId":"tabaqat-shuara","type":"section","seq":493,"chapter":"طبقات فحول الشعراء","title":"494- وقوله —","page":"ص0","text":"وقوله\n(إنا وإياك إن بلغن أرحلنا ... كمن بواديه بعد المحل ممطور)"},{"id":"tabaqat-shuara:494","bookId":"tabaqat-shuara","type":"section","seq":494,"chapter":"طبقات فحول الشعراء","title":"495- وقوله —","page":"ص0","text":"وقوله\n(بنى الفاروق أمك وابن أروى ... به عثمان مروان المصابا)"},{"id":"tabaqat-shuara:495","bookId":"tabaqat-shuara","type":"section","seq":495,"chapter":"طبقات فحول الشعراء","title":"496- وقوله —","page":"ص0","text":"وقوله\n(إلى ملك ما أمه من محارب ... أبوه ولا كانت كليب تصاهره)"},{"id":"tabaqat-shuara:496","bookId":"tabaqat-shuara","type":"section","seq":496,"chapter":"طبقات فحول الشعراء","title":"497- وقوله —","page":"ص0","text":"وقوله\n(إليك أمير المؤمنين رمت بنا ... هموم المنى والهوجل المتعسف)\n(وعض زمان يا ابن مروان لم يدع ... من المال إلا مسحتا أو مجلف)"},{"id":"tabaqat-shuara:497","bookId":"tabaqat-shuara","type":"section","seq":497,"chapter":"طبقات فحول الشعراء","title":"498- وقوله —","page":"ص0","text":"وقوله\n(ولقد دنت لك بالتخلب إذ دنت ... منها بلا بخل ولا مبذول)\n(وكأن لون رضاب فيها إذ بدا ... برد بفرع بشامة مصقول)"},{"id":"tabaqat-shuara:498","bookId":"tabaqat-shuara","type":"section","seq":498,"chapter":"طبقات فحول الشعراء","title":"499- وقوله فيها لمالك بن المنذر —","page":"ص0","text":"وقوله فيها لمالك بن المنذر\n(إن ابن جبارى ربيعة مالكا ... لله سيف صنيعة مسلول)\n(مازال من آل المعلى قبله ... سيف لكل خليفة ورسول)"},{"id":"tabaqat-shuara:499","bookId":"tabaqat-shuara","type":"section","seq":499,"chapter":"طبقات فحول الشعراء","title":"500- وقوله —","page":"ص0","text":"وقوله\n(والشيب ينهض في الشباب كأنه ... ليل يصيح بجانبيه نهار)"},{"id":"tabaqat-shuara:500","bookId":"tabaqat-shuara","type":"section","seq":500,"chapter":"طبقات فحول الشعراء","title":"501- أنا أبو خليفة نا ابن سلام قال حدثني أبي قال قال — لهما أعني الفرزدق وجريرا بعض الخلفاء حتى م","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني أبي قال قال\nلهما أعني الفرزدق وجريرا بعض الخلفاء حتى متى لا تنزعان فقال جرير يا أمير المؤمنين إنه والله يظلمني قال صدق أنا أظلمه ووجدت أبي يظلم أباه"},{"id":"tabaqat-shuara:501","bookId":"tabaqat-shuara","type":"section","seq":501,"chapter":"طبقات فحول الشعراء","title":"502- قال وحدثني أبو الغراف قال دخل الفرزدق على بلال فقال له أحججت يا أبا فراس قال نعم قال فما ر","page":"ص0","text":"قال وحدثني أبو الغراف قال دخل الفرزدق على بلال فقال له أحججت يا أبا فراس قال نعم قال فما رأيت قال رأيت شيخا يطوف بالبيت آخذة امرأته بحجزته خلفها ولدان لها وهو يقول\n(أنت وهبت زائدا ومزيدا ... وكهلة أولج فيها الأجردا)\nوهي تقول إذا شئت إذا شئت فقلت له ممن أنت يا شيخ قال أشعري قال كذبت والله ما رأيت هذا ولكن ائتفكتها من حينك"},{"id":"tabaqat-shuara:502","bookId":"tabaqat-shuara","type":"section","seq":502,"chapter":"طبقات فحول الشعراء","title":"503- أنا أبو خليفة نا ابن سلام قال حدثني يونس قال قدم الأحوص الشاعر فنزل على عمرو بن عبيد الأنص","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني يونس قال قدم الأحوص الشاعر فنزل على عمرو بن عبيد الأنصاري فمر به الفرزدق فقال له عهدك بالزنا يا أبا فراس قال مذ ماتت العجوز"},{"id":"tabaqat-shuara:503","bookId":"tabaqat-shuara","type":"section","seq":503,"chapter":"طبقات فحول الشعراء","title":"504- أنا أبو خليفة نا ابن سلام قال حدثني أبو يحيى الضبي قال بينما الفرزدق يسير إذ مر برهط من بن","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني أبو يحيى الضبي قال بينما الفرزدق يسير إذ مر برهط من بني كليب فأخذوه فجاؤوه بأتان فقالوا له إنك تعيرنا بالأتن فوالله لا تريم حتى تنزو عليها قال دعوني لا أبا لكم فأبوا عليه قال فهاتوا الصخرة التى كان يقوم عليها عطية"},{"id":"tabaqat-shuara:504","bookId":"tabaqat-shuara","type":"section","seq":504,"chapter":"طبقات فحول الشعراء","title":"505- وقال الفرزدق حين صار إلى الحجاز ولجأ إلى سعيد —","page":"ص0","text":"وقال الفرزدق حين صار إلى الحجاز ولجأ إلى سعيد\n(نمتك العرانين الطوال ولا أرى ... لفعلك إلا حامدا غير لائم)\n(فإلا تداركنى من الله نعمة ... ومن آل حرب ألق طير الأشائم)"},{"id":"tabaqat-shuara:505","bookId":"tabaqat-shuara","type":"section","seq":505,"chapter":"طبقات فحول الشعراء","title":"506- أخبرني أبو خليفة قال حدثنا محمد بن سلام قال قال الفرزدق وهو بالمدينة —","page":"ص0","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام قال قال الفرزدق وهو بالمدينة\n(هما دلتانى من ثمانين قامة ... كما انقض باز أقتم الريش كاسره)\n(فلما استوت رجلاي في الأرض قالتا ... أحى يرجى أم قتيل نحآذره)\n(فقلت أرفعوا الأسباب لا يفطنوا بنا ... ووليت في أعجاز ليل أبادره)\n(أبادر بوابين قد وكلا بنا ... وأحمر من ساج تبص مسامره)\n(وأصبحت في القوم الجلوس وأصبحت ... مغلقة دوني عليها دسا كره)\nقال فأنكرت ذلك قريش عليه وأزعجه مروان عن المدينة وهو واليها لمعاوية وأجله ثلاثا فقال\n(يامرو إن مطيتي محبوسة ... ترجو الحباء وربها لم ييأس)\n(وأتيتني بصحيفة مختومة ... أخشى علي بها حباء النقرس)\n(ألق الصحيفة يا فرزدق لا تكن ... نكداء مثل صحيفة المتلمس)\nوقال في ذلك\n(وأخرجني وأجلني ثلاثا ... كما وعدت لمهلكها ثمود)\nوذكر ذلك جرير في مناقضته إياه فقال\n(وشبهت نفسك أشقى ثمود ... فقالوا ضللت ولم تهتد)\nيعني تأجيل مروان له ثلاثا وقال فيه أيضا جرير\n(تدليت تزني من ثمانين قامة ... وقصرت عن باع العلى والمكارم)\nوهما قصيدتان"},{"id":"tabaqat-shuara:506","bookId":"tabaqat-shuara","type":"section","seq":506,"chapter":"طبقات فحول الشعراء","title":"507- أنا أبو خليفة نا ابن سلام قال سألت بشارا العقيلي عن الثلاثة فقال لم يكن الأخطل مثلهما ولكن","page":"ج2 ص373","text":"أنا أبو خليفة نا ابن سلام قال سألت بشارا العقيلي عن الثلاثة فقال لم يكن الأخطل مثلهما ولكن ربيعة تعصبت له وأفرطت فيه فقلت فجرير والفرزدق قال كان جرير يحسن ضروبا من الشعر لا يحسنها الفرزدق وفضل جريرا عليه"},{"id":"tabaqat-shuara:507","bookId":"tabaqat-shuara","type":"section","seq":507,"chapter":"طبقات فحول الشعراء","title":"508- وقال العلاء بن حريز العنبري وكان قد أدرك الناس — وسمع قال كان يقال الأخطل إذا لم يجيء سابقا","page":"ج2 ص373","text":"وقال العلاء بن حريز العنبري وكان قد أدرك الناس\nوسمع قال كان يقال الأخطل إذا لم يجيء سابقا فهو سكيت والفرزدق لا يجىء سابقا ولا سكيتا فهو بمنزلة المصلي وجرير يجىء سابقا وسكيتا ومصليا"},{"id":"tabaqat-shuara:508","bookId":"tabaqat-shuara","type":"section","seq":508,"chapter":"طبقات فحول الشعراء","title":"509- قال ابن سلام وتأويل قوله أن للأخطل خمسا أو ستا أو سبعا طوالا روائع غررا جيادا هو بهن سابق","page":"ص0","text":"قال ابن سلام وتأويل قوله أن للأخطل خمسا أو ستا أو سبعا طوالا روائع غررا جيادا هو بهن سابق وسائر شعره دون أشعارها فهو فيما بقي بمنزلة السكيت والسكيت آخر الخيل في الرهان ويقال إن الفرزدق دونه في هذه الروائع وفوقه في بقية شعره فهو كالمصلي أبدا والمصلي الذي يجيء بعد السابق وقبل السكيت وجرير له روائع هو بهن سابق وأوساط هو بهن مصل وسفسافات هو بهن سكيت"},{"id":"tabaqat-shuara:509","bookId":"tabaqat-shuara","type":"section","seq":509,"chapter":"طبقات فحول الشعراء","title":"510- قال ابن سلام وأهل البادية والشعراء بشعر جرير أعجب","page":"ص0","text":"قال ابن سلام وأهل البادية والشعراء بشعر جرير أعجب"},{"id":"tabaqat-shuara:510","bookId":"tabaqat-shuara","type":"section","seq":510,"chapter":"طبقات فحول الشعراء","title":"511- أنا أبو خليفة نا ابن سلام قال وأخبرني أبان بن عثمان الكوفي قال سئل الأخطل عن جرير بالكوفة","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال وأخبرني أبان بن عثمان الكوفي قال سئل الأخطل عن جرير بالكوفة فقال دعوا جريرا أخزاه الله فإنه كان بلاء على من صب عليه وذكر من قوله\n(ما قاد من عرب إلى جوادهم ... إلا تركت جوادهم محسورا)\n(أبقت مراكضتي الرهان مجربا ... عند المواطن يرزق التيسيرا)"},{"id":"tabaqat-shuara:511","bookId":"tabaqat-shuara","type":"section","seq":511,"chapter":"طبقات فحول الشعراء","title":"512- أخبرنا أبو خليفة قال ابن سلام قال مسلمة بن محارب بن سلم بن زياد كان الفرزدق عند أبي في مشر","page":"ص0","text":"أخبرنا أبو خليفة قال ابن سلام قال مسلمة بن محارب بن سلم بن زياد كان الفرزدق عند أبي في مشربة له فدخل رجل فقال وردت اليوم المربد قصيدة لجرير تناشدها الناس فانتقع لون الفرزدق قال ليست فيك يا أبا فراس قال ففيمن قال في ابن لجأ التيمي قال أفحفظت منها شيئا قال نعم علقت منها ببيتين قال ماهما قال\n(لئن عمرت تيم زمانا بغرة ... لقد حديت تيم حداء عصبصبا)\n(فلا يضغمن الليث عكلا بغرة ... وعكل يشمون الفريس المنيبا)\nفقال الفرزدق قاتله الله إذا أخذ هذا المأخذ لا يقام له"},{"id":"tabaqat-shuara:512","bookId":"tabaqat-shuara","type":"section","seq":512,"chapter":"طبقات فحول الشعراء","title":"513- أنا أبو خليفة نا ابن سلام قال اخبرني يونس قال كان الفرزدق يتضور ويجزع إذا انشد لجرير وكان","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال اخبرني يونس قال كان الفرزدق يتضور ويجزع إذا انشد لجرير وكان جرير أصبرهما"},{"id":"tabaqat-shuara:513","bookId":"tabaqat-shuara","type":"section","seq":513,"chapter":"طبقات فحول الشعراء","title":"514- أنا أبو خليفة نا ابن سلام قال واخبراني أبو البيداء الرياحى قال قال الفرزدق أبي وإياه لنغتر","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال واخبراني أبو البيداء الرياحى قال قال الفرزدق أبي وإياه لنغترف من بحر واحد وتضطرب دلاؤه عند طول النهز"},{"id":"tabaqat-shuara:514","bookId":"tabaqat-shuara","type":"section","seq":514,"chapter":"طبقات فحول الشعراء","title":"515- قال ابن سلام وذاكرت مروان بن أبى حفصة جريرا — والفرزدق فقال أحكم فى الثلاثة بشعر فإن الكلام","page":"ص0","text":"قال ابن سلام وذاكرت مروان بن أبى حفصة جريرا\nوالفرزدق فقال أحكم فى الثلاثة بشعر فإن الكلام يرويه كل قوم بأهوائهم فقال\n(ذهب الفرزدق بالفخار وإنما ... حلو الكلام ومره لجرير)\n(ولقد هجا فأمض أخطل تغلب ... وحوى اللهى بمديحه المشهور)\n(كل الثلاثة قد أجاد فمدحه ... وهجاؤه قد سار كل مسير)"},{"id":"tabaqat-shuara:515","bookId":"tabaqat-shuara","type":"section","seq":515,"chapter":"طبقات فحول الشعراء","title":"516- وسألت الأسيدي أخا بني سلامة عنهما فقال — بيوت الشعر أربعة فخر ومديح ونسيب وهجاء وفي كلها غلب","page":"ص0","text":"وسألت الأسيدي أخا بني سلامة عنهما فقال\nبيوت الشعر أربعة فخر ومديح ونسيب وهجاء وفي كلها غلب جرير في الفخر في قوله\n(إذا غضبت عليك بنو تميم ... حسبت الناس كلهم غضابا)\nوفي المدح قوله\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nوفي الهجاء قوله\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\nوفي النسيب قوله\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\nوإلى هذا يذهب أهل البادية\nقال أبو عبد الله محمد بن سلام وبيت النسيب عندي\n(فلما التقى الحيان ألقيت العصا ... ومات الهوى لما أصيبت مقاتله)\nقلت للأسيدي أما والله لقد أوجعكم يعني في الهجاء فقال يا أحمق أو ذاك يمنعه أن يكون شاعرا"},{"id":"tabaqat-shuara:516","bookId":"tabaqat-shuara","type":"section","seq":516,"chapter":"طبقات فحول الشعراء","title":"517- أنا أبو خليفة نا ابن سلام قال قال أبو الغراف كان الخطفي ذا إبل ومال فلما ولد جرير لعطية كا","page":"ج2 ص379","text":"أنا أبو خليفة نا ابن سلام قال قال أبو الغراف كان الخطفي ذا إبل ومال فلما ولد جرير لعطية كان ينحله من إبله وماله فولد للخطفي صبية فرجع فيما كان نحل جريرا فقال\n(ألا حي رهبي ثم حي المطاليا ... لقد كان مأنوسا فأصبح خاليا)\n(عفا الرسم إلا أن تذكر أو ترى ... ثماما حوالى منصب الخيم باليا)\n(إذا ما أراد الحي أن يتحملوا ... وحنت جمال الحي حنت جماليا)\n(وإنيى لمغرور أعلل بالمنى ... غداة أرجي أن مالك ماليا)\n(وإني لعف الفقر مشترك الغنى ... سريع إذا لم أرض داري انتقاليا)\n(وليست لسيفي في العظام بقية ... وللسيف أشوى وقمة من لسانيا)"},{"id":"tabaqat-shuara:517","bookId":"tabaqat-shuara","type":"section","seq":517,"chapter":"طبقات فحول الشعراء","title":"518- ووفد جرير بعد ذلك إلى يزيد بن معاوية وهو خليفة وجرير حدث فأنشده —","page":"ص0","text":"ووفد جرير بعد ذلك إلى يزيد بن معاوية وهو خليفة وجرير حدث فأنشده\n(وإني لعف الفقر مشترك الغنى ... سريع إذا لم أرض داري انتقاليا)\nقال كذبت ذاك جرير قال فأنا جرير قال والله لقد فارق أمير المؤمنين معاوية الدنيا وهو يرى أن هذا البيت لي"},{"id":"tabaqat-shuara:518","bookId":"tabaqat-shuara","type":"section","seq":518,"chapter":"طبقات فحول الشعراء","title":"519- أنا أبو خليفة قال قال ابن سلام أخبرني أبان بن عثمان البجلي قال تنازع رجلان في عسكر المهلب","page":"ص0","text":"أنا أبو خليفة قال قال ابن سلام أخبرني أبان بن عثمان البجلي قال تنازع رجلان في عسكر المهلب في جرير والفرزدق وهو بإزاء الخوارج فصارا إليه وسألاه فقال لا أقول فيهما شئيا وكره أن يعرض نفسه ولكن أدلكما على من يهون عليه سخطهما عبيدة بن هلال اليشكري وهو مولى بني قيس بن ثعلبة وهو يومئذ في عسكر قطري فأتياه فوقفا حيال العسكر فدعواه وخرج يجر رمحه وظن أنه دعي للبراز فقالا له الفرزدق أشعر أم جرير فقال عليكما وعليهما لعنة الله قالا نحب أن تخبرنا ثم نصير إلى ما تريد قال من يقول\n(وطوى القياد مع الطراد بطونها ... طي التجار بحضرموت برودا)\nقالا جرير قال هو أشعرهما"},{"id":"tabaqat-shuara:519","bookId":"tabaqat-shuara","type":"section","seq":519,"chapter":"طبقات فحول الشعراء","title":"520- أنا أبو خليفة نا محمد بن سلام قال أخبرني أبو رجاء الكلبي قال كان لأمامة امرأة جرير ابن أخ","page":"ص0","text":"أنا أبو خليفة نا محمد بن سلام قال أخبرني أبو رجاء الكلبي قال كان لأمامة امرأة جرير ابن أخ ذو إبل يقال له عضيدة لقصر في يده فلم تزل به امرأته حتى زوجه ابنته فعتب عليه فقال\n(وغرتنا أمامة فافتحلنا ... عضيدة إذ تنخلت الفحول)\n(إذا ما كان فحلك فحل سوء ... خلجت النسل أو لؤم الفصيل)"},{"id":"tabaqat-shuara:520","bookId":"tabaqat-shuara","type":"section","seq":520,"chapter":"طبقات فحول الشعراء","title":"521- أنا أبو خليفة أنا ابن سلام أخبرنا أبو الغراف قال — دخل جرير على الوليد بن عبد الملك وهو خليف","page":"ص0","text":"أنا أبو خليفة أنا ابن سلام أخبرنا أبو الغراف قال\nدخل جرير على الوليد بن عبد الملك وهو خليفة وعنده عدي ابن الرقاع العاملي فقال الوليد لجرير أتعرف هذا قال لا يا أمير المؤمنين قال هذا رجل من عاملة\nقال الذين يقول الله جل {خاشعة عاملة ناصبة تصلى نارا} حامية ثم قال\n(يقصر باع العاملي عن العلي ... ولكن أير العاملى طويل)\nفقال العاملي\n(أأمك كانت أخبرتك بطوله ... أم انت امرؤ لم تدر كيف تقول)\nفقال لا بل لم أدر كيف أقول فوثب العاملي إلى رجل الوليد فقبلها وقال أجرني منه فقال الوليد لجرير لئن سميته لأسرجنك ولألجمنك ولير كبنك فتعيرك بذلك الشعراء فكنى جرير عن اسمه واسمه عدي فقال\n(إني إذا الشاعر المغرور حربنى ... جار لقبر على مران مرموس)\n(قد كان أشوس أباء فأورثنا ... شغبا على الناس في أبنائنا الشوس)\n(أقصر فإن نزارا لا يفآخرهم ... فرع لئيم وأصل غير مغروس)\n(وابنا نزار أحلاني بمنزلة ... فى رأس أرعن عادى القداميس)\n(وابن اللبون إذا ما لز في قرن ... لم يستطع صولة البزل القناعيس)"},{"id":"tabaqat-shuara:521","bookId":"tabaqat-shuara","type":"section","seq":521,"chapter":"طبقات فحول الشعراء","title":"522- أنا أبو خليفة نا ابن سلام قال حدثني أبو يحيى الصنبي قال ورد البعيث المجاسعي على بني سليط ب","page":"ج2 ص385","text":"أنا أبو خليفة نا ابن سلام قال حدثني أبو يحيى الصنبي قال ورد البعيث المجاسعي على بني سليط بن يربوع وكان ولدهم وولدوه فشكوا إليه قهر جرير صاحبهم يعني غسان السليطي فقال البعيث\n(إذا يسرت معزى عطية وارتعت ... تلاعا من المروت أحوى جميعها)\n(تعرضت لي حتى صككتك صكة ... على الوجه يكبو لليدين أميمها)\n(أليست كليب ألأم الناس كلهم ... وأنت إذا عدت كليب لئيمها)"},{"id":"tabaqat-shuara:522","bookId":"tabaqat-shuara","type":"section","seq":522,"chapter":"طبقات فحول الشعراء","title":"523- وكانت ام البعيت أمة حمراء سجستانية تسمي فرتنا فكان يقال له ابن حمراء العجان فهجاه جرير فثا","page":"ج2 ص385","text":"وكانت ام البعيت أمة حمراء سجستانية تسمي فرتنا فكان يقال له ابن حمراء العجان فهجاه جرير فثاوره فضج إلى الفرزدق والفرزدق يومئذ بالبصرة وقد قيد نفسه وآلى لا يفك\nقيده حتى يقرأ القرآن فقال البعيث\n(لعمرى لئن ألهى الفرزدق قيده ... ودرج نوار ذو الدهان وذو الغسل)\n(ليبتعثن مني عداة مجاشع ... بديهة لاواني الجراء ولا وغل)\nفقال جرير\n(جزعت إلى درجي نوار وغسلها ... فأصبحت عبدا ماتمر وما تحلي)\nوعده الناس مغلوبا حين استغاث"},{"id":"tabaqat-shuara:523","bookId":"tabaqat-shuara","type":"section","seq":523,"chapter":"طبقات فحول الشعراء","title":"524- قال وقال الفرزدق إني إن وثبت على جرير الآن حققت على البعيث الغلبة ولكني كأني وثبت عليهما ف","page":"ص0","text":"قال وقال الفرزدق إني إن وثبت على جرير الآن حققت على البعيث الغلبة ولكني كأني وثبت عليهما فأدع البعيث وآخذ\nجريرا فقالوا الطبيب أطب فقال\n(لود جرير اللؤم لو كان عانيا ... ولم يدن من زأر الأسود الضراغم)\n(وليس ابن حمراء العجان بمفلتي ... ولم يزدجر طير النحوس الأشائم)\n(وإنكما قد هجتماني عليكما ... فلا تجزعا واستسمعا للمراجم)"},{"id":"tabaqat-shuara:524","bookId":"tabaqat-shuara","type":"section","seq":524,"chapter":"طبقات فحول الشعراء","title":"525- وقال —","page":"ص0","text":"وقال\n(دعاني ابن حمراء العجان ولم يجد ... له إذ دعا مستأخرا عن دعائيا)\n(فنفست عن أنفيه حتى تنفسا ... وقلت له لا تخش شيئا ورائيا)"},{"id":"tabaqat-shuara:525","bookId":"tabaqat-shuara","type":"section","seq":525,"chapter":"طبقات فحول الشعراء","title":"526- فلما استطار كل واحد منهما في صاحبه قال البعيث —","page":"ص0","text":"فلما استطار كل واحد منهما في صاحبه قال البعيث\n(أشاركتني في ثعلب قد أكلته ... فلم يبق إلا رأسه وأكارعه)\n(فدونك خصييه وما ضمت استه ... فإنك رمام خبيث مراتعه)\nقال وسقط البعيث بينهما"},{"id":"tabaqat-shuara:526","bookId":"tabaqat-shuara","type":"section","seq":526,"chapter":"طبقات فحول الشعراء","title":"527- ولج الهجاء نحوا من أربعين سنة لم يغلب واحد منهما على صاحبه — ولم يتهاج شاعران في الجاهلية ول","page":"ص0","text":"ولج الهجاء نحوا من أربعين سنة لم يغلب واحد منهما على صاحبه\nولم يتهاج شاعران في الجاهلية ولا الإسلام بمثل ما تهاجيا به وأشعارهما أكثر من أن تأتي عليها ولكنا نكتب منها النادر"},{"id":"tabaqat-shuara:527","bookId":"tabaqat-shuara","type":"section","seq":527,"chapter":"طبقات فحول الشعراء","title":"528- وقال الفزردق لجرير —","page":"ص0","text":"وقال الفزردق لجرير\n(غلبتك بالمفقىء والمعنى ... وبيت المحتبي والخافقات)\nالمفقىء قوله\n(ولست ولو فقأت عينك واجدا ... أبا لك إن عد المساعي كدارم)\n(هو الشيخ وابن الشيخ لا شيخ مثله ... أبو كل ذي بيت رفيع الدعائم)\nوالمعني قوله\n(وإنك إذ تسعى لتدرك دارما ... لأنت المعنى يا جرير المكلف)\n(والمحتبي قوله\n(بيتا زرارة محتب بفنائه ... ومجاشع وأبو الفوارس نهشل)\nوالخافقات قوله\n(وأين تقضي المالكان أمورها ... بخير وأين الخافقات اللوامع)"},{"id":"tabaqat-shuara:528","bookId":"tabaqat-shuara","type":"section","seq":528,"chapter":"طبقات فحول الشعراء","title":"529- فقال جرير —","page":"ص0","text":"فقال جرير\n(أقين بن قين ما يسر نساءنا ... بذي نجب أنا ادعينا لدارم)\n(هو القين وابن القين لدقين مثله ... لفطح المساحي أولجدل الأداهم)\nالجدل الفتل والأداهم الحبال نا أبو خليفة كل من كان في عمله حديد فهو قين بذى نجب يوم التقت بنو حنظلة وبنو عامر إلا بني مالك بن حنظلة"},{"id":"tabaqat-shuara:529","bookId":"tabaqat-shuara","type":"section","seq":529,"chapter":"طبقات فحول الشعراء","title":"530- قال ابن سلام واشترى جرير جارية من رجل من أهل اليمامة يقال له زيد يعرف بابن النجار ففركته و","page":"ص0","text":"قال ابن سلام واشترى جرير جارية من رجل من أهل اليمامة يقال له زيد يعرف بابن النجار ففركته وكرهت خشونة عيشه فقال\n(تكلفني معيشة آل زيد ... ومن لي بالمرقق والصناب)\n(وقالت لا تضم كضم زيد ... وماضمى وليس معي شبابي)\nفقال الفرزدق\n(لئن فركتك علجة آل زيد ... وأعوزك المرقق والصناب)\n(لقدما كان عيش أبيك جدبا ... يعيش بما تعيش به الكلاب)"},{"id":"tabaqat-shuara:530","bookId":"tabaqat-shuara","type":"section","seq":530,"chapter":"طبقات فحول الشعراء","title":"531- أنا أبو خليفة نا ابن سلام حدثني حاجب بن زيد وأبو الغراف قالا تزوج الفرزدق حدراء بنت زيق بن","page":"ص0","text":"أنا أبو خليفة نا ابن سلام حدثني حاجب بن زيد وأبو الغراف قالا تزوج الفرزدق حدراء بنت زيق بن بسطام بن قيس بن مسعود بن قيس بن خالد بن ذى الجدين وهو عبد الله بن عمرو بن الحارث بن همام بن مرة بن ذهل بن شيبان على حكم أبيها\nفاحتكم مئة من الإبل فدخل على الحجاج فعذله وقال تزوجتها على حكمها وحكم أبيها مئة بعير وهي نصرانية وجئتنا متعرضا أن نسوقها عنك اخرج مالك عندنا شيء فقال عنبسة بن سعيد وأراد نفعه أيها الأمير إنما هي من حواشي إبل الصدقة فأمر له بها الحجاج فوثب عليه جرير فقال\n(يا زيققد كنت من شيبان في حسب ... يا زيق ويحكمن أنكحت يا زيق)\n(أنكحت ويلك قينا باسته حمم ... يا زيق ويحك أن بارت بك السوق)\n(غاب المثنى فلم يشهد نجيكم ... والحوفزان ولم يشهدك مفروق)\n(يارب قائلة بعد البناء بها ... لا الصهر راض ولا ابن القين معشوق)\n(أين الألى استنزلوا النعمان ضاحية ... أم أين أبناء شيبان الغرانيق)"},{"id":"tabaqat-shuara:531","bookId":"tabaqat-shuara","type":"section","seq":531,"chapter":"طبقات فحول الشعراء","title":"532- قال فلم يجبه الفرزدق فقال جرير أيضا —","page":"ج2 ص393","text":"قال فلم يجبه الفرزدق فقال جرير أيضا\n(فلا أنا معطي الحكم عن شف منصب ... ولا عن بنات الحنظليين راغب)\n(وهن كماء المزن يشفى به الصدى ... وكانت ملاحا غيرهن المشارب)\n(فلو كنت حرا كان عشر سياقكم ... إلى آل زيق والوصيف المقارب)"},{"id":"tabaqat-shuara:532","bookId":"tabaqat-shuara","type":"section","seq":532,"chapter":"طبقات فحول الشعراء","title":"533- فقال الفرزدق —","page":"ج2 ص393","text":"فقال الفرزدق\n(فنل مثلها من مثلهم ثم لمهم ... على دارمى بين ليلى وغالب)\n(هم زوجوا قبلى لقيطا وأنكحوا ... ضرارا وهم أكفاؤنا في المناسب)\n(ولو قبلوا منا عطية سقته ... إلى آل زيق من وصيف مقارب)\n(ولو تنكح الشمس النجوم بناتها ... إذن لنكحناهن قبل الكواكب)"},{"id":"tabaqat-shuara:533","bookId":"tabaqat-shuara","type":"section","seq":533,"chapter":"طبقات فحول الشعراء","title":"534- أنا أبو خليفة نا ابن سلام قال حدثني الزراري — عن أبيه قال ما كانت امرأة من بني حنظلة إلا ترف","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني الزراري\nعن أبيه قال ما كانت امرأة من بني حنظلة إلا ترفع لجرير اللوية في عكمها تطرفه لقوله\n(وهن كماء المزن يشفى به الصدى ... وكانت ملاحا غيرهن المشارب)\nفقلت للزراري ما اللوية قال الشريحة من اللحم وهي الفدرة من التمر والكبة من الشحم أو الجلة من الأقط فإذا كانت الصفرية وذهبت الألبان وضاقت المعيشة كانت طرفة عندهم"},{"id":"tabaqat-shuara:534","bookId":"tabaqat-shuara","type":"section","seq":534,"chapter":"طبقات فحول الشعراء","title":"535- وقال جرير —","page":"ص0","text":"وقال جرير\n(أثائرة حدراء من جر بالنقا ... وهل لأبي حدراء في الوتر طالب)\n(أتثأر بسطاما إذا ابتلت استها ... وقد بولت في مسمعيه الثعالب)\nقال ابن سلام والنقا الذي عناه جرير هو الموضع الذي قتلت فيه بنو ضبة بسطاما وهو بسطام بن قيس قال فكرهت بنو شيبان أن يهتك جرير أعراضهم فلما أراد الفرزدق نقل حدراء اعتلوا عليه وقالوا له إنها ماتت"},{"id":"tabaqat-shuara:535","bookId":"tabaqat-shuara","type":"section","seq":535,"chapter":"طبقات فحول الشعراء","title":"536- قال الجرير —","page":"ص0","text":"قال الجرير\n(فأقسمت ماماتت ولكنما التوى ... بحدراء قوم لم يروك لها أهلا)\n(رأوا أن صهر القين عار عليهم ... وأن لبسطام على غالب فضلا)"},{"id":"tabaqat-shuara:536","bookId":"tabaqat-shuara","type":"section","seq":536,"chapter":"طبقات فحول الشعراء","title":"537- انا أبو خليفة أنا ابن سلام قال حدثني حاجب بن يزيد بن شيبان بن علقمة بن زرارة قال جرير بالك","page":"ص0","text":"انا أبو خليفة أنا ابن سلام قال حدثني حاجب بن يزيد بن شيبان بن علقمة بن زرارة قال جرير بالكوفة\n(لقدء قادني من حب ماوية الهوى ... وما كنت ألقى للجنيبة أقودا)\n(أحب ثرى نجد وبالغور حاجة ... فغار الهوى يا عبد قيس وأنجدا)\n(أقول له يا عبد قيس صبابة ... بأي ترى مستوقد النار أوقدا)\n(فقال أراها أرثت بوقودها ... بحيث استفاض الجزع شيحا وغرقدا)\nفأعجبت الناس وتناشدوها"},{"id":"tabaqat-shuara:537","bookId":"tabaqat-shuara","type":"section","seq":537,"chapter":"طبقات فحول الشعراء","title":"538- فحدثني جابر بن جندل قال فقال لنا جرير أعجبتكم هذه الأبيات قالوا نعم قال كأنكم بالقين قد قا","page":"ص0","text":"فحدثني جابر بن جندل قال فقال لنا جرير أعجبتكم هذه الأبيات قالوا نعم قال كأنكم بالقين قد قال\n(أعد نظرا يا عبد قيس فإنما ... أضاءت لك النار الحمار المقيدا)\nفلم يلبثوا أن جاءهم في قول الفرزدق هذا البيت وبعده\n(حمار بمروت السحامة قاربت ... وظيفيه حول البيت حتى ترددا)\n(كليبية لم يجعل الله وجهها ... كريما ولم يسنح بها الطير أسعدا)\nفتناشدها الناس فقال الفرزدق كأنكم بابن المراغة قد قال\n(وما عبت من نار أضاء وقودها ... فراسا وبسطام بن قيس مقيدا)\nقال فإذا هي قد جاءت لجرير وفيها هذا البيت ومعه\n(فأوقدت بالسيدان نارا ذليلة ... وأشهدت من سوآت جمعثن مشهدا)"},{"id":"tabaqat-shuara:538","bookId":"tabaqat-shuara","type":"section","seq":538,"chapter":"طبقات فحول الشعراء","title":"539- قال واجتمعنا عند سليمان بن عبد الملك وهو خليفة وأتى بأسرى من الروم قال ابن سلام فأخبرني اب","page":"ج2 ص399","text":"قال واجتمعنا عند سليمان بن عبد الملك وهو خليفة وأتى بأسرى من الروم قال ابن سلام فأخبرني ابو يحيى الضبي قال وفي حرسه رجل من بني عبس قد علم ان سيأمر أصحابه بضرب أعناقهم\nفأتى الفرزدق وذلك لسوء أثره في قيس فقال إن أمير المؤمنين حرى أن يأمر بضرب عنق بعض هؤلاء الأسرى وهذا سيفي يكفيك أن أن تومىء به فيأتي على ضريبته وأتاه بسيف كليل كهام فقال له الفرزدق ممن أنت قال من بني ضبة أخوالك وأمره سليمان بضرب عنق بعضهم فتناول السيف من العبسى ثم هزه فضرب به\nعنقه فما حص شعرة ولم يؤثر به أثرا فضحك سليمان والناس\nفقال هذه ضربة سيقول فيها هذا يعني جريرا وتقول فيها العرب وقال\n(فإن يك سيف خان أو قدر أبى ... لتأخير نفس حتفها غير شاهد)\n(فسيف بني عبس وقد ضربوا به ... نبا بيدى ورقاء عن رأس خالد)\n(كذاك سيوف الهند تنبو ظباتها ... ويقطعن أحيانا مناط القلائد)"},{"id":"tabaqat-shuara:539","bookId":"tabaqat-shuara","type":"section","seq":539,"chapter":"طبقات فحول الشعراء","title":"540- وقال جرير —","page":"ص0","text":"وقال جرير\n(بسيف أبي رغوان سيف مجاشع ... ضربت ولم تضرب بسيف ابن ظالم)\n(ضربت به عند الإمام فأرعشت ... يداك وقالوا محدث غير صارم)"},{"id":"tabaqat-shuara:540","bookId":"tabaqat-shuara","type":"section","seq":540,"chapter":"طبقات فحول الشعراء","title":"541- وقال —","page":"ص0","text":"وقال\n(أخزيت قومك في مقام قمته ... ووجدت سيف مجاشع لا يقطع)"},{"id":"tabaqat-shuara:541","bookId":"tabaqat-shuara","type":"section","seq":541,"chapter":"طبقات فحول الشعراء","title":"542- وقال الفرزدق —","page":"ص0","text":"وقال الفرزدق\n(فهل ضربة الرومي جاعلة لكم ... أبا عن كليب أوأبا مثل دارم)\n(ولا نقتل الأسرى ولكن نفكهم ... إذا أثقل الأعناق حمل المغارم)"},{"id":"tabaqat-shuara:542","bookId":"tabaqat-shuara","type":"section","seq":542,"chapter":"طبقات فحول الشعراء","title":"543- وقال اللعين —","page":"ص0","text":"وقال اللعين\n(سأحكم بين كلب بني كليب ... وبين القين قين بني عقال)\n(فإن الكلب مطعمه خبيث ... وإن القين يعمل في سفال)\n(وقد حسر البعيث وأقعدته ... لئيمات المناخر والسبال)\n(ويترك جده الخطفى جرير ... ويندب حاجبا وبني عقال)\nقال ابن سلام وسمعت يونس يقول فلم يلتفتا لفته وأراد أن يذكراه فيرفعه ذلك فقال\n(فما بقيا على تركتماني ... ولكن خفتما صرد النبال)"},{"id":"tabaqat-shuara:543","bookId":"tabaqat-shuara","type":"section","seq":543,"chapter":"طبقات فحول الشعراء","title":"544- وقال الصلتان العبدي —","page":"ص0","text":"وقال الصلتان العبدي\n(ألا إنما تحظى كليب بشعرها ... وبالمجد تحظى نهشل والأقارع)\n(أنا الصلتا بى الذي قد عرفتم ... متى مايحكم فهو بالحكم صادع)\n(أتتني تميم حين هابت قضاتها ... فهل أنت للفصل المبين سامع)\n(قضاء امرىء لا يرهب الشتم منكم ... وليس له في الحكم منكم منافع)\n(فما رجع الأعشى قضية عامر ... وما لتميم في قضائي راجع)\n(فإن يك بحر الحنظليين واحدا ... فما تستوى حيتانه والضفادع)\n(فيا شاعرا لاشاعر اليوم مثله ... جرير ولكن فى كليب تواضع)\n(ويرفع من شعر الفرزدق أنه ... ينوء بحى للخسيسة رافع)\n(يناشدني النصر الفرزدق بعدما ... ألحت عليه من جرير صواقع)\nفلم يرض واحد منهما قوله فقال الفرزدق أما الشرف فقد عرفه وأما الشعر فما للبحراني والشعر"},{"id":"tabaqat-shuara:544","bookId":"tabaqat-shuara","type":"section","seq":544,"chapter":"طبقات فحول الشعراء","title":"545- وقال جرير","page":"ج2 ص404","text":"وقال جرير (أقول ولم أملك سوابق عبرة ... متى كان حكم الله في كرب النخل)"},{"id":"tabaqat-shuara:545","bookId":"tabaqat-shuara","type":"section","seq":545,"chapter":"طبقات فحول الشعراء","title":"546- فقال الصلتان —","page":"ج2 ص404","text":"فقال الصلتان\n(أعيرتنا بالنخل أن كان مالنا ... لود أبوك الكلب لو كان ذا نخل)"},{"id":"tabaqat-shuara:546","bookId":"tabaqat-shuara","type":"section","seq":546,"chapter":"طبقات فحول الشعراء","title":"547- فاعترضه خليد عينين من أهل هجر فقال —","page":"ج2 ص404","text":"فاعترضه خليد عينين من أهل هجر فقال\n(وأى نبى كان في غير قرية ... وما الحكم يا ابن اللؤم إلا مع الرسل)"},{"id":"tabaqat-shuara:547","bookId":"tabaqat-shuara","type":"section","seq":547,"chapter":"طبقات فحول الشعراء","title":"548- وقال جرير —","page":"ج2 ص404","text":"وقال جرير\n(فخل الفخر يا ابن أبي خليد ... وأد خراج رأسك كل عام)\n(لقد علقت يمينك رأس ثور ... وما علقت يمينك باللجام)"},{"id":"tabaqat-shuara:548","bookId":"tabaqat-shuara","type":"section","seq":548,"chapter":"طبقات فحول الشعراء","title":"549- أنا أبو خليفة نا ابن سلام قال حدثني أبو الغراف قال قال الحجاج لهما وهو في قصره بحزيز البصر","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني أبو الغراف قال قال الحجاج لهما وهو في قصره بحزيز البصرة ائتيا في لباس آبائكما في الجاهلية فجاء الفرزدق وقد لبس الديباج والخز وقعد في قبة وشاور جرير دهاة بني يربوع فقالوا ما لباس آبائنا إلا الحديد فلبس جرير درعا وتقلد سيفا وأخذ رمحا وركب فرسا لعباد بن الحصين يقال له المنحاز وأقبل في أربعين فارسا من بني يربوع وجاء الفرزدق في هيئته فقال جرير\n(لبست سلاحي والفرزدق لعبة ... عليه وشاحا كرج وجلاجله)\n(أعدوا مع الخز الملاب فإنما ... جرير لكم بعل وأنتم حلائله)\nثم رجعا فوقف جرير في مقبرة بني حصن ووقف الفرزدق في المربد"},{"id":"tabaqat-shuara:549","bookId":"tabaqat-shuara","type":"section","seq":549,"chapter":"طبقات فحول الشعراء","title":"550- فأخبرني أبي عن محمد بن زياد قال كنت أختلف بينهما يومئذ فكأن جريرا كان يومئذ أظفرهما","page":"ص0","text":"فأخبرني أبي عن محمد بن زياد قال كنت أختلف بينهما يومئذ فكأن جريرا كان يومئذ أظفرهما"},{"id":"tabaqat-shuara:550","bookId":"tabaqat-shuara","type":"section","seq":550,"chapter":"طبقات فحول الشعراء","title":"551- أنا أبو خليفة نا ابن سلام قال حدثني شعيب بن صخر عن هارون بن إبراهيم قال رأيتهما في مسجد دم","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني شعيب بن صخر عن هارون بن إبراهيم قال رأيتهما في مسجد دمشق والفرزدق في عصابة من خندف والناس عنق على جرير قيس وموالى بني أمية وهم يسلمون عليه ويسألونه يا أبا حزرة كيف كنت في مسيرك وذلك لمديحه قيسا وقوله في العجم\n(فيجمعنا والغر أولاد سارة ... أب لا نبالي بعده من تغدرا)"},{"id":"tabaqat-shuara:551","bookId":"tabaqat-shuara","type":"section","seq":551,"chapter":"طبقات فحول الشعراء","title":"552- قال أبو خليفة سمعت عمارة بن عقيل بن بلال يقول وافته في يومه مئة حلة من بني الأحرار","page":"ص0","text":"قال أبو خليفة سمعت عمارة بن عقيل بن بلال يقول وافته في يومه مئة حلة من بني الأحرار"},{"id":"tabaqat-shuara:552","bookId":"tabaqat-shuara","type":"section","seq":552,"chapter":"طبقات فحول الشعراء","title":"553- أنا أبو خليفة نا ابن سلام وحدثني أبو اليقظان نا جويرية بن أسماء قال قلت لنصيب مولى عبد الم","page":"ص0","text":"أنا أبو خليفة نا ابن سلام وحدثني أبو اليقظان نا جويرية بن أسماء قال قلت لنصيب مولى عبد الملك يا أبا محجن من أشعر الناس فقال أخو بني تميم\nقلت ثم من قال أنا قال قلت ثم من قال ابن يسار النساء فلقيت إسماعيل بن يسار النسائى فقلت يا أبا فائد من أشعر الناس قال اخو بني تميم قلت ثم من قال أنا قلت ثم من قال نصيب قلت إنكما لتتقارضان الثناء قال وما ذاك قال قلت سألته فقال فيك مثل\nما قلت فيه قال إنه والله شاعر كريم ولا أظنه إلا بدأ بابن يسار قبل نصيب"},{"id":"tabaqat-shuara:553","bookId":"tabaqat-shuara","type":"section","seq":553,"chapter":"طبقات فحول الشعراء","title":"554- قال ابن سلام ومما قال جرير من الأبيات المقلدة قوله —","page":"ص0","text":"قال ابن سلام ومما قال جرير من الأبيات المقلدة قوله\n(وليست لسيفي في العظام بقية ... وللسيف أشوى وقعة من لسانيا)"},{"id":"tabaqat-shuara:554","bookId":"tabaqat-shuara","type":"section","seq":554,"chapter":"طبقات فحول الشعراء","title":"555- وقوله —","page":"ص0","text":"وقوله\n(لا يلبث القرناء أن يتفرقوا ... ليل يكر عليهم ونهار)"},{"id":"tabaqat-shuara:555","bookId":"tabaqat-shuara","type":"section","seq":555,"chapter":"طبقات فحول الشعراء","title":"556- وقوله —","page":"ص0","text":"وقوله\n(زعم الفرزدق أن سيقتل مربعا ... أبشر بطول سلامة يا مربع)"},{"id":"tabaqat-shuara:556","bookId":"tabaqat-shuara","type":"section","seq":556,"chapter":"طبقات فحول الشعراء","title":"557- وقوله —","page":"ص0","text":"وقوله\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)"},{"id":"tabaqat-shuara:557","bookId":"tabaqat-shuara","type":"section","seq":557,"chapter":"طبقات فحول الشعراء","title":"558- وقوله —","page":"ص0","text":"وقوله\n(لا يأمنن قوى نقض مرته ... إني أرى الدهر ذا نقض وإمرار)"},{"id":"tabaqat-shuara:558","bookId":"tabaqat-shuara","type":"section","seq":558,"chapter":"طبقات فحول الشعراء","title":"559- وقوله —","page":"ص0","text":"وقوله\n(أنا البازي المطل على نمير ... أتيح من السماء لها انصبابا)"},{"id":"tabaqat-shuara:559","bookId":"tabaqat-shuara","type":"section","seq":559,"chapter":"طبقات فحول الشعراء","title":"560- وقوله —","page":"ص0","text":"وقوله\n(وإني لعف الفقر مشترك الغنى ... سريع إذا لم أرض داري انتقاليا)"},{"id":"tabaqat-shuara:560","bookId":"tabaqat-shuara","type":"section","seq":560,"chapter":"طبقات فحول الشعراء","title":"561- وقوله —","page":"ص0","text":"وقوله\n(يحالفهم فقر قديم وذلة ... وبئس الخليطان المذلة والفقر)\n(فصبرا على ذل ربيع بن مالك ... وكل ذليل خير عادته الصبر)"},{"id":"tabaqat-shuara:561","bookId":"tabaqat-shuara","type":"section","seq":561,"chapter":"طبقات فحول الشعراء","title":"562- وقوله —","page":"ص0","text":"وقوله\n(دعون الهوى ثم ارتمين قلوبنا ... بأسهم أعداء وهن صديق)\n(أوانس أما من أردن عناءه ... فعان ومن أطلقن فهو طليق)"},{"id":"tabaqat-shuara:562","bookId":"tabaqat-shuara","type":"section","seq":562,"chapter":"طبقات فحول الشعراء","title":"563- وقوله —","page":"ص0","text":"وقوله\n(إن الذين غدوا بلبك غادروا ... وشلا بعينك ما يزال معينا)\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)"},{"id":"tabaqat-shuara:563","bookId":"tabaqat-shuara","type":"section","seq":563,"chapter":"طبقات فحول الشعراء","title":"564- وقوله —","page":"ص0","text":"وقوله\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\n(إذا غضبت عليك بنو تميم ... حسبت الناس كلهم غضابا)"},{"id":"tabaqat-shuara:564","bookId":"tabaqat-shuara","type":"section","seq":564,"chapter":"طبقات فحول الشعراء","title":"565- وقوله —","page":"ص0","text":"وقوله\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)"},{"id":"tabaqat-shuara:565","bookId":"tabaqat-shuara","type":"section","seq":565,"chapter":"طبقات فحول الشعراء","title":"566- وقوله —","page":"ص0","text":"وقوله\n(يا أهل جزرة إني قد نصبت لكم ... بالمنجنيق ولما يرسل الحجر)"},{"id":"tabaqat-shuara:566","bookId":"tabaqat-shuara","type":"section","seq":566,"chapter":"طبقات فحول الشعراء","title":"567- وقوله —","page":"ص0","text":"وقوله\n(ولما التقى الحيان ألقيت العصى ... ومات الهوى لما أصيبت مقاتله)"},{"id":"tabaqat-shuara:567","bookId":"tabaqat-shuara","type":"section","seq":567,"chapter":"طبقات فحول الشعراء","title":"568- وقوله —","page":"ص0","text":"وقوله\n(تريدين أن أرضى وأنت بخيلة ... ومن ذا الذي يرضي الأخلاء بالبخل)\n(فإنك لا يرضى إذا كان عاتبا ... خليلك إلا بالمودة والبذل)"},{"id":"tabaqat-shuara:568","bookId":"tabaqat-shuara","type":"section","seq":568,"chapter":"طبقات فحول الشعراء","title":"569- وقوله —","page":"ص0","text":"وقوله\n(ياتيم إن بيوتكم تيمية ... قعس العماد قصيرة الأطناب)\n(قوم إذا حضر الملوك وفودهم ... نتفت شواربهم على الأبواب)"},{"id":"tabaqat-shuara:569","bookId":"tabaqat-shuara","type":"section","seq":569,"chapter":"طبقات فحول الشعراء","title":"570- وقوله —","page":"ص0","text":"وقوله\n(وكنت إذا نزلت بدار قوم ... ظعنت بخزية وتركت عارا)"},{"id":"tabaqat-shuara:570","bookId":"tabaqat-shuara","type":"section","seq":570,"chapter":"طبقات فحول الشعراء","title":"571- وقوله —","page":"ص0","text":"وقوله\n(أتنسى إذ تودعنا سليمى ... بعود بشامة سقى البشام)\n(بنفسي من تجنبه عزيز ... علي ومن زيارته لمام)\n(ومن أمسي وأصبح لا أراه ... ويطرقني إذا هجع النيام)"},{"id":"tabaqat-shuara:571","bookId":"tabaqat-shuara","type":"section","seq":571,"chapter":"طبقات فحول الشعراء","title":"572- وقوله —","page":"ص0","text":"وقوله\n(وابن اللبون إذا ما لز في قرن ... لم يستطع صولة البزل القناعيس)"},{"id":"tabaqat-shuara:572","bookId":"tabaqat-shuara","type":"section","seq":572,"chapter":"طبقات فحول الشعراء","title":"573- وقوله —","page":"ص0","text":"وقوله\n(لو كنت حرا يا ابن قين مجاشع ... شيعت ضيفك فرسخين وميلا)"},{"id":"tabaqat-shuara:573","bookId":"tabaqat-shuara","type":"section","seq":573,"chapter":"طبقات فحول الشعراء","title":"574- وقوله —","page":"ص0","text":"وقوله\n(لا يستطيع امتناعا فقع قرقرة ... بين الطريقين بالبيد الأ ما ليس)"},{"id":"tabaqat-shuara:574","bookId":"tabaqat-shuara","type":"section","seq":574,"chapter":"طبقات فحول الشعراء","title":"575- وقوله —","page":"ص0","text":"وقوله\n(لا يستطيع أخو الصبابة أن يرى ... حجرا أصم ولا يكون حديدا)"},{"id":"tabaqat-shuara:575","bookId":"tabaqat-shuara","type":"section","seq":575,"chapter":"طبقات فحول الشعراء","title":"576- وقوله —","page":"ص0","text":"وقوله\n(لو أن عصم ممتايتين ويذبلا ... سمعا حديثك أنزل الأوعالا)"},{"id":"tabaqat-shuara:576","bookId":"tabaqat-shuara","type":"section","seq":576,"chapter":"طبقات فحول الشعراء","title":"577- أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثنا أبو اليقظان عن جويرية بن أسماء قال قدم ا","page":"ص0","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثنا أبو اليقظان عن جويرية بن أسماء قال قدم الفرزدق اليمامة وعليها المهاجر بن عبد الله الكلابي فقال لو دخلت على هذا فأصبت منه شيئا ولم يعلم بي جرير فلم تستقر به الدار حتى قال جرير\n(رأيتك إذ لم يغنك الله بالغنى ... رجعت إلى قيس وخدك ضارع)\n(وما ذاك إن أعطى الفرزدق باسته ... بأول ثغر ضيعته مجاشع)\nفلما بلغ ذلك الفرزدق قال لا جرم والله لا أدخل عليه ولا أرزؤه شيئا ولا أقيم باليمامة ثم رحل"},{"id":"tabaqat-shuara:577","bookId":"tabaqat-shuara","type":"section","seq":577,"chapter":"طبقات فحول الشعراء","title":"578- أنا أبو خليفة نا ابن سلام قال أخبرني أبو الغراف — قال نعي الفرزدق لجرير وهو عند المهاجر بن ع","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال أخبرني أبو الغراف\nقال نعي الفرزدق لجرير وهو عند المهاجر بن عبد الله باليمامة فقال\n(مات الفرزدق بعد ما جدعته ... ليت الفرزدق كان عاش قليلا)\nفقال له المهاجر لبئس ما قلت تهجو ابن عمك بعد ما مات لو رثيته كان أحسن بك قال والله إني لأعلم ان بقائي بعده لقليل وإن كان نجمي موافقا لنجمه فلأ رثينه قال بعد ما قيل لك لو كنت بكيته ما نسيتك العرب"},{"id":"tabaqat-shuara:578","bookId":"tabaqat-shuara","type":"section","seq":578,"chapter":"طبقات فحول الشعراء","title":"579- قال ابن سلام فانشدني معاوية بن أبي عمرو لجرير يرثي الفرزدق —","page":"ص0","text":"قال ابن سلام فانشدني معاوية بن أبي عمرو لجرير يرثي الفرزدق\n(فلا ولدت بعد الفرزدق حامل ... ولا ذات حمل من نفاس تعلت)\n(هو الوافد المأمون والراتق الثأى ... إذا النعل يوما بالعشيرة زلت)"},{"id":"tabaqat-shuara:579","bookId":"tabaqat-shuara","type":"section","seq":579,"chapter":"طبقات فحول الشعراء","title":"580- أنا أبو خليفة نا ابن سلام قال حدثني يونس ابن حبيب النحوي قال كان عبد الملك بن مروان لا يسم","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني يونس ابن حبيب النحوي قال كان عبد الملك بن مروان لا يسمع لشعراء مضر ولا يأذن لهم لأنهم كانوا زبيرية فوفد إليه الحجاج وفادته التي وفدها لم يفد إليه غيرها فأهدى إليه جريرا\nفدخل عليه فأذن له في النشيد فقام فأنشد مديح الحجاج واحدة بعد واحدة فأومأ إليه الحجاج أن ينشد مديح عبد الملك فأنشده التي يقول فيها\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nواعتمد على ابن الزبير فقال\n(دعوت الملحدين أبا خبيب ... جماحا هل شفيت من الجماح)\n(وقد وجدوا الخليفة هبرزيا ... ألف العيص ليس من النواحي)\n(وما شجرات عيصك في قريش ... بعشات الفروع ولا ضواحي)"},{"id":"tabaqat-shuara:580","bookId":"tabaqat-shuara","type":"section","seq":580,"chapter":"طبقات فحول الشعراء","title":"581- أنا أبو خليفة نا ابن سلام قال اخبرني أبو الغراف قال لما أنشده فيها —","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال اخبرني أبو الغراف قال لما أنشده فيها\n(تعزت أم حزرة ثم قالت ... رأيت الموردين ذوى لقاح)\n(تعلل وهي ساغبة بنيها ... بأنفاس من الشبم القراح)\n(سيكفيك العواذل أرحبي ... هجان اللون كالفرد اللياح)\n(يعز على الطريق بمنكبيه ... كما ابترك الخليع على القداح)\nفقال له عبد الملك فهل ترويها مئة فقال وهل إليها من سبيل جعلني الله فداءك يا أمير المؤمنين وأعطاه مئة وثمانية من الرعاء"},{"id":"tabaqat-shuara:581","bookId":"tabaqat-shuara","type":"section","seq":581,"chapter":"طبقات فحول الشعراء","title":"582- فذكرها جرير في مديحه يزيد بن عبد الملك وهو خليفة فقال —","page":"ص0","text":"فذكرها جرير في مديحه يزيد بن عبد الملك وهو خليفة فقال\n(أعطوا هنيدة يحدوها ثمانية ... مافي عطائهم من ولا سرف)"},{"id":"tabaqat-shuara:582","bookId":"tabaqat-shuara","type":"section","seq":582,"chapter":"طبقات فحول الشعراء","title":"583- أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثنا أبو الغراف قال أتى الفرزدق مجلس بني الهج","page":"ص0","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثنا أبو الغراف قال أتى الفرزدق مجلس بني الهجيم في مسجدهم فأنشدهم وبلغ ذلك جريرا فأتاهم من الغد لينشدهم كما أنشدهم الفرزدق فقال له شيخ منهم يا هذا اتق الله فإن هذا المسجد إنما بني لذكر الله والصلاة فقال جرير أقررتم للفرزدق ومنعتموني وخرج مغضبا وهو يقول\n(إن الهجيم قبيلة ملعونة ... حص اللحى متشابهو الألوان)\n(هم يتركون بنيهم وبناتهم ... صغر الأنوف لريح كل دخان)\n(لو يسمعون بأكلة أو شربة ... بعمان أصبح جمعهم بعمان)\nقال وخفة اللحى في بني هجيم ظاهرة وقيل لرجل منهم ما بالكم يابني الهجيم حص اللحى قال إن الفحل واحد"},{"id":"tabaqat-shuara:583","bookId":"tabaqat-shuara","type":"section","seq":583,"chapter":"طبقات فحول الشعراء","title":"584- أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثني أبو يحيى الضبي قال نازع جرير بني حمان في","page":"ص0","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثني أبو يحيى الضبي قال نازع جرير بني حمان في ركية لهم فصاروا إلى إبراهيم بن عربي باليمامة يتحاكمون إليه فقال جرير\n(أعوذ بالأمير غير الجبار ... من ظلم حمان وتحويل الدار)\n(ما كان قبل حفرنا من محفار ... وضربي المنقار بعد المنقار)\n(في جبل أصم غير خوار ... يصيح بالجب صياح الصرار)\n(له صهيل كصهيل الأمهار ... فاسأل بني صحب ورهط الجرار)\n(والسلميين العظام الأخطار ... والجار قد يخبر عن دار الجار)\nفقال الحماني\n(مالكليب من حمى ولا دار ... غير مقام أتن وأعيار)\n(قعس الظهور داميات الأثفار ... )\nقال فقال جرير فعن مقامهن جعلت فداك أجادل فقال ابن عربى للحماني قد أقررت لخصمك وحكم بها لجرير"},{"id":"tabaqat-shuara:584","bookId":"tabaqat-shuara","type":"section","seq":584,"chapter":"طبقات فحول الشعراء","title":"585- قال ابن سلام وأخبرني أبو يحيى الضبي قال بينا جرير — يسير على راحلته إذ هجم على أبيات من مازن","page":"ص0","text":"قال ابن سلام وأخبرني أبو يحيى الضبي قال بينا جرير\nيسير على راحلته إذ هجم على أبيات من مازن وهلال وهما بطنان من ضبة فخافهم لسوء أثره في ضبة فقال\n(فلا خوف عليك ولن تراعي ... بعقوة مازن وبني هلال)\n(هما الحيان إن فزعا يطيرا ... إلى جرد كأمثال السعالي)\n(أمازن يا ابن كعب إن قلبي ... لكم طول الحياة لغير قالي)\n(غطاريف يبيت الجار فيهم ... قرير العين في أهل ومال)\nقالوا أجل يا أبا حزرة فلا خوف عليك"},{"id":"tabaqat-shuara:585","bookId":"tabaqat-shuara","type":"section","seq":585,"chapter":"طبقات فحول الشعراء","title":"586- أنا أبوخليفة نا ابن سلام قال حدثني أبو يحيى — الضبي قال كان الذي هاج الهجاء بين جرير وعمر بن","page":"ص0","text":"أنا أبوخليفة نا ابن سلام قال حدثني أبو يحيى\nالضبي قال كان الذي هاج الهجاء بين جرير وعمر بن لجأ أن عمر كان ينشد أرجوزة له يصف فيها إبله وجرير حاضر بالماء فقال التيمي\n(قد وردت قبل إبى ضحائها ... تقرش الحيات في خرشائها)\n(جر العجوز الثنى من ردائها ... )\nفقال له جرير أخففت مرها قال فكيف أقول قال تقول\n(جر العروس الثنى من ردائها ... )\nقال التيمي وحمى فما قلت انت أسوأ من قولي قال فما هو قال قولك\n(وأوثق عند المردفات عشية ... لحاقا إذا ما جرد السيف لامع)\nفجعلتهن مردفات غدوة ثم تداركتهن عشية قال فكيف أقول قال تقول\n(وأوثق عند المرهفات عشية ... )\nقال فقال جرير فوالله لهذا البيت أحب إلي من بكرى حزرة ولكنك محلب للفرزدق"},{"id":"tabaqat-shuara:586","bookId":"tabaqat-shuara","type":"section","seq":586,"chapter":"طبقات فحول الشعراء","title":"587- فقال فيه جرير —","page":"ج2 ص425","text":"فقال فيه جرير\n(ألا سوانا ادرأتم يا بني لجأ ... شيئا يقارب أو وحشا لها غرر)\n(أحين كنت سماما يا بني لجأ ... وخاطرت بي عن أحسابها مضر)\n(إن الحفافيث عهدي يا بني لجأ ... يطرقن حين يسور الحية الذكر)\n(خل الطريق لمن يبني المناربه ... وابرز ببززة حيث اضطرك القدر)\n(أنت ابن برزة منسوبا إلى لجأ ... عبد العصارة والعيدان تعتصر)\nويروى\n(ألست نزوة خوار على أمة ... عبد العصارة والعيدان تعتصر)"},{"id":"tabaqat-shuara:587","bookId":"tabaqat-shuara","type":"section","seq":587,"chapter":"طبقات فحول الشعراء","title":"588- فقال التيمي يرد عليه —","page":"ص0","text":"فقال التيمي يرد عليه\n(لقد كذبت وشر القول أكذبه ... ما خاطرت بك عن أحسابها مضر)\n(ألست نزوة خوار على أمة ... لا يسبق الحلبات اللؤم والخور)\n(ما قلت من مرة إلا سأنقضها ... يا ابن الأتان بمثلي تنقض المرر)\n(قد أصبح الخز يبكي في بني الخطفى ... ياخز كرمان صبرا إنها الهتر)"},{"id":"tabaqat-shuara:588","bookId":"tabaqat-shuara","type":"section","seq":588,"chapter":"طبقات فحول الشعراء","title":"589- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(ما استردفت يوم الهذيل نساؤنا ... ولاقمن في صف لسجحة سجدا)\n(ولكن منعناهن في الشرك بالقنا ... وفي السلم صدقنا النبي محمدا)"},{"id":"tabaqat-shuara:589","bookId":"tabaqat-shuara","type":"section","seq":589,"chapter":"طبقات فحول الشعراء","title":"590- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(عجبت لما لا قت رياح من الأذى ... وما اقتبسوا منى وللشر قابس)\n(غضابا لكلب من كليب فرسته ... هوى ولشدات الأسود فرائس)\n(إذا ما ابن يربوع أتاك لمأكل ... على مجلس إن الأكيل مجالس)\n(فقل لابن يربوع ألست بداحض ... سبالك عنا إنهن نجائس)\n(تمسح يربوع سبالا لئيمة ... بها من منى العبد رطب ويابس)\nيريد ماصنع أبو سواج الضبي باليربوعي"},{"id":"tabaqat-shuara:590","bookId":"tabaqat-shuara","type":"section","seq":590,"chapter":"طبقات فحول الشعراء","title":"591- وكان أبو سواج أخذ بالبريرة صرد بن جمرة في شيء كان بينهما فجاء بزنج فأوثبهم على جارية له فك","page":"ص0","text":"وكان أبو سواج أخذ بالبريرة صرد بن جمرة في شيء كان بينهما فجاء بزنج فأوثبهم على جارية له فكانوا يمنون في قعب ثم حلب عليه فسقاه إياه فقتله وذلك قول الفرزدق لجرير حين أمرهم الحجاج أن يأتوه في لباس آبائهم فجاء جرير في الحديد فقال الفرزدق\n(وقد تلبس الحبلى السلاح وبطنها ... إذا انتطقت عبء عليها تعادله)"},{"id":"tabaqat-shuara:591","bookId":"tabaqat-shuara","type":"section","seq":591,"chapter":"طبقات فحول الشعراء","title":"592- وذلك قول الأخطل لجرير —","page":"ص0","text":"وذلك قول الأخطل لجرير\n(تعيب الخمر وهي شراب كسرى ... ويشرب قومك العجب العجيبا)\n(منى العبد عبد أبي سواج ... أحق من المدامة أن تعيبا)"},{"id":"tabaqat-shuara:592","bookId":"tabaqat-shuara","type":"section","seq":592,"chapter":"طبقات فحول الشعراء","title":"593- ثم وافى جرير والتيمي المدينة وقد وردها الوليد بن عبد الملك وكان يتأله في نفسه فقال تقذفان","page":"ص0","text":"ثم وافى جرير والتيمي المدينة وقد وردها الوليد بن عبد الملك وكان يتأله في نفسه فقال تقذفان المحصنات وتعضهان وتنفيان فأمر أبا بكر بن محمد بن عمرو بن حزم الأنصاري وكان واليه على المدينة بضربهما فضربهما وأقامهما على البلس مقرونين والتيمي يومئذ أشب من جرير وأقوى فجعل يشول بجرير وجرير يقول وهو المشول به\n(جزعت من العذاب غريب تيم ... وملأت القميص مع الإزار)\n(ولست مفارقا قرني حتى ... يطول تصعدي بك وانحداري)\nفقال التيمي\n(ولما أن قرنت إلى جرير ... أبى ذو بطنه إلا انحدارا)\nفقال له قدامة بن إبراهيم الجمحي بئسما قلت جعلت نفسك المقرون إليه قال فكيف أقول قال تقول\n(ولما لز في قربي جرير ... أبى ذو بطنه إلا انحدارا)\nقال لا والله لا أقول له أبدا إلا هكذا"},{"id":"tabaqat-shuara:593","bookId":"tabaqat-shuara","type":"section","seq":593,"chapter":"طبقات فحول الشعراء","title":"594- قال أبو البيداء لقي الفرزدق عمرو بن عطية أخا جرير وهو حينئذ يهاجي ابن لجأ فقال له ويلك قل","page":"ج2 ص432","text":"قال أبو البيداء لقي الفرزدق عمرو بن عطية أخا جرير وهو حينئذ يهاجي ابن لجأ فقال له ويلك قل لأخيك ثكلتك أمك إيت التيمي من عل كما أصنع بك أنا\nوكان الفرزدق قد حمي وأنف لجرير أن يتعلق به التيمي قال ابن سلام وأنشدنى له خلف الأحمر يعني الفرزدق شعرا يقول للتيمي\n(وما أنت إن قرما تميم تساميا ... أخا التيم إلا كالو شيظة في العظم)\n(فلو كنت مولى الظلم أو في ظلاله ... ظلمت ولكن لا يدى لك بالظلم)\nفأجابه ابن لجأ فقال\n(كذبت إأنا القرم الذي دق مالكا ... وأفناء يربوع وما أنت بالقرم)"},{"id":"tabaqat-shuara:594","bookId":"tabaqat-shuara","type":"section","seq":594,"chapter":"طبقات فحول الشعراء","title":"595- فحدثني أبو الغراف قال مشت رجال تميم بين جرير والتيمي وقالوا والله ماشعراؤنا إلا بلاء علينا","page":"ص0","text":"فحدثني أبو الغراف قال مشت رجال تميم بين جرير والتيمي وقالوا والله ماشعراؤنا إلا بلاء علينا يثيرون مخازينا ويهجون أحياءنا وأمواتنا فلم يزالوا يمشون بينهما حتى أصلحوا بينهما بالعهود والمواثيق المغلظة أن لا يعودا في الهجاء فكف التيمي وكان جرير لا يزال يسل الواحدة فيقول التيمي والله ما نقضت هذه ولا سمعتها فيقول جرير هذه كانت قبل الصلح"},{"id":"tabaqat-shuara:595","bookId":"tabaqat-shuara","type":"section","seq":595,"chapter":"طبقات فحول الشعراء","title":"596- حدثني عثمان بن عثمان عن عبد الرحمن بن حرملة قال لما ورد علينا هجاء جرير والتيمي قال لي سعي","page":"ص0","text":"حدثني عثمان بن عثمان عن عبد الرحمن بن حرملة قال لما ورد علينا هجاء جرير والتيمي قال لي سعيد بن المسيب تروأ لنا مما قالا شيئا فأتيته وقد استقبل القبلة يريد أن يكبر فقال أرويت شيئا قلت نعم فأقبل علي بوجهه فأنشدته للتيمي وهو يقول هيه هيه ثم أنشدته لجرير فقال أكله أكله"},{"id":"tabaqat-shuara:596","bookId":"tabaqat-shuara","type":"section","seq":596,"chapter":"طبقات فحول الشعراء","title":"597- أخبرني أبو الخطاب الزراري عن حجناء بن جرير — قال قلت لأبي ياأبت ما هجوت قوما قط إلا فضحتهم أ","page":"ص0","text":"أخبرني أبو الخطاب الزراري عن حجناء بن جرير\nقال قلت لأبي ياأبت ما هجوت قوما قط إلا فضحتهم أوقال أفسدتهم إلا التيم قال يا بني إني لم أجد بناء فأهدمه ولا حسبا أضعه أو قال أصمه"},{"id":"tabaqat-shuara:597","bookId":"tabaqat-shuara","type":"section","seq":597,"chapter":"طبقات فحول الشعراء","title":"598- وكانت تيم رعاء غنم فيغدون في غنمهم ثم يروحون وقد جاء كل رجل منهم بأبيات فيرفدون بها عمر بن","page":"ص0","text":"وكانت تيم رعاء غنم فيغدون في غنمهم ثم يروحون وقد جاء كل رجل منهم بأبيات فيرفدون بها عمر بن لجأ وكان أشعرهم بعد ابن لجأ السرندى"},{"id":"tabaqat-shuara:598","bookId":"tabaqat-shuara","type":"section","seq":598,"chapter":"طبقات فحول الشعراء","title":"599- وقيل لجرير ما صنعت في التيم شيئا قال إنهم شعراء لئام","page":"ص0","text":"وقيل لجرير ما صنعت في التيم شيئا قال إنهم شعراء لئام"},{"id":"tabaqat-shuara:599","bookId":"tabaqat-shuara","type":"section","seq":599,"chapter":"طبقات فحول الشعراء","title":"600- وحدثني مسمع بن عبد الملك وهو كردين قال كان عرادة النميري نديما للفرزدق فقدم الراعي البصرة","page":"ص0","text":"وحدثني مسمع بن عبد الملك وهو كردين قال كان عرادة النميري نديما للفرزدق فقدم الراعي البصرة فدعاه عرادة فأطعمه وسقاه وقال فضل الفرزدق على جرير فأبي فلما أخذ فيه الشراب لم يزل به حتى قال\n(يا صاحبي دنا الرواح فسيرا ... غلب الفرزدق في الهجاء جريرا)"},{"id":"tabaqat-shuara:600","bookId":"tabaqat-shuara","type":"section","seq":600,"chapter":"طبقات فحول الشعراء","title":"601- حدثني أبو الغراف قال كان الذي هاج الهجاء بين جرير الراعي وهو عبيد بن حصين أن الراعي كان يس","page":"ص0","text":"حدثني أبو الغراف قال كان الذي هاج الهجاء بين جرير الراعي وهو عبيد بن حصين أن الراعي كان يسأل عن جرير والفرزدق فيقول البفرزدق أكرمهما وأشعرهما\nفلقيه جرير فاستعاذه من نفسه وطلب إليه أن لا يدخل بينهما وقال أنا كنت أولى بعونك إني لأمدحكم وإنه ليهجوكم قال أجل ولست لمساءتك بعائد ثم بلغ جريرا أنه عاد في تفضيل الفرزدق عليه فلقيه بالبصرة وجرير على بغلة فعاتبه وقال استعذتك فزعمت أنك غير داخل بيني وبين ابن عمي قال والراعي يعتذر إليه وأقبل ابنه جندل وكان فيه خطل وعجب فقال لأبيه ألا أراك تعتذر إلى ابن الأتان نعم والله لنفضلن عليك ولنروين هجاءك ولنهجونك من تلقاء انفسنا وضرب وجه بغلته وقال\n(ألم تر أن كلب بني كليب ... أراد حياض دجلة ثم هابا)\nفانصرف جرير مغضبا محفظا فقال الراعي لابنه والله لهجوني\nوإياك فليته لا يجاوزنا ولكن سيذكر نسوتك وعلم الراعي أنه قد أساء فندم فتزعم نمير أنه حلف أن لا يجيبه سنة غضبا على ابنه وأنه مات في السنة ويقول غيرهم إنه كمد لما سمعها فمات"},{"id":"tabaqat-shuara:601","bookId":"tabaqat-shuara","type":"section","seq":601,"chapter":"طبقات فحول الشعراء","title":"602- وكان جرير يوم جرى هذا بينهما بالبصرة نازلا على امرأة من كليب فبات في علية لها وهي في سفل د","page":"ص0","text":"وكان جرير يوم جرى هذا بينهما بالبصرة نازلا على امرأة من كليب فبات في علية لها وهي في سفل دارها قالت المرأة فبات ليلته لا ينام يتردد في البيت حتى ظننت أنه عرض له جني أو سنح له بلاء حتى فتح له فقال\n(أقلي اللوم عاذل والعتابا ... وقولي إن أصبت لقد أصابا)\nحتى قال\n(إذا غضبت عليك بنو تميم ... حسبت الناس كلهم غضابا)\nثم أصبح فغدا إلى المربد فقال يا بني تميم قيدوا أي\nاكتبوا فلم يجبه الراعي ولم يهجه جرير بغيرها"},{"id":"tabaqat-shuara:602","bookId":"tabaqat-shuara","type":"section","seq":602,"chapter":"طبقات فحول الشعراء","title":"603- فقال لي بعض رواة قيس وعلمائهم كان الراعي فحل مضر حتى ضغمه الليث يعني جريرا","page":"ص0","text":"فقال لي بعض رواة قيس وعلمائهم كان الراعي فحل مضر حتى ضغمه الليث يعني جريرا"},{"id":"tabaqat-shuara:603","bookId":"tabaqat-shuara","type":"section","seq":603,"chapter":"طبقات فحول الشعراء","title":"604- قال أبو البيداء مر راكب يتغنى —","page":"ص0","text":"قال أبو البيداء مر راكب يتغنى\n(وعاو عوى من غير شىء رميته ... بقاقية أسبابها تقطر الدما)\n(خروج بأفواه الرواة كأنها ... قرا هندوانى إذا هز صمما)\nفسمعه الراعي فأتبعه رسولا فقال لمن البيتان قال جرير قال والله لو اجتمعت الجن والإنس على صاحب هذين البيتين ما أغنوا فيه شيئا ثم قال لمن حضر ويحكم ألام على أن يغلبني مثل هذا\nوإنما يعني جرير البعيث وكذلك كان اعتراض البعيث جريرا في غير شيء"},{"id":"tabaqat-shuara:604","bookId":"tabaqat-shuara","type":"section","seq":604,"chapter":"طبقات فحول الشعراء","title":"605- حدثني أبان بن عثمان قال كان سراقة البارقي شاعرا ظريفا تحبه الملوك حلو الحديث وكان قاتل الم","page":"ص0","text":"حدثني أبان بن عثمان قال كان سراقة البارقي شاعرا ظريفا تحبه الملوك حلو الحديث وكان قاتل المختار فأخذه أسيرا فأمر بقتله فقال والله لا تقتلني حتى تنقض دمشق حجرا حجرا فقال المختار لأبي عمرة من يخرج أسرارنا ثم قال من أسرك قال قوم على خيل بلق عليهم ثياب بيض لا أراهم في عسكرك قال فأقبل المختار على أصحابه فقال عدوكم يرى من هذا ما لا ترون قال إني قاتلك قال والله يا أمين آل محمد إنك تعلم أن هذا ليس باليوم الذي تقتلني فيه قال ففي أي يوم أقتلك قال يوم تضع كرسيك على باب مدينة دمشق فتدعو بي يومئذ فتضرب عنقي فقال المختار لأصحابه يا شرطة الله من يرفع حدثني ثم خلى عنه فقال سراقة وكان المختار يكنى أبا إسحاق\n(ألا أبلغ أبا إسحاق عني ... رأيت البلق دهما مصمتات)\n(أرى عيني ما لم تبصراه ... كلانا عالم بالترهات)\n(كفرت بوحيكم وجعلت نذرا ... على قتالكم حتى الممات)"},{"id":"tabaqat-shuara:605","bookId":"tabaqat-shuara","type":"section","seq":605,"chapter":"طبقات فحول الشعراء","title":"606- ثم قدم سراقة بعد ذلك العراق مع بشر بن مروان وكان بشر من فتيان قريش سخاء ونجدة وكان ممدحا ف","page":"ص0","text":"ثم قدم سراقة بعد ذلك العراق مع بشر بن مروان وكان بشر من فتيان قريش سخاء ونجدة وكان ممدحا فمدحه جرير والأخطل والفرزدق وكثير وأعشى بني شيبان وكان بشر يغري بين الشعراء وهو أغرى بين جرير والأخطل فحمل سراقة\nعلى جرير حتى هجاه فقال سراقة\n(أبلغ تميما غثها وسمينها ... والقول يقصد تارة ويجور)\n(أن الفرزدق برزت حلباته ... عفوا وغودر في الغبارجرير)\n(ما كنت أول محمر عثرت به ... آباؤه إن اللئيم عثور)\n(حرر كليبا إن خير صنيعة ... يوم الحساب الصوم والتحرير)\n(هذا القضاء البارقي وإنني ... بالميل في ميزانه لجدير)"},{"id":"tabaqat-shuara:606","bookId":"tabaqat-shuara","type":"section","seq":606,"chapter":"طبقات فحول الشعراء","title":"607- فقال جرير في قصيدته التي قال فيها —","page":"ص0","text":"فقال جرير في قصيدته التي قال فيها\n(يا صاحبي هل الصباح منير ... أم هل للوم عواذلي تفتير)\n(يا بشر إنك لم تزل في نعمة ... يأتيك من قبل العلي بشير)\n(بشر ابو مروان إن عاسرته ... عسر وعند يساره ميسور)\n(يابشر حق لوجهك التبشير ... هلا غضبت لنا وأنت أمير)\n(قد كان حقك أن تقول لبارق ... يا آل بارق فيم سب جرير)\n(إن الكريمة ينصر الكرم ابنها ... وابن اللئيمة للئام نصور)\n(أمسى سراقة قد عوى لشقائه ... خطب وأمك يا سراق يسير)\n(أسراق إنك قد غشيت ببارق ... أمرا مطالعه عليك وعور)\n(أسراق إنك لا نزارا نلتم ... والحي من يمن عليك نصير)\n(أكسحت باستك للفخار وبارق ... شيخان أعمى مقعد وكسير)"},{"id":"tabaqat-shuara:607","bookId":"tabaqat-shuara","type":"section","seq":607,"chapter":"طبقات فحول الشعراء","title":"608- وقال جرير —","page":"ج2 ص442","text":"وقال جرير\n(أمسى خليلك قد أجد فراقا ... هاج الحزين وذكر الأشواقا)\n(وإذا لقيت مجيلسا من بارق ... لا قيت أطبع مجلس أخلاقا)\n(قفد الأ كف عن المكارم كلها ... والجامعين مذلة ونفاقا)\n(ولقد هممت بأن أدمدم بارقا ... فحفظت فيهم عمنا إسحاقا)\n(قال ابن سلام يعني إسحاق الذبيح ثم نزعا"},{"id":"tabaqat-shuara:608","bookId":"tabaqat-shuara","type":"section","seq":608,"chapter":"طبقات فحول الشعراء","title":"609- فمر جرير بسراقة بمنى والناس مجتمعون على سراقة وهو ينشد فجهره جماله واستحسن نشيده فقال جرير","page":"ج2 ص442","text":"فمر جرير بسراقة بمنى والناس مجتمعون على سراقة وهو ينشد فجهره جماله واستحسن نشيده فقال جرير من أنت\nقال بعض من أخزاه الله على يديك قال أما والله لو عرفتك لوهبتك لظرفك"},{"id":"tabaqat-shuara:609","bookId":"tabaqat-shuara","type":"section","seq":609,"chapter":"طبقات فحول الشعراء","title":"610- قال كان العباس بن يزيد الكندي هجا جريرا وكانت الشعراء تعرض له ليهجوهم","page":"ص0","text":"قال كان العباس بن يزيد الكندي هجا جريرا وكانت الشعراء تعرض له ليهجوهم"},{"id":"tabaqat-shuara:610","bookId":"tabaqat-shuara","type":"section","seq":610,"chapter":"طبقات فحول الشعراء","title":"611- وكان يقول لا أبتدي ولكن أعتدي","page":"ص0","text":"وكان يقول لا أبتدي ولكن أعتدي"},{"id":"tabaqat-shuara:611","bookId":"tabaqat-shuara","type":"section","seq":611,"chapter":"طبقات فحول الشعراء","title":"612- قال أبو الغراف فتأناهم حولا وذلك قوله —","page":"ص0","text":"قال أبو الغراف فتأناهم حولا وذلك قوله\n(ألم ينه عني الناس أن لست ظالما ... بريئا وأنى للمتاحين متيح)"},{"id":"tabaqat-shuara:612","bookId":"tabaqat-shuara","type":"section","seq":612,"chapter":"طبقات فحول الشعراء","title":"613- فأتته كندة فاستعدوه من نفسه وطلبوا أن لا يذكرهم قال فأخبروني بمساويه إن كنتم صادقين ففرشوه","page":"ص0","text":"فأتته كندة فاستعدوه من نفسه وطلبوا أن لا يذكرهم قال فأخبروني بمساويه إن كنتم صادقين ففرشوه أمره فقالوا هم أهل بيت كانوا في فزارة مجاورين ثم تحولوا إلى بني كلاب ثم تحولوا في طيىء ومعه ابنة له جارية حدثة فطبن لها غلام منهم يقال له عتاب فكان يلاعبها فقالوا إنها حبلت منه وولدت وقتل الولد وكانوا نزولا في جبل يقال له شعبي وكانوا أهل بيت سرو وجمال قال رأيت رجلا من ولده فما رأيت أجمل منه\nفقال جرير\n(ستطلع من ذرى شعبى قواف ... على الكندي تلتهب التهابا)\n(أيوما في فزارة مستجيرا ... ويوما ناشدا حلفا كلابا)\n(أعتابا تجاور حين أجنت ... نخيل أجا وأعنزه الربابا)\n(يخاتلها وتحسبه لعابا ... أساء غلام جيرتك اللعابا)\n(وما خفيت هضيبة يوم جرت ... ولا إطعام سخلتها الكلابا)\n(يقطع بالمشاقص حالبيها ... وقد بلت مشمتها الترابا)\n(وقد حملت ثمانية وتمت ... لتاسعها وتحسبها كعابا)\n(أعبدا حل في شعبى غريبا ... ألؤما لا أبا لك واغترابا)\n(إذا نزل الحجيج على قنيع ... دببت الليل تسترق العيابا)\n(فقد حلت يمينك إن إمام ... أقام الحد واتبع الكتابا)\nفيزعم الناس أنه لما أتنه هذه الأبيات كمد فمات"},{"id":"tabaqat-shuara:613","bookId":"tabaqat-shuara","type":"section","seq":613,"chapter":"طبقات فحول الشعراء","title":"614- قال وقال رجل من عبد القيس يقال له أحمز بن غدانة من بني عصر —","page":"ج2 ص446","text":"قال وقال رجل من عبد القيس يقال له أحمز بن غدانة من بني عصر\n(علام تعنى ياجرير وقد قضى ... أخو عصر أن قد علاك الفرزدق)\n(وإن امرأ سوى كليبا بدارم ... وسوى جريرا بالفرزدق أحمق)\nفأخذه عبد العزيز بن عمرو بن مرجوم وكان سيد عبد القيس بالبصرة وأبوه سيد وجده سيد"},{"id":"tabaqat-shuara:614","bookId":"tabaqat-shuara","type":"section","seq":614,"chapter":"طبقات فحول الشعراء","title":"615- وكان جده مرجوم اسمه عامر بن عبيد فنافر رجلا من قومه إلى النعمان فنفرة عليه وقال رجمتك بالش","page":"ص0","text":"وكان جده مرجوم اسمه عامر بن عبيد فنافر رجلا من قومه إلى النعمان فنفرة عليه وقال رجمتك بالشرف فسمي مرجوما وفيه يقول لبيد\n(وقبيل من لكيز شاهد ... رهط مرجوم ورهط ابن المعل)"},{"id":"tabaqat-shuara:615","bookId":"tabaqat-shuara","type":"section","seq":615,"chapter":"طبقات فحول الشعراء","title":"616- فشده وثاقا فأرسل به إلى جرير وقال احكم فيه — فقال جرير —","page":"ص0","text":"فشده وثاقا فأرسل به إلى جرير وقال احكم فيه\nفقال جرير\n(لولا ابن عمرو بن مرجوم لقد خرجت ... شنعاء لا تتقي سمعا ولا بصرا)\n(إني لأرجو وراجي الخير مدركه ... أن يجبر الله في الدنيا بني عصرا)\n(كم من يتيم ومسكين وأرملة ... وبائس في قديم الدهر قد جبرا)"},{"id":"tabaqat-shuara:616","bookId":"tabaqat-shuara","type":"section","seq":616,"chapter":"طبقات فحول الشعراء","title":"617- وقال جرير يرد على الصلتان —","page":"ص0","text":"وقال جرير يرد على الصلتان\n(أقول ولم أملك أمال بن حنظل ... متى كان حكم الله في كرب النخل)"},{"id":"tabaqat-shuara:617","bookId":"tabaqat-shuara","type":"section","seq":617,"chapter":"طبقات فحول الشعراء","title":"618- فاعترضه خليد عينين من أهل هجر فقال —","page":"ص0","text":"فاعترضه خليد عينين من أهل هجر فقال\n(وأي نبي كان من أهل قرية ... وما الحكم يا ابن اللؤم إلامع الرسل)"},{"id":"tabaqat-shuara:618","bookId":"tabaqat-shuara","type":"section","seq":618,"chapter":"طبقات فحول الشعراء","title":"619- فقال جرير —","page":"ص0","text":"فقال جرير\n(فخل الفخر يا ابن أبى خليد ... وأد خراج رأسك كل عام)\n(لقد علقت يمينك رأس ثور ... وما علقت يمينك باللجام)"},{"id":"tabaqat-shuara:619","bookId":"tabaqat-shuara","type":"section","seq":619,"chapter":"طبقات فحول الشعراء","title":"620- وقال جرير —","page":"ص0","text":"وقال جرير\n(كم عمة لك يا خليد وخالة ... خضر نواجذها من الكراث)\n(نبتت بمنبته فطاب لشمها ... ونأت عن القيصوم والجثجاث)\nفسكت خليد"},{"id":"tabaqat-shuara:620","bookId":"tabaqat-shuara","type":"section","seq":620,"chapter":"طبقات فحول الشعراء","title":"621- وقال في أحمر بن غدانة —","page":"ص0","text":"وقال في أحمر بن غدانة\n(نبئت عبدا بالعيون يسبني ... أحيمر سوارا على كرب النخل)\nفقال أحمر\n(أعيرتنا بالنخل أن كان مالنا ... وود أبوك اللؤم لو كان ذا نخل)\nفهم جرير ببني عصر فأتاه عبد العزيز بن عمرو بن مرجوم فشده فأرسله إلى جرير وحمل جريرا وكساه"},{"id":"tabaqat-shuara:621","bookId":"tabaqat-shuara","type":"section","seq":621,"chapter":"طبقات فحول الشعراء","title":"622- حدثني عامر بن عبد الملك المسمعي قال لما بلغ الأخطل تهاجى جرير والفرزدق قال لابنه مالك انحد","page":"ص0","text":"حدثني عامر بن عبد الملك المسمعي قال لما بلغ الأخطل تهاجى جرير والفرزدق قال لابنه مالك انحدر إلى العراق حتى تسمع منهما وتأتيني بخبرهما قال فلقيهما ثم استمع فأتى أباه فقال جرير يغرف من بحر والفرزدق ينحت من صخر فقال الأخطل فجرير أشعرهما ثم قال\n(إني قضيت قضاء غير ذي جنف ... لما سمعت ولما جاءني الخبر)\n(أن الفرزدق قد شالت نعامته ... وعضه حية من قومه ذكر)"},{"id":"tabaqat-shuara:622","bookId":"tabaqat-shuara","type":"section","seq":622,"chapter":"طبقات فحول الشعراء","title":"623- ثم قدم الأخطل الكوفة على بشر بن مروان فبعث إليه محمد بن عمير بن عطارد بن حاجب بن زرارة بدر","page":"ص0","text":"ثم قدم الأخطل الكوفة على بشر بن مروان فبعث إليه محمد بن عمير بن عطارد بن حاجب بن زرارة بدراهم وحملان وكسوة وخمر وبلغني أن الذي بعث بهذا شبة بن عقال المجاشعي وقال للأخطل فضل شاعرنا عليه وسبه فقال الأخطل\n(اخسأ كليب إليك إن مجاشعا ... وأبا الفوارس نهشلا أخوان)\n(قوم إذا خطرت إليك قرومهم ... جعلوك بين كلا كل وجران)\n(وإذا وضعت أباك في ميزانهم ... رجحوا وشال أبوك في الميزان)\nفقال جرير\n(ياذا العباية إن بشرا قد قضى ... أن لا تجوز شهادة النشوان)"},{"id":"tabaqat-shuara:623","bookId":"tabaqat-shuara","type":"section","seq":623,"chapter":"طبقات فحول الشعراء","title":"624- وأخبرني أبو عبيد النحوي قال لما أتى الأخطل قول جرير —","page":"ص0","text":"وأخبرني أبو عبيد النحوي قال لما أتى الأخطل قول جرير\n(جاريت مطلع الرهان بسنه ... روق شبيبته وعمرك فاني)\nويروى\n(جاريت مطلع الرهان بروقه ... ماء الشباب وماء روقك فاني)\nقال الأخطل صدق ابن المراغة وقد أديل مني حين أقول\nلنابغة بني جعدة\n(لقد جارى أبو ليلى بقحم ... ومنتكث على التقريب وان)\n(إذا خبط الخبار أكب فيه ... وخر على الجحافل والجران)\nيروى إذا دخل الخبار\nوكان الأخطل من أسن أهل طبقته"},{"id":"tabaqat-shuara:624","bookId":"tabaqat-shuara","type":"section","seq":624,"chapter":"طبقات فحول الشعراء","title":"625- أنشدني محمد بن الفضل الهاشمي لجرير في محمد بن عمير ابن عطارد —","page":"ص0","text":"أنشدني محمد بن الفضل الهاشمي لجرير في محمد بن عمير ابن عطارد\n(إنا لنعلم ما أبوك بحاجب ... فالحق بأصلك من بني دهمان)\nوهي قصيدة"},{"id":"tabaqat-shuara:625","bookId":"tabaqat-shuara","type":"section","seq":625,"chapter":"طبقات فحول الشعراء","title":"626- وقال لشبة بن عقال وكانت فيه شوهة وذاك في ولده بين —","page":"ص0","text":"وقال لشبة بن عقال وكانت فيه شوهة وذاك في ولده بين\n(فضح العشيرة يوم يسلح قائما ... ظل النعامة شبة بن عقال)"},{"id":"tabaqat-shuara:626","bookId":"tabaqat-shuara","type":"section","seq":626,"chapter":"طبقات فحول الشعراء","title":"627- وقال للأخطل —","page":"ص0","text":"وقال للأخطل\n(رشتك مجاشع سكرا بفلس ... فلا تهنيك رشوة من رشاكا)\nوهي قصيدة طويلة"},{"id":"tabaqat-shuara:627","bookId":"tabaqat-shuara","type":"section","seq":627,"chapter":"طبقات فحول الشعراء","title":"628- وقال —","page":"ص0","text":"وقال\n(يا شب ويحك إلا تكفر فوارسنا ... يوم ابن كبشة عالي الملك جبار)\n(لولا حماية يربوع نساءكم ... كانت لغيركم فيهن أطهار)"},{"id":"tabaqat-shuara:628","bookId":"tabaqat-shuara","type":"section","seq":628,"chapter":"طبقات فحول الشعراء","title":"629- قال ابن سلام وسألت بشارا المرعث أي الثلاثة أشعر فقال لم يكن الأخطل مثلهما ولكن ربيعة تعصبت","page":"ص0","text":"قال ابن سلام وسألت بشارا المرعث أي الثلاثة أشعر فقال لم يكن الأخطل مثلهما ولكن ربيعة تعصبت له وأفرطت فيه قلت فهذان قال كانت لجرير ضروب من الشعر لا يحسنها الفرزدق ولقد ماتت النوار فقاموا ينوحون عليها بشعر جرير\nفقلت لبشار وأي شيء لجرير من المراثى إلا التي رثى بها امرأته فأنشدني لجرير يرثي ابنه سوادة ومات بالشام\n(قالوا نصيبك من أجرفقلت لهم ... كيف العزاء وقد فارقت أشبالي)\n(فارقتني حين كف الدهر من بصري ... وحين صرت كعظم الرمة البالي)\n(أمسى سوادة يجلو مقلتى لحم ... باز يصرصر فوق المربأ العالي)\n(قد كنت أعرفه مني إذا غلقت ... رهن الجياد ومد الغاية الغالي)\n(إن الثوى بذي الزيتون فاحتسبي ... قد أسرع اليوم في عقلي وفي حالي)\n(إلا تكن لك بالديرين معولة ... فرب باكية بالرمل معوال)\n(كأم بو عجول عند معهده ... حنت إلى جلد منه وأوصال)\n(حتى إذا عرفت أن لا حياة به ... ردت هماهم حرى الجوف مثكال)\n(زادت على وجدها وجدا وإن رجعت ... في الصدر منها خطوب ذات بلبال)"},{"id":"tabaqat-shuara:629","bookId":"tabaqat-shuara","type":"section","seq":629,"chapter":"طبقات فحول الشعراء","title":"630- حدثني عبد الجبار بن سعيد بن المساحقى سليمان عن المحرر بن أبى هريرة قال إني بأريحا في عسكر","page":"ج2 ص458","text":"حدثني عبد الجبار بن سعيد بن المساحقى سليمان عن المحرر بن أبى هريرة قال إني بأريحا في عسكر سليمان بن عبد الملك وفيه جرير والفرزدق إذ أتانا الفرزدق فقال اشهدوا جنازة محمد ابن أخي ثم قال\n(بتنا بدير أريحاء بليلة ... خدارية يزداد طولا تمامها)\n(أكابد فيها نفس أقرب من مشى ... أبوه يإمر غاب عني نيامها)\n(وكنا نرى من غالب في محمد ... شمائل يعلو الفاعلين كرامها)\n(وكان إذا ما حل أرضا تزينت ... بزينته صحراؤها وإكامها)\n(سقى أريحاء الغيث وهي بغيضة ... إلينا ولكن كى ليسقاه هامها)\nثم انصرف وجاء جرير فقال قد رأيت هذا وسمعت ما قال في ابن أخيه وما ابن أخيه فعل الله به وفعل وذكر اللعن قال ومضى جرير فلا والله ما لبثنا إلا جمعا حتى جاء جرير فقام مقامه فقال اشهدوا سوادة ابنه"},{"id":"tabaqat-shuara:630","bookId":"tabaqat-shuara","type":"section","seq":630,"chapter":"طبقات فحول الشعراء","title":"631- ثم قال —","page":"ج2 ص460","text":"ثم قال\n(كأن سوادة يجلو مقلتى لحم ... باز يصرصر فوق المربأ العالي)\n(ودعتني حين كف الدهر من بصري ... وحين صرت كعظم الرمة البالي)\n(إلا تكن لك بالديرين باكية ... فرب باكية بالرمل معوال)\n(قالوا نصيبك من أجرفقلت لهم ... كيف العزاء وقد فارقت أشبالي)"},{"id":"tabaqat-shuara:631","bookId":"tabaqat-shuara","type":"section","seq":631,"chapter":"طبقات فحول الشعراء","title":"632- حدثني أبو يحيى الضبي قال كان عبد الرحمن بن حسان ويزيد بن معاوية يتقاولان فاستعلاه ابن حسان","page":"ج2 ص460","text":"حدثني أبو يحيى الضبي قال كان عبد الرحمن بن حسان ويزيد بن معاوية يتقاولان فاستعلاه ابن حسان قال يزيد لكعب\nابن جعيل التغلبي أجبه عني واهجه فقال والله ما تلتقي شفتاي بهجاء الأنصار ولكني أدلك على الشاعر الماهر الفاجر فتى منا يقول له غياث بن الغوث نصراني"},{"id":"tabaqat-shuara:632","bookId":"tabaqat-shuara","type":"section","seq":632,"chapter":"طبقات فحول الشعراء","title":"633- وكان كعب سماه الأخطل وذاك أنه سمعه ينشد هجاء فقال يا غلام إنك لأخطل اللسان","page":"ص0","text":"وكان كعب سماه الأخطل وذاك أنه سمعه ينشد هجاء فقال يا غلام إنك لأخطل اللسان"},{"id":"tabaqat-shuara:633","bookId":"tabaqat-shuara","type":"section","seq":633,"chapter":"طبقات فحول الشعراء","title":"634- قال أبو يحيى قال كعب بن جعيل إني قد هجوت نفسي ببيتين وقد ضممت عليهما فمن أصابهما فهو الشاع","page":"ص0","text":"قال أبو يحيى قال كعب بن جعيل إني قد هجوت نفسي ببيتين وقد ضممت عليهما فمن أصابهما فهو الشاعر فقال الأخطل\n(سميت كعبا بشر العظام ... وكان أبوك سمى الجعل)\n(وإن محلك من وائل ... محل القراد من است الجمل)\nقال هما هذان"},{"id":"tabaqat-shuara:634","bookId":"tabaqat-shuara","type":"section","seq":634,"chapter":"طبقات فحول الشعراء","title":"635- قال أبو يحيى أرسل إليه يزيد أن اهجهم فقال كيف أصنع بمكانهم أخافهم على نفسي قال لك ذمة أمير","page":"ص0","text":"قال أبو يحيى أرسل إليه يزيد أن اهجهم فقال كيف أصنع بمكانهم أخافهم على نفسي قال لك ذمة أمير المؤمنين وذمتي فذلك حين يقول\n(ذهبت قريش بالسماحة والندى ... واللؤم تحت عمائم الأنصار)"},{"id":"tabaqat-shuara:635","bookId":"tabaqat-shuara","type":"section","seq":635,"chapter":"طبقات فحول الشعراء","title":"636- فجاء النعمان بن بشير الأنصاري إلى معاوية فقال يا أمير المؤمنين بلغ منا أمر ما بلغ منا مثله","page":"ص0","text":"فجاء النعمان بن بشير الأنصاري إلى معاوية فقال يا أمير المؤمنين بلغ منا أمر ما بلغ منا مثله في جاهلية ولا إسلام قال من بلغ ذاك منكم قال غلام نصراني من بني تغلب قال ما حاجتك فيه قال لسانه قال ذاك لك"},{"id":"tabaqat-shuara:636","bookId":"tabaqat-shuara","type":"section","seq":636,"chapter":"طبقات فحول الشعراء","title":"637- وكان النعمان ذا منزلة من معاوية وكان معاوية يقول يا معشر الأنصار تستبطئونني وما صحبني منكم","page":"ص0","text":"وكان النعمان ذا منزلة من معاوية وكان معاوية يقول يا معشر الأنصار تستبطئونني وما صحبني منكم إلا النعمان بن بشير وقد رأيتم ما صنعت به وكان ولاه الكوفة وأكرمه"},{"id":"tabaqat-shuara:637","bookId":"tabaqat-shuara","type":"section","seq":637,"chapter":"طبقات فحول الشعراء","title":"638- فأخبر الأخطل فصار إلى يزيد فدخل يزيد إلى أبيه — فقال يا أمير المؤمنين هجوني وذكروك فجعلت له","page":"ص0","text":"فأخبر الأخطل فصار إلى يزيد فدخل يزيد إلى أبيه\nفقال يا أمير المؤمنين هجوني وذكروك فجعلت له ذمتك وذمتي على أن ردعني فقال معاوية للنعمان لا سبيل إلى ذمة أبي خالد"},{"id":"tabaqat-shuara:638","bookId":"tabaqat-shuara","type":"section","seq":638,"chapter":"طبقات فحول الشعراء","title":"639- فذاك حيث يقول الأخطل —","page":"ص0","text":"فذاك حيث يقول الأخطل\n(أبا خالد دافعت عني عظيمة ... وأدركت لحمي قبل أن ينبددا)\n(وأطفأت عني نار نعمان بعدما ... أغذ لأمر فاجر وتجردا)\n(ولما رأى نعمان دوني ابن حرة ... طوى الكشح إذ لم يستطعني وعردا)\n(وما مفعم يعلو جزائر حامر ... يشق إليها خيزرانا وغرقدا)\n(تحرز منه أهل عانات بعد ما ... كسا سورها الأدنى غثاء منضدا)\n(كأن بنات الماء في حجراتها ... أباريق أهدتها دياف لصرخدا)\n(يقمص بالملاح حتى يشفه ... الحذار وإن كان المشيح المعودا)\n(بمطرد الآذى جون كأنما ... زفا بالقراقير النعام المطردا)\n(بأجود سيبا من يزيد إذا غدت ... به بخته يحملن ملكا وسوددا)\n(يقلص بالسيف الطويل نجاده ... خميص إذا السربال عنه تقددا)"},{"id":"tabaqat-shuara:639","bookId":"tabaqat-shuara","type":"section","seq":639,"chapter":"طبقات فحول الشعراء","title":"640- حدثني يونس وعامر بن عبد الملك وأبو الغراف فألفت ما قالوا قال أتى الأخطل الكوفة فأتى الغضبا","page":"ج2 ص465","text":"حدثني يونس وعامر بن عبد الملك وأبو الغراف فألفت ما قالوا قال أتى الأخطل الكوفة فأتى الغضبان بن القبعثرى الشيباني وهو يومئذ سيد بكر بن وائل فسأله في حمالة وكان سؤلة على مثال فعلة قال إن شئت أعطيتك ألفين وإن شئت أعطيتك درهمين قال ما بال الألفين وما بال الدرهمين قال إن أعطيتك ألفين لم يعطكها إلا قليل وإن أعطينا درهمين لم يبق بكري بالكوفة إلا أعطاك درهمين وكتبنا لك إلى إخواننا من أهل البصرة فلم يبق بكري إلا أعطاك درهمين فخفت عليهم المؤونه\nوكثر لك النيل قال فهذه إذن قال نقسمها لك إلى أن ترجع من البصرة فكتب له بالبصرة إلى سويد بن منجوف السدوسي وهو زعيم بكر بن وائل بالبصرة"},{"id":"tabaqat-shuara:640","bookId":"tabaqat-shuara","type":"section","seq":640,"chapter":"طبقات فحول الشعراء","title":"641- قال يونس بن حبيب في حديثه فنزل على آل الصلت ابن حريث الحنفي فأخبرني من سمعه أنه قال والله","page":"ص0","text":"قال يونس بن حبيب في حديثه فنزل على آل الصلت ابن حريث الحنفي فأخبرني من سمعه أنه قال والله لا أزال أفعل ذاك"},{"id":"tabaqat-shuara:641","bookId":"tabaqat-shuara","type":"section","seq":641,"chapter":"طبقات فحول الشعراء","title":"642- ثم رجع إلى الحديث الأول قال وأتى سويدا بالكتاب فأخبره بحاجته قال نعم وأقبل على قومه فقال ه","page":"ص0","text":"ثم رجع إلى الحديث الأول قال وأتى سويدا بالكتاب فأخبره بحاجته قال نعم وأقبل على قومه فقال هذا أبو مالك قد أتاكم يسألكم أن تجمعوا له وهو أهل ان نقضي حاجته وهو الذي يقول\n(إذا ما قلت قد صالحت بكرا ... أبى البغضاء لا النسب البعيد)\n(وأيام لنا ولهم طوال ... يعض الهام فيهن الحديد)\n(ومهراق الدماء بواردات ... تبيد المخزيات وما تبيد)\n(هما أخوان يصطليان نارا ... رداء الموت بينهما جديد)\nفهيجهم على الأخطل قالوا فلاها الله إذن والله لا نعطيه شيئا"},{"id":"tabaqat-shuara:642","bookId":"tabaqat-shuara","type":"section","seq":642,"chapter":"طبقات فحول الشعراء","title":"643- فخرج وهو يقول —","page":"ص0","text":"فخرج وهو يقول\n(فإن تمنع سدوس درهميها ... فإن الريح طيبة قبول)\n(تواكلني بنو العلات منهم ... وغالت مالكا ويزيد غول)\n(صريعا وائل هلكا جميعا ... كان الأرض بعدهما محول)\nيريد مالك بن مسمع ويزيد بن رويم الشيباني"},{"id":"tabaqat-shuara:643","bookId":"tabaqat-shuara","type":"section","seq":643,"chapter":"طبقات فحول الشعراء","title":"644- وقال لسويد بن منجوف وكان سويد رجلا تقتحمه العين وليس بذي منظرة —","page":"ص0","text":"وقال لسويد بن منجوف وكان سويد رجلا تقتحمه العين وليس بذي منظرة\n(وما جذع سوء خرق السوس أصله ... لما حملته وائل بمطيق)\nويروى خرب السوس جوفه"},{"id":"tabaqat-shuara:644","bookId":"tabaqat-shuara","type":"section","seq":644,"chapter":"طبقات فحول الشعراء","title":"645- وكان الأخطل مع مهارته وشعره يسقط كان مدح سماكا الأسدي وهو سماك الهالكي بن عمير بن عمرو بن","page":"ص0","text":"وكان الأخطل مع مهارته وشعره يسقط كان مدح سماكا الأسدي وهو سماك الهالكي بن عمير بن عمرو بن أسد وبنو عمرو يلقبون القيون ومسجد سماك بالكوفة معروف وكان\nمن أهلها فخرج أيام علي هاربا فلحق بالجزيرة فمدحه الأخطل فقال\n(نعم المجير سماك من بني أسد ... بالمرج إذ قتلت جيرانها مضر)\n(قد كنت أحسبه قينا وأنبؤه ... فاليوم طير عن أثوابه الشرر)\nويروى قد كنت أنبؤه قينا وأخبره\n(إن سماكا بنى مجدا لأسرته ... حتى الممات وفعل الخير يبتدر)\n(فقال سماك يا أخطل أردت مديحي فهجوتني كان الناس يقولون قولا فحققته"},{"id":"tabaqat-shuara:645","bookId":"tabaqat-shuara","type":"section","seq":645,"chapter":"طبقات فحول الشعراء","title":"646- فلما هجا سويدا قال له سويد يا أبا مالك والله ما تحسن أن تهجو ولا تمدح لقد أردت مدح الأسدي","page":"ج2 ص470","text":"فلما هجا سويدا قال له سويد يا أبا مالك والله ما تحسن أن تهجو ولا تمدح لقد أردت مدح الأسدي فهجوته يعني قوله قد كنت أحسبه قينا وأردت هجائي فمدحتني جعلت وائلا كلها حملتني أمورها وما طمعت في بني ثعلبة فضلا عن بكر فزدتني تغلب"},{"id":"tabaqat-shuara:646","bookId":"tabaqat-shuara","type":"section","seq":646,"chapter":"طبقات فحول الشعراء","title":"647- أبان بن عثمان البجلي قال مر الأخطل بالكوفة في بني رؤاس ومؤذنهم ينادي بالصلاة فقال بعض شبان","page":"ج2 ص470","text":"أبان بن عثمان البجلي قال مر الأخطل بالكوفة في بني رؤاس ومؤذنهم ينادي بالصلاة فقال بعض شبانهم ابا مالك الا تدخل فتصلي فقال\n(أصلي حيث تدركني صلاتي ... وليس البر وسط بني رؤاس)\nحدثني أبوالحصين المدني قال بينا الأخطل قد خلا مع صاحب له بخميرة لهما في نزهة إذ طرأ عليهما طارىء لا يعرفانه ولا يستخفانه فشرب شرابهما وثقل عليهما فقال الأخطل\n(وليس القذى بالعود يسفط في الخمر ... ولا بذباب خطبه أيسر الأمر)\n(ولكن شخصا لا يسر بقربه ... ترامى به الغيطان من حيث لا ندري)"},{"id":"tabaqat-shuara:647","bookId":"tabaqat-shuara","type":"section","seq":647,"chapter":"طبقات فحول الشعراء","title":"649- أبان بن عثمان حدثني أبي قال دعا الأخطل شاب من شباب أهل الكوفة إلى منزله فقال يا ابن أخي أن","page":"ص0","text":"أبان بن عثمان حدثني أبي قال دعا الأخطل شاب من شباب أهل الكوفة إلى منزله فقال يا ابن أخي أنت لا تحتمل المؤونة وليس عليك محتمل فلم يزل به حتى انتجعه فأتى الباب\nفقال يا شقراء فخرجت إليه امرأة فقال لها أعلمي فلانا مكاني\nفقال لأمة هذا أبو مالك قد زارنا فباعت غزلا فاشترت لهم لحما ونبيذا وريحانا فدخل خصا لهم فأكل معه وشرب فقال في ذلك\n(وبيت كظهر الفيل جل متاعه ... أباريقه والشارب المتقطر)\n(ترى فيه أثلام الأصيص كأنها ... إذا بال فيها الشيخ حفر معور)\n(لعمرك ما عشنا بيوم معيشة ... من الدهر إلا يوم شقراء أقصر)\n(حوارية لا يدخل الذم بيتها ... مطهرة يأوي إليها مطهر)"},{"id":"tabaqat-shuara:648","bookId":"tabaqat-shuara","type":"section","seq":648,"chapter":"طبقات فحول الشعراء","title":"650- قال أبو يحيى الضبي اجتمع الفرزدق وجرير والأخطل عند بشر بن مروان وكان يغرى بين الشعراء فقال","page":"ج2 ص473","text":"قال أبو يحيى الضبي اجتمع الفرزدق وجرير والأخطل عند بشر بن مروان وكان يغرى بين الشعراء فقال للأخطل احكم بين الفرزدق وجرير\nقال أعفني أيها الأمير قال احكم بينهما فاستعفاه بجهده فأبي إلا أن يقول فقال هذا حكم مشؤوم ثم قال الفرزدق ينحت من صخر وجرير يغرف من بحر فلم يرض جرير بذلك وكان سبب الهجاء بينهما فقال جرير في حكومته\n(ياذا العباية إن بشرا قد قضى ... أن لا تجوز حكومة النشوان)\n(فدعوا الحكومة لستم من أهلها ... إن الحكومة في بني شيبان)\n(قلوا كليبكم بلقحة جارهم ... يا خزر تغلب لستم بهجان)"},{"id":"tabaqat-shuara:649","bookId":"tabaqat-shuara","type":"section","seq":649,"chapter":"طبقات فحول الشعراء","title":"651- وقال الأخطل يرد عليه —","page":"ص0","text":"وقال الأخطل يرد عليه\n(ولقد تقايستم إلى أحسابكم ... وجعلتم حكما من الصلتان)\n(فإذا كليب لا يساوي دارما ... حتى يساوى حصرم بأبان)\n(وإذا جعلت أباك في ميزانهم ... رجحوا وشال أبوك في الميزان)\n(وإذا وردت الماء كان لدارم ... عفواته وسهولة الأعطان)\nثم استطار الهجاء"},{"id":"tabaqat-shuara:650","bookId":"tabaqat-shuara","type":"section","seq":650,"chapter":"طبقات فحول الشعراء","title":"652- وحدثني رجل من بني مروان شامي قال اجتمع جرير والأخطل عند عبد الملك بن مروان فقال له الأخطل","page":"ص0","text":"وحدثني رجل من بني مروان شامي قال اجتمع جرير والأخطل عند عبد الملك بن مروان فقال له الأخطل أين تركت أعيار أمك قال ترعى مع خنازير أبيك"},{"id":"tabaqat-shuara:651","bookId":"tabaqat-shuara","type":"section","seq":651,"chapter":"طبقات فحول الشعراء","title":"653- أبو الغراف قال تناشدا عند الوليد بن عبد الملك فأنشد الأخطل كلمة عمرو بن كلثوم —","page":"ص0","text":"أبو الغراف قال تناشدا عند الوليد بن عبد الملك فأنشد الأخطل كلمة عمرو بن كلثوم\n(ألا هبي بصحنك فاصبحينا ... )\nفتحرك الوليد فقال مغر يا جرير يريد قصيدة أوس بن مغراء السعدي ثم القريعي\n(ماذا يهيجك من دار بفيحانا ... قفر توهمت منها اليوم عرفانا)\n(منا النبي الذي قد عاش مؤتمنا ... وصاحباه وعثمان بن عفانا)\n(تحالف الناس مما يعلمون لنا ... ولا نخالف إلا الله مولانا)\n(محمد خير من يمشي على قدم ... وكان صافية لله خلصانا)\nفقال الأخطل أعلى تعصب يا أمير المؤمنين وعلي تعين وأنا صاحب عبد الرحمن بن حسان وصاحب قيس وصاحب كذا"},{"id":"tabaqat-shuara:652","bookId":"tabaqat-shuara","type":"section","seq":652,"chapter":"طبقات فحول الشعراء","title":"654- وكان الأخطل مستعليا قيسا في حربهم فقال —","page":"ص0","text":"وكان الأخطل مستعليا قيسا في حربهم فقال\n(إن السيوف غدوها ورواحها ... تركت هوازن مثل قرن الأعضب)\nوكان يونس ينشد هذا البيت غدوها ورواحها جعله ظرفا"},{"id":"tabaqat-shuara:653","bookId":"tabaqat-shuara","type":"section","seq":653,"chapter":"طبقات فحول الشعراء","title":"655- وقال الأخطل —","page":"ص0","text":"وقال الأخطل\n(لقد خبرت والأنباء تنمي ... لقد نجاك يا زفر الفرار)"},{"id":"tabaqat-shuara:654","bookId":"tabaqat-shuara","type":"section","seq":654,"chapter":"طبقات فحول الشعراء","title":"656- إلى أن قال —","page":"ص0","text":"إلى أن قال\n(ألا أبلغ الجحاف هل هو ثائر ... بقتلى أصيبت من سليم وعامر)\nفجمع لهم الجحاف السلمي وهو أحد بني فالج بن ذكوان وولد بالبصرة هو وزفر بن الحارث وكانا عثمانيين فلما ظهر علي بن أبي طالب على أهل البصرة خرجا إلى الشام فسادا أهلها\nوزفر من بني نفيل بن عمرو بن كلاب من ولد يزيد بن الصعق وهو سيد شريف وله يقول القطامي حين أسره فمن عليه\n(من البيض الوجوه بني نفيل ... أبت أخلاقهم إلا ارتفاعا)"},{"id":"tabaqat-shuara:655","bookId":"tabaqat-shuara","type":"section","seq":655,"chapter":"طبقات فحول الشعراء","title":"657- فجمع لهم الجحاف جمعا فأغار على البشر وهي منازل تغلب فأسرف في القتل فيهم فاستخذأ الأخطل فقا","page":"ص0","text":"فجمع لهم الجحاف جمعا فأغار على البشر وهي منازل تغلب فأسرف في القتل فيهم فاستخذأ الأخطل فقال\n(لقد أوقع الجحاف بالبشر وقعة ... إلى الله منها المشتكى والمعول)\n(فإلا تغيرها قريش بملكها ... يكن عن قريش مستماز ومزحل)\nفقال إلى أين لا أم لك قال إلى النار"},{"id":"tabaqat-shuara:656","bookId":"tabaqat-shuara","type":"section","seq":656,"chapter":"طبقات فحول الشعراء","title":"658- فوثب عليه جرير عند استخذائه فقال —","page":"ص0","text":"فوثب عليه جرير عند استخذائه فقال\n(فإنك والجحاف حين تحضه ... أردت بذاك المكث والورد أعجل)\n(سما لكم ليلا كأن نجومه ... قناديل فيهن الذبال المفتل)\n(فما ذر قرن الشمس حتى تبينوا ... كراديس يهديهن ورد محجل)\n(وما زالت القتلى تمج دماءها ... مع المد حتى ماء دجلة أشكل)\n(فإلا تعلق من قريش بذمة ... فليس على أسياف قيس معول)\n(بكى دوبل لا يرقىء الله دمعه ... ألا إنما يبكي من الذل دوبل)"},{"id":"tabaqat-shuara:657","bookId":"tabaqat-shuara","type":"section","seq":657,"chapter":"طبقات فحول الشعراء","title":"659- أنا أبو خليفة قال قال ابن سلام قال أبو الغراف قال الأخطل والله ما سمتني أمي دوبلا إلا يوما","page":"ص0","text":"أنا أبو خليفة قال قال ابن سلام قال أبو الغراف قال الأخطل والله ما سمتني أمي دوبلا إلا يوما واحدا فمن أين سقط إلى الخبيث"},{"id":"tabaqat-shuara:658","bookId":"tabaqat-shuara","type":"section","seq":658,"chapter":"طبقات فحول الشعراء","title":"660- وقال الجحاف يجيب الأخطل —","page":"ص0","text":"وقال الجحاف يجيب الأخطل\n(أبا مالك هل لمتني مذ حضضتني ... على القتلأم هل لامني لك لائم)"},{"id":"tabaqat-shuara:659","bookId":"tabaqat-shuara","type":"section","seq":659,"chapter":"طبقات فحول الشعراء","title":"661- ولقى الجحاف الأخطل فقال أبا مالك كيف رأيت — قال رأيت شيخا فاجرا","page":"ص0","text":"ولقى الجحاف الأخطل فقال أبا مالك كيف رأيت\nقال رأيت شيخا فاجرا"},{"id":"tabaqat-shuara:660","bookId":"tabaqat-shuara","type":"section","seq":660,"chapter":"طبقات فحول الشعراء","title":"662- وقال لي أبان الأعرج أدرك الجحاف الجاهلية فقلت له لم تقول ذاك قال لقوله —","page":"ص0","text":"وقال لي أبان الأعرج أدرك الجحاف الجاهلية فقلت له لم تقول ذاك قال لقوله\n(شهدن مع النبي مسومات ... حنينا وهي دامية الكلام)\n(نعرض للطعان إذا التقينا ... وجوها لا تعرض للطام)\nفقلت له إنما عني خيل قومه بني سليم"},{"id":"tabaqat-shuara:661","bookId":"tabaqat-shuara","type":"section","seq":661,"chapter":"طبقات فحول الشعراء","title":"663- وذكرت ذلك لعبد القاهر بن السري فقال جدي قيس ابن الهيثم أعطى حكيم بن أمية جارية ولدت له الج","page":"ص0","text":"وذكرت ذلك لعبد القاهر بن السري فقال جدي قيس ابن الهيثم أعطى حكيم بن أمية جارية ولدت له الجحاف في غرفة في دارنا لا أحسبه إلا قال رأيتها"},{"id":"tabaqat-shuara:662","bookId":"tabaqat-shuara","type":"section","seq":662,"chapter":"طبقات فحول الشعراء","title":"664- وروى سفيان بن عيينة عن عمرو بن دينار قال رأيت — الجحاف يطوف بالبيت في أنفه خزام وهو يقول الل","page":"ص0","text":"وروى سفيان بن عيينة عن عمرو بن دينار قال رأيت\nالجحاف يطوف بالبيت في أنفه خزام وهو يقول اللهم اغفر لي ولا أراك تفعل فقلت من هذا قالوا الجحاف وكان بعد ذلك يتأله ويظهر التوبة"},{"id":"tabaqat-shuara:663","bookId":"tabaqat-shuara","type":"section","seq":663,"chapter":"طبقات فحول الشعراء","title":"665- ومر عكرمة بن ربعي الفياض التيمي بأسماء بن خارجة حين قتلت تغلب عمير بن الحباب فقال عكرمة لأ","page":"ص0","text":"ومر عكرمة بن ربعي الفياض التيمي بأسماء بن خارجة حين قتلت تغلب عمير بن الحباب فقال عكرمة لأسماء أبا مالك قتلت تغلب عميرا في دارهم قال نعم ومقبلا غير مدبر قال نعم قال فلا بأس قال فلما أدبر عكرمة قال أسماء\n(يدي لك رهن من سليم بغارة ... تشيب لها أصداغ بكر بن وائل)\n(وأن يتركوا رهط الفدوكس عصبة ... أيامى يتامى عرضة للقبائل)"},{"id":"tabaqat-shuara:664","bookId":"tabaqat-shuara","type":"section","seq":664,"chapter":"طبقات فحول الشعراء","title":"666- قال ابن سلام قدم الأخطل الكوفة فأتى حوشب ابن رويم الشيباني فقال إني تحملت حمالتين لأحقن به","page":"ص0","text":"قال ابن سلام قدم الأخطل الكوفة فأتى حوشب ابن رويم الشيباني فقال إني تحملت حمالتين لأحقن بهما دماء قومي فنهره\nفأتى شداد بن البزيعة فسأله فاعتذر إليه فأتى عكرمة الفياض وكان كاتبا لبشر بن مروان فسأله وأخبره بمارد عليه الرجلان فقال أما إني لا أنهرك ولا أعتذر إليك ولكني أعطيك إحداهما عينا\nوالأخرى عرضا قال وحدث أمر بالكوفة فاجتمع له الناس فى المسجد فقيل له إن أردت أن تكافىء عكرمة يوما فاليوم فلبس جبة خز وركب فرسا وتقلد صليبا من ذهب وأتى باب المسجد ونزل عن فرسه فلما رآه حوشب وشداد نفسا عليه ذلك وقال له عكرمة يا أبا مالك فجاء فوقف وابتدأ ينشد قصيدته\n(لمن الديار بحائل فوعال ... )\nحتى انتهى إلى قوله\n(إن ابن ربعي كفاني سيبه ... ضغن العدو وعذرة المحتال)\n(أغليت حين توا كلتني وائل ... إن المكارم عند ذاك غوالي)\n(ولقد مننت على ربيعة كلها ... وكفيت كل موا كل خذال)\n(كابن البزيعة أو كآخر مثله ... أولى لك ابن مسيمة الأجمال)\n(إن اللئيم إذا سألت بهرته ... وترى الكريم يراح كالمختال)\n(وإذا عدلت به رجالا لم تجد ... فيض الفرات كراشح الأوشال)\nقال فجعل عكرمة يبتهج ويقول هذه والله أحب إلي من حمر النعم"},{"id":"tabaqat-shuara:665","bookId":"tabaqat-shuara","type":"section","seq":665,"chapter":"طبقات فحول الشعراء","title":"667- أنا أبو خليفة الفضل بن الحباب نا ابن سلام قال أخبرني أبو الغراف قال لما قال جرير —","page":"ج2 ص485","text":"أنا أبو خليفة الفضل بن الحباب نا ابن سلام قال أخبرني أبو الغراف قال لما قال جرير\n(إذا أخذت قيس عليك وخندف ... بأقطارها لم تدرمن أين تسرح)\nفلما أنشده الأخطل قال لامن أين سدو الله علي الدنيا حتى أنشد قوله\n(فمالك في نجد حصاة تعدها ... ومالك في غوري تهامة أبطح)\nفقال الأخطل لا أبالي والله أن لا يكون فتح والصليب لي القول ثم قال\n(ولكن لنا بر العراق وبحره ... وحيث يرى القرقور في الماء يسبح)"},{"id":"tabaqat-shuara:666","bookId":"tabaqat-shuara","type":"section","seq":666,"chapter":"طبقات فحول الشعراء","title":"668- أخبرني أبو خليفة عن محمد بن سلام قال قال أبو الخطاب حدثني نوح بن جرير قال قلت لأبي أنت أشع","page":"ص0","text":"أخبرني أبو خليفة عن محمد بن سلام قال قال أبو الخطاب حدثني نوح بن جرير قال قلت لأبي أنت أشعر أم الأخطل فنهرني وقال\nبئس ما قلت وما أنت وذاك لا أم لك فقلت وما أنا وغيره قال لقد أعنت عليه بكفر وكبر سن وما رأيته إلا خشيت أن يبتلعني"},{"id":"tabaqat-shuara:667","bookId":"tabaqat-shuara","type":"section","seq":667,"chapter":"طبقات فحول الشعراء","title":"669- وفي حديث أبي قيس العنبري عن عكرمة بن جرير — حين سأل اباه عن الشعراء فقال في الأخطل يجيد نعت","page":"ص0","text":"وفي حديث أبي قيس العنبري عن عكرمة بن جرير\nحين سأل اباه عن الشعراء فقال في الأخطل يجيد نعت الملوك ويصيب صفة الخمر"},{"id":"tabaqat-shuara:668","bookId":"tabaqat-shuara","type":"section","seq":668,"chapter":"طبقات فحول الشعراء","title":"670- أخبرني أبو خليفة قال أنبأنا محمد بن سلام قال حدثني شيخ من ضبيعة قال خرج جرير إلى الشأم فنز","page":"ص0","text":"أخبرني أبو خليفة قال أنبأنا محمد بن سلام قال حدثني شيخ من ضبيعة قال خرج جرير إلى الشأم فنزل منزلا لبني تغلب فخرج متلثما عليه ثياب سفره فلقيه رجل لا يعرفه فقال ممن الرجل قال من بني تميم\nقال أما سمعت ما قلت لغاوي بني تميم فأنشده مما قال لجرير فقال أما سمعت ما قال لك غاوي بني تميم فأنشده ثم عاد الأخطل وعاد جرير في نقضه حتى كثر ذلك بينهما\nفقال التغلبي من أنت لا حياك الله والله لكأنك جرير قال فأنا جرير قال وأنا الأخطل"},{"id":"tabaqat-shuara:669","bookId":"tabaqat-shuara","type":"section","seq":669,"chapter":"طبقات فحول الشعراء","title":"671- أنا أبو خليفة نا ابن سلام قال سمعت سلمة ابن عياش يقول تذاكرنا جرير والفرزدق والأخطل فقال ق","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال سمعت سلمة ابن عياش يقول تذاكرنا جرير والفرزدق والأخطل فقال قائل من مثل الأخطل إن في كل بيت له بيتين إذ يقول\n(ولقد علمت إذا العشار تروحت ... هدج الرئال تكبهن شمالا)\n(أنا نعجل بالعبيط لضيفنا ... قبل العيال ونقتل الأبطالا)\nولو شاء لقال\n(ولقد علمت إذا العشار ... تروحت هدج الرئال)\n(أنا نعجل بالعبيط ... لضيفنا قبل العيال)\nفكان هذا شعرا وكان على غير ذلك الوزن"},{"id":"tabaqat-shuara:670","bookId":"tabaqat-shuara","type":"section","seq":670,"chapter":"طبقات فحول الشعراء","title":"672- وقيل للأخطل عند الموت أتوصي أبا مالك فقال —","page":"ص0","text":"وقيل للأخطل عند الموت أتوصي أبا مالك فقال\n(أوصي الفرزدق عند الممات ... بأم جرير وأعيارها)\n(وزار القبور أبو مالك ... برغم العداة وأوتارها)"},{"id":"tabaqat-shuara:671","bookId":"tabaqat-shuara","type":"section","seq":671,"chapter":"طبقات فحول الشعراء","title":"673- أنا أبو خليفة نا ابن سلام قال فحدثني أبان بن عثمان قال لما بلغ الفرزدق قول الأخطل جعل يحن","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال فحدثني أبان بن عثمان قال لما بلغ الفرزدق قول الأخطل جعل يحن عليه ويقول سآخذ بوصية أخي"},{"id":"tabaqat-shuara:672","bookId":"tabaqat-shuara","type":"section","seq":672,"chapter":"طبقات فحول الشعراء","title":"674- أنا أبو خليفة نا ابن سلام قال حدثني محمد بن حفص بن عائشة التيمي قال قال إسحاق بن عبد الله","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني محمد بن حفص بن عائشة التيمي قال قال إسحاق بن عبد الله بن الحارث بن نوفل بن الحارث بن عبد المطلب خرجت مع أبي إلى الشام فخرجت إلى دمشق أنظر إلى بنائها فإذا كنيسة وإذا الأخطل في ناحيتها\nفلما راني أنكرني فسأل عني فأخبر بنسبي فقال يا فتى إن لك موضعا وشرفا وإن الأسقف قد حبسني فأنا أحب أن تأتيه تكلمه في إطلاقي\nقال قلت نعم فذهبت إلى الأسقف وانتسبت له فكلمته وطلبت إليه في تخليته فقال مهلا أعيذك بالله أن تكلم في مثل هذا فإن لك موضعا وشرفا وهذا ظالم يشتم اعراض الناس ويهجوهم فلم أزل به حتى قام معي فدخل عليه الكنيسة فجعل يوعده ويرفع عليه العصا والأخطل يتضرع إليه وهو يقول له أتعود أتعود فيقول لا قال إسحاق فقلت له يا أبا مالك تهابك الملوك وتكرمك الخلفاء وذكرك في الناس عظيم أمره وأنت تخضع\nلهذا هذا الخضوع وتستخذى له قال فجعل يقول لي إنه الدين إنه الدين"},{"id":"tabaqat-shuara:673","bookId":"tabaqat-shuara","type":"section","seq":673,"chapter":"طبقات فحول الشعراء","title":"675- أنا أبو خليفة نا محمد بن سلام حدثني محمد ابن الحجاج الأسيدي قال خرجت إلى الصائفة فنزلت منز","page":"ص0","text":"أنا أبو خليفة نا محمد بن سلام حدثني محمد ابن الحجاج الأسيدي قال خرجت إلى الصائفة فنزلت منزلا لبني تغلب فلم أجد به طعاما ولا شرابا ولا علفا لدابتي شرى ولا قرى ولم أجد ظلا\nفقلت لرجل منهم أما في داركم هذه مسجد استظل بفيئه قال ممن أنت قلت من بني تميم قال ما كنت أرى عمك جريرا إلا قد أخبرك حين قال\n(فينا المساجد والإمام ولا ترى ... في دار تغلب مسجدا معمورا)"},{"id":"tabaqat-shuara:674","bookId":"tabaqat-shuara","type":"section","seq":674,"chapter":"طبقات فحول الشعراء","title":"676- أخبرني أبو خليفة إجازة عن محمد بن سلام قال قال أبان بن عثمان حدثني سماك بن حرب عن ضوء بن ا","page":"ص0","text":"أخبرني أبو خليفة إجازة عن محمد بن سلام قال قال أبان بن عثمان حدثني سماك بن حرب عن ضوء بن اللجلاج\nقال دخلت حماما بالكوفة وفيه الأخطل قال فقال ممن الرجل قلت من بني ذهل\nقال اتروي للفرزدق شيئا قلت نعم قال ما أشعر خليلي على أنه ما أسرع مارجع في هبته قلت وما ذاك قال قوله\n(أبني غدانة إنني حررتكم ... فوهبتكم لعطية بن جعال)\n(لولا عطية لآجتدعت أنوفكم ... من بين ألأم آنف وسبال)\nوهبهم في الأول ورجع في الاخر فقلت لو أنكر الناس كلهم هذا ما كان ينبغي أن تنكره أنت قال كيف قلت هجوت زفر بن الحارث ثم خوفت الخليفة منه فقلت\n(بني أمية إنى ناصح لكم ... فلا يبيتن فيكم آمنا زفر)\n(مفترشا كافتراش الليث كلكله ... لوقعة كائن فيها له جزر)\nومدحت سماك بن مخرمة فقلت\n(قد كنت أحسبه قينا وأخبره ... فاليوم طير عن أثوابه الشرر)\nلو أردت المبالغة في هجائه ما زدت على هذا فقال لي الأخطل والله لولا أنك من قوم سبق لي منهم ما سبق لهجوتك هجاء يدخل معك قبرك ثم قال\n(ما كنت هاجي قوم بعد مدحهم ... ولا تكدر نعمى بعد ما تجب)\nاخرج عنى"},{"id":"tabaqat-shuara:675","bookId":"tabaqat-shuara","type":"section","seq":675,"chapter":"طبقات فحول الشعراء","title":"677- أنا أبو خليفة نا ابن سلام نا أبو الغراف قال انشد الأخطل قصيدته التي يقول —","page":"ج2 ص492","text":"أنا أبو خليفة نا ابن سلام نا أبو الغراف قال انشد الأخطل قصيدته التي يقول\n(وإذا افتقرت إلى الذخائر لم تجد ... ذخرا يكون كصالح الأعمال)\nفقال له هشام بن عبد الملك هنيئا لك أبا مالك الإسلام أو قال\nأسلمت قال مازلت مسلما يقول في ديني"},{"id":"tabaqat-shuara:676","bookId":"tabaqat-shuara","type":"section","seq":676,"chapter":"طبقات فحول الشعراء","title":"678- أخبرنا أبو خليفة إجازة عن محمد بن سلام قال قال لي معاوية بن ابي عمرو بن العلاء أي البيتين","page":"ص0","text":"أخبرنا أبو خليفة إجازة عن محمد بن سلام قال قال لي معاوية بن ابي عمرو بن العلاء أي البيتين عندك أجود قول جرير\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nأم قول الأخطل\n(شمس العداوة حتى يستقاد لهم ... وأعظم الناس أحلاما إذا قدروا)\nفقلت بيت جرير أحلى وأسير وبيت الأخطل أجزل وأرزن\nفقال صدقت وهكذا كانا في أنفسهما عند الخاصة والعامة"},{"id":"tabaqat-shuara:677","bookId":"tabaqat-shuara","type":"section","seq":677,"chapter":"طبقات فحول الشعراء","title":"679- وقال الأخطل فيها —","page":"ص0","text":"وقال الأخطل فيها\n(حشد على الحق عن قول الخناخرس ... وإن ألمت بهم مكروهة صبروا)\n(بني أمية إني ناصح لكم ... فلا يبيتن فيكم آمنا زفر)\n(فإن مشهده كفر وغائلة ... وما تغيب من أخلاقه دعر)\n(إن العداوة تلقاها وإن قدمت ... كالعر يكمن أحيانا وينتشر)\n(بني أمية قد ناضلت دونكم ... أبناء قوم هم آووا وهم نصروا)\n(وقيس عيلان حتى أقبلوا رقصا ... فبايعوك جهارا بعدما كفروا)\n(ضنجوا من الحرب إذ عضت غواربهم ... وقيس عيلان من أخلاقها الضجر)"},{"id":"tabaqat-shuara:678","bookId":"tabaqat-shuara","type":"section","seq":678,"chapter":"طبقات فحول الشعراء","title":"680- وقوله لجرير —","page":"ص0","text":"وقوله لجرير\n(قوم إذا استنبح الأضياف كلبهم ... قالوا لأمهم بولي على النار)"},{"id":"tabaqat-shuara:679","bookId":"tabaqat-shuara","type":"section","seq":679,"chapter":"طبقات فحول الشعراء","title":"681- وقوله له —","page":"ص0","text":"وقوله له\n(يا ابن المراغة إن عمي اللذا ... قتلا الملوك وفككا الأغلالا)\n(وأخوهم السفاح ظمأ خيله ... حتى وردن جبى الكلاب نهالا)\n(فانعق بضأنك يا جرير فإنما ... منتك نفسك في الخلاء ضلالا)\n(منتك نفسك أن تكون كدارم ... أو أن توازن حاجبا وعقالا)"},{"id":"tabaqat-shuara:680","bookId":"tabaqat-shuara","type":"section","seq":680,"chapter":"طبقات فحول الشعراء","title":"682- وقوله في قصيدته التي أوقع فيها بقيس قبيلة قبيلة وشبب بهند بنت أسماء —","page":"ج2 ص497","text":"وقوله في قصيدته التي أوقع فيها بقيس قبيلة قبيلة وشبب بهند بنت أسماء\n(ألا يا اسلمى يا هند بني بدر ... وإن كان حيانا عدى آخر الدهر)\n(وإن كنت قد أقصدتني إذرميتني ... بسهمك والرامي يصيب ولا يدري)"},{"id":"tabaqat-shuara:681","bookId":"tabaqat-shuara","type":"section","seq":681,"chapter":"طبقات فحول الشعراء","title":"683- وقال فيها —","page":"ج2 ص497","text":"وقال فيها\n(وقد سرني من قيس عيلان أنني ... رأيت بني العجلان سادوا بنى بدر)"},{"id":"tabaqat-shuara:682","bookId":"tabaqat-shuara","type":"section","seq":682,"chapter":"طبقات فحول الشعراء","title":"684- قال واستنشد سلم بن قتيبة وهو أمير على البصرة عيسى بن عمر وكان أحسن الناس نشيدا فأنشده كلمة","page":"ج2 ص497","text":"قال واستنشد سلم بن قتيبة وهو أمير على البصرة عيسى بن عمر وكان أحسن الناس نشيدا فأنشده كلمة الأخطل هذه\nفلما مضى فيها انتبه فأقصر\nفقال له سلم اضرب بها وجوهنا في ظلمة الليل أبا عمرو"},{"id":"tabaqat-shuara:683","bookId":"tabaqat-shuara","type":"section","seq":683,"chapter":"طبقات فحول الشعراء","title":"685- وقوله لجرير —","page":"ص0","text":"وقوله لجرير\n(تخست بيربوع لتدرك دارما ... لقد ضل من مناك تلك الأمانيا)\n(جريت شباب الدهر لم تستطعهم ... أفا لآن لما أصبح الدهر فانيا)\n(أتشتم قوما أثلوك بنهشل ... وتولاهم كنتم كعكل مواليا)"},{"id":"tabaqat-shuara:684","bookId":"tabaqat-shuara","type":"section","seq":684,"chapter":"طبقات فحول الشعراء","title":"686- وقوله لمصقلة بن هبيرة الشيباني —","page":"ص0","text":"وقوله لمصقلة بن هبيرة الشيباني\n(دع المغمر لاتسأل بمصرعه ... واسأل بمصقلة البكري ما فعلا)\n(إن ربيعة لن تنفك صالحة ... مادافع الله عن حوبائك الأجلا)"},{"id":"tabaqat-shuara:685","bookId":"tabaqat-shuara","type":"section","seq":685,"chapter":"طبقات فحول الشعراء","title":"687- وقوله لبشر بن مروان —","page":"ص0","text":"وقوله لبشر بن مروان\n(إذا أتيت أبا مروان تسأله ... وجدته حاضراه الجود والحسب)"},{"id":"tabaqat-shuara:686","bookId":"tabaqat-shuara","type":"section","seq":686,"chapter":"طبقات فحول الشعراء","title":"688- وقوله —","page":"ص0","text":"وقوله\n(فقلت اصبحونا لا أبا لأبيكم ... وما وضعوا الأثقال إلا ليفعلوا)"},{"id":"tabaqat-shuara:687","bookId":"tabaqat-shuara","type":"section","seq":687,"chapter":"طبقات فحول الشعراء","title":"689- وقال فيها لخالد بن عبد الله بن أسيد —","page":"ص0","text":"وقال فيها لخالد بن عبد الله بن أسيد\n(أبى عودك المعجوم إلا صلابة ... وكفاك إلا نائلا حين تسأل)"},{"id":"tabaqat-shuara:688","bookId":"tabaqat-shuara","type":"section","seq":688,"chapter":"طبقات فحول الشعراء","title":"690- وقوله —","page":"ص0","text":"وقوله\n(وشارب مربح بالكأس نادمني ... لا بالحصور ولا فيها بسوار)\n(عذراء لم يجتل الخطاب بهجتها ... حتى اجتلاها عبادى بدينار)"},{"id":"tabaqat-shuara:689","bookId":"tabaqat-shuara","type":"section","seq":689,"chapter":"طبقات فحول الشعراء","title":"691- وقوله ليزيد بن معاوية —","page":"ص0","text":"وقوله ليزيد بن معاوية\n(وترى عليه إذا العيون شزرنه ... سيما الحليم وهيبة الجبار)\nالراعي"},{"id":"tabaqat-shuara:690","bookId":"tabaqat-shuara","type":"section","seq":690,"chapter":"طبقات فحول الشعراء","title":"الراعي","page":"ص0","text":"عبيد بن حصين كان من رجال العرب ووجوه قومه وكان يقال له في شعره كأنه يعتسف الفلاة بغير دليل أي أنه لا يحتذى شعر شاعر ولا يعارضه وكان مع ذلك بذيا هجاء لعشيرته قال له جرير\n(وقرضك في هوازن شر قرض ... تهجيها وتمتدح الوطابا)"},{"id":"tabaqat-shuara:691","bookId":"tabaqat-shuara","type":"section","seq":691,"chapter":"طبقات فحول الشعراء","title":"693- قال ابن سلام وسمعت يونس وقيل له ما يعني الراعي بقوله —","page":"ص0","text":"قال ابن سلام وسمعت يونس وقيل له ما يعني الراعي بقوله\n(يبيت الحية النضناض منه ... مكان الحب يستمع السرارا)\nقال يونس الحب القرط وقال الشنف والنضناض الذي يخرج لسانه قال يونس يقولون حية ذكر ونعامة ذكر وشاة ذكر وبطة ذكر ولم أسمعه منه"},{"id":"tabaqat-shuara:692","bookId":"tabaqat-shuara","type":"section","seq":692,"chapter":"طبقات فحول الشعراء","title":"694- وكان بعد هجاء جرير له مغلبا قال رجل من قومه علامة وراوية فصيح كان فحل مضر حتى ضغمه الليث ي","page":"ص0","text":"وكان بعد هجاء جرير له مغلبا قال رجل من قومه علامة وراوية فصيح كان فحل مضر حتى ضغمه الليث يعني جريرا"},{"id":"tabaqat-shuara:693","bookId":"tabaqat-shuara","type":"section","seq":693,"chapter":"طبقات فحول الشعراء","title":"695- ولقد هجا الراعي فأوجع قال لابن الرقاع العاملي —","page":"ص0","text":"ولقد هجا الراعي فأوجع قال لابن الرقاع العاملي\n(لو كنت من أحد يهجى هجوتكم ... يا ابن الرقاع ولكن لست من أحد)\n(تأبى قضاعة أن تعرف لكم نسبا ... وابنا نزار فأنتم بيضة البلد)"},{"id":"tabaqat-shuara:694","bookId":"tabaqat-shuara","type":"section","seq":694,"chapter":"طبقات فحول الشعراء","title":"696- أخبرنا أبو خليفة قال أخبرنا محمد بن سلام قال قال أبو الغراف جاور راعي الإبل بني سعد بن زيد","page":"ص0","text":"أخبرنا أبو خليفة قال أخبرنا محمد بن سلام قال قال أبو الغراف جاور راعي الإبل بني سعد بن زيد مناة بن تميم فنسب بامرأة منهم من بني عبد شمس ثم أحد بني وابش فقال\n(بني وابش إنا هوينا جواركم ... وما جمعتنا نية قبلها معا)\n(خليطين من حيين شتى تجاورا ... جميعا وكانا بالتفرق أضيعا)\n(أرى أهل ليلى لا يبالى أميرهم ... على حالة المحزون أن يتصدعا)"},{"id":"tabaqat-shuara:695","bookId":"tabaqat-shuara","type":"section","seq":695,"chapter":"طبقات فحول الشعراء","title":"697- وقال فيها أيضا —","page":"ص0","text":"وقال فيها أيضا\n(تذكر هذا القلب هند بني سعد ... سفاها وجهلا ما تذكر من هند)\n(تذكر عهدا كان بيني ووبينها ... قديما وهل أبقت لك الحرب من عهد)"},{"id":"tabaqat-shuara:696","bookId":"tabaqat-shuara","type":"section","seq":696,"chapter":"طبقات فحول الشعراء","title":"698- قال ابن سلام فلما بلغهم شعره أزعجوه وأصابوه بأذى فخرج عنهم وقال فيهم —","page":"ص0","text":"قال ابن سلام فلما بلغهم شعره أزعجوه وأصابوه بأذى فخرج عنهم وقال فيهم\n(أرى إبلي تكالأ راعياها ... مخافة جارها الدنس الذميم)\n(وقد جاورتهم فرأيت سعدا ... شعاع الأمر عازبة الحلوم)\n(فأمي أرض قومكإن سعدا ... تحملت المخازي عن تميم)"},{"id":"tabaqat-shuara:697","bookId":"tabaqat-shuara","type":"section","seq":697,"chapter":"طبقات فحول الشعراء","title":"699- أنا أبو خليفة نا ابن سلام قال وحدثني أبو يحيى الضبي قال وفد الراعي إلى عبد الملك يشكو بعض","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال وحدثني أبو يحيى الضبي قال وفد الراعي إلى عبد الملك يشكو بعض عماله وكانت قيس زبيرية وكان عبد الملك ثقيل النفس عليه فأتاه وقد قال في مديحه بشر بن مروان في كلمة يعتذر من تزبر قومه\n(فلو كنت من أصحاب مروان إذدعا ... بعذراء يممت الهدى إذ بدا ليا)\n(على بردى إذ قال إن كان عهدهم ... أضيع فكونوا لا علي ولا ليا)\n(ولكنني غيبت عنهم فلم يطع ... رشيد ولم تعص العشيرة غاويا)\nقال فأنشدتها جابر بن جندل أبا عبد الله الفزاري فقال هو الذي يخطب الدراهم حتى أتت قومه"},{"id":"tabaqat-shuara:698","bookId":"tabaqat-shuara","type":"section","seq":698,"chapter":"طبقات فحول الشعراء","title":"700- وقال لعبد الملك —","page":"ج2 ص507","text":"وقال لعبد الملك\n(إني حلفت على يمين برة ... لا أكذب اليوم الخليفة قيلا)\n(ما إن أتيت أبا خبيب وافدا ... يوما أردت لبيعتي تبديلا)\n(ولا أتيت نجيدة بن عويمر ... أبغى الهدى فيزيدني تضليلا)\n(أزمان قومي والجماعة كالذي ... لزم الرحالة أن تميل مميلا)\n(أخذوا العريف فشققوا حيزومه ... بالأصبحية قائما مغلولا)\n(كهداهد كسر الرماة جناحه ... يدعو بقارعة الشريف هديلا)\n(فارفع مظالم عيلت أبناءنا ... عنا وأنقذ شلونا المأكولا)\n(ولئن بقيت لأدعون لطية ... تدع الفرائض بالشريف قليلا)\nفقال له عبد الملك وأين من الله والسلطان لا أم لك فقال\nيا أمير المؤمنين من عامل إلى عامل ومصدق إلى مصدق فلم يحظ ولم يحل منه بشىء"},{"id":"tabaqat-shuara:699","bookId":"tabaqat-shuara","type":"section","seq":699,"chapter":"طبقات فحول الشعراء","title":"701- فوفد إليه من قابل فقال في كلمة أخرى —","page":"ج2 ص510","text":"فوفد إليه من قابل فقال في كلمة أخرى\n(أما الفقير الذي كانت حلوبته ... وفق العيال فلم يترك له سبد)\n(واختل ذو المال والمثرون قد بقيت ... على التلاتل من أموالهم عقد)\n(فإن رفعت بهم رأسا نعشتهم ... وإن لقوا مثلها في قابل فسدوا)\nفقال له عبد الملك أنت العام أعقل منك عام أول"},{"id":"tabaqat-shuara:700","bookId":"tabaqat-shuara","type":"section","seq":700,"chapter":"طبقات فحول الشعراء","title":"702- أنا أبو خليفة نا ابن سلام قال حدثني أبو الورد الكلابي قال اجتمع الراعي والأخطل عند بشر بن","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال حدثني أبو الورد الكلابي قال اجتمع الراعي والأخطل عند بشر بن مروان فقال لهما أيكما أشعر فقال الراعي أما الشعر فالأمير أعلم به ولكن والله ما تمخضت تغلبية عن مثلك وأم بشر قطية بنت بشر بن عامر بن مالك إبي براء ملاعب الأسنة وقال له الراعي\n(نزلت من البطحاء في آل جعفر ... ومن عبد شمس منزلا متعاليا)"},{"id":"tabaqat-shuara:701","bookId":"tabaqat-shuara","type":"section","seq":701,"chapter":"طبقات فحول الشعراء","title":"703- وقال الأخطل في حرب تغلب وقيس في التي هجا فيها قبائل قيس —","page":"ص0","text":"وقال الأخطل في حرب تغلب وقيس في التي هجا فيها قبائل قيس\n(وقد سرني من قيس عيلان أنني ... رأيت بني العجلان سادوا بني بدر)\nوقد غبر العجلان حينا إذا بكي ... على الزاد ألقته الوليدة في الكسر)\n(فيصبح كالخفاش يدلك عينه ... فقبح من وجه لئيم ومن حجر)"},{"id":"tabaqat-shuara:702","bookId":"tabaqat-shuara","type":"section","seq":702,"chapter":"طبقات فحول الشعراء","title":"704- فعارضه الراعى فقال —","page":"ص0","text":"فعارضه الراعى فقال\n(برهط ابن كلثوم بدأنا فأصبحوا ... لتغلب أذنابا وكانوا نواصيا)\n(وغارتنا أودت ببهراء إنها ... تصيب الصريح مرة والمواليا)"},{"id":"tabaqat-shuara:703","bookId":"tabaqat-shuara","type":"section","seq":703,"chapter":"طبقات فحول الشعراء","title":"705- وقال وكانت امرأة من العرب من بني نمير حسانة وكانت تظعن مع الراعي إذا ظعن وتحل معه إذا حل ف","page":"ص0","text":"وقال وكانت امرأة من العرب من بني نمير حسانة وكانت تظعن مع الراعي إذا ظعن وتحل معه إذا حل فغار رجل منهم يقال إنه من قيس كبة فقطع بطانها لما رحلت فسقط هودجها وعنتت فقال الراعي\n(ولم أر به معقورا به وسط معشر ... أقل انتصارا باللسان وباليد)\n(سوى نظر ساج بعين مريضة ... جرت عبرة منها ففاضت بإثمد)\n(بكت عين من أذرى دموعك إنما ... وشى بك واش من بنى أخت مسرد)\n(فلو كنت معذورا بنصرك طيرت ... صقورى غربان البعير المقيد)"},{"id":"tabaqat-shuara:704","bookId":"tabaqat-shuara","type":"section","seq":704,"chapter":"طبقات فحول الشعراء","title":"706- قال وكان أوس بن مغراء السعدي القريعي يهاجي النابغة الجعدي وراعي الإبل وابن السمط من بني عا","page":"ص0","text":"قال وكان أوس بن مغراء السعدي القريعي يهاجي النابغة الجعدي وراعي الإبل وابن السمط من بني عامر بن صعصعة فقال الراعي لأوس بن مغراء\n(وأوس بن مغراء الهجين يسبني ... وأوس بن مغراء الهجين أعاقبه)\n(تمنى قريش أن تكون أخاهم ... لينفعك القول الذي أنت كاذبه)\n(قريش الذي لا تستطيع كلامه ... ويكسر عند الباب أنفك حاجبه)"},{"id":"tabaqat-shuara:705","bookId":"tabaqat-shuara","type":"section","seq":705,"chapter":"طبقات فحول الشعراء","title":"707- فسالم أوس بن مغراء الجعدي وابن السمط فقال الراعي في صلحهم —","page":"ص0","text":"فسالم أوس بن مغراء الجعدي وابن السمط فقال الراعي في صلحهم\n(فإن كنت يا ابن السمط سالمت دوننا ... وقيس أبو ليلى فلما نسالم)\n(وإن كنتما أعطيتما القوم موثقا ... فلا تغدرا واستسمعا للمراجم)\n(فإني زعيم أن أقول قصيدة ... محبرة كالنقب بين المخارم)\n(خفيفة أعجاز المطي ثقيلة ... على قرنها نزالة بالمواسم)"},{"id":"tabaqat-shuara:706","bookId":"tabaqat-shuara","type":"section","seq":706,"chapter":"طبقات فحول الشعراء","title":"708- أنا أبو خليفة نا ابن سلام حدثني جابر بن جندل — الفزاري بقصة وفي إثرها قال وضاف الراعي رجل من","page":"ص0","text":"أنا أبو خليفة نا ابن سلام حدثني جابر بن جندل\nالفزاري بقصة وفي إثرها قال وضاف الراعي رجل من بني كلاب في سنة حصاء ولم يحضره قرى وكان الكلابي على ناب له فأمر الراعي ابن أخ له يقال له حبتر فنحرها فأطعمها إياه ولا يعلم الكلابي فعيره بنو عم له من قومه كانوا يهاجونه الحلال وخنزر\nفزعم أنه أخلفها له وقال الراعي\n(عجبت من السارين والريح قرة ... إلى ضوء ناربين فردة والرحا)\n(إلى ضوء نار يشتوى القد أهلها ... وقد يكرم الأضياف والقد يشتوى)\n(فلما أتونا فاشتكينا إليهم ... بكوا وكلا الحيين مما به بكى)\n(بكى معوز من أن يلام وطارق ... يشد من الجوع الإزار على الحشا)\n(فطأطأت طرفي هل أرى من سمينة ... تدارك فيهابى عامين والصوى)\n(فأبصرتها كوماء ذات عريكة ... هجانا من اللاتي تمتعن بالصوى)\n(فأومضت إيماضا خفيا لحبتر ... ولله عينا حبتر أيما فتى)\n(فقلت له ألصق بأيبس ساقها ... فإن بجبر العرقوب لا يرقأ النسا)\n(فقام إليها حبتر بسلاحه ... مضى غير منكود ومتصله انتضى)\n(كأني وقد أشبعته من سنامها ... كشفت غطاء عن فؤادي فانجلى)\n(فبتنا وباتت قدرنا ذات هزة ... لنا قبل مافيها شواء ومصطلى)\n(وأصبح راعينا بريمة عندنا ... بستين أنقتها الأسنة والخلا)\n(فقلت لرب الناب خذها فتية ... وناب عليها مثل نابك في الحيا)\nسقط في تسلسل الأرقام بين الطبقة الأولى وبين الطبقة الثانية الأرقام من 523 - 532"},{"id":"tabaqat-shuara:707","bookId":"tabaqat-shuara","type":"section","seq":707,"chapter":"طبقات فحول الشعراء","title":"709- البعيث واسمه خداش بن بشر بن خالد بن بيبة بن قرط ابن سفيان بن مجاشع بن دارم وسمي البعيث بقو","page":"ج2 ص522","text":"البعيث واسمه خداش بن بشر بن خالد بن بيبة بن قرط ابن سفيان بن مجاشع بن دارم وسمي البعيث بقوله\n(تبعث مني ما تبعث بعد ما ... أمرت حبال كل مرتها شزرا)\nوهو أول شعر قاله"},{"id":"tabaqat-shuara:708","bookId":"tabaqat-shuara","type":"section","seq":708,"chapter":"طبقات فحول الشعراء","title":"710- والقطامي واسمه عمرو بن شييم بن عمرو أحد بني بكر بن حبيب بن عمرو بن غنم بن تغلب","page":"ص0","text":"والقطامي واسمه عمرو بن شييم بن عمرو أحد بني بكر بن حبيب بن عمرو بن غنم بن تغلب"},{"id":"tabaqat-shuara:709","bookId":"tabaqat-shuara","type":"section","seq":709,"chapter":"طبقات فحول الشعراء","title":"711- وكثير بن عبد الرحمن الخزاعي وهو ابن أبي جمعة وكنيته أبو صخر وهو عند أهل الحجاز أشعر من كل","page":"ص0","text":"وكثير بن عبد الرحمن الخزاعي وهو ابن أبي جمعة وكنيته أبو صخر وهو عند أهل الحجاز أشعر من كل من قدمنا عليه"},{"id":"tabaqat-shuara:710","bookId":"tabaqat-shuara","type":"section","seq":710,"chapter":"طبقات فحول الشعراء","title":"712- وذو الرمة واسمه غيلان وهو الذي يقول —","page":"ص0","text":"وذو الرمة واسمه غيلان وهو الذي يقول\n(أنا أبو الحارث واسمي غيلان ... )\nابن عقبة بن بهيش بن مسعود بن حارثة بن عمرو بن ربيعة بن ساعدة بن كعب بن عوف بن ثعلبة بن ربيعة بن ملكان بن عدي بن\nعبد مناة بن أد وهم عدي التيم وتيم عدي والتيم من الرباب"},{"id":"tabaqat-shuara:711","bookId":"tabaqat-shuara","type":"section","seq":711,"chapter":"طبقات فحول الشعراء","title":"713- وكان البعيث شاعرا فاخر الكلام حر اللفظ وقد غلبه جرير وأخمله وكان قد قاوم جريرا في قصائده ث","page":"ص0","text":"وكان البعيث شاعرا فاخر الكلام حر اللفظ وقد غلبه جرير وأخمله وكان قد قاوم جريرا في قصائده ثم ضج إلى الفرزدق واستغاثه"},{"id":"tabaqat-shuara:712","bookId":"tabaqat-shuara","type":"section","seq":712,"chapter":"طبقات فحول الشعراء","title":"714- وكان القطامي شاعرا فحلا رقيق الحواشي حلو الشعر والأخطل أبعد منه ذكرا وأمتن شعرا","page":"ص0","text":"وكان القطامي شاعرا فحلا رقيق الحواشي حلو الشعر والأخطل أبعد منه ذكرا وأمتن شعرا"},{"id":"tabaqat-shuara:713","bookId":"tabaqat-shuara","type":"section","seq":713,"chapter":"طبقات فحول الشعراء","title":"715- وكان زفر بن الحارث أسره في حرب بينهم وبين تغلب فمن عليه وأعطاه مئة من الإبل ورد عليه ماله","page":"ص0","text":"وكان زفر بن الحارث أسره في حرب بينهم وبين تغلب فمن عليه وأعطاه مئة من الإبل ورد عليه ماله فقال القطامي في كلمة له\n(من مبلغ زفر القيسي مدحته ... عن القطامي قولا غير إفناد)\n(إن وإن كان قومي ليس بينهم ... وبين قومك إلا ضربة الهادي)\n(مثن عليك بما أسلفت من حسن ... وقد تعرض مني مقتل بادي)\n(فلن أثيبك بالنعماء مشتمة ... ولن أبدل إحسانا بإفساد)\n(فإن هجوتك ما تمت محافظتي ... وإن مدحت لقد أحسنت إصفادي)\n(إذ يعتريك رجال يسألون دمي ... ولو تطيعهم أبكيت عوادي)\n(وإذ يقولون أرضيت العداة بنا ... لا بل قدحت بزند غير صلاد)\n(ولا كردك مالي بعد ما كربت ... تبدي الشماتة أعدائي وحسادي)\n(فإن قدرت على يوم جزيت به ... والله يجعل أقواما بمرصاد)\nقال ابن سلام فلما بلغ زفر قوله قال لا قدرت على ذلك اليوم"},{"id":"tabaqat-shuara:714","bookId":"tabaqat-shuara","type":"section","seq":714,"chapter":"طبقات فحول الشعراء","title":"716- وقال القطامي يمدحه في أخرى —","page":"ج2 ص536","text":"وقال القطامي يمدحه في أخرى\n(ومن يكن استلام إلى ثوى ... فقد أحسنت يازفر المتاعا)\n(أكفر بعد دفع الموت عني ... وبعد عطائك المئة الرتاعا)\n(ولم أر منعمين أقل منا ... وأكرم عندما اصطنعوا اصطناعا)\n(من البيض الوجوه بني نفيل ... أبت أخلاقهم إلا اتساعا)\n(بني القرم الذي علمت معد ... تفضل فوقهم حسبا وباعا)"},{"id":"tabaqat-shuara:715","bookId":"tabaqat-shuara","type":"section","seq":715,"chapter":"طبقات فحول الشعراء","title":"717- والقطامي الذي يقول —","page":"ص0","text":"والقطامي الذي يقول\n(ألم يحزنك أن حبال قيس ... وتغلب قد تباينتا انقطاعا)\n(أمور لو تدبرها حليم ... إذا لنهى وهيب ما استطاعا)\n(ولكن الأديم إذا تفرى ... بلى وتعينا غلب الصناعا)\n(ومعصية الشفيق عليك مما ... يزيدك مرة منه استماعا)\n(وخير الرأي ما استقبلت منه ... وليس بأن تتبعه اتباعا)"},{"id":"tabaqat-shuara:716","bookId":"tabaqat-shuara","type":"section","seq":716,"chapter":"طبقات فحول الشعراء","title":"718- وقال يمدح أسماء بن خارجة بن حصن بن حذيفة بن بدر الفزاري —","page":"ص0","text":"وقال يمدح أسماء بن خارجة بن حصن بن حذيفة بن بدر الفزاري\n(إذا مات ابن خارجة بن حصن ... فلامطرت على الأرض السماء)\n(ولا رجع البريد بغنم خير ... ولا حملت على الطهر النساء)"},{"id":"tabaqat-shuara:717","bookId":"tabaqat-shuara","type":"section","seq":717,"chapter":"طبقات فحول الشعراء","title":"719- وقال فيه أيضا —","page":"ص0","text":"وقال فيه أيضا\n(وعليك أسماء بن خارجة الذي ... على الفعال ورفع البنيانا)\n(فستعلمين أصادر وراده ... عنه وأي فتى فتى غطفانا)"},{"id":"tabaqat-shuara:718","bookId":"tabaqat-shuara","type":"section","seq":718,"chapter":"طبقات فحول الشعراء","title":"720- وكان كثير شاعر أهل الحجاز وإنهم ليقدمونه على بعض من قدمنا عليه وهو شاعر فحل ولكنه منقوص حظ","page":"ص0","text":"وكان كثير شاعر أهل الحجاز وإنهم ليقدمونه على بعض من قدمنا عليه وهو شاعر فحل ولكنه منقوص حظه بالعراق"},{"id":"tabaqat-shuara:719","bookId":"tabaqat-shuara","type":"section","seq":719,"chapter":"طبقات فحول الشعراء","title":"721- وسمعت يونس النحوي يقول كان ابن أبي إسحاق يقول كان كثير أشعر أهل الإسلام","page":"ص0","text":"وسمعت يونس النحوي يقول كان ابن أبي إسحاق يقول كان كثير أشعر أهل الإسلام"},{"id":"tabaqat-shuara:720","bookId":"tabaqat-shuara","type":"section","seq":720,"chapter":"طبقات فحول الشعراء","title":"722- قال ابن سلام ورأيت ابن أبي حفصة يعجبه مذهبه في المديح جدا يقول كان يستقضي المديح","page":"ص0","text":"قال ابن سلام ورأيت ابن أبي حفصة يعجبه مذهبه في المديح جدا يقول كان يستقضي المديح"},{"id":"tabaqat-shuara:721","bookId":"tabaqat-shuara","type":"section","seq":721,"chapter":"طبقات فحول الشعراء","title":"723- وكان فيه مع جودة شعره خطل وعجب وكانت له منزلة عند قريش وقدر","page":"ص0","text":"وكان فيه مع جودة شعره خطل وعجب وكانت له منزلة عند قريش وقدر"},{"id":"tabaqat-shuara:722","bookId":"tabaqat-shuara","type":"section","seq":722,"chapter":"طبقات فحول الشعراء","title":"724- قال وقدم على عبد الملك بن مروان الشام فأنشده والأخطل عنده فقال عبد الملك كيف ترى يا أبا ما","page":"ص0","text":"قال وقدم على عبد الملك بن مروان الشام فأنشده والأخطل عنده فقال عبد الملك كيف ترى يا أبا مالك قال أرى شعرا حجازيا مقرورا لو ضغطه برد الشام لاضمحل"},{"id":"tabaqat-shuara:723","bookId":"tabaqat-shuara","type":"section","seq":723,"chapter":"طبقات فحول الشعراء","title":"725- قال وأخبرني أبان بن عثمان البجلي قال دخل كثير على عبد الملك فأنشده مدحته وفيها —","page":"ص0","text":"قال وأخبرني أبان بن عثمان البجلي قال دخل كثير على عبد الملك فأنشده مدحته وفيها\n(على ابن أبي العاصي دلاص حصينة ... أجاد المسدي سردها وأذالها)\nفقال له عبد الملك أفلا قلت كما قال الأعشى لقيس ابن معدي كرب\n(وإذا تجيء كتيبة ملمومة ... شهباء يخشى الذائدون نهالها)\n(كنت المقدم غير لابس جنة ... بالسيف تضرب معلما أبطالها)\nفقال يا أمير المؤمنين وصفه بالخرق ووصفتك بالحزم"},{"id":"tabaqat-shuara:724","bookId":"tabaqat-shuara","type":"section","seq":724,"chapter":"طبقات فحول الشعراء","title":"726- أنا أبو خليفة نا ابن سلام قال أخبرني عثمان بن عبد الرحمن قال أنشد كثير عبد الملك بن مروان","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال أخبرني عثمان بن عبد الرحمن قال أنشد كثير عبد الملك بن مروان حين أزمع بالمسير إلى مصعب\n(إذا ما أراد الغزو لم تثن همه ... حصان عليها نظم در يزينها)\n(نهته فلما لم تر النهى عاقه ... بكت وبكى مما شجاها قطينها)\nفقال عبد الملك ولله لكأنه شهد عاتكة بنت يزيد بن معاوية وهي امرأته أم يزيد بن عبد الملك"},{"id":"tabaqat-shuara:725","bookId":"tabaqat-shuara","type":"section","seq":725,"chapter":"طبقات فحول الشعراء","title":"727- وقدم كثير على يزيد بن عبد الملك وقد مدحه بقصائد جياد مشهورة فأعجب بهن يزيد وقال له احتكم ق","page":"ص0","text":"وقدم كثير على يزيد بن عبد الملك وقد مدحه بقصائد جياد مشهورة فأعجب بهن يزيد وقال له احتكم قال وقد جعلت ذلك إلي قال نعم قال مئة الف قال ويحك مئة ألف قال على جود أمير المؤمنين أبقى أم على بيت المال قال مابي استكثارها ولكني أكره أن يقول الناس أعطى شاعرا مئة ألف ولكن فيها عروض قال نعم يا أمير المؤمنين"},{"id":"tabaqat-shuara:726","bookId":"tabaqat-shuara","type":"section","seq":726,"chapter":"طبقات فحول الشعراء","title":"728- فكان يحضر سمر يزيد ويدخل عليه فقال له ليلة — يا أمير المؤمنين ما يعني الشماخ بقوله —","page":"ص0","text":"فكان يحضر سمر يزيد ويدخل عليه فقال له ليلة\nيا أمير المؤمنين ما يعني الشماخ بقوله\n(إذا عرقت مغابنها وجادت ... بدرتها قرى جحن قتين)\nقال فسكت عنه يزيد فقال بصبصن إذ حدين ثم أعاد فسكت عنه يزيد فقال بصبصن إذ حدين فقال له يزيد وما على أمير المؤمنين أن لا يعرف هذا هو القراد أشبه الدواب بك وكان كثير قصيرا متقارب الخلق فحجب عن يزيد فلم يصل إليه فكلم مسلمة بن عبد الملك يزيد فقال يا أمير المؤمنين مدحك قال بكم مدحنا قال بسبع قصائد قال فله سبعمئة دينار والله لا أزيده عليها"},{"id":"tabaqat-shuara:727","bookId":"tabaqat-shuara","type":"section","seq":727,"chapter":"طبقات فحول الشعراء","title":"729- أنا أبو خليفة نا ابن سلام نا أو حدثني ابن جعدبة وأبو اليقظان عن جويرية بن أسماء قال مات كث","page":"ص0","text":"أنا أبو خليفة نا ابن سلام نا أو حدثني ابن جعدبة وأبو اليقظان عن جويرية بن أسماء قال مات كثير وعكرمة\nمولى ابن عباس في يوم واحد فأجغلت قريش في جنازة كثير ولم يوجد لعكرمة من يحمله"},{"id":"tabaqat-shuara:728","bookId":"tabaqat-shuara","type":"section","seq":728,"chapter":"طبقات فحول الشعراء","title":"730- وكان لكثير في التشبيب نصيب وافر وجميل مقدم عليه وعلى أصحاب النسيب جميعا في النسيب وله في ف","page":"ص0","text":"وكان لكثير في التشبيب نصيب وافر وجميل مقدم عليه وعلى أصحاب النسيب جميعا في النسيب وله في فنون الشعر ما ليس لجميل وكان جميل صادق الصبابة وكان كثير يتقول ولم يكن عاشقا وكان راوية جميل"},{"id":"tabaqat-shuara:729","bookId":"tabaqat-shuara","type":"section","seq":729,"chapter":"طبقات فحول الشعراء","title":"731- وهو القائل —","page":"ص0","text":"وهو القائل\n(ألمم بعزة إن الركب منطلق ... وإن نأتك ولم يلمم بها خرق)\n(قامت تراءى لنا والعين ساجية ... كأن إنسانها في لجة غرق)\n(ثم استدار على أرجاء مقلتها ... مبادرا خلسات الطرف يستبق)\n(كأنه حين مار المأقيان به ... در تحلل من أسلاكه نسق)"},{"id":"tabaqat-shuara:730","bookId":"tabaqat-shuara","type":"section","seq":730,"chapter":"طبقات فحول الشعراء","title":"732- قال وسمعت الناس يستحسنون من قوله —","page":"ص0","text":"قال وسمعت الناس يستحسنون من قوله\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nقال ابن سلام وسمعت من يطعن عليه يقول ما له يريد ينسى ذكرها"},{"id":"tabaqat-shuara:731","bookId":"tabaqat-shuara","type":"section","seq":731,"chapter":"طبقات فحول الشعراء","title":"733- تعلق الناس على كثير بقوله —","page":"ص0","text":"تعلق الناس على كثير بقوله\n(فإن أمير المؤمنين هو الذي ... غزا كامنات الصدر مني فنالها)\nوقوله\n(ترى ابن أبي العاصي وقد صف دونه ... ثمانون ألفا قد توافت كمولها)\n(يقلب عينى حية بمحارة ... إذا أمكنته شدة لا يقيلها)\nقال ابن سلام فقلت لابن أبي حفصة من جودة مديحه هذا جعل دونه ثمانين ألفا وجعله يقلب عيني حية بمحارة وجعل أمير المؤمنين غزا كامنات صدره فقال هذا النابغة قال لملك العرب\n(أحكم كحكم فتاة الحي إذ نظرت ... إلى حمام شراع وارد الثمد)\nأمره أن يحكم كحكم فتاة"},{"id":"tabaqat-shuara:732","bookId":"tabaqat-shuara","type":"section","seq":732,"chapter":"طبقات فحول الشعراء","title":"734- وقال كثير لعبد العزيز بن مروان —","page":"ص0","text":"وقال كثير لعبد العزيز بن مروان\n(وما زالت رقاك تسل ضغني ... وتخرج من مضابئها ضبابي)\n(ويرقيني لك الحاوون حتى ... أجابك حية تحت الحجاب)"},{"id":"tabaqat-shuara:733","bookId":"tabaqat-shuara","type":"section","seq":733,"chapter":"طبقات فحول الشعراء","title":"735- وحدثني أبو خليفة عن محمد بن سلام قال كان علماؤنا يقولون أحسن الجاهلية تشبيها امرؤ القيس وأ","page":"ص0","text":"وحدثني أبو خليفة عن محمد بن سلام قال كان علماؤنا يقولون أحسن الجاهلية تشبيها امرؤ القيس وأحسن أهل الإسلام تشبيها ذو الرمة"},{"id":"tabaqat-shuara:734","bookId":"tabaqat-shuara","type":"section","seq":734,"chapter":"طبقات فحول الشعراء","title":"736- وقوله —","page":"ص0","text":"وقوله\n(بها العين والآرام فوضى كأنها ... ذبال تذكى أو نجوم طوالع)"},{"id":"tabaqat-shuara:735","bookId":"tabaqat-shuara","type":"section","seq":735,"chapter":"طبقات فحول الشعراء","title":"737- وقوله —","page":"ص0","text":"وقوله\n(كأن يدي حربائها متشمسا ... يدا مجرم يستغفر الله تائب)"},{"id":"tabaqat-shuara:736","bookId":"tabaqat-shuara","type":"section","seq":736,"chapter":"طبقات فحول الشعراء","title":"738- وقوله —","page":"ص0","text":"وقوله\n(فنلنا صدورا من حديث كأنه ... جنى النحل ممزوجا بماء الوقائع)"},{"id":"tabaqat-shuara:737","bookId":"tabaqat-shuara","type":"section","seq":737,"chapter":"طبقات فحول الشعراء","title":"739- أخبرني أبو خليفة عن محمد بن سلام قال أخبرنا أبو البيداء الرياحي قال قال جرير قاتل الله ذا","page":"ص0","text":"أخبرني أبو خليفة عن محمد بن سلام قال أخبرنا أبو البيداء الرياحي قال قال جرير قاتل الله ذا الرمة حيث يقول\n(ومنتزع من بين نسعيه جرة ... نشيج الشجا جاءت إلى ضرسه نزرا)\nأما والله لو قال من بين جنبيه لما كان عليه من سبيل"},{"id":"tabaqat-shuara:738","bookId":"tabaqat-shuara","type":"section","seq":738,"chapter":"طبقات فحول الشعراء","title":"740- حدثنا أبو خليفة عن ابن سلام قال كان ذو الرمة — من جرير والفرزدق بمنزلة قتادة من الحسن وابن س","page":"ص0","text":"حدثنا أبو خليفة عن ابن سلام قال كان ذو الرمة\nمن جرير والفرزدق بمنزلة قتادة من الحسن وابن سيرين وكان يروي عنهما وعن الصحابة وكذلك ذو الرمة هو دونهما ويساويهما في بعض شعره"},{"id":"tabaqat-shuara:739","bookId":"tabaqat-shuara","type":"section","seq":739,"chapter":"طبقات فحول الشعراء","title":"741- قال ويقال إن ذا الرمة راوية راعي الإبل ولم يكن له حظ في الهجاء وكان مغلبا","page":"ص0","text":"قال ويقال إن ذا الرمة راوية راعي الإبل ولم يكن له حظ في الهجاء وكان مغلبا"},{"id":"tabaqat-shuara:740","bookId":"tabaqat-shuara","type":"section","seq":740,"chapter":"طبقات فحول الشعراء","title":"742- أنا أبو خليفة نا ابن سلام قال كان أبو عمرو بن العلاء يقول إنما شعره نقط عروس يضمحل عن قليل","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال كان أبو عمرو بن العلاء يقول إنما شعره نقط عروس يضمحل عن قليل وأبعار ظباء لها مشم فى أول شمها ثم تعود إلى أرواح البعر"},{"id":"tabaqat-shuara:741","bookId":"tabaqat-shuara","type":"section","seq":741,"chapter":"طبقات فحول الشعراء","title":"743- أخبرني محمد بن يحيى عن الفضل بن الحباب عن محمد ابن سلام قال مر الفرزدق بذي الرمة وهو ينشد —","page":"ص0","text":"أخبرني محمد بن يحيى عن الفضل بن الحباب عن محمد ابن سلام قال مر الفرزدق بذي الرمة وهو ينشد\n(أمنزلتى مى سلام عليكما ... هل الأزمن اللائى مضين رواجع)\nفوقف حتى فرغ منها فقال كيف ترى يا أبا فراس قال أرى خيرا قال فمالي لا أعد في الفحول قال يمنعك عن ذلك صفة الصحاري وأبعار الإبل وولى الفرزدق وهو ينشد\n(ودوية لو ذو الرميمة رامها ... بصيدح أودى ذو الرميم وصيدح)\n(قطعت إلى معروفها منكراتها ... إذا خب آل دونها يتوضح)"},{"id":"tabaqat-shuara:742","bookId":"tabaqat-shuara","type":"section","seq":742,"chapter":"طبقات فحول الشعراء","title":"744- وكان هوى ذي الرمة مع الفرزدق على جرير وذلك لما كان بين جرير وابن لجأ التيمي وتيم وعدي أخوا","page":"ص0","text":"وكان هوى ذي الرمة مع الفرزدق على جرير وذلك لما كان بين جرير وابن لجأ التيمي وتيم وعدي أخوان من الرباب وعكل أخوهم ولذلك يقول جرير\n(فلا يضغمن الليث عكلا بغرة ... وعكل يشمون الفريس المنيبا)\nالفريس ههنا ابن لجأ وكذلك يفعل السبع إذا ضغم شاة ثم طرد عنها أو سبقته أقبلت الغنم تشم موضع الضغم فيفترسها السبع وهي تشم ولذلك قال جرير لبني عدي\n(وقلت نصاحة لبني عدى ... ثيابكم ونضح دم القتيل)\n(يحذر عديا ما لقى ابن لجأ ... )"},{"id":"tabaqat-shuara:743","bookId":"tabaqat-shuara","type":"section","seq":743,"chapter":"طبقات فحول الشعراء","title":"745- أنا أبو خليفة نا ابن سلام قال أخبرني أبو يحيى الضبي قال قال ذو الرمة يوما لقد قلت أبياتا إ","page":"ص0","text":"أنا أبو خليفة نا ابن سلام قال أخبرني أبو يحيى الضبي قال قال ذو الرمة يوما لقد قلت أبياتا إن لها لعروضا وإن لها لمرادا ومعنى بعيدا قال الفرزدق وما قلت قال قلت\n(أحين أعاذت ربي تميم نساءها ... وجردت تجريد اليماني من الغمد)\n(ومدت بضبعي الرباب ومالك ... وعمرو وشالت من ورائي بنو سعد)\n(ومن آل يربوع زهاء كأنه ... زها الليل محمود النكاية والرفد)\nفقال له الفرزدق لا تعودن فيها فأنا أحق بها منك قال والله لا أعود فيها ولا أنشدها أبدا إلا لك\nفهي في قصيدة الفرزدق التي يقول فيها\n(وكنا إذا القيسي نب عتوده ... ضربناه فوق الأنثيين على الكرد)\nالأنثيان الأذنان والكرد العنق"},{"id":"tabaqat-shuara:744","bookId":"tabaqat-shuara","type":"section","seq":744,"chapter":"طبقات فحول الشعراء","title":"746- أنا أبو خليفة نا محمد بن سلام حدثني أبو الغراف قال مر ذو الرمة بمنزل لامرىء القيس بن زيد م","page":"ص0","text":"أنا أبو خليفة نا محمد بن سلام حدثني أبو الغراف قال مر ذو الرمة بمنزل لامرىء القيس بن زيد مناة يقال له مرأة به نخل فلم ينزلوه ولم يقروه فقال\n(نزلنا وقد طال النهار وأوقدت ... علينا حصى المعزاء شمس تنالها)\n(أنخنا فظللنا بأبراد يمنة ... عتاق وأسياف قديم صقالها)\n(فلما رآنا أهل مرأة أغلقوا ... مخادع لم ترفع لخير ظلالها)\n(وقد سميت باسم امرىء القيس قرية ... كرام صواديها لئام رجالها)\nفلج الهجاء بين ذي الرمة وبين هشام المرئي"},{"id":"tabaqat-shuara:745","bookId":"tabaqat-shuara","type":"section","seq":745,"chapter":"طبقات فحول الشعراء","title":"747- فمر الفرزدق بذي الرمة وهو ينشد —","page":"ص0","text":"فمر الفرزدق بذي الرمة وهو ينشد\n(وقفت على ربع لمية ناقتي ... فما زلت أبكي عنده وأخاطبه)\n(وأسقيه حتى كاد مما أبثه ... تكلمني أحجاره وملاعبه)\nفقال الفرزدق ألهاك التبكاء في الديار والعبد يرجز بك في المقبرة يعني هشاما"},{"id":"tabaqat-shuara:746","bookId":"tabaqat-shuara","type":"section","seq":746,"chapter":"طبقات فحول الشعراء","title":"748- وكان ذو الرمة مستعليا هشاما حتى لقي جرير هشاما فقال غلبك العبد يعني ذا الرمة قال فما أصنع","page":"ص0","text":"وكان ذو الرمة مستعليا هشاما حتى لقي جرير هشاما فقال غلبك العبد يعني ذا الرمة قال فما أصنع يا أبا حزرة وأنا راجز وهو يقصد والرجز لا يقوم للقصيد في الهجاء فلو رفدتني فقال له جرير لتهمته ذا الرمة وميله إلى الفرزدق قل له\n(غضبت لرهط من عدي تشمسوا ... وفي أي يوم لم تشمس رحالها)\n(وفيم عدي عبد تيم من العلا ... وأيامنا اللاتي يعد فعالها)\n(وضبة عمي يا ابن جل فلا ترم ... مساعي قوم ليس منك سجالها)\n(يماشي عديا لؤمها لا تجنه ... من الناس ما ماشت عديا ظلالها)\n(فقل لعدي تستعن بنسائها ... علي فقد أعيى عديا رجالها)\n(أذا الرم قد قلدت قومك رمة ... بطيئا بأيدى المطلقين انحلالها)"},{"id":"tabaqat-shuara:747","bookId":"tabaqat-shuara","type":"section","seq":747,"chapter":"طبقات فحول الشعراء","title":"749- قال ابن سلام فحدثني أبو الغراف قال لما بلغت الأبيات ذا الرمة قال والله ما هذا بكلام هشام و","page":"ص0","text":"قال ابن سلام فحدثني أبو الغراف قال لما بلغت الأبيات ذا الرمة قال والله ما هذا بكلام هشام ولكنه كلام ابن الأتان"},{"id":"tabaqat-shuara:748","bookId":"tabaqat-shuara","type":"section","seq":748,"chapter":"طبقات فحول الشعراء","title":"750- قال وحدثني أبو البيداء قال لما سمعها قال هو والله شعر حنظلي عدوي","page":"ص0","text":"قال وحدثني أبو البيداء قال لما سمعها قال هو والله شعر حنظلي عدوي"},{"id":"tabaqat-shuara:749","bookId":"tabaqat-shuara","type":"section","seq":749,"chapter":"طبقات فحول الشعراء","title":"751- وغلب هشام على ذي الرمة","page":"ص0","text":"وغلب هشام على ذي الرمة"},{"id":"tabaqat-shuara:750","bookId":"tabaqat-shuara","type":"section","seq":750,"chapter":"طبقات فحول الشعراء","title":"752- وكان ذو الرمة يتشبب بمي بنت طلبة بن قيس بن عاصم المنقري وكانت كنزة أمة مولدة لآل قيس بن عا","page":"ص0","text":"وكان ذو الرمة يتشبب بمي بنت طلبة بن قيس بن عاصم المنقري وكانت كنزة أمة مولدة لآل قيس بن عاصم وهي أم سهم ابن بردة اللبن الذي قتله سنان بن مخيس القشيري أيام محمد بن سليمان فقالت كنزة\n(على وجه مي مسحة من ملاحة ... وتحت الثياب الخزي لو كان باديا)\n(ألم تر أن الماء يخبث طعمه ... ولو كان لون الماء في العين صافيا)\nونحلتها ذا الرمة فامتعض من ذلك وحلف بجهد أيمانه ما قالها قال وكيف أقول هذا وقد قطعت دهري وأفنيت شبابي أشبب بها وأمدحها ثم أقول هذا ثم اطلع على أن كنزة قالتها ونحلتها إياه"},{"id":"tabaqat-shuara:751","bookId":"tabaqat-shuara","type":"section","seq":751,"chapter":"طبقات فحول الشعراء","title":"753- وأخبرني أبو سوار الغنوي وكان فصيحا قال رأيت — ميا ورأيت معها بنين لها صغار قلت فصفها قال مسن","page":"ص0","text":"وأخبرني أبو سوار الغنوي وكان فصيحا قال رأيت\nميا ورأيت معها بنين لها صغار قلت فصفها قال مسنونة الوجه طويلة الخدين شماء الأنف عليها وسم جمال فقالت لي ما تلقيت بأحد من هؤلاء إلا في الإبل قلت له أفكانت تنشدك ما قال فيها ذو الرمة قال أي والله تسح سحا ما رأى مثله أحد"},{"id":"tabaqat-shuara:752","bookId":"tabaqat-shuara","type":"section","seq":752,"chapter":"طبقات فحول الشعراء","title":"754- قال حدثني أبو يحيى الضبي قال لقي ذو الرمة رؤبة فقال له ذو الرمة ما يعني الراعي بقوله —","page":"ص0","text":"قال حدثني أبو يحيى الضبي قال لقي ذو الرمة رؤبة فقال له ذو الرمة ما يعني الراعي بقوله\n(أناخا بأشوال طروقا بخبة ... قليلا وقد أعي سهيل فعردا)\nفجعل رؤبة يقع مرة ههنا ومرة ههنا إلى أن قال هي أرض بين المكلئة والمجدبة وكذاك هي"},{"id":"tabaqat-shuara:753","bookId":"tabaqat-shuara","type":"section","seq":753,"chapter":"طبقات فحول الشعراء","title":"755- قال وكان ذو الرمة أيضا ينسب بخرقاء إحدى نساء بني عامر بن ربيعة وكانت تحل فلجة ويمر بها الح","page":"ص0","text":"قال وكان ذو الرمة أيضا ينسب بخرقاء إحدى نساء بني عامر بن ربيعة وكانت تحل فلجة ويمر بها الحاج فتقعد لهم وتحدثهم وتهاديهم وتقول أنا منسك من مناسك الحج ثم كانت تجلس معها فاطمة ابنتها فحدثني من رآها قال لم تكن فاطمة مثلها وإنما قالت أنا من مناسك الحج لقول ذي الرمة\n(تمام الحج أن تقف المطايا ... على خرقاء واضعة اللثام)"},{"id":"tabaqat-shuara:754","bookId":"tabaqat-shuara","type":"section","seq":754,"chapter":"طبقات فحول الشعراء","title":"756- وقال فيها —","page":"ص0","text":"وقال فيها\n(أعن ترسمت من خرقاء منزلة ... ماء الصبابة من عينيك مسجوم)\n(تثني الخمار على عرنين أرنبة ... شماء مارنها بالمسك مرثوم)"},{"id":"tabaqat-shuara:755","bookId":"tabaqat-shuara","type":"section","seq":755,"chapter":"طبقات فحول الشعراء","title":"757- وكانت مية عند ابن عم لها يقال له عاصم فيه يقول ذو الرمة —","page":"ص0","text":"وكانت مية عند ابن عم لها يقال له عاصم فيه يقول ذو الرمة\n(ألا ليت شعري هل يموتن عاصم ... ولم تشتعبني للمنايا شعوبها)\n(رمى الله من حتف المنية عاصما ... بقاصمة يدعى لها فيجيبها)"},{"id":"tabaqat-shuara:756","bookId":"tabaqat-shuara","type":"section","seq":756,"chapter":"طبقات فحول الشعراء","title":"758- قال وحدثني أبي سلام قال دخلت على خرقاء فقالت اخرجي يا فاطمة تعني ابنتها فخرجت امرأة جميلة","page":"ص0","text":"قال وحدثني أبي سلام قال دخلت على خرقاء فقالت اخرجي يا فاطمة تعني ابنتها فخرجت امرأة جميلة وليست كأمها"},{"id":"tabaqat-shuara:757","bookId":"tabaqat-shuara","type":"section","seq":757,"chapter":"طبقات فحول الشعراء","title":"759- قال ابن سلام في خبره وأرسلت خرقاء إلى القحيف العقبلي تسأله أن يشبب بها فقال —","page":"ص0","text":"قال ابن سلام في خبره وأرسلت خرقاء إلى القحيف العقبلي تسأله أن يشبب بها فقال\n(لقد أرسلت خرقاء نحوي جريها ... لتجعلني خرقاء فيمن أضلت)\n(وخرقاء لا تزداد إلا ملاحة ... ولو عمرت تعمير نوح وجلت)"},{"id":"tabaqat-shuara:758","bookId":"tabaqat-shuara","type":"section","seq":758,"chapter":"طبقات فحول الشعراء","title":"760- قال وحدثني محمد بن أبي عدي الفقيه قال قال — ذو الرمة بلغت نصف عمر الهرم وأنا ابن أربعين سنة","page":"ص0","text":"قال وحدثني محمد بن أبي عدي الفقيه قال قال\nذو الرمة بلغت نصف عمر الهرم وأنا ابن أربعين سنة قال ولم يبق ذو الرمة بعد ذلك إلا قليلا لأنه مات شابا"},{"id":"tabaqat-shuara:759","bookId":"tabaqat-shuara","type":"section","seq":759,"chapter":"طبقات فحول الشعراء","title":"761- قال ابن سلام وحدثني أبو الغراف أنه مات وهو يريد هشاما وقال في طريقه ذلك —","page":"ص0","text":"قال ابن سلام وحدثني أبو الغراف أنه مات وهو يريد هشاما وقال في طريقه ذلك\n(بلاد بها أهلون لست ابن أهلها ... وأخرى بها أهلون ليس لها أهل)"},{"id":"tabaqat-shuara:760","bookId":"tabaqat-shuara","type":"section","seq":760,"chapter":"طبقات فحول الشعراء","title":"762- قال وكانوا إخوة ثلاثة غيلان وهو ذو الرمة — وأوفى ومسعود بنو عقبة فهلك أوفى ثم هلك ذو الرمة ف","page":"ص0","text":"قال وكانوا إخوة ثلاثة غيلان وهو ذو الرمة\nوأوفى ومسعود بنو عقبة فهلك أوفى ثم هلك ذو الرمة فقال مسعود\n(تعزيت عن أوفى بغيلان بعده ... عزاء وجفن العين ملآن مترع)\n(ولم ينسني أوفى المصيبات بعده ... ولكن نكأ القرح بالقرح أوجع)"},{"id":"tabaqat-shuara:761","bookId":"tabaqat-shuara","type":"section","seq":761,"chapter":"طبقات فحول الشعراء","title":"763- ولمسعود يقول ذو الرمة —","page":"ص0","text":"ولمسعود يقول ذو الرمة\n(بل عجبت أخت بني لبيد ... وهزئت مني ومن مسعود)\n(رأت غلامى سفر بعيد ... يدرعان الليل ذا السدود)\n(مثل ادراع اليلمق الجديد ... أما بكل كوكب حريد)\n(إذا سهيل لاح كالوقود ... فردا كشاة البقر المطرود)\n(يا صاحبي صوتا بالقود ... وعللاهن بهيد هيد)\nوفيها يقول\n(أشعث باق رمة التقليد ... )\nوبهذه الكلمة سمي ذا الرمة"},{"id":"tabaqat-shuara:762","bookId":"tabaqat-shuara","type":"section","seq":762,"chapter":"طبقات فحول الشعراء","title":"764- وحدثني أبي سلام بن عبيد الله قال رأيت ذا الرمة ورأيت لمته وهيئته وقال لأبي الغراف فيك مشاب","page":"ص0","text":"وحدثني أبي سلام بن عبيد الله قال رأيت ذا الرمة ورأيت لمته وهيئته وقال لأبي الغراف فيك مشابه منه"},{"id":"tabaqat-shuara:763","bookId":"tabaqat-shuara","type":"section","seq":763,"chapter":"طبقات فحول الشعراء","title":"765- حدثني أبو الغراف قال دارأ الحكم بن عوانة ذا الرمة في بعض قوله فقال فيه —","page":"ص0","text":"حدثني أبو الغراف قال دارأ الحكم بن عوانة ذا الرمة في بعض قوله فقال فيه\n(فلو كنت من كلب صحيحا هجوتكم ... جميعا ولكن لا إخالك من كلب)\n(ولكنما أخرت أنك ملصق ... كما ألصقت من غيرها ثلمة القعب)\n(تدهدى فخرت ثلمة من صحيحه ... فلز بأخرى بالغراء وبالشعب)"},{"id":"tabaqat-shuara:764","bookId":"tabaqat-shuara","type":"section","seq":764,"chapter":"طبقات فحول الشعراء","title":"766- وحدثني أبو الغراف قال دخل ذو الرمة على بلال بن أبي بردة وكان بلال راوية فصيحا أديبا فأنشد","page":"ص0","text":"وحدثني أبو الغراف قال دخل ذو الرمة على بلال بن أبي بردة وكان بلال راوية فصيحا أديبا فأنشد بلال أبيات حاتم طيء\n(لحا الله صعلوكا مناه وهمه ... من العيش أن يلقى لبوسا ومطعما)\n(يرى الخمس تعذيبا وإن نال شعبة ... يبت قلبه من قلة الهم مبهما)\nفقال ذو الرمة يرى الخمص تعذيبا وإنما الخمس للإبل وإنما هو خمص البطون فمحك بلال وكان محكا وقال هكذا أنشدنيها رواة طيء\nفرد عليه ذو الرمة فمحك فدخل أبو عمرو بن العلاء فقال له بلال كيف تنشدها فعرف أبو عمرو الذي به فقال كلا الوجهين فقال أتأخذون عن ذي الرمة قال إنه لفصيح وإنا لنأخذ عنه بتمريض وخرجا من عنده فقال ذو الرمة لأبي عمرو\nوالله لولا أني أعلمك حطبت في حبله وملت في هواه لهجواتك هجاء لا يقعد إليك معه اثنان"},{"id":"tabaqat-shuara:765","bookId":"tabaqat-shuara","type":"section","seq":765,"chapter":"طبقات فحول الشعراء","title":"767- كعب بن جعيل بن قمير بن عجرة بن عوف بن مالك ابن بكر بن حبيب بن عمرو بن غنم بن تغلب بن وائل","page":"ج2 ص570","text":"كعب بن جعيل بن قمير بن عجرة بن عوف بن مالك ابن بكر بن حبيب بن عمرو بن غنم بن تغلب بن وائل"},{"id":"tabaqat-shuara:766","bookId":"tabaqat-shuara","type":"section","seq":766,"chapter":"طبقات فحول الشعراء","title":"768- وعمرو بن أحمر بن العمرد بن تميم بن ربيعة بن حرام ابن فراص بن معن الباهلي","page":"ج2 ص570","text":"وعمرو بن أحمر بن العمرد بن تميم بن ربيعة بن حرام ابن فراص بن معن الباهلي"},{"id":"tabaqat-shuara:767","bookId":"tabaqat-shuara","type":"section","seq":767,"chapter":"طبقات فحول الشعراء","title":"769- وسحيم بن وثيل بن أعيفر بن أبي عمرو بن إهاب بن حميري ابن رياح بن يربوع","page":"ج2 ص570","text":"وسحيم بن وثيل بن أعيفر بن أبي عمرو بن إهاب بن حميري ابن رياح بن يربوع"},{"id":"tabaqat-shuara:768","bookId":"tabaqat-shuara","type":"section","seq":768,"chapter":"طبقات فحول الشعراء","title":"770- وأوس بن مغراء من قريع بن عوف بن كعب ابن سعد","page":"ص0","text":"وأوس بن مغراء من قريع بن عوف بن كعب ابن سعد"},{"id":"tabaqat-shuara:769","bookId":"tabaqat-shuara","type":"section","seq":769,"chapter":"طبقات فحول الشعراء","title":"771- كعب بن جعيل شاعر مفلق قديم في أول الإسلام أقدم من الأخطل والقطامي وقد لحقا به وكانا معه وه","page":"ص0","text":"كعب بن جعيل شاعر مفلق قديم في أول الإسلام أقدم من الأخطل والقطامي وقد لحقا به وكانا معه وهو يقول\n(وأبيض جني عليه سموطه ... من الإنس في قصر منيف غواربه)\n(تدليته سقط الندى بعد هجعة ... فبت أمنيه المنى وأخالبه)\n(بما ينزل الأروى من الشعف العلى ... وما لو يسني حية مال جانبه)\n(ندمت على شتم العشيرة بعد ما ... مضى واستتبت للرواة مذاهبه)\n(فأصبحت لا أسطيع ردا لما مضى ... كما لا يرد الدر في الضرع حالبه)\n(معاوي أنصف تغلب ابنة وائل ... من الناس أودعها وحيا تضاربه)\n(قليل على باب الأمير لباثتي ... إذا رابني باب الأمير وحاجبه)\n(ولما تداروا في تراث محمد ... سمعت بابن هند في قريش مضاربه)"},{"id":"tabaqat-shuara:770","bookId":"tabaqat-shuara","type":"section","seq":770,"chapter":"طبقات فحول الشعراء","title":"772- وكعب يقول في عبيد الله بن عمر بن الخطاب وقتل — بصفين وهو مع معاوية قتلته بنو شيبان —","page":"ج2 ص573","text":"وكعب يقول في عبيد الله بن عمر بن الخطاب وقتل\nبصفين وهو مع معاوية قتلته بنو شيبان\n(ألا إنما تبكي العيون لفارس ... بصفين أجلت خيله وهو واقف)\n(تبدل من أسماء أسياف وائل ... وكان فتى لو أخطأته المتالف)\n(تركن عبيد الله بالقاع مسندا ... تمج دم الجوف العروق النوازف)\n(يحللن عنه جيب درع حصينة ... وأي فتى لو أخطأته المآلف)\n(وحافظ صدر من ربيعة صابر ... وطارالو شيظ عنهم والزعانف)\n(إذا قيل أي الناس شر قبيلة ... بني أسد إني لما قيل عارف)\n(أغرتم علينا تسرقون عبابنا ... وما إن لنا في بطن صفين قائف)"},{"id":"tabaqat-shuara:771","bookId":"tabaqat-shuara","type":"section","seq":771,"chapter":"طبقات فحول الشعراء","title":"773- وسحيم بن وثيل الرياحي شريف مشهور الأمر في الجاهلية والإسلام جيد الموضع في قومه شاعر خنذيذ","page":"ج2 ص575","text":"وسحيم بن وثيل الرياحي شريف مشهور الأمر في الجاهلية والإسلام جيد الموضع في قومه شاعر خنذيذ وكان\nالغالب عليه البداء والخشنة وهو الذي ناحر غالب بن صعصعة أبا الفرزدق بالكوفة أيام علي بن أبي طالب رضي الله عنه\nتفاخرا وقد أقدما جلبا لهما فتناحرا فجعل غالب لا يفرس وجعل سحيم يفرس فقيل له أتجاري هوج بني دارم أقلع وغدا الناس بالمدى والجفان ليأخذوا اللحم فقال علي أيها الناس لا تأكلوا منه فإنه مما أهل لغير الله به فارتدع الناس"},{"id":"tabaqat-shuara:772","bookId":"tabaqat-shuara","type":"section","seq":772,"chapter":"طبقات فحول الشعراء","title":"774- قال كان عثمان بن عفان رضي الله عنه استعمل سمرة بن عمرو بن قرط بن جناب بن عدي بن جندب العنب","page":"ص0","text":"قال كان عثمان بن عفان رضي الله عنه استعمل سمرة بن عمرو بن قرط بن جناب بن عدي بن جندب العنبري في ولده وأسرته شرف إلى اليوم يقال لهم بنو السمرات فاستعمله على هوامي عمرو ابن تميم وفلج وما يليها فكان لا يخبر بضالة في قوم إلا أخذها\nفعرفها فكان من ذهبت له ضالة طلبها عنده\nفبلغه أن ناقة في أبل بني وثيل فأتاهم وأعبد معه وليس هناك من بني وثيل أحد وأمهم ليلى بنت شداد من بني حميري بن رياح بن يربوع عجوز كبيرة في غلمة لهم فقال اعرضوا علي الإبل فأبت فأخذ ليعرضها فأهوت له فدفعها فقالت فمي فمي وزعموا أن ثنيتيها قد كانتا سقطتا قبل ذلك بزمان\nفلما رأى ذلك سمرة لها عنها وترك الإبل فلما قدم سحيم بن وثيل إلى أمه أخبرته الخبر فسكت حتى يلقى عبيد ابن غاضرة بن سمرة فصرعه فدق فمه فاستعدى عليه سمرة ابن عفان وكان عثمان إذا عاقب بالغ فأشخص سحيم إليه إلى المدينة وحبست إبله حتى ضاعت فقال لعثمان يا أمير المؤمنين إنه كسر فم أمي قال ألا استعديت عليه وقال عثمان لأفطعن منك طابقا أو يرضى سمرة\nوصادف سحيم بن وثيل يزيد بن مسعود بن خالد بن مالك بن ربعي بن سلمى بن جندل أخا لليلى بنت مسعود أم عبيد الله\nابن علي بن أبي طالب ونعيما أبا قران اليربوعي فقاما بأمر سحيم وحملا للعنبري مئة من الإبل فقال في ذلك سحيم ابن وثيل\n(كفاني أبو قران نفسي فداؤه ... ومن يك مولاه فليس بواحد)"},{"id":"tabaqat-shuara:773","bookId":"tabaqat-shuara","type":"section","seq":773,"chapter":"طبقات فحول الشعراء","title":"775- وسحيم بن وثيل القائل —","page":"ج2 ص578","text":"وسحيم بن وثيل القائل\n(أنا ابن جلا وطلاع الثنايا ... متى أضع العمامة تعرفوني)\n(ألم تر أنني في حميري ... مكان الليث من وسط العرين)\n(عذرت البزل إن هي خاطرتني ... فما بالي وبال ابني لبون)\n(وماذا يغمز الأعداء مني ... وقد جاوزت رأس الأربعين)"},{"id":"tabaqat-shuara:774","bookId":"tabaqat-shuara","type":"section","seq":774,"chapter":"طبقات فحول الشعراء","title":"776- وعمرو بن أحمر صحيح الكلام كثير الغريب وهو القائل —","page":"ص0","text":"وعمرو بن أحمر صحيح الكلام كثير الغريب وهو القائل\n(إن الفتى يقتر بعد الغنى ... ويغتني من بعد ما يفتقر)\n(والحي كالميت ويبقى التقى ... والعيش فنان فحلو ومر)\n(إما على نفسي وإما لها ... فعايش النفس وفيها وقر)\n(هل يهلكني بسط ما في يدي ... أو يخلدني منع ما أدخر)\n(أو ينسأن يومي إلى غيره ... أني حوالي وأني حذر)\n(ولن ترى مثلي ذا شيبة ... أعلم ما ينفع مما يضر)"},{"id":"tabaqat-shuara:775","bookId":"tabaqat-shuara","type":"section","seq":775,"chapter":"طبقات فحول الشعراء","title":"777- نهشل بن حرى أحد بني نهشل بن دارم","page":"ج2 ص581","text":"نهشل بن حرى أحد بني نهشل بن دارم"},{"id":"tabaqat-shuara:776","bookId":"tabaqat-shuara","type":"section","seq":776,"chapter":"طبقات فحول الشعراء","title":"778- وحميد بن ثور الهلالي","page":"ج2 ص581","text":"وحميد بن ثور الهلالي"},{"id":"tabaqat-shuara:777","bookId":"tabaqat-shuara","type":"section","seq":777,"chapter":"طبقات فحول الشعراء","title":"779- والأشهب بن رميلة","page":"ج2 ص581","text":"والأشهب بن رميلة"},{"id":"tabaqat-shuara:778","bookId":"tabaqat-shuara","type":"section","seq":778,"chapter":"طبقات فحول الشعراء","title":"780- وعمر بن لجأ التيمي من تيم الرباب","page":"ج2 ص581","text":"وعمر بن لجأ التيمي من تيم الرباب"},{"id":"tabaqat-shuara:779","bookId":"tabaqat-shuara","type":"section","seq":779,"chapter":"طبقات فحول الشعراء","title":"781- فنهشل بن حرى شاعر شريف مشهور وأبوه حرى شاعر مذكور وجده ضمرة بن ضمرة شريف فارس شاعر بعيد ال","page":"ج2 ص581","text":"فنهشل بن حرى شاعر شريف مشهور وأبوه حرى شاعر مذكور وجده ضمرة بن ضمرة شريف فارس شاعر بعيد الذكر كبير الأمر وأبواه ضمرة بن جابر سيد ضخم الشرف بعيد الذكر وأبوه جابر له ذكر وشهرة وشرف وأبوه قطن له شرف وفعال وذكر في العرب فهم ستة كما ذكرنا لا أعلم في تميم رهطا يتوالون توالي هؤلاء"},{"id":"tabaqat-shuara:780","bookId":"tabaqat-shuara","type":"section","seq":780,"chapter":"طبقات فحول الشعراء","title":"782- ونهشل بن حرى الذي يقول —","page":"ص0","text":"ونهشل بن حرى الذي يقول\n(إذا كنت جارا لامرىء فارهب الخنا ... على عرضه إن الخنا طرف الغدر)\n(وذد عن حراه ما عقدت حباله ... بحبلك واستره بما لك من ستر)\n(وجار منعناه من الضيم والعدى ... وجيران أقوام بمدرجة الدهر)\n(ويوم كأن المصطلين بحره ... وإن لم تكن نار قعود على جمر)\n(صبرنا له حتى يبوخ وإنما ... تفرج أيام الكريهة بالصبر)"},{"id":"tabaqat-shuara:781","bookId":"tabaqat-shuara","type":"section","seq":781,"chapter":"طبقات فحول الشعراء","title":"783- وحميد بن ثور القائل —","page":"ص0","text":"وحميد بن ثور القائل\n(قليل المعي إلا مصيرا يبله ... دم الجوف أو سؤر من الحوض ناقع)\n(ترى طرفيه يعسلان كلاهما ... كما اختب عود الساسم المتتابع)\n(ينام بإحدى مقلتيه ويتقي المنايا ... بأخري فهو يقظان هاجع)"},{"id":"tabaqat-shuara:782","bookId":"tabaqat-shuara","type":"section","seq":782,"chapter":"طبقات فحول الشعراء","title":"784- والأشهب بن رميلة ورميلة أمه وأبوه ثور وكان الأشهب شاعرا وكان يهاجي الفرزدق وهو أحد بني نهش","page":"ص0","text":"والأشهب بن رميلة ورميلة أمه وأبوه ثور وكان الأشهب شاعرا وكان يهاجي الفرزدق وهو أحد بني نهشل بن دارم"},{"id":"tabaqat-shuara:783","bookId":"tabaqat-shuara","type":"section","seq":783,"chapter":"طبقات فحول الشعراء","title":"785- وكان له أخ يدعى زبابا وكان من أشد الناس وأخبثهم وكان الفرزدق يفرقه فرقا شديدا وفيه يقول ال","page":"ص0","text":"وكان له أخ يدعى زبابا وكان من أشد الناس وأخبثهم وكان الفرزدق يفرقه فرقا شديدا وفيه يقول الأشهب\n(وقائلة تنعى زبابا وقائل ... جزى الله خيرا ما أعف وأمنعا)\n(وأطعن في الهيجا وأضرب في الوغى ... وأطعم إن أمسى المراضيع جوعا)\n(شمت ابن قين أن أصابت مصيبة ... كريما ولم يترك لك الدهر مسمعا)\n(كريما حماك الدهر طول حياته ... وأنت لئيم منبت الحمض أجمعا)\n(أعيني قلت أسوة من أخيكما ... بأن تسهرا الليل التمام وتدمعا)\n(قتلنا زعيم القوم لا خير بعده ... ولم يك في الأحجار منع فأمنعا)\n(إذا ما ذكرنا من أخينا أخاهم ... روينا ولم نشف الغليل فينقعا)\nالأحجار صخر وجندل وجرول بنو نهشل فغلب الفرزدق على الأشهب وفضل عليه"},{"id":"tabaqat-shuara:784","bookId":"tabaqat-shuara","type":"section","seq":784,"chapter":"طبقات فحول الشعراء","title":"786- وأما عمر بن لجأ فحدثني أبو الغراف قال قدم لقمان الخزاعي على صدقات الرباب فكانت وجوه الرباب","page":"ج2 ص587","text":"وأما عمر بن لجأ فحدثني أبو الغراف قال قدم لقمان الخزاعي على صدقات الرباب فكانت وجوه الرباب تحضره وفيهم عمر بن لجأ بن حدير أحد بني مصاد فأنشده يوما\n(تأوبني ذكر لزولة كالخبل ... وما حيث تلقى بالكثبب ولا السهل)\n(تحل وركن من طمية دونها ... وجو قسا مما يحل به أهلي)\n(تريدين أن أرضى وأنت بخيلة ... ومن ذا الذي يرضي الأخلاء بالبخل)\nفقال لقمان مازلنا نسمع بالشام أنها كلمة جرير وأبلغ لقمان جريرا فقال زعم أنك سرقتها منه فقال جرير وأنا أحتاج أن أسرق قول عمر وهو القائل وقد وصف إبله فذكر قصة قد ذكرها ابن سلام عن أبي يحيى الضبي في أخبار جرير"},{"id":"tabaqat-shuara:785","bookId":"tabaqat-shuara","type":"section","seq":785,"chapter":"طبقات فحول الشعراء","title":"787- قال فرد عليه عمر بن لجأ —","page":"ص0","text":"قال فرد عليه عمر بن لجأ\n(أنبئت كلب كليب قد عوى جزعا ... وكل عاو بفيه الترب والحجر)\n(قد لمتني ظالما في سنة سبقت ... أن الكليبي لم يكتب له الظفر)\n(هبت الفرزدق واستبعثتني عبثا ... للموت تعمد والموت الذي تذر)\n(فاخسأ لعلك ترجو أن يحل بنا ... رحل الفرزدق لما مسك الدبر)"},{"id":"tabaqat-shuara:786","bookId":"tabaqat-shuara","type":"section","seq":786,"chapter":"طبقات فحول الشعراء","title":"788- ومن قوله —","page":"ص0","text":"ومن قوله\n(أجد القلب هجرا واجتنابا ... لمن أمسى يواصلنا خلابا)\n(ومن يدنو ليعجبنا وينأى ... فقد جمع التدلل والكذابا)\n(ألا تجزين من أثنى عليكم ... وأحسن حين قال وما استتابا)\n(تصدت بعد شيبك أم بكر ... لتطرد عنك حلما حين ثابا)\n(بجيد غزال مقفرة وماحت ... بعود أراكة بردا عذابا)\n(كأن سلافة خلطت بمسك ... ليغلبها وكان لها قطابا)\n(مذاقتها إذا ما بيتتها ... سواد الزوج والتثم الرضابا)\n(ليغتبق العلالة من نداها ... كفى فوها لمغتبق وطابا)\n(أسيلة معقد السمطين منها ... وريا حيث تعتقد الحقابا)\n(إذا مالت روادفها بمتن ... كغصن البان فاضطرب اضطرابا)\n(تهادى في الثياب كما تهادى ... حباب الماء يتبع الحبابا)\n(ترى الخلخال والدملوج منها ... إذا ما أكرها نشبا فغابا)\n(إذا ما الشىء لم تقدر عليه ... فلا ذكرا لذاك ولا طلابا)"},{"id":"tabaqat-shuara:787","bookId":"tabaqat-shuara","type":"section","seq":787,"chapter":"طبقات فحول الشعراء","title":"789- أبو زبيد الطائي واسمه حرملة بن المنذر","page":"ج2 ص592","text":"أبو زبيد الطائي واسمه حرملة بن المنذر"},{"id":"tabaqat-shuara:788","bookId":"tabaqat-shuara","type":"section","seq":788,"chapter":"طبقات فحول الشعراء","title":"790- والعجير بن عبد الله بن عبيدة بن كعب بن عائشة بن الربيع بن ضبيط بن جابر بن عبد الله بن سلول","page":"ج2 ص592","text":"والعجير بن عبد الله بن عبيدة بن كعب بن عائشة بن الربيع بن ضبيط بن جابر بن عبد الله بن سلول"},{"id":"tabaqat-shuara:789","bookId":"tabaqat-shuara","type":"section","seq":789,"chapter":"طبقات فحول الشعراء","title":"791- وعبد الله بن همام السلولي","page":"ج2 ص592","text":"وعبد الله بن همام السلولي"},{"id":"tabaqat-shuara:790","bookId":"tabaqat-shuara","type":"section","seq":790,"chapter":"طبقات فحول الشعراء","title":"792- ونفيع بن لقيط الأسدي","page":"ج2 ص592","text":"ونفيع بن لقيط الأسدي"},{"id":"tabaqat-shuara:791","bookId":"tabaqat-shuara","type":"section","seq":791,"chapter":"طبقات فحول الشعراء","title":"793- أنا أبو خليفة نا محمد بن سلام أخبرنا أبو الغراف قال كان أبو زبيد الطائي من زوار الملوك ولم","page":"ج2 ص592","text":"أنا أبو خليفة نا محمد بن سلام أخبرنا أبو الغراف قال كان أبو زبيد الطائي من زوار الملوك ولملوك العجم خاصة\nوكان عالما بسيرهم وكان عثمان بن عفان يقربه على ذلك ويدنيه ويدني مجلسه وكان نصرانيا\nفحضر ذات يوم عثمان وعنده المهاجرون والأنصار فتذاكروا مآثر العرب وأشعارها فالتفت عثمان إلى أبي زبيد فقال يا أخا تبع المسيح أسمعنا بعض قولك فقد أنبئت أنك تجيد فأنشده قصيدته التي يقول فيها\n(من مبلغ قومي النائين إذ شحطوا ... أن الفؤاد إليهم شيق ولع)\nووصف فيها الأسد فقال عثمان تالله تفتأ تذكر الأسد ما حييت والله إني لأحسبك جبانا هدانا فقال كلا يا أمير المؤمنين ولكني رأيت منه منظرا وشهدت منه مشهدا لا يبرح ذكره يتجدد في قلبي ومعذور أنا يا أمير المؤمنين غير ملوم\nفقال عثمان وأنى كان ذلك قال خرجت في صيابة أشراف من أفناء قبائل العرب ذوي هيئة وشارة حسنة ترتمي بنا المهارى بأكسائها ونحن نريد الحارث بن أبي شمر الغساني ملك الشام فاخروط بنا المسير في حمارة القيظ\nحتى إذا عصبت الأفواه وذبلت الشفاه وشالت المياه وأذكت الجوزاء المعزاء وذاب الصيهد وصر الجندب وضاف العصفور الضب في جحره أو قال في وجاره قال قائلنا يا أيها الركب غوروا بنا في ضوج هذا الوادي\nوإذا واد قديد يمتنا كثير الدغل دائم الغلل شجراؤه مغنة وأطياره مرنة فحططنا رواحلنا في أصول دوحات كنهبلات فأصبنا من فضلات المزاود وأتبعناها الماء البارد\nفأنا لنصف حر يومنا ذلك ومماطلته إذ صر أقصى الخيل أذنيه وفحص الأرض بيديه\nفو الله مالبث أن جال ثم حمحم فبال وفعل فعله الذي يليه واحدا فواحدا فتضعضعت الخيل وتكعكعت الإبل وتقهقرت البغال فمن نافر بشكاله وناهض بعقاله فعلمنا أن قد أتينا وأنه السبع ففزع كل امرىء منا إلى سيفه فاستله من جربانه ثم وقفنا رزدقا فأقبل يتظالع من بغيه كأنه مجنوب أو في هجار لصدره نحيط ولبلاعيمه غطيط ولطرفه وميض ولأرساغه نقيض كأنما يخبط هشيما وإنما يطأ صريما فإذا هامة كالمجن وإذا خد كالمسن\nوعينان سجراوان كأنهما سراجان يقدان وقصرة ربلة ولهزمة رهلة وكتد مغبط وزور مفرط وساعد مجدول وعضد مفتول وكف شثنة البراثن إلى مخالب كالمحاجن\nفضرب بيديه فأرهج وكشر فأفرج عن أنياب كالمعاول مصقولة غير مفلولة وفم أشدق كالغار الأخرق ثم تمطى فأشرع بيديه وحفز وركيه برجليه حتى صار ظله مثليه\nثم أقعى فاقشعر ثم تميل فاكفهر ثم تجهم فازبأر فلا والذي بيته في السماء ما انفيناه إلا بأول أخ لنا من بني فزارة كان ضخم الجزارة فوقصه ثم نفضه نفضه فقضقض متنيه ثم جعل يلغ\nفي دمه فذمرت أصحابي فبعد لأي ما استقدموا فهجهجنا به فكر مقشعرا بزبرة كأن بين كتفيه شيهما حوليا فاختلج رجلا أعجر ذا حوايا فنفضه نفضة تزايلت مفاصله ثم نهم ففرفر ثم زفر فبربر ثم زأر فجرجر ثم لحظ فوالله لخلت البرق يتطاير من تحت جفونه من عن شماله ويمينه فأرعشت الأيدي واصطكت الأرجل وأطت الأضلاع وارتجت الأسماع وحمجت العيون ولحقت البطون وانخزلت المتون وساءت الظنون\nفقال عثمان اسكت قطع الله لسانك فقد رعبت قلوب المؤمنين"},{"id":"tabaqat-shuara:792","bookId":"tabaqat-shuara","type":"section","seq":792,"chapter":"طبقات فحول الشعراء","title":"794- وقال يصف الأسد —","page":"ج2 ص598","text":"وقال يصف الأسد\n(فباتوا يدلجون وبات يسري ... بصير بالدجى هاد هموس)\n(إلى أن عرسوا وأغب عنهم ... قريبا ما يحس له حسيس)\n(خلا أن العتاق من المطايا ... حسين به فهن إليه شوس)\n(فلما أن رآهم قد تدانوا ... أتاهم وسط أرحلهم يميس)\n(فثار الزاجرون فزاد منهم ... تقرابا وواجهه ضبيس)\n(بنصل السيف ليس له مجن ... فصد ولم يصادفه جبيس)\n(فيضرب بالشمال إلى حشاه ... وقد نادى فأخلفه الأنيس)\n(بسمر كالمحاجن في قنوب ... يقيها قضة الأرض الدخيس)\n(فخر بالسيف واختلفت يداه ... وكان بنفسه وقيت نفوس)\n(فطار القوم شتى والمطايا ... وغودر في مكرهم الرئيس)\n(وجال كأنه فرس صنيع ... يجر جلاله ذبل شموس)\n(كأن بنحره وبساعديه ... عبيرا بات تعبؤه عروس)\n(فذلك إن تفادوه تفادوا ... ويصرف عنكم أمر شكيس)"},{"id":"tabaqat-shuara:793","bookId":"tabaqat-shuara","type":"section","seq":793,"chapter":"طبقات فحول الشعراء","title":"795- وحدثني أبي سلام عمن حدثه أن رجلا من طيء من بني حية نزل به رجل من بني الحارث بن ذهل بن شيبا","page":"ج2 ص602","text":"وحدثني أبي سلام عمن حدثه أن رجلا من طيء من بني حية نزل به رجل من بني الحارث بن ذهل بن شيبان يقال له المكاء فذبح له شاة وسقاه من الخمر فلما سكر الطائي قال هلم أفاخرك أبنو حية أكرم أم بنو شيبان فقال له الشيباني\nحديث حسن ومنادمة كريمة أحب إلينا من المفاخرة فقال الطائي والله ما مد رجل قط يدا أطول من يدي فقال الشيباني والله لئن أعدتها لأخضبنها من كوعها فرفع الطائي يده فخضبها من كوعها فقال أبو زبيد في ذلك\n(خبرتنا الركبان أن قد فخرتم ... وفرحتم بضربة المكاء)\n(ولعمري لعارها كان أدنى ... لكم من تقى وحسن وفاء)\n(ظل ضيفا أخوكم لأخينا ... في صبوح ونعمة وشواء)\n(ثم لما رآه رانت به الخمر ... وأن لا يريبه باتقاء)\n(لم يهب حرمة النديم وحقت ... يالقوم للسوأة السوآء)"},{"id":"tabaqat-shuara:794","bookId":"tabaqat-shuara","type":"section","seq":794,"chapter":"طبقات فحول الشعراء","title":"796- وقال حين عزل الوليد بن عقبة بن أبى معيط عن الكوفة وحملت أثقاله —","page":"ص0","text":"وقال حين عزل الوليد بن عقبة بن أبى معيط عن الكوفة وحملت أثقاله\n(من يرى العير لابن أروى على ظهر ... المرورى حداتهن عجال)\n(مصعدات والبيت بيت أبي وهب ... خلاء تحن فيه الشمال)\n(يعرف الجاهل المضلل أن الدهر ... فيه النكراء والزلزال)\n(ليت شعري كذا كم العهد أم كانوا ... أناسا كمن يزول فزالوا)\n(بعد ما تعلمين يا أم زيد ... كان فيهم عز لنا وجمال)\n(أصبح البيت قد تبدل بالحي ... وجوها كأنها أقتال)\n(غير ما طالبين ذحلا ولكن ... مال دهر على أناس فمالوا)\n(كل شىء تحتال فيه الرجال ... غير أن ليس للمنايا احتيال)"},{"id":"tabaqat-shuara:795","bookId":"tabaqat-shuara","type":"section","seq":795,"chapter":"طبقات فحول الشعراء","title":"797- وقال أبو زبيد وكان في أخواله بني تغلب وكان يقيم فيهم أكثر أيامه وكان له غلام يرعى إبله وأن","page":"ج2 ص605","text":"وقال أبو زبيد وكان في أخواله بني تغلب وكان يقيم فيهم أكثر أيامه وكان له غلام يرعى إبله وأن بهراء غزت بني\nتغلب فمروا بغلامه فدفع إليهم الإبل وقال انطلقوا أدلكم على عورة القوم وأقاتل معكم فصحبهم فالتقوا فهزمت تغلب بهراء وقتل العبد فقال أبو زبيد\n(قد كنت في منظر ومستمع ... عن نصر بهراء غير ذي فرس)\n(تسعى إلى فتية الأراقم واستعجلت ... قيل الجمان والقبس)\nفي عارض من جبال بهرا بها الأل مرين الحروب عن درس\n(فنهزة من لقوا حسبتهم ... أحلى وأشهى من بارد الدبس)\n(لا ترة عندهم فتطلبها ... ولا هم نهزة لمختلس)\n(جود كرام إذا هم ندبوا ... غير لئام صنجر ولاكبس)\n(صمت عظام الحلوم إن قعدوا ... من غير عي بهم ولاخرس)\n(تقوت أفراسهم نساؤهم ... يزجون أجمالهم مع الغلس)\n(صادفت لما خرجت منطلقا ... جهم المحيا كباسل شرس)\n(فجال في كفه مثقفة ... تلمع فيها كشعلة القبس)\n(بكف حران ثائر بدم ... طلاب وتر في الموت منغمس)\n(إما تقارش بك الرماح فلا ... أبكيك إلا للدلو والمرس)\n(حمدت أمري ولمت أمرك إذ ... أمسك جلز السنان بالنفس)\n(وقد تصليت حر نارهم ... كما تصلى المقرور من قرس)\n(تذب عنه كف بها رمق ... طيرا عكوفا كزور العرس)\n(عما قليل علون جثته ... فهن من والغ ومنتهس)"},{"id":"tabaqat-shuara:796","bookId":"tabaqat-shuara","type":"section","seq":796,"chapter":"طبقات فحول الشعراء","title":"798- فلما فرغ أبو زبيد من قصيدته بعثت إليه بنو تغلب بدية غلامه وما ذهب من إبله فقال في ذلك —","page":"ج2 ص611","text":"فلما فرغ أبو زبيد من قصيدته بعثت إليه بنو تغلب بدية غلامه وما ذهب من إبله فقال في ذلك\n(إلا أبلغ بني عمرو رسولا ... فإني في مودتكم نفيس)"},{"id":"tabaqat-shuara:797","bookId":"tabaqat-shuara","type":"section","seq":797,"chapter":"طبقات فحول الشعراء","title":"799- ويقال إن أزد عمان قتلت رجلا من طييء فقال في ذلك أبو زبيد —","page":"ص0","text":"ويقال إن أزد عمان قتلت رجلا من طييء فقال في ذلك أبو زبيد\n(بلغا طيئا جميعا وشتى ... ولسعد مما أقول نصيب)\n(إنهم إخوة أبوهم أبونا ... غير دعوى والنائبات تنوب)\n(قتلتنا سيوف أزد عمان ... سفها والدهور فيها العجيب)\n(من دم ضائع تغيب عنه ... أقربوه إلا الصدى والجبوب)\n(يابن سلمى وللنجيبة سلمى ... ولقد ينجل النجيب النجيب)\n(ليتني مت إذ دعونك إذ تدعو ... تميما ولا حميم يجيب)\n(ليت شعري بك ابن أم عميس ... إن قلبي مما شهدت مريب)\n(غبت عنه وأنت لم تك عنه ... غائبا والمليك رب حسيب)\n(ركبوا ما تهيب الناس منا ... قد عمرنا وعزنا مرهوب)"},{"id":"tabaqat-shuara:798","bookId":"tabaqat-shuara","type":"section","seq":798,"chapter":"طبقات فحول الشعراء","title":"800- وقال أيضا يرثي ابن أخته اللجلاج وكان من أحب الناس إليه وجزع عليه جزعا شديدا —","page":"ج2 ص614","text":"وقال أيضا يرثي ابن أخته اللجلاج وكان من أحب الناس إليه وجزع عليه جزعا شديدا\n(غير أن اللجلاج قد هد ركنى ... يوم فارقته بأعلى الصعيد)\n(في ضريح عليه عبء ثقيل ... من تراب وجندل منضود)"},{"id":"tabaqat-shuara:799","bookId":"tabaqat-shuara","type":"section","seq":799,"chapter":"طبقات فحول الشعراء","title":"801- أخبرني أبو خليفة في كتابه إلي قال حدثنا محمد بن — سلام الجمحي قال حدثنا أبو الغراف قال كان ا","page":"ج2 ص614","text":"أخبرني أبو خليفة في كتابه إلي قال حدثنا محمد بن\nسلام الجمحي قال حدثنا أبو الغراف قال كان العجير السلولي دل عبد الملك بن مروان على ماء يقال له مطلوب وكان لناس من خثعم فأنشأ يقول\n(لا نوم إلا غرار العين ساهرة ... إن لم أروع بغيظ أهل مطلوب)\n(إن تشتموني فقد بدلت أيكتكم ... ذرق الدجاج بحفان اليعاقيب)\n(وكنت أخبركم أن سوف يعمرها ... بنو أمية وعدا غير مكذوب)\nقال فركب رجل من خثعم يقال له أمية إلى عبد الملك حتى دخل عليه فقال يا أمير المؤمنين إنما أراد العجير أن يصل إليك وهو شويعر سئآل وحربه عليه فكتب إلى عامله بأن يشد\nيدي العجير إلى عنقه ثم يبعثه في الحديد فبلغ العجير الخبر فركب في الليل حتى أتى عبد الملك\nفقال يا أمير المؤمنين أنا عندك فاحتبسني وابعث من يبصر الأرضين والضياع فإن لم يكن الأمر على ما أخبرتك فلك دمي حل وبل فبعث فاتخذ ذلك الماء ضيعة فهو اليوم من خيار ضياع بني أمية"},{"id":"tabaqat-shuara:800","bookId":"tabaqat-shuara","type":"section","seq":800,"chapter":"طبقات فحول الشعراء","title":"802- وقال العجير السلولي —","page":"ج2 ص616","text":"وقال العجير السلولي\n(خلقت جوادا والجواد مثابر ... على جريه ذو علة ويسير)\n(ولا يسبق الغايات مستسلم الصلا ... مغل لأطراف الرماح عثور)\n(ولكن مشيح الركض مستبعد المدى ... إذا ابتل من سجم الحميم طحور)\n(فلا توزعيني إنما يوزع الذي ... به ضعف أوفي القيام فتور)\n(ولا تزدريني وانظري ما خليقتي ... إذا ضاف أمر أو أناخ أمير)\n(فإن بني كعب رجال كأنهم ... ليوث الشرى سدت بهن ثغور)\n(تحلب أيديهم نجيعا ونائلا ... إذا البزل لم يصبح بهن درور)\n(مروها بأطراف العوالي فأسبلت ... نجيعا له تحت اللبان خرير)\n(مقيمين لا تعتاد إلا وجدتهم ... كما بالرحا من صاحتين صخور)\n(إذا غار منهم كوكب ناء كوكب ... لأني الندى جم الفراغ مطير)\n(وإن هبطوا بينا أذلوا ترابه ... فأضحى وفيه مورد وصدور)"},{"id":"tabaqat-shuara:801","bookId":"tabaqat-shuara","type":"section","seq":801,"chapter":"طبقات فحول الشعراء","title":"803- وقال يذم ابن عم له ويرثي سليم بن زيد السلولي —","page":"ج2 ص618","text":"وقال يذم ابن عم له ويرثي سليم بن زيد السلولي\n(الأجبل الشم بعدما ... دجا الليل واجتر الجمال القوامح)\n(نهارك ما فيه ليان ولا قرى ... لعين وأيام ابن زيد صوالح)\n(وذاك ابن عم الصدق أما عطاؤه ... فجزل وأما صدره فهو ناصح)\n(وكان شفاء غير داء دنوه ... إذا احول أبصار العيون اللوامح)\n(إذا قال لي قم قلت بل أنت فاكفني ... فقام فجلى أبيض الوجه واضح)"},{"id":"tabaqat-shuara:802","bookId":"tabaqat-shuara","type":"section","seq":802,"chapter":"طبقات فحول الشعراء","title":"804- وقال العجير وخرج هو وابنه القيل وكان مسنا كثير اللحم فخرجا ماشيين في أمر قطبة ابنة الضحاك","page":"ج2 ص620","text":"وقال العجير وخرج هو وابنه القيل وكان مسنا كثير اللحم فخرجا ماشيين في أمر قطبة ابنة الضحاك أخيه فأعي القيل وبلد فذمه العجير ومدح ابنه الآخر واسمه الفرزدق\n(إذا ما لقيت الخاضبات أكفها ... عليهن مقصور الحجال المروق)\n(فلا تجعلن القيل إلا لمزرع ... رواء ولكن الشجاع الفرزدق)\n(سمين وكان الأسمنون خيارنا ... بيوتا وأندانا يداحين نطرق)\n(هو ابني لغراء الجبين نجيبة ... تلقت على طهر به غير أحمق)\n(تداعى لها من أكرم الحي نسوة ... يطفن بكسرى بيتها وهي تطلق)\n(ولكن لعمري إن قتلت لألفين ... سبطرا كإرسال الرديني أعنق)\n(فجاءت بعارى لساعدين كأنه ... من الطيرأ قنى ينفض الطل أزرق)\n(لجوح غداة الفوت حتى كأنه ... حصان يلاقي دعقة الخيل أبلق)"},{"id":"tabaqat-shuara:803","bookId":"tabaqat-shuara","type":"section","seq":803,"chapter":"طبقات فحول الشعراء","title":"805- وقال العجير لموسى بن عبد الرحمن بن عبيدة وأم عبد الرحمن من بني عقيل وأم العجير من بني أسان","page":"ج2 ص622","text":"وقال العجير لموسى بن عبد الرحمن بن عبيدة وأم عبد الرحمن من بني عقيل وأم العجير من بني أسان من بني سعد ابن غنم\n(ألم ترأن الحي حي مبشر ... كفوا غرمهم واستفضل المال حامله)\n(أولئك أخوالي وأخوال ذي القفا ... قبيل توقى بالحجاز معاقله)"},{"id":"tabaqat-shuara:804","bookId":"tabaqat-shuara","type":"section","seq":804,"chapter":"طبقات فحول الشعراء","title":"806- وقال العجير في محمد بن يوسف بن الحكم بن أبي عقيل أخي الحجاج بن يوسف —","page":"ص0","text":"وقال العجير في محمد بن يوسف بن الحكم بن أبي عقيل أخي الحجاج بن يوسف\n(فداك النساء الحتف كم من سرادق ... به البخت والأنباط شهب قنابله)\n(دخلت وأشراف الرجال يرونني ... على سبط الكفين جم فواضله)\n(على يوسفي لوتناخ ركابه ... على البحر أفناه نداه ونائله)"},{"id":"tabaqat-shuara:805","bookId":"tabaqat-shuara","type":"section","seq":805,"chapter":"طبقات فحول الشعراء","title":"807- وقال في عمر بن عبد العزيز —","page":"ص0","text":"وقال في عمر بن عبد العزيز\n(الحمد لله حمدا لا شريك له ... والحمدث لله أما بعد ياعمر)\n(فافرج لنا الباب لا تحبس مطيتنا ... فإن بابك لا ضيق ولا ضرر)"},{"id":"tabaqat-shuara:806","bookId":"tabaqat-shuara","type":"section","seq":806,"chapter":"طبقات فحول الشعراء","title":"808- والثالث عبد الله بن همام السلولي","page":"ص0","text":"والثالث عبد الله بن همام السلولي"},{"id":"tabaqat-shuara:807","bookId":"tabaqat-shuara","type":"section","seq":807,"chapter":"طبقات فحول الشعراء","title":"809- قال حدثني يونس بن حبيب وأبو الغراف قالا كان عبد الله همام رجلا له جاه عند السلطان ووصلة به","page":"ص0","text":"قال حدثني يونس بن حبيب وأبو الغراف قالا كان عبد الله همام رجلا له جاه عند السلطان ووصلة بهم وكان سريا في نفسه له همة تسمو به وكان عند آل حرب مكينا حظيا فيهم\nفكان الذي حدا يزيد بن معاوية على البيعة لابنه معاوية بن يزيد أن عبد الله بن همام السلولي قام إلى يزيد بن معاوية فأنشده شعرا رثى فيه معاوية بن أبي سفيان وحضه على البيعة لابنه معاوية فقال\n(تعزوا يا بني حرب بصبر ... فمن هذا الذي يرجو الخلودا)\n(لعمر مناخهن ببطن جمع ... لقد جهزتم ميتا فقيدا)\n(لقد وارى قليبكم بيانا ... وحلما لا كفاء له وجودا)\n(وجدناه بغيضا في الأعادي ... حبيبا في رعيته حميدا)\n(أمينا مؤمنا لم يقض أمرا ... فيوجد غبه إلا رشيدا)\n(فقد أضحى العدو رخى بال ... وقد أمسى التقى به عميدا)\n(فعاض الله أهل الدين منكم ... ورد لنا خلافتكم جديدا)\n(مجانبة المحاق وكل نحس ... مقارنة الأيامن والسعودا)\n(خلافة ربكم حاموا عليها ... إذا غمزت خنابسة أسودا)\n(تعلمها الكهول المرد حتى ... تذل بها الأكف وتستقيدا)\n(إذا مابان ذو ثقة تلقت ... أخا ثقة بها صنعا مجيدا)\n(تلقفها يزيد عن أبيه ... وخذها يا معاوى عن يزيدا)\n(فإن عرفت لكم فتلقفوها ... ولا ترموا بها الغرض البعيدا)\n(فإن دنيا كم بكم اطمأنت ... فأولوا أهلها خلقا سديدا)\n(وإن ضجرت عليكم فاعصبوها ... عصابا تستدر به شديدا)"},{"id":"tabaqat-shuara:808","bookId":"tabaqat-shuara","type":"section","seq":808,"chapter":"طبقات فحول الشعراء","title":"810- قال وأنشده هذا الشعر أيضا —","page":"ج2 ص628","text":"قال وأنشده هذا الشعر أيضا\n(إنا نقول ويقضى الله مقتدرا ... مهما يدم ربنا من صالح يدم)\n(يزيد يا ابن أبي سفيان هل لكم ... إلى ثناء ومجد غير منصرم)\n(اعزم عزيمة أم غبه رشد ... قبل الوفاة وقطع قالة الكلم)\n(واقدر بقائلكم خذها يزيد فقل ... خذها معاوى لا تعجز ولا تلم)\n(إن الخلافة إن تعرف لثالثكم ... تثبت مراتبها فيكم ولا ترم)\n(ولا تزال وفود في دياركم ... يغشون أبلج سباقا إلى الكرم)\n(يزم أمر قريش غير منتكث ... ولو سما كل قرم منهم قطم)\n(عيشوا وأنتم من الدنيا على حذر ... واستصلحوا جند أهل الشام للبهم)\n(ولا تحلنها في دار غيركم ... إني أخاف عليكم حسرة الندم)\n(وأطعم الله أقواما على قدر ... ولم يحاسبكم في الرزق والطعم)\n(ولا لمن سالك الشورى مشاورة ... إلا بطعن وضرب صائب خذم)\n(أنى تكون لهم شورى وقد قتلوا ... عثمان ضحوا به في أشهر الحرم)\n(خير البرية راعوا المسلمين به ... ملحبا ضرجت أثوابه بدم)\n(وكان قاتله منكم لمصرعه ... مثل الأحيمر إذ قفى على إرم)\n(أو كالدهيم وما كانت مباركة ... أدت إلى أهلها ألفا من اللجم)\n(نفسي فداء الفتى في الحرب لزهم ... حتى تدانوا وألهى الناس بالسلم)\n(وبارك الله في الأرض التي ضمنت ... أوصاله وسقاها باكر الديم)\nفلم تزل في نفس يزيد حتى بايع معاوية ابنه فعاش أربعين ليلة بعد أن أتته البيعة من الآفاق ثم مات فقيل له أوصه فقال ما أحب أن أزودهم الدنيا وأخرج عنها"},{"id":"tabaqat-shuara:809","bookId":"tabaqat-shuara","type":"section","seq":809,"chapter":"طبقات فحول الشعراء","title":"811- وحدثني يونس بن حسان أن عبد الله بن همام كان يسمع أبا عمرة صاحب شرطة المختار واسمه كيسان يذ","page":"ج2 ص631","text":"وحدثني يونس بن حسان أن عبد الله بن همام كان يسمع أبا عمرة صاحب شرطة المختار واسمه كيسان يذكر الشيعة وينال\nمن عثمان فقنعه بالسوط فلما ظهر المختار كان معتزلا حتى استأمن له ابن شداد فجاء إلى المختار فأنشده شعرا له فيه يذكره ويذكر أصحابه فقال\n(ألا انتسأت بالود عنك وأدبرت ... معالنة بالهجر أم سريع)\n(وحملها واش سعى غير مصلح ... فآب بهم في الفؤاد وجيع)\n(فخفض عليك الشأن لا يردك الهوى ... فليس انتقال خلة ببديع)\n(وفي ليلة المختار ما يذهل الفتى ... ويلهيه عن رؤد الشباب شموع)\n(دعا يالثارات الحسين فأقبلت ... كتائب من همدان بعد هزيع)\n(ومن مذحج جاءالرئيس ابن مالك ... يقود جموعا عفيت بجموع)\n(ومن أسد وفي يزيد لنصره ... بكل فتى حامي الذمار منيع)\n(وجاء نعيم خير شيبان كلها ... بأمر لدى الهيجاء جد رفيع)\n(وما ابن شميط إذ يحرض قومه ... هناك بمخذول ولا بمضيع)\n(ولا قيس نهد لا ولا ابن هوازن ... وكان أخا حنانة وخشوع)\n(وسار أبو النعمان لله سعيه ... إلى ابن إياس مصحرا لوقوع)\n(فكر الخيول كرة أتلفتهم ... وشد بأولاها على ابن مطيع)\n(فولى بضرب يفلق الهام وقعه ... وطعن غداة السكتين وجيع)\n(فمر وزير ابن الوصي عليهم ... وكان لهم في الناس خير شفيع)\n(فآب الهدى حقا إلى مستقره ... بخير إياب آبه ورجوع)\n(إلى الهاشمي المهتدى بضيائه ... فنحن له من سامع ومطيع)"},{"id":"tabaqat-shuara:810","bookId":"tabaqat-shuara","type":"section","seq":810,"chapter":"طبقات فحول الشعراء","title":"812- فلما أنشدها المختار قال لأصحابه قد أثنى عليكم كما تسمعون وقد أحسن الثناء فأحسنوا جزاءه ثم","page":"ج2 ص634","text":"فلما أنشدها المختار قال لأصحابه قد أثنى عليكم كما تسمعون وقد أحسن الثناء فأحسنوا جزاءه ثم قال فقال لا تبرحوا حتى أخرج إليكم فقال عبد الله بن شداد فإن له عندي فرسا ومطرفا وقال قيس بن طهفة فإن له عندي فرسا ومطرفا وقال ليزيد بن أنس ما تعطيه قال إن كان ثواب الله أراد بما يقول فما له عند الله خير له وإن اعترى بهذا القول أموالنا فوالله ما في\nأموالنا ما يسعه ثم وقع بينهم كلام شديد فوثب به بعضهم فضمه إبراهيم بن الأشتر إلى نفسه وقال أنا جار له فأنقذه منهم فقال عبد الله بن همام\n(أطفأ عني نار كلبين ألبا ... على الكلاب ذو الفعال ابن مالك)\n(فتى حين يلقى الخيل يفرق بينها ... بطعن دراك أو بضرب مواشك)\n(وقد غضبت لي من هوازن عصبة ... طوال الذرى فيها عزاز المبارك)\n(إذ ابن شميط أو يزيد تعرضا ... لها وقعا في مستحار المهالك)\n(وثبتم علينا يا موالى طامر ... مع ابن شميط شر ماش وراتك)\n(وأعظم جبار على الله فرية ... وما مفتر طاغ كآخر ناسك)\n(كأنهم في العز قيس وخثعم ... وهل أنتم إلا لئام عوارك)"},{"id":"tabaqat-shuara:811","bookId":"tabaqat-shuara","type":"section","seq":811,"chapter":"طبقات فحول الشعراء","title":"813- والرابع نويفع بن لقيط وتارة كان يقول نافع فحدثني أبو الغراف قال كان لنافع بن لقيط امرأة من","page":"ج2 ص636","text":"والرابع نويفع بن لقيط وتارة كان يقول نافع فحدثني أبو الغراف قال كان لنافع بن لقيط امرأة من بني منقذ بن\nجحوان تدعى حية وكان في أخلاقها زعارة وقد كانا تشارا مرة ثم إن قومها أنفوا من ذلك فادعوا عليه طلاقا فقاتلهم حتى كان بينهم جراح وكان مستخفيا من الحجاج فقال وهو مستخف\n(لم يبق مني الكرى يا أم نافع ... ولا الروغ في الحلفاء غير المعارف)\n(إذا قيل هذا فارس طار طيرة ... فؤادي وما فزعت من مثل خائف)\n(ولكنما الغاوي إذا سود اسمه ... بأنقاسه ضيف على السرح واقف)\nفرفعوا أمره إلى الحجاج فبعث إليه نفرا وهو في أجمة الأسود أجمة خفية فأحرق عليه في نواحي الأجمة وقالوا قد كفتنا الأسود والنار أمره فأدركهم الليل فانصرفوا وخلصه الله حتى لحق بقومه بالقنان والعزاف فتزوج ابنة عمه جمهة ابنت شيبان بن مرثد فتغنى يوما فقال\n(وردت بئارا ملحة فكرهتها ... بأهلي أهلي الأولون وماليا)"},{"id":"tabaqat-shuara:812","bookId":"tabaqat-shuara","type":"section","seq":812,"chapter":"طبقات فحول الشعراء","title":"814- قال وأنشدني أبو الغراف عن سليمان الجذامي لنويفع ابن لقيط —","page":"ج2 ص639","text":"قال وأنشدني أبو الغراف عن سليمان الجذامي لنويفع ابن لقيط\n(أدوا إلى ميدان عنكم عرسه ... ودعوا سبابى يا بني عرقوب)\n(إن المخازي قدر ثمن أنوفكم ... رثم الحجارة إصبع المنكوب)\n(لن تهدموا شرفي بلؤم أبيكم ... ونهاق عير فيكم مكروب)"},{"id":"tabaqat-shuara:813","bookId":"tabaqat-shuara","type":"section","seq":813,"chapter":"طبقات فحول الشعراء","title":"815- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(وإياك والظلم المبين إنني ... أرى الظلم يغشى بالرجال المغاشيا)\n(أتجمع إن كنت ابن تقن فطانة ... وتغلب أحيانا وتأتي الدواهيا)\n(إذا أنت أكثرت المجاهل كدرت ... وعليك من الأخلاق ما كان صافيا)\n(فلا تك حفارا بظلفك إنما ... تصيب سهام الغي من كان غاويا)\n(ألا إن آبائي على كل موطن ... وخال أبي لم يورثوني المخازيا)\n(أبا حوالنا المجد التليد وإنهم ... لمنبت زندى الفروع الأعاليا)"},{"id":"tabaqat-shuara:814","bookId":"tabaqat-shuara","type":"section","seq":814,"chapter":"طبقات فحول الشعراء","title":"816- قال وأنشدني محمد بن أنس الحذلمي الأسدي عن — أعراب بني أسد أنه قال في الحجاج بن يوسف —","page":"ص0","text":"قال وأنشدني محمد بن أنس الحذلمي الأسدي عن\nأعراب بني أسد أنه قال في الحجاج بن يوسف\n(لو كنت في العنقاء أوفي عماية ... ظننتك إلا أن تصد تراني)\n(أسهد من نوم العشاء كأنني ... سليم يغر الضرو بالنبوان)\n(عليه تميمات كأن فؤاده ... جناحا عقاب دائم الخفقان)\n(تضيق بي الأرض الفضاء لخوفه ... وإن كنت قد طوفت كل مكان)\n(وآليت لا آتيك إلا مسالما ... معي منك يا ابن الأكرمين أماني)\n(وما العرق كانت لي بدار إقامة ... ولا الجو منها كان لي بمغاني)\n(أعوذ بقبرى يوسف وابن يوسف ... أخيك وبالقبر الذى بعدان)\n(سمى نبي الله من أن تنالني ... يداك ومن يغتر بالحدثان)"},{"id":"tabaqat-shuara:815","bookId":"tabaqat-shuara","type":"section","seq":815,"chapter":"طبقات فحول الشعراء","title":"817- قال وكان نويفع من رجالات العرب شعرا ونجدة وكان ربما أخاف السبيل فأطرده الحجاج لجناية فلم ي","page":"ج2 ص644","text":"قال وكان نويفع من رجالات العرب شعرا ونجدة وكان ربما أخاف السبيل فأطرده الحجاج لجناية فلم يزل خائفا"},{"id":"tabaqat-shuara:816","bookId":"tabaqat-shuara","type":"section","seq":816,"chapter":"طبقات فحول الشعراء","title":"818- حجازية أربعة رهط","page":"ص0","text":"حجازية أربعة رهط"},{"id":"tabaqat-shuara:817","bookId":"tabaqat-shuara","type":"section","seq":817,"chapter":"طبقات فحول الشعراء","title":"819- عبد الله بن قيس بن شريح بن مالك بن ربيعة بن أهيب ابن ضباب بن حجير بن عبد بن معيص بن عامر ب","page":"ص0","text":"عبد الله بن قيس بن شريح بن مالك بن ربيعة بن أهيب ابن ضباب بن حجير بن عبد بن معيص بن عامر بن لؤي بن غالب من قريش الظواهر وإنما نسب إلى الرقيات لأن جدات له توالين يسمين رقية\nوالأحوص عبد الله بن محمد بن عاصم بن ثابت بن قيس وهو أبو الأقلح شهد عاصم بدرا وقتل يوم الرجيع وحمته الدبر وهو من الأوس"},{"id":"tabaqat-shuara:818","bookId":"tabaqat-shuara","type":"section","seq":818,"chapter":"طبقات فحول الشعراء","title":"821- وجميل بن معمر بن خيبري بن ظبيان بن حن بن ربيعة بن حرام بن ضنة بن عبد بن كبير بن عذرة بن سع","page":"ص0","text":"وجميل بن معمر بن خيبري بن ظبيان بن حن بن ربيعة بن حرام بن ضنة بن عبد بن كبير بن عذرة بن سعد بن زيد بن ليث بن سود بن أسلم بن الحاف بن قضاعة"},{"id":"tabaqat-shuara:819","bookId":"tabaqat-shuara","type":"section","seq":819,"chapter":"طبقات فحول الشعراء","title":"822- ونصيب مولى عبد العزيز بن مروان بن الحكم بن أبي العاص","page":"ص0","text":"ونصيب مولى عبد العزيز بن مروان بن الحكم بن أبي العاص"},{"id":"tabaqat-shuara:820","bookId":"tabaqat-shuara","type":"section","seq":820,"chapter":"طبقات فحول الشعراء","title":"823- فحدثني يونس حبيب قال كان عبد الله بن قيس الرقيات أشد قريش أسر شعر في الإسلام بعد ابن الزبع","page":"ص0","text":"فحدثني يونس حبيب قال كان عبد الله بن قيس الرقيات أشد قريش أسر شعر في الإسلام بعد ابن الزبعري وكان غزلا وأغزل من شعره شعر عمر بن أبي ربيعة وكان عمر يصرح بالغزل ولد يهجو ولا يمدح وكان عبد الله يشبب ولا يصرح ولم يكن له\nمعقود عشق وغزل كعمر بن أبي ربيعة"},{"id":"tabaqat-shuara:821","bookId":"tabaqat-shuara","type":"section","seq":821,"chapter":"طبقات فحول الشعراء","title":"824- وكان انقطاعه إلى آل الزبير فمدح مصعبا وهجا عبد الملك بن مروان وذلك حين يقول —","page":"ص0","text":"وكان انقطاعه إلى آل الزبير فمدح مصعبا وهجا عبد الملك بن مروان وذلك حين يقول\n(إنما مصعب شهاب من الله ... تجلت عن وجهه الظلماء)\n(ملكه ملك قوة ليس فيه ... جبروت ولا له كبرياء)\n(يتقى الله في الأمور وقد أفلح ... من كان همه الاتقاء)\nوقال لعبد الملك فيها\n(قد رضينا فمت بدائك غيظا ... لاتميتن غيرك الأدواء)\nوالأحوص عبد الله بن محمد بن عاصم بن ثابت بن قيس وهو أبو الأقلح شهد عاصم بدرا وقتل يوم الرجيع وحمته الدبر وهو من الأوس"},{"id":"tabaqat-shuara:822","bookId":"tabaqat-shuara","type":"section","seq":822,"chapter":"طبقات فحول الشعراء","title":"821- وجميل بن معمر بن خيبري بن ظبيان بن حن بن ربيعة بن حرام بن ضنة بن عبد بن كبير بن عذرة بن سع","page":"ص0","text":"وجميل بن معمر بن خيبري بن ظبيان بن حن بن ربيعة بن حرام بن ضنة بن عبد بن كبير بن عذرة بن سعد بن زيد بن ليث بن سود بن أسلم بن الحاف بن قضاعة"},{"id":"tabaqat-shuara:823","bookId":"tabaqat-shuara","type":"section","seq":823,"chapter":"طبقات فحول الشعراء","title":"822- ونصيب مولى عبد العزيز بن مروان بن الحكم بن أبي العاص","page":"ص0","text":"ونصيب مولى عبد العزيز بن مروان بن الحكم بن أبي العاص"},{"id":"tabaqat-shuara:824","bookId":"tabaqat-shuara","type":"section","seq":824,"chapter":"طبقات فحول الشعراء","title":"823- فحدثني يونس حبيب قال كان عبد الله بن قيس الرقيات أشد قريش أسر شعر في الإسلام بعد ابن الزبع","page":"ص0","text":"فحدثني يونس حبيب قال كان عبد الله بن قيس الرقيات أشد قريش أسر شعر في الإسلام بعد ابن الزبعري وكان غزلا وأغزل من شعره شعر عمر بن أبي ربيعة وكان عمر يصرح بالغزل ولد يهجو ولا يمدح وكان عبد الله يشبب ولا يصرح ولم يكن له\n(حيث لم تأت قبله خيل ذي الأكتاف ... يوجفن بين قف ومرج)\n(أنزلوا من حصونهن بنات الترك ... يأتين بعد عرج بعرج)\n(كل خرق سميدع وشنون ... ساهم الوجه تحت أحناء سرج)\n(يلبس الجيش بالجيوش ويسقي ... لبن البخت في عساس الخلنج)"},{"id":"tabaqat-shuara:825","bookId":"tabaqat-shuara","type":"section","seq":825,"chapter":"طبقات فحول الشعراء","title":"827- وقال في عبد الملك لما أخذ عبد الله بن جعفر ذي الجناحين الأمان له —","page":"ج2 ص652","text":"وقال في عبد الملك لما أخذ عبد الله بن جعفر ذي الجناحين الأمان له\n(عاد له من كثيرة الطرب ... فعينه بالدموع تنسكب)\n(كوفية نازح محلتها ... لا أمم دارها ولا سقب)\nثم قال\n(ما نقموا من بني أمية إلا ... أنهم يحلمون إن غضبوا)\n(وأنهم معدن الملوك فلا ... تصلح إلا عليهم العرب)\n(إن الفنيق الذي أبوه أبو العاصي ... عليه الوقار والحجب)\n(خليفة الله فوق منبره ... جفت بذاك الأقلام والكتب)\n(يعتدل التاج فوق مفرقه ... على جبين كأنه الذهب)\n(أحفظهم قومهم بباطلهم ... حتى إذا حاربوهم حربوا)\n(تجردوا يطلبون باطلهم ... بالحق حتى تبين الكذب)\n(قوم هم الأكثرون قبص حصى ... في الناس والأكرمون إن نسبوا)"},{"id":"tabaqat-shuara:826","bookId":"tabaqat-shuara","type":"section","seq":826,"chapter":"طبقات فحول الشعراء","title":"828- والثاني الأحوص فحدثني أبي عمن حدثه أحسبه — قال عن الزهري قال كان الأحوص الشاعر يشبب بنساء أه","page":"ج2 ص654","text":"والثاني الأحوص فحدثني أبي عمن حدثه أحسبه\nقال عن الزهري قال كان الأحوص الشاعر يشبب بنساء أهل المدينة فتأذوا به وكان معبد وغيره من المغنين يغنون في شعره فشكاه قومه فبلغ ذلك سليمان بن عبد الملك فكتب إلى عامله بالمدينة أن يضربه مئة سوط ويقيمه على البلس للناس ويسيره إلى دهلك ففعل به فثوى بها سلطان سليمان وعمر بن عبد العزيز فأتى رجال من الأنصار عمر بن عبد العزيز فسألوه أن يرده وقالوا قد عرفت نسبه وموضعه من قومه وقد أخرج إلى أرض الشرك فنطلب إليك أن ترده إلى حرم رسول الله صلى الله عليه ودار قومه فقال عمر من الذي يقول\n(فما هو إلا أن أراها فجاءه ... فأبهت حتى ما أكاد أجيب)\nقالوا الأحوص قال فمن الذي يقول\n(أدور ولولا أن أرى أم جعفر ... بأبياتكم مادرت حيث أدور)\nقالوا الأحوص قال فمن الذي يقول\n(سيلقى لها في القلب في مضمر الحشا ... سريرة حب حين تبلى السرائر)\nقالوا الأحوص قال إنه يومئذ عنها لمشغول والله الا أرده ما كان لي سلطان فمكث هناك بقية ولاية عمر وصدرا من ولاية يزيد بن عبد الملك ثم استخلف يزيد بن عبد الملك فبينا يزيد على سطح وحبابة جاريته تغنيه بشعر الأحوص إذ قال يزيد من يقول هذا الشعر قالت لا وعيشك ما أدري قال وقد كان ذهب من الليل شطره قال ابعثوا إلى الزهري فعسى أن يكون عنده علم من ذلك فأتى ابن شهاب الزهري فقرع بابه فخرج فزعا حتى أتي يزيد فلما صعد إليه قال لا بأس عليك لم ندعك إلا لخير\nاجلس فجلس يقال من الذى يقول هذا الشعر قال الأحوص يا أمير المؤمنين قال فما فعل قال قد طال حبسه بدهلك قال عجيب لعمر بن عبد العزيز كيف أغفله فأمر بالكتاب بتخلية سبيله وأمر له بأربعمئة دينار\nفأقبل الزهري من ليلته إلى ناس من الأنصار فبشرهم بتخلية سبيل الأحوص ثم قدم عليه فأجازه وأحسن إليه"},{"id":"tabaqat-shuara:827","bookId":"tabaqat-shuara","type":"section","seq":827,"chapter":"طبقات فحول الشعراء","title":"829- وحدثنى أبو الغراف عمن يثق به قال بعث يزيد ابن عبد الملك حين قتل يزيد بن المهلب إلى الشعراء","page":"ج2 ص657","text":"وحدثنى أبو الغراف عمن يثق به قال بعث يزيد ابن عبد الملك حين قتل يزيد بن المهلب إلى الشعراء فأمرهم بهجاء يزيد وأهل بيته منهم الفرزدق وكثير والأحوص فقال الفرزدق لقد امتدحت بنى المهلب بمدح ما امتدحت بمثله أحدا وإنه لقبيح بمثلى أن يكذب نفسه على رأس الكبر فليعفنى أمير المؤمنين\nفأعفاه وقال كثير إنى لأكره أن أعرض نفسى وقومى لشعراء أهل العراق إن هجوت بنى المهلب وأما الأحوص فإنه هجاهم فلما بعث به يزيد بن عبد الملك إلى الجراح بن عبد الله الحكمى وهو\nبأذربيجان وقد كان بلغ الجراح هجاء الأحوص بنى المهلب فبعث إليه بزق من خمر فأدخل منزل الأحوص ثم بعث إليه خيلا فدخلوا منزله فصبوا الخمر على رأسه ثم أخرجوه على رؤوس الناس وأتوا به الجراح فأمر به فحلق رأسه ولحيته وضربه الحد يتراوحه الرجال وهو يقول ليس هكذا تضرب الحدود فجعل الجراح يقول صدقت أجل ولكن لما تعلم ثم كتب إلى يزيد بن عبد الملك بالذى كان من أمره فأغضى له عليها"},{"id":"tabaqat-shuara:828","bookId":"tabaqat-shuara","type":"section","seq":828,"chapter":"طبقات فحول الشعراء","title":"830- فمما قال الأحوص قال يمدح عبد العزيز بن مروان —","page":"ص0","text":"فمما قال الأحوص قال يمدح عبد العزيز بن مروان\n(أقول بعمان وهل طربى به ... إلى أهل سلع إن تشوفت نافع)\n(أصاح ألم تحزنك ريح مريضة ... وبرق تلالا بالعقيقين رافع)\n(فإن الغريب الدار مما يشوقه ... نسيم الرياح والبروق اللوامع)\n(نظرت على فوت وأوفى عشية ... بنا منظر من حصن عمان يافع)\n(وللعين أسراب تفيض كأنما ... تعل بكحل الصاب منها المدامع)\n(لأبصر أحياء بخاخ تضمنت ... منازلهم منها التلاع الدوافع)\n(فأبدت كثيرا نظرتى من صبابتى ... وأكثر منها ما تجن الأضالع)\n(وكيف اشتياق المرء يبكى صبابة ... إلى من نأى عن داره وهو طائع)\n(لعمر ابنة الزيدى إن ادكارها ... على كل حال للفؤاد لرائع)\n(وإنى لذكراها على كل حالة ... من الغور أو جلس البلاد لنازع)\n(لقد كنت أبكى والنوى مطمئنة ... بناوبكم من علم ما البين صانع)\n(وقد ثبتت فى الصدر منها مودة ... كما ثبتت فى الراحتين الأصابع)\n(أهم لأنسى ذكرها فيشوقنى ... رفاق إلى أهل الحجاز نوازع)\n(وإنا عدانا عن بلاد نحبها ... إمام دعانا نفعه المتتابع)\n(أغر لمروان وليلى كأنه ... حسام جلت عنه الصياقل قاطع)\n(هو الفرع من عبدى مناف كليهما ... إليه انتهت أحسابها والدسائع)\n(فكل غنى قانع بفعاله ... وكل عزيز عنده متواضع)\n(هو الموت أحيانا يكون وإنه ... لغيث حيا يحيى به الناس واسع)"},{"id":"tabaqat-shuara:829","bookId":"tabaqat-shuara","type":"section","seq":829,"chapter":"طبقات فحول الشعراء","title":"831- وهو الذى يقول —","page":"ج2 ص662","text":"وهو الذى يقول\n(إنى إذا جهل اللئام رأيتنى ... كالشمس لا تخفى بكل مكان)\n(ما من مصيبة نكبة أمنى بها ... إلا تشرفنى وترفع شانى)\n(فتزول حين تزول عن متخمط ... تخشى بوادره على الأقران)"},{"id":"tabaqat-shuara:830","bookId":"tabaqat-shuara","type":"section","seq":830,"chapter":"طبقات فحول الشعراء","title":"832- وحدثنى أبى سلام بن عبيد الله قال بلغنى أن مسلمة بن عبد الملك قال ليزيد بن عبد الملك يا أمي","page":"ج2 ص662","text":"وحدثنى أبى سلام بن عبيد الله قال بلغنى أن مسلمة بن عبد الملك قال ليزيد بن عبد الملك يا أمير المؤمنين ببابك وفود الناس وتقف ببابك أشراف العرب فلا تجلس لهم وأنت قريب عهد بعمر بن عبد العزيز وقد أقبلت على هؤلاء الإماء قال أرجو أن لا تعاتبنى على هذا بعد اليوم فلما خرج مسلمة من عنده استلقى على فراشه وجاءت حبابة جاريته فلم يكلمها فقالت ما دهاك عنى\nفأخبرها بما قال مسلمة وقال تنحى عنى حتى أفرغ للناس قالت فأمتعنى منك مجلسا واحدا ثم اصنع ما بدا لك قال نعم فقالت لمعبد كيف الحيلة قال يقول الأحوص أبياتا وتغنى فيها قالت نعم فقال الأحوص\n(ألا لا تلمه اليوم أن يتبلدا ... فقد غلب المحزون أن يتجلدا)\n(إذا كنت عزهاة عن اللهو والصبا ... فكن حجرا من يابس الصخر جلمدا)\n(فما العيش إلا ما تلذ وتشتهى ... وإن لام فيه ذو الشنان وفندا)\nفغنى فيه معبد وقال مررت البارحة بدير نصارى وهم يقرأون بصوت شج فحكيته فى هذا الصوت فلما غنته حبابة هذا الصوت قال لعن الله مسلمة صدقت والله لا أطيعهم أبدا"},{"id":"tabaqat-shuara:831","bookId":"tabaqat-shuara","type":"section","seq":831,"chapter":"طبقات فحول الشعراء","title":"833- ومن قوله أيضا —","page":"ج2 ص664","text":"ومن قوله أيضا\n(أمن آل سلمى الطارق المتأوب ... ألم وبيش دون سلمى وكبكب)\n(فكدت اشتياقا إذ ألم خيالها ... أبوح ويبدو من هواى المغيب)\n(ويوما بذي بيش ظللت تشوقا ... لعينيك أسراب من الدمع تسكب)\n(أتيحت لنا إحدى كلاب بن عامر ... وقد يقدر الحين البعيد ويجلب)\n(بأرض نأى عنها الصديق وغالني ... بها منزل عن طية الحي أجنب)\n(وما هربت من حاجة نزلت بها ... ولكنها من خشية الجزم تهرب)\n(أقامت ببيش في ظلال ونعمة ... لها قيم يخشى الجرائر مذنب)\n(غريب نأى عن أرضه وسمائه ... ليحيى وطول)"},{"id":"tabaqat-shuara:832","bookId":"tabaqat-shuara","type":"section","seq":832,"chapter":"طبقات فحول الشعراء","title":"834- أخبرنا أبو غانم قال أخبرنا أبو خليفة قال حدثني محمد ابن سلام قال حدثني محمد بن أبان أن الأ","page":"ص0","text":"أخبرنا أبو غانم قال أخبرنا أبو خليفة قال حدثني محمد ابن سلام قال حدثني محمد بن أبان أن الأحوص بن محمد الشاعر كان يهوى أخت امرأته ويكتم ذلك وينسب بها ولا يفصح باسمها فتزوجها مطر فبلغه الأمر فأنشأ يقول\n(أأن نادى هديلا ذات فلج ... مع الإشراق في فنن حمام)\n(ظللت كأن دمعك در سلك ... هوى نسقا وأسلمه النظام)\n(تموت تشوقا طربا وتحيي ... وأنت جو بدائك مستهام)\n(كأنك من تذكر أم حفص ... وحبل وصالها خلق رمام)\n(صريع مدامة غلبت عليه ... تموت لها المفاصل والعظام)\n(وأنى من ديارك أم حفص ... سقى بلدا تحل به الغمام)\n(أحل النعف من أحد وأدنى ... مساكنها الشبيكة أو سنام)\n(سلام الله يا مطر عليها ... وليس عليك يا مطر السلام)\n(ولا غفر الإله لمنكحيها ... ذنوبهم وإن صلوا وصاموا)\n(كأن المالكين نكاح سلمى ... غداة يرومها مطر نيام)\n(فإن يكن النكاح أحل شيئا ... فإن نكاحها مطر حرام)\n(فلو لم ينكحوا إلا كفيا ... لكان كفيها ملك همام)\n(فطلقها فلست لها بأهل ... وإلا عض مفرقك الحسام)"},{"id":"tabaqat-shuara:833","bookId":"tabaqat-shuara","type":"section","seq":833,"chapter":"طبقات فحول الشعراء","title":"835- أخبرني أبو خليفة عن محمد بن سلام عن سالم بن أبي السمحاء وكان صاحب حماد الراوية أن حمادا كا","page":"ج2 ص667","text":"أخبرني أبو خليفة عن محمد بن سلام عن سالم بن أبي السمحاء وكان صاحب حماد الراوية أن حمادا كان يقدم الأحوص في النسيب"},{"id":"tabaqat-shuara:834","bookId":"tabaqat-shuara","type":"section","seq":834,"chapter":"طبقات فحول الشعراء","title":"836- الثالث جميل بن معمر فحدثني أبو الغراف عن الأخيل ابن أبي الأخيل قال حدثني أدهم التميمي قال","page":"ص0","text":"الثالث جميل بن معمر فحدثني أبو الغراف عن الأخيل ابن أبي الأخيل قال حدثني أدهم التميمي قال لقيني كثير عزة فقال لقيني جميل بن معمر في هذا الموضع الذي لقيتك فيه فقال من أين أقبلت قلت من عند أبي الحبيبة أعني أبا بثينة ثم قال لي وإلى أين تريد قلت إلى الحبيبة أعني عزة قال لابد من أن ترجع عودك على بدئك فتستجد لي موعدا قلت فإن عهدى بأبيها الساعة وأنا أستحى قال لابد من ذلك قلت فمتى عهدك بهم قال بالدوم وهم يرحضون ثيابهم فأتيت أباها قال ماردك يا ابن أخي قلت أبيات عرضت أحببت أن أعرضها عليك قال هات فأنشدته\n(فقلت لها يا عزأرسل صاحبي ... على نأي دار والموكل مرسل)\n(بأن تجعلي بيني وبينك موعدا ... وأن تأمريني ما الذي فيه أفعل)\n(وآخر عهد منك يوم لقيتني ... بأسفل وادي الدوم والثوب يغسل)\nفضربت بثينة جانب الخدر وقالت اخسأ اخسأ قال أبوها مهيم يا بثينة قالت كلب يأتينا إذا نوم الناس من وراء الرابية قال فأتيته فأخبرته أنها قد وعدته إذا نوم الناس من وراء الرابية"},{"id":"tabaqat-shuara:835","bookId":"tabaqat-shuara","type":"section","seq":835,"chapter":"طبقات فحول الشعراء","title":"837- ومن قوله —","page":"ص0","text":"ومن قوله\n(ما من قرينة آلف لقرينه ... إلا لحبل قرينها إقصار)\n(وإذا أردت ولا يخونك كاتم ... حتى يشيع حديثك الإظهار)\n(كتمان سرك يا بثين وإنما ... عند الأمين تغيب الأسرار)"},{"id":"tabaqat-shuara:836","bookId":"tabaqat-shuara","type":"section","seq":836,"chapter":"طبقات فحول الشعراء","title":"838- ومن قوله —","page":"ص0","text":"ومن قوله\n(ويحسب نسوان من الحي أنني ... إذا جئت إياهن كنت أريد)\n(فأقسم طرفي بينهن فيستوي ... وفي الصدر بون بينهن بعيد)\n(ألا ليت شعري هل أبيتن ليلة ... بوادي القرى إني إذا لسعيد)\n(وهل ألقين سعدى من الدهر مرة ... وما مر من عصر الشباب جديد)\n(ومن يعط في الدنيا قرينا كمثلها ... فذلك في عيش الحياة رشيد)\n(يموت الهوى منى إذا ما لقيتها ... ويحيى إذا فارقتها فيعود)"},{"id":"tabaqat-shuara:837","bookId":"tabaqat-shuara","type":"section","seq":837,"chapter":"طبقات فحول الشعراء","title":"839- ومن قوله —","page":"ص0","text":"ومن قوله\n(وكنا إذا ما معشر جحفوا بنا ... ومرت جواري طيرهم وتعيفوا)\n(وضعنا لهم صاع القصاص رهينة ... وسوف نوفيها إذا الناس طففوا)\n(ترى الناس ماسرنا يسيرون خلفنا ... وإن نحن أومأنا إلى الناس وقفوا)\nفشد الفرزدق على هذا البيت وقال أنا أحق به وقال لا تعد فيه فلم يكترث له\n(برزنا وأصحرنا لكل قبيلة ... بأسيافنا إذ يؤكل المتضعف)\n(فأي معد كان فىء رماحه ... كما قد أفأنا والمفاخر منصف)\n(ونحن منعنا يوم أود ذمارنا ... ويوم أخي والأسنة ترعف)\n(ونحن حمينا يوم مكة بالقنا ... قصيا وأطراف القنا تتقصف)\n(فحطنالهم أكناف مكة بعدما ... أرادات بها ماقد أبي الله خندف)"},{"id":"tabaqat-shuara:838","bookId":"tabaqat-shuara","type":"section","seq":838,"chapter":"طبقات فحول الشعراء","title":"840- وقال يمدح عبد العزيز بن مروان —","page":"ج2 ص672","text":"وقال يمدح عبد العزيز بن مروان\n(إلى القرم الذي فاتت يداه ... بفعل العرف سطوة من ينيل)\n(إذا ما أغلي الحمد اشتراه ... فما إن يستقيل ولا يقيل)\n(أمين الصدر يحفظ ما تولى ... بما يكفي القوى به النبيل)\n(أبا مروان أنت فتى قريش ... وكهلهم إذا عد الكهول)\n(توليه العشيرة ما عناها ... فلا ضيق الذراع ولا بخيل)\n(إليك تشير أيديهم إذا ما ... رضوا أو غالهم أمر جليل)\n(كلا يوميه بالمعروف طلق ... وكل فعاله حسن جميل)\n(نما بك في الذؤابة من قريش ... بناة المجد والعز الأثيل)\n(أروم ثابت يهتز فيه ... بأكرم منبت فرع طويل)"},{"id":"tabaqat-shuara:839","bookId":"tabaqat-shuara","type":"section","seq":839,"chapter":"طبقات فحول الشعراء","title":"841- والرابع نصيب مولى عبد العزيز بن مروان فحدثني أبو الغراف قال مر جرير بنصيب وهو ينشد فقال له","page":"ج2 ص674","text":"والرابع نصيب مولى عبد العزيز بن مروان فحدثني أبو الغراف قال مر جرير بنصيب وهو ينشد فقال له اذهب فأنت أشعر أهل جلدتك وكان نصيب أسود فقال وجلدتك يا أبا حزرة"},{"id":"tabaqat-shuara:840","bookId":"tabaqat-shuara","type":"section","seq":840,"chapter":"طبقات فحول الشعراء","title":"842- وحدثني أبو اليقظان قال حدثني جويرية بن أسماء قال قلت لنصيب مولى عبد العزيز يا أبا محجن من","page":"ج2 ص674","text":"وحدثني أبو اليقظان قال حدثني جويرية بن أسماء قال قلت لنصيب مولى عبد العزيز يا أبا محجن من أشعر الناس قال أخو بني تميم قلت ثم من قال أنا فقلت ثم من قال ابن يسار فلقيت إسماعيل بن يسار فقلت من أشعر الناس قال أخو\nبني تميم قلت ثم من قال أنا قلت ثم من قال نصيب قلت إنكما لتقارضان الثناء قال وما ذاك قلت لقيت نصيبا فقال فيك ما قلت فيه قال إنه لشاعر والله كريم ولا أظنه إلا بدأ بابن يسار قبل نصيب"},{"id":"tabaqat-shuara:841","bookId":"tabaqat-shuara","type":"section","seq":841,"chapter":"طبقات فحول الشعراء","title":"843- فمن قوله —","page":"ص0","text":"فمن قوله\n(حريب أصاب المال من بعد ثروة ... لديه فأضحى وهو أسوان معدم)\n(فإن تك ليلى العامرية أصبحت ... على النأى منى غير ذنبى تنقم)\n(فما ذاك من ذنب أكون اجتنيته ... إليها فتجريني به حيث أعلم)\n(ولكن إنسانا إذا مل صاحبا ... وحاول صرما لم يزل يتجرم)"},{"id":"tabaqat-shuara:842","bookId":"tabaqat-shuara","type":"section","seq":842,"chapter":"طبقات فحول الشعراء","title":"844- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(وكيف يقودني كلف بسعدى ... وهذا الشيب أصبح قد علاني)\n(وودعني الشباب وكنت أسعى ... إلى داعي الشباب إذا دعاني)\n(فإن يفن الشباب فكل شىء ... من الدنيا فلا يغررك فاني)\n(ولو إني بقيت لمسى ليل ... وصبح نهاره يتداولاني)\n(صحيحا لا ألاقي الموت حتى ... أدب على القناة لأبلياني)"},{"id":"tabaqat-shuara:843","bookId":"tabaqat-shuara","type":"section","seq":843,"chapter":"طبقات فحول الشعراء","title":"845- وقال يذكر الحكم بن أبي بكر بن عبد العزيز —","page":"ص0","text":"وقال يذكر الحكم بن أبي بكر بن عبد العزيز\n(في قرى مجد وجدت له ... فراط مكرمة كانوا لنا قدما)\n(ملك تقود الناس كلهم ... قود الجنائب خضعا تتبع الخزما)\n(بلادا أن يصاب به ... حق وإن نسبوا فالقوم من كرما)\n(ستعمل الأنضاء دائبة ... في الخرق لابسة أعلامها قتما)\n(قن مروق النبل من علم ... مرت أخذن بنا من بعده علما)\n(أتتك بنا خوصا مقدمة ... قد باشرت بعد غرب الجدة الخدما)"},{"id":"tabaqat-shuara:844","bookId":"tabaqat-shuara","type":"section","seq":844,"chapter":"طبقات فحول الشعراء","title":"846- ومن قوله أيضا —","page":"ص0","text":"ومن قوله أيضا\n(الصبا والرأس قد ظهرت به ... روائع شيب هزعته عواسله)\n(الشباب فإنه ... أخ لك إن طالت حياتك عاذله)\n(ثوبيه الجديدين بعدما ... لبستهما حينا وعادت مباذله)"},{"id":"tabaqat-shuara:845","bookId":"tabaqat-shuara","type":"section","seq":845,"chapter":"طبقات فحول الشعراء","title":"848- المتوكل الليثي ويكنى أبا جهمة وهو المتوكل بن عبد الله بن نهشل بن وهب بن عمرو بن لقيط بن يع","page":"ص0","text":"المتوكل الليثي ويكنى أبا جهمة وهو المتوكل بن عبد الله بن نهشل بن وهب بن عمرو بن لقيط بن يعمر بن عوف بن عامر ابن ليث بن بكر بن عبد مناة بن كنانة وكان كوفيا وكان في عصر معاوية"},{"id":"tabaqat-shuara:846","bookId":"tabaqat-shuara","type":"section","seq":846,"chapter":"طبقات فحول الشعراء","title":"849- والثاني يزيد بن ربيعة بن مفرغ بن مصعب الحميري","page":"ص0","text":"والثاني يزيد بن ربيعة بن مفرغ بن مصعب الحميري"},{"id":"tabaqat-shuara:847","bookId":"tabaqat-shuara","type":"section","seq":847,"chapter":"طبقات فحول الشعراء","title":"850- والثالث زياد الأعجم وهو زياد بن سليم العبدي","page":"ص0","text":"والثالث زياد الأعجم وهو زياد بن سليم العبدي"},{"id":"tabaqat-shuara:848","bookId":"tabaqat-shuara","type":"section","seq":848,"chapter":"طبقات فحول الشعراء","title":"851- والرابع عدي بن الرقاع وهو عدي بن زيد بن مالك بن عدي بن الرقاع بن عصر بن عدة بن شعل بن معاو","page":"ص0","text":"والرابع عدي بن الرقاع وهو عدي بن زيد بن مالك بن عدي بن الرقاع بن عصر بن عدة بن شعل بن معاوية بن قاسط بن عميرة ابن زيد بن الحاف بن قضاعة"},{"id":"tabaqat-shuara:849","bookId":"tabaqat-shuara","type":"section","seq":849,"chapter":"طبقات فحول الشعراء","title":"852- فحدثني أبي سلام عمن حدثه قال كانت رهيم امرأة المتوكل أقعدت فسألته الطلاق فقال ليس ذا حين ط","page":"ص0","text":"فحدثني أبي سلام عمن حدثه قال كانت رهيم امرأة المتوكل أقعدت فسألته الطلاق فقال ليس ذا حين طلاق فأبت عليه فطلقها فبرأت بعد الطلاق فقال يذكرها\n(قفي قبل التفرق يا أماما ... وردي قبل بينكم السلاما)\n(سعى الواشون حتى أزعجوها ... ورث الحبل فانجذم انجذاما)\n(فلست بزائل مادمت حيا ... مسرا من تذكرها هياما)\n(ترجيها وقد شحطت نواها ... ومنتك المنى عاما فعاما)\n(خدلجة لها كفل وبوص ... ينوء بها إذا قامت قياما)\n(صليني واعرفي أني كريم ... وأن حلاوتي خلطت سماما)\n(وأني ذو محافظة صليب ... خلقت لمن يضارسني لجاما)\n(فلا وأبيك لا أنساك حتى ... تجاور هامتي في القبر هاما)"},{"id":"tabaqat-shuara:850","bookId":"tabaqat-shuara","type":"section","seq":850,"chapter":"طبقات فحول الشعراء","title":"853- ومن قوله أيضا —","page":"ص0","text":"ومن قوله أيضا\n(أرعى الأمانة للأمين بحقها ... فيبين عفا سره مكتوم)\n(وأشد للمولى المدفع ركنه ... شفقا من التعجيز وهو مليم)\n(ينأى بجانبه إذا لم يفتقر ... وعلى للخصم الألد خصيم)\n(إن الأذلة واللئام معاشر ... مولاهم المتهضم المظلوم)\n(وإذا أهنت أخاك أو أفردته ... عمدا فأنت الواهن المذموم)\n(لا تتبع سبل السفاهة والخنا ... إن السفيه معنف مشتوم)\n(وأقم لمن صافيت وجها واحدا ... وخليقة إن الكريم قؤوم)\n(لاتنه عن خلق وتأتي مثله ... عار عليك إذا فعلت عظيم)\n(وإذا رأيت المرء يقفو نفسه ... والمحصنات فما لذاك حريم)\n(ومعيري بالفقر قلت له اقتصد ... إني أمامك في الأنام قديم)\n(قد يكثر النكس المقصر همه ... ويقل مال المرء وهو كريم)"},{"id":"tabaqat-shuara:851","bookId":"tabaqat-shuara","type":"section","seq":851,"chapter":"طبقات فحول الشعراء","title":"854- قال كان رجل من بني جشم يقال له الهذيل بن حية صديقا لأبي المتوكل ثم جفاه قليلا فقال المتوكل","page":"ص0","text":"قال كان رجل من بني جشم يقال له الهذيل بن حية صديقا لأبي المتوكل ثم جفاه قليلا فقال المتوكل\n(ألا أبلغ أبا قيس رسولا ... فإني لم أخنك ولم تخني)\n(ولكني طويت الكشح لما ... رأيتك قد طويت الكشح عني)\n(وكنت إذا الخليل أراد صرمي ... قلبت لصرمه ظهر المجن)\n(كذاك قضيت للخلان إني ... أدين عليهم وأدين مني)\n(ولست بآمن أبدا خليلا ... على شيء إذا لم يأتمني)"},{"id":"tabaqat-shuara:852","bookId":"tabaqat-shuara","type":"section","seq":852,"chapter":"طبقات فحول الشعراء","title":"855- وقال —","page":"ص0","text":"وقال\n(ولقد علمت لو ان علمي نافع ... وأتاك ما يتحدث الأكفاء)\n(الذين حصونهم ... زرق الأسنة والحصون فضاء)\n(إنا أناس تستنير جدودنا ... ويموت أقوام وهم أحياء)\n(ول المجتنى ... ودعائم الإسلام والنجباء)\n(اخ سوابقا ... زرق القتير كأنهن نهاء)\n(معتفيهم مرحبا ... مع ذاك فيهم قوة ووفاء)\n(على المضاف إذا دعا ... حتى ينفس والرماح رواء)\n(بيض كأن شعاعها ... تحت العجاجة بالأكف ضياء)\n(قد يعلم الأقوام غير تنحل ... أنا نجوم فوقهم وسماء)"},{"id":"tabaqat-shuara:853","bookId":"tabaqat-shuara","type":"section","seq":853,"chapter":"طبقات فحول الشعراء","title":"856- والثاني يزيد بن مفرغ الحميري فحدثني يونس ابن حبيب أن يزيد بن ربيعة بن مفرغ كان رجلا من أهل","page":"ص0","text":"والثاني يزيد بن مفرغ الحميري فحدثني يونس ابن حبيب أن يزيد بن ربيعة بن مفرغ كان رجلا من أهل يحصب وكان عديدا لبني أسيد بن أبي العيص بن أمية من أهل البصرة وكان رجلا شريرا هجاء للناس فصحب عباد بن زياد وعباد يومئذ على سجستان عامل عبيد الله بن زياد وعبيد الله يومئذ على البصرة دون الكوفة وذلك في خلافة معاوية بن أبي سفيان فهجا ابن مفرغ عبادا فبلغه ذلك وكان على ابن مفرغ دين فأمر عباد الديان\nفاستعدوا عليه فبيع ماله في دينه فقضى الديان وكان فيما بيع غلام يقال له برد وجارية يقال لها أراكة فقال ابن مفرغ\n(أقفرت من آل ليلى الهضاب ... وعفى بعد الأنيس الجناب)\n(منزل منا ومن آل ليلى ... إذ خيام دارهم وقباب)\n(داركم دار لنا إن سلمنا ... وانقضى الغزو وحان الإياب)\n(أيها الشاتم جهلا سعيدا ... وسعيد في الحوادث ناب)\n(ما أبوكم مشبها لأبيه ... سائلوا الناس بذاكم تجابوا)\n(ساد عباد وملك جندا ... سبحت من ذاك صم صلاب)\n(إن دهرا كنت فيه أميرا ... تخطب الناس لدهر عجاب)\nوسعيد هذا الذي ذكره في شعره سعيد بن عثمان بن عفان وكان عاملا لمعاوية على خراسان وكان دعا يزيد بن مفرغ أن يصحبه فأبى عليه وصحب عباد بن زياد"},{"id":"tabaqat-shuara:854","bookId":"tabaqat-shuara","type":"section","seq":854,"chapter":"طبقات فحول الشعراء","title":"857- وقال ابن مفرغ أيضا لعباد بن زياد —","page":"ج2 ص687","text":"وقال ابن مفرغ أيضا لعباد بن زياد\n(أصرمت حبلك من أمامه ... من بعد أيام برامه)\n(لهفي على الرأي الذي ... كانت عواقبه ندامه)\n(تركي سعيدا ذا الندى ... والبيت ترفعه الدعامه)\n(وتبعت عبد بني علاج ... تلك أشراط القيامه)\n(جاءت به حبشية ... سكاء تحسبها نعامه)\n(من نسوة سود الوجوه ... ترى عليهن الندامه)\n(وشريت بردا ليتني ... من بعد برد كنت هامه)\n(هامة تدعو صدى ... بين المشقر واليمامه)\n(العبد يقرع بالعصا ... والحر تكفيه الملامه)\n(والريح تبكى شجوها ... والبرق يلمع في الغمامه)\n(ورمقتها فوجدتها ... كالضلع ليس له استقامه)"},{"id":"tabaqat-shuara:855","bookId":"tabaqat-shuara","type":"section","seq":855,"chapter":"طبقات فحول الشعراء","title":"858- ثم أقبل ابن مفرغ حتى قدم البصرة وكان عبيد الله وافدا على معاوية فعرف ابن مفرغ الذى أثر في","page":"ج2 ص689","text":"ثم أقبل ابن مفرغ حتى قدم البصرة وكان عبيد الله وافدا على معاوية فعرف ابن مفرغ الذى أثر في بني زياد فأتي الأحنف ابن قيس التميمي فقال أجرني من بني زياد فقال لا أجير عليهم ولكني أكفيك شعراء بني تميم أن يهجوك فقال أما هذا فلا أريد أن تكفينيه فأتى أمية بن عبد الله بن خالد بن أسيد فقال له أجرني فوعده وأتى عمر بن عبيد الله بن معمر وأتى طلحة الطلحات فوعده وأتى المنذر بن الجارود فأجاره وبلغ عبيد الله الذي كان من هجاء ابن مفرغ عبادا وهو عند معاوية فقال إن ابن مفرغ قد هجانا فأذن لي في قتله قال أما قتله فلا ولكن مادون القتل فلما قدم عبيد الله البصرة لم يكن له همة إلا ابن مفرغ فسأل عنه فقيل أجاره ابن الجارود وهو في داره فأرسل إلى المنذر فأتاه فلما دخل عليه أرسل عبيد الله الشرط إلى دار المنذر فأخذوا ابن مفرغ فأتوا به عبيد الله بن زياد فلم يشعر المنذر حتى رآه واقفا عليه وعلى\nعبيد الله فقام إلى عبيد الله فكلمه فيه فقال أجرته فقال عبيد الله يا منذر ليمدحن أباك وليهجون أبي وليمدحنك وليهجوني ثم أرضى بذلك قال فخرج المنذر من الدار وحبس ابن مفرغ وأسلم إلى الحجامين ليعلموه الحجامة فهو الذي يقول\n(وما كنت حجاما ولكن أحلني ... بمنزلة الحجام نأيى عن الأهل)"},{"id":"tabaqat-shuara:856","bookId":"tabaqat-shuara","type":"section","seq":856,"chapter":"طبقات فحول الشعراء","title":"859- وقال يهجو الذين أجاروه ثم خفروا —","page":"ص0","text":"وقال يهجو الذين أجاروه ثم خفروا\n(غدرت جذيمة غدرة مذكورة ... طوق الحمامة يعرفون بهاضحى)\n(سائل بني الجارود أين نزيلهم ... أغدا مع الغادين يوما أو ثوى)\n(لا يبعد الجار الذي أسلمتموا ... زين المجالس والفتى كل الفتى)\n(لعن الثلاثة منذر وابن استها ... وطليحة الداعى جهارا للردى)\n(وأمية الكذاب قال مقالة ... كانت مني منه وما تغني المنى)"},{"id":"tabaqat-shuara:857","bookId":"tabaqat-shuara","type":"section","seq":857,"chapter":"طبقات فحول الشعراء","title":"860- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(تركت قريشا أن أجاور فيهم ... وجاورت عبد القيس أهل المشقر)\n(أناس أجاروبي فكان جوارهم ... أعاصير من فسو العراق المبذر)\n(فأصبح جاري من جذيمة نائما ... ولا يمنع الجيران غير المشمر)"},{"id":"tabaqat-shuara:858","bookId":"tabaqat-shuara","type":"section","seq":858,"chapter":"طبقات فحول الشعراء","title":"861- وقال في عبيد الله بن زياد —","page":"ص0","text":"وقال في عبيد الله بن زياد\n(إن العبيد وما أدت طروقته ... لأعبد من زوان لا يصلونا)\n(بزند ورد خذوا منها مساحيكم ... واستبدلوا بالمآزير التبا بينا)\n(انتم قريش لئن لم تخب ناركم ... موتوا فإن قريشا قد يموتونا)\n(قد يقتل المرء لم يسلم حليلته ... ولم يقل لابنتيه استعرضا البينا)\n(ولم يذر أمه في الدار والهة ... قد استجار لها إذ هم يجارونا)"},{"id":"tabaqat-shuara:859","bookId":"tabaqat-shuara","type":"section","seq":859,"chapter":"طبقات فحول الشعراء","title":"862- والثالث زياد الأعجم وكان زياد رجلا هجاء قليل المدح للملوك والوفادة إليهم ولم تكن له همة تد","page":"ص0","text":"والثالث زياد الأعجم وكان زياد رجلا هجاء قليل المدح للملوك والوفادة إليهم ولم تكن له همة تدعوه وكانت همته ومركزه بخراسان وما يليها وكان أكثر نزوله بإصطخر من أرض فارس وكان يهاجي كعبا الشقري شقرة بني تميم وكان صاحب بديهة وقدرة في الشعر"},{"id":"tabaqat-shuara:860","bookId":"tabaqat-shuara","type":"section","seq":860,"chapter":"طبقات فحول الشعراء","title":"863- فحدثني أبو الغراف أن خالد بن عبد الله القسري قال — للأقيشر التميمي أي الناس أسرع بديها قال أ","page":"ص0","text":"فحدثني أبو الغراف أن خالد بن عبد الله القسري قال\nللأقيشر التميمي أي الناس أسرع بديها قال أنا أصلحك الله قال فأين زياد الأعجم قال والله لوددت أنه بينى وبينك فكتب خالد إلى أسد بن عبد الله وزياد عنده بخراسان أن وجهه إلي فلما قدم جمع بينهما فقال يا أبا امامة زعم هذا أنه أسرع بديها منك قال إن شاء فليبدأ وإن شاء بدأت فقال هات يا أبا أمامة فأطرق غير طويل ثم أنشأ يقول\n(ألم تر أنني وترت قوسي ... لأبقع من كلاب بني تميم)\n(عوى فرميته بسهام موت ... يصبن عوادى الكلب اللئيم)\n(وكنت إذا غمزت قناة قوم ... كسرت كعوبها أو تستقيم)\nثم قال هات يا أقيشر فأطرق طويلا ثم قال خنقت فأعطى زيادا وحباه"},{"id":"tabaqat-shuara:861","bookId":"tabaqat-shuara","type":"section","seq":861,"chapter":"طبقات فحول الشعراء","title":"864- وقال زياد —","page":"ج2 ص694","text":"وقال زياد\n(وما ترك الهاجون لي إن هجوته ... مصحا أراه في أديم الفرزدق)\n(ولا تركوا لحما يرى فوق عظمه ... لآكله أبقوه للمتعرق)\n(سأكسر ما له أبقوا من عظامه ... وانكت مخ الساق منه فأنتقى)\n(وإنا وما تهدى لنا إن هجوتنا ... لك البحر مهما يلق في البحر يغرق)"},{"id":"tabaqat-shuara:862","bookId":"tabaqat-shuara","type":"section","seq":862,"chapter":"طبقات فحول الشعراء","title":"865- قال وحدثني أبي سلام قال حدثنا بعض أصحابنا أن زيادا أتى عبد الله بن الحشرج الجعدى وهو على ق","page":"ص0","text":"قال وحدثني أبي سلام قال حدثنا بعض أصحابنا أن زيادا أتى عبد الله بن الحشرج الجعدى وهو على قهستان فأجازه بثلاثين ألفا فقيل له ترحل فإنه إن احتاج إليها أخذها وقالوا له إنه قد كان يعطى الرجل فإذا نابته نائبة أخذ ما أعطاه فإذا أتاه مال رد عليه فخرج زياد ولم يسلم عليه ففقده وسأل عنه فقال ما فعل زياد فقالوا خرج فأرسل غلاما له بفرو فقال الحقه فقل له البس هذا الفرو لا تقر فلحقه الغلام فدفعه إليه فقال زياد\n(نبأتنى أن عبد الله منتزع ... منى عطاياه لكاع بن لكاع)\n(كذبت لم تغذه سوداء مقرفة ... بشر ثدى كأنف الكلب دماع)\n(إلا بألبان حور كالدمى شمس ... من عامر ونمته بين أفراع)"},{"id":"tabaqat-shuara:863","bookId":"tabaqat-shuara","type":"section","seq":863,"chapter":"طبقات فحول الشعراء","title":"866- وقال يهجو بنى يشكر —","page":"ص0","text":"وقال يهجو بنى يشكر\n(ألم تر أن اللؤم حل عماده ... على يشكر الحمر القصار السوالف)\n(إذا ما رأيت الخز فوق ظهورهم ... عرفت نجار اللؤم تحت المطارف)"},{"id":"tabaqat-shuara:864","bookId":"tabaqat-shuara","type":"section","seq":864,"chapter":"طبقات فحول الشعراء","title":"867- وقال يهجو جرما —","page":"ص0","text":"وقال يهجو جرما\n(تكلفنى سويق الكرم جرم ... وما جرم وما ذاك السويق)\n(فما شربوه إذ كانت حلالا ... ولا غالوا بها فى يوم سوق)\n(فأولى ثم أولى ثم أولى ... ثلاثا يا ابن جرم أن تذوقى)\n(ولما نزل التحريم فيها ... إذا الجرمى عنها لا يفيق)"},{"id":"tabaqat-shuara:865","bookId":"tabaqat-shuara","type":"section","seq":865,"chapter":"طبقات فحول الشعراء","title":"868- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(إنى لأكرم نفسى أن أكلفها ... هجاء جرم وما يهجوهم أحد)\n(ماذا يقول لهم من كان هاجيهم ... لا يبلغ الناس ما فيهم ولو جهدوا)"},{"id":"tabaqat-shuara:866","bookId":"tabaqat-shuara","type":"section","seq":866,"chapter":"طبقات فحول الشعراء","title":"869- وقال الأعجم يهجو بنى يشكر —","page":"ص0","text":"وقال الأعجم يهجو بنى يشكر\n(لو أن بكرا براه الله راحلة ... لكان يشكر منها موضع الذنب)\n(لبسوا إليه ولكن يعلقون به ... كما تعلق راقى النخل بالكرب)"},{"id":"tabaqat-shuara:867","bookId":"tabaqat-shuara","type":"section","seq":867,"chapter":"طبقات فحول الشعراء","title":"870- الرابع عدى بن الرقاع العاملى فحدثنى أبو الغراف قال لما أتت الخلافة سليمان بن عبد الملك أتت","page":"ص0","text":"الرابع عدى بن الرقاع العاملى فحدثنى أبو الغراف قال لما أتت الخلافة سليمان بن عبد الملك أتته وهو بالسبع فكتب إلى عامله أن ابعث إلى عدى بن الرقاع في وثاق مع ثقة فوجهه إليه فلما دخل عليه قال إن كنت لكارها لخلافتى قال وكيف ذاك يا أمير المؤمنين قال حين تقول في مدحه الوليد\n(عذنا بذى العرش أن نبقى ونفقده ... أو أن نكون لراع بعده تبعا)\nقال ابن الرقاع والله ما هكذا قلت يا أمير المؤمنين ولكنى قلت\n(عذنا بذى العرش أن نبقى ونفقدهم ... أو أن نكون لراع بعدهم تبعاأ)\nقال وكذلك قلت قال نعم قال فكوا حديده وردوه على مركبه إلى أهله وإنما كان خص بتلك المدحة الوليد"},{"id":"tabaqat-shuara:868","bookId":"tabaqat-shuara","type":"section","seq":868,"chapter":"طبقات فحول الشعراء","title":"871- وحدثنى أبى سلام قال قام روح بن زنباع الجذامى يوم الجمعة إلى يزيد بن معاوية حين فصل بين الخ","page":"ص0","text":"وحدثنى أبى سلام قال قام روح بن زنباع الجذامى يوم الجمعة إلى يزيد بن معاوية حين فصل بين الخطبتين فقال يا أمير المؤمنين ألحقنا بإخوتنا فإنا قوم معديون والله ما نحن من قصب ولا من غاف شجر اليمن فألحقنا بإخوتنا فقال يزيد إن أجمع على ذلك قومك فنحن جاعلوك حيث شئت فبلغت الدعوى عدى بن الرقاع فقال\n(إنا رضينا وإن غابت جماعتنا ... ما قال سيدنا روح بن زنباع)\n(يرعى ثمانين ألفا كان مثلهم ... مما يخالف أحيانا على الراعى)\nفبلغ ذلك ناتل بن قيس الجذامى فجاء يركض حتى دخل المقصورة فقال أين جلس الفاجر الكاذب روح بن زنباع فأشاروا له إلى مجلسه فانتظر يزيد حتى إذا كان عند فصل خطبته قام فقال يا أمير المؤمنين بلغنى أن روح بن زنباع قام فزعم أنه من معد وذلك مالا نعرفه ولا نقر به ولكنا من قحطان يسعنا ما وسع قحطان ويعجز عنا ما يعجز عنهم فبلغ ذلك ابن الرقاع فقال\n(لو أن أطعتك ياغرار كسوتنى ... في كل مجمعة ثياب صغار)\n(أضلال ليل ساقط أكنافه ... في الناس أعذر أم ضلال نهار)\n(قحطان والدنا الذى ندعى له ... وأبو خزيمة خندف بن نزار)\n(أنبيع والدنا الذى ندعى له ... بأبي معاشر غائب متوارى)\n(تلك التجارة لا نجيب لمثلها ... ذهب يباع بآنك وأبار)\nفقالوا غيرت يا ابن الرقاع فقال إنه والله أعزهما سخطا يعنى ناتلا"},{"id":"tabaqat-shuara:869","bookId":"tabaqat-shuara","type":"section","seq":869,"chapter":"طبقات فحول الشعراء","title":"872- وحدثنى يونس النحوى قال استسقى ابن الرقاع بنى بحر من بنى زهير بن جناب الكلبيين فلم يسقوه وه","page":"ج2 ص702","text":"وحدثنى يونس النحوى قال استسقى ابن الرقاع بنى بحر من بنى زهير بن جناب الكلبيين فلم يسقوه وهو على ماء لهم يقال له الدمعانة فورد على بنى تغلب ماء يقال له خالة وفيه جفر يقال له القنينى فكانت بنو تغلب قد رعت فيه فوقع قعب في القنينى فزعم أنه وجد في التراب القعب فاقتتلت في ذلك الجفر بنو تغلب حتى كادت تتفانى ثم اصطلحوا على أن ملأوه حجارة وقتادا واحتفروا حوله فموضع القنينى من خالة معروف يقال لما حوله القنينيات فقال ابن الرقاع\n(غابت سراة بنى بحر ولو شهدوا ... يوما لأعطيت ما أبغى وأطلب)\n(لما دفعت إلى الماحوز قلت له ... هل أنت مفتعل خيرا ومحتسب)\n(إذا خطيب قضى منا مقالته ... ثنى بأخرى خطيب فاصل أرب)\n(حتى وردنا القنينيات ضاحية ... في ساعة من نهار الصيف تلتهب)\n(فجاد بالبارد العذب الزلال لنا ... مادام يمسك عودى دلونا الكرب)\n(من ماء خالة جياش بجمته ... مما توارثه الأوحاد والعتب)\nالعتب يريد عتبة بن سعد وعتاب بن سعد وعتبان ابن سعد والأوحاد عوف وكعب ابنا سعد من بنى تغلب"},{"id":"tabaqat-shuara:870","bookId":"tabaqat-shuara","type":"section","seq":870,"chapter":"طبقات فحول الشعراء","title":"873- وقال يمدح عبد الملك بن مروان ويهجو مصعب ابن الزبير —","page":"ج2 ص704","text":"وقال يمدح عبد الملك بن مروان ويهجو مصعب ابن الزبير\n(لعمرى لقد أصحرت خيلنا ... بأكناف دجلة للمصعب)\n(وجرت سنابكها بالعراق ... حتى تركناه كالمشجب)\n(وردنا الفرات وخابوره ... وكانا هما ثقة المشرب)\n(على كل ريق ترى معلما ... يصرف كالجمل الأجرب)\n(لضاحية الشمس في رأسه ... شعاع تلألأ كالكوكب)\n(إذا ما منافق أهل العراق ... عوتب ثمت لم يعتب)\n(دلفنا إليه بذى تدرأ ... قليل التفقد للغيب)\n(يقومنا واضح وجهه ... كريم المضارب والمنصب)\n(أغر يضىء لنا نوره ... إذا ما انجلت غمرة الموكب)\n(تظل القنابل بكشونه ... رواقا من النقع لم يطنب)\n(أعين بنا ونصرنا به ... ومن ينصر الله لا يغلب)"},{"id":"tabaqat-shuara:871","bookId":"tabaqat-shuara","type":"section","seq":871,"chapter":"طبقات فحول الشعراء","title":"874- وقال أيضا —","page":"ج2 ص706","text":"وقال أيضا\n(والقوم أشباه وبين حلومهم ... بون كذاك تفاضل الأشياء)\n(كالبرق منه وابل متتابع ... جود وآخر ما يجود بماء)\n(والدهر يفرق بين كل جماعة ... ويلف بين تباعد وتنائى)\n(والمرء يورث مجده أبناءه ... ويموت آخر وهو في الأحياء)"},{"id":"tabaqat-shuara:872","bookId":"tabaqat-shuara","type":"section","seq":872,"chapter":"طبقات فحول الشعراء","title":"875- وقال أيضا —","page":"ج2 ص706","text":"وقال أيضا\n(تزجى أغن كأن إبرة روقه ... قلم أصاب من الدواة مدادها)\n(ركبت به من عالج متحيزا ... قفرا تربب وحشه أولادها)\n(بمجر مرتجز الرواعد بعجت ... غر السحاب به الثقال مزادها)\n(إبي إذا مالم تصلني خلة ... وتباعدت عنى اغتفرت بعادها)\n(وإذا القرينة لم تزل في نجدة ... من ضغنها سئم القرين قيادها)\n(إما ترى شيبي تفشغ لمتى ... حتى علا وضح يلوح سوادها)\n(فلقد تبيت يد الفتاة وسادة ... لى جاعلا إحدى يدى وسادها)"},{"id":"tabaqat-shuara:873","bookId":"tabaqat-shuara","type":"section","seq":873,"chapter":"طبقات فحول الشعراء","title":"876- عقيل بن علفة المرى","page":"ج2 ص708","text":"عقيل بن علفة المرى"},{"id":"tabaqat-shuara:874","bookId":"tabaqat-shuara","type":"section","seq":874,"chapter":"طبقات فحول الشعراء","title":"877- وبشامة بن الغدير المرى أحد بنى سهم بن مرة","page":"ج2 ص708","text":"وبشامة بن الغدير المرى أحد بنى سهم بن مرة"},{"id":"tabaqat-shuara:875","bookId":"tabaqat-shuara","type":"section","seq":875,"chapter":"طبقات فحول الشعراء","title":"878- وشبيب بن البرصاء واسمه شبيب بن يزيد بن جمرة بن عوف بن أبي حارثة بن مرة بن نشبة وأمه البرصا","page":"ج2 ص708","text":"وشبيب بن البرصاء واسمه شبيب بن يزيد بن جمرة بن عوف بن أبي حارثة بن مرة بن نشبة وأمه البرصاء بنت الحارث بن عوف بن أبي حارثة"},{"id":"tabaqat-shuara:876","bookId":"tabaqat-shuara","type":"section","seq":876,"chapter":"طبقات فحول الشعراء","title":"879- وقراد بن حنش بن عمر بن عبد الله بن عبد العزى بن صبيح بن سلامة بن الصادر بن مرة","page":"ج2 ص708","text":"وقراد بن حنش بن عمر بن عبد الله بن عبد العزى بن صبيح بن سلامة بن الصادر بن مرة"},{"id":"tabaqat-shuara:877","bookId":"tabaqat-shuara","type":"section","seq":877,"chapter":"طبقات فحول الشعراء","title":"880- قال فحدثنى أبو عبيدة أن يزيد بن عبد الملك خطب إلى عقيل بن علفة ابنته وقال زوجنى فلست بواجد","page":"ص0","text":"قال فحدثنى أبو عبيدة أن يزيد بن عبد الملك خطب إلى عقيل بن علفة ابنته وقال زوجنى فلست بواجد في قومى مثلى قال عقيل بلى والله لأجدن في قومك مثلك وما أنت بواجد في قومى مثلى فحبسه فضرب عقيل كتف ابنه وقال زوجه يا بنى فأنت أحق بالأمة منى فزوجه أم عمرو بنت عقيل فلما أهداها عقيل تمثل جثامة بن عقيل فقال\n(أيعذر لاهينا ويلحين في الصبا ... وهل هن والفتيان إلاشقائق)\nفرماه عقيل بسهم وقال تمثل بهذا عند بناتى فخرج جثامة مراغما لأبيه فأتى يزيد بن عبد الملك فكتب عقيل إلى يزيد إنه أتاك أعق خلق الله وكان يزيد قد أعطاه وحباه فأخذ ذلك منه وحبسه"},{"id":"tabaqat-shuara:878","bookId":"tabaqat-shuara","type":"section","seq":878,"chapter":"طبقات فحول الشعراء","title":"881- وحدثنى أبو عبيدة قال كان علفة بن عقيل بن علفة — هوى امراة من قومه من بنى مالك بن مرة وهويته","page":"ص0","text":"وحدثنى أبو عبيدة قال كان علفة بن عقيل بن علفة\nهوى امراة من قومه من بنى مالك بن مرة وهويته فأراد أن يتزوجها فخطبها أبوه فتزوجته فأقامت عنده حينا ثم أن قومها ادعوا عليه طلاقا فهرب بها إلى الشأم فقال في ذلك علفة بن عقيل بن علفة\n(لعمرى لئن كانت سلافة بدلت ... من الرملة العفراء قفلا تزاو له)\n(ونوحا يغنيها دوين حمامة ... إذا هى ضجت بزله وجواز له)"},{"id":"tabaqat-shuara:879","bookId":"tabaqat-shuara","type":"section","seq":879,"chapter":"طبقات فحول الشعراء","title":"882- قال وخرج عقيل ومعه بنوه علفة وعملس وجثامة وابنته الجرباء حتى إذا كانوا بجنب دومة الجندل تغ","page":"ج2 ص711","text":"قال وخرج عقيل ومعه بنوه علفة وعملس وجثامة وابنته الجرباء حتى إذا كانوا بجنب دومة الجندل تغنى علفة بن عقيل فقال\n(قفى يا ابنة المري نسألك ما الذى ... تريدين فيما بيننا إنه سهل)\n(نخبرك إن لم تنجزى الوأى أننا ... ذوا خلة لم يبق بينهما وصل)\n(فإن شئت كان الصرم ماهبت الصبا ... وإن شئت لم يفن التكارم والبذل)\n(ونسألك ماتغنى عن الجاهل المنى ... وهل يستقيدن الجنيب ولا حبل)\nفعدا عليه أبوه بالسيف وقال ياعدو الله ما هذه المرية واتهمه بامرأته وقال تشبب بأمك فكلمه أخوه فحمل عليهما ويرميه عملس بسهم في فخذه فصرعه فقال عقيل\n(إن بنى رملونى بالدم ... شنشنة أعرفها من أخزم)\n(من يلق أحدان الرجال يكلم ... )"},{"id":"tabaqat-shuara:880","bookId":"tabaqat-shuara","type":"section","seq":880,"chapter":"طبقات فحول الشعراء","title":"883- وقال عقيل بن علفة يهجو بنى بدر بن عمرو —","page":"ص0","text":"وقال عقيل بن علفة يهجو بنى بدر بن عمرو\n(إذا جارة حلت على الهجم لم تجد ... كريما ولم تعدم لئيما يزورها)\n(ألم تر بدرا لا تمانى دماءهم ... دماء ولم يعقد لجار مجيرها)\n(أتقصر عن باع الكرام أكفها ... وتبلغ أنصاف المخازى أيورها)"},{"id":"tabaqat-shuara:881","bookId":"tabaqat-shuara","type":"section","seq":881,"chapter":"طبقات فحول الشعراء","title":"884- وحدثنى أبو عبيدة أنه كان لعقيل بن علفة نديم من بنى كلاب يقال له غثراء وكان عقيل يسمر عند ع","page":"ص0","text":"وحدثنى أبو عبيدة أنه كان لعقيل بن علفة نديم من بنى كلاب يقال له غثراء وكان عقيل يسمر عند عبد الملك فأصاب وجه عقيل أثر فترك إتيان عبد الملك فبعث إليه فأتاه فرأى\nمابوجهه فقال ما هذا بوجهك قال يا أمير المؤمنين لا والله إلا أننى اشتهيت اللبن فقمت إلى الفلانية ناقة له لأحلبها فزبنتنى\nفقال عبد الملك أشهدك غثراء قال والله يا أمير المؤمنين لقد ذهبت مذهبا وظننت ظنا الله سائلك عنه قال أنا أسئل عنه أم من عمله يا ضب"},{"id":"tabaqat-shuara:882","bookId":"tabaqat-shuara","type":"section","seq":882,"chapter":"طبقات فحول الشعراء","title":"885- وحدثنى أبو عبيدة أنه قيل لعقبل بن علفة والله ما نراك تقرأ شيئا من كتاب الله قال بلى والله","page":"ص0","text":"وحدثنى أبو عبيدة أنه قيل لعقبل بن علفة والله ما نراك تقرأ شيئا من كتاب الله قال بلى والله إنى لأقرأ قالوا فاقرأ فقال إنا بعثنا نوحا وقيل ما قال إنا فرطنا نوحا فقالوا قد والله أخطأت قال فكيف تقولون قالوا {إنا أرسلنا نوحا} فقال أرسلنا وبعثنا أشهدكم أنكم تعلمون أنهما سواء ثم قال\n(خذا صدر هرشى أو قفاها فإنه ... كلا جانبى هرشى لهن طريق)"},{"id":"tabaqat-shuara:883","bookId":"tabaqat-shuara","type":"section","seq":883,"chapter":"طبقات فحول الشعراء","title":"886- وقال يرثى ابنه علفة بن عقيل —","page":"ص0","text":"وقال يرثى ابنه علفة بن عقيل\n(لتمض المنايا حيث شئن فإنها ... محللة بعد الفتى ابن عقيل)\n(فتى كان مولاه يحل بنجوة ... فحل الموالى بعده بمسيل)"},{"id":"tabaqat-shuara:884","bookId":"tabaqat-shuara","type":"section","seq":884,"chapter":"طبقات فحول الشعراء","title":"887- وكان عقيل بن علفة زوج ابنته الجرباء يحيى بن الحكم ابن أبي العاص فطلقها يحيى فأقبل إليها عق","page":"ص0","text":"وكان عقيل بن علفة زوج ابنته الجرباء يحيى بن الحكم ابن أبي العاص فطلقها يحيى فأقبل إليها عقيل ومعه ابناه العملس وحزام فحملها فقال في ذلك\n(فضت وطرا من دير يحيى وطالما ... على عرض ناطحنه بالجماجم)\n(فأصبحن بالموماة ينقلن فتية ... نشاوى من الإدلاج ميل العمائم)\nثم قال أجز يا حزام فأرتج عليه فقالت الجرباء\n(كأن الكرى يسقيهم صرخدية ... عقارا تمشى في المطا والقوائم)\nفقال عقيل شربتها ورب الكعبة ثم شد عليها بالسيف فطرح حزام نفسه عليها فضربها فأصاب حزاما"},{"id":"tabaqat-shuara:885","bookId":"tabaqat-shuara","type":"section","seq":885,"chapter":"طبقات فحول الشعراء","title":"888- وحدثنى أبو عبيدة انه كان لعقيل جار من بنى سلامان فخطب إليه فأخذه فقمطه ودهن استه بشحم وألق","page":"ص0","text":"وحدثنى أبو عبيدة انه كان لعقيل جار من بنى سلامان فخطب إليه فأخذه فقمطه ودهن استه بشحم وألقاه فى قرية النمل فأكلن خصييه فخلاه وقال له يخطب إلى عبد الملك فأرده وتجترىء على ثم إنه بعد ذلك ورد وادى القرى فثار بنوحن بن ربيعة\nفعقروا به فقال في ذلك\n(لقد عقرت حن بنا وتلعبت ... وما لعبت حن بذى حسب قبلى)\n(رويد بنى حن تسيحوا وتأمنوا ... وتنتشر الأنعام في بلد سهل)"},{"id":"tabaqat-shuara:886","bookId":"tabaqat-shuara","type":"section","seq":886,"chapter":"طبقات فحول الشعراء","title":"889- وحدثنى أبو عبيدة أن عقيل بن علفة جاور جذاما فبينا هو ذات يوم بفنائه إذ أتته جماعة منهم فخط","page":"ص0","text":"وحدثنى أبو عبيدة أن عقيل بن علفة جاور جذاما فبينا هو ذات يوم بفنائه إذ أتته جماعة منهم فخطبوا إليه فقام يسعى حتى صعد شرفا ثم رمى ببصره إلى الحجاز ثم عوى عواء الكلب فقالوا والله لقد جن فانصرفوا فقالت ابنته يآبه إنه والله ما أنت ببلاد غطفان حيث تقول ما أحببت لاتخاف أحدا وإنى أخاف أن يغتالك القوم فالحق ببلادك فعرف ما قالت فلما أمسى قرب رواحله وانصرف إلى قومه وقال عقيل\n(ألا ليت شعرى هل أشنن غارة ... بغضيان أووادى تبوك المصوب)\n(وهل أشهدن خيلا كأن غبارها ... بأسفل علكد دواخن تنضب)\n(تصب على رمص كأن عيونهم ... فقاح الدجاج في الودى المعصب)"},{"id":"tabaqat-shuara:887","bookId":"tabaqat-shuara","type":"section","seq":887,"chapter":"طبقات فحول الشعراء","title":"890- والثانى بشامة بن الغدير بن عمرو بن ربيعة بن هلال بن سهم بن مرة بن عوف","page":"ص0","text":"والثانى بشامة بن الغدير بن عمرو بن ربيعة بن هلال بن سهم بن مرة بن عوف"},{"id":"tabaqat-shuara:888","bookId":"tabaqat-shuara","type":"section","seq":888,"chapter":"طبقات فحول الشعراء","title":"891- قال محمد بن سلام الجمحى فحدثنى أبو عبيدة أن بشامة ابن الغدير كان كثير المال وكان ممن فقأ ع","page":"ص0","text":"قال محمد بن سلام الجمحى فحدثنى أبو عبيدة أن بشامة ابن الغدير كان كثير المال وكان ممن فقأ عين بعير في الجاهلية وكان الرجل إذا ملك ألف بعير فقأ عين فحلها"},{"id":"tabaqat-shuara:889","bookId":"tabaqat-shuara","type":"section","seq":889,"chapter":"طبقات فحول الشعراء","title":"892- وكان قد أقعد فلما حضره الموت ولم يكن له ولد قسم ماله بين إخوته وبنى أخيه وأقاربه فقال له ز","page":"ص0","text":"وكان قد أقعد فلما حضره الموت ولم يكن له ولد قسم ماله بين إخوته وبنى أخيه وأقاربه فقال له زهير بن أبي سلمى\nوهو ابن أخته ماذا قسمت لي يا خالاه قال أفضل ذلك كله قال ما هو قال شعرى\nفيزعم من يزعم أن زهيرا جاءه الشعر من قبل بشامة بن الغدير"},{"id":"tabaqat-shuara:890","bookId":"tabaqat-shuara","type":"section","seq":890,"chapter":"طبقات فحول الشعراء","title":"893- قال بشامة —","page":"ص0","text":"قال بشامة\n(ياقومنا لا تسومونا التى كرهت ... إن الكرام إذا ما أكرهوا غشموا)\n(لا تظلمونا ولا تنسوا قرابتنا ... إطوا إلينا فقدما تعطف الرحم)\n(لا ترجعن أحاديثا وتنتهكوا ... منا محارمنا قد تتقى الحرم)\n(ولا يكن لكم يا قومنا مثلا ... فيما مضى من زمان سالف جلم)"},{"id":"tabaqat-shuara:891","bookId":"tabaqat-shuara","type":"section","seq":891,"chapter":"طبقات فحول الشعراء","title":"894- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(إن الخليط أجدالبين فابتكروا ... لنية ثم ما عاجوا وما انتظروا)\n(زموا الجمال وقالوا إن مشربكم ... ماء بكلية لاملح ولا كدر)\n(ما كان بينهم إلا مجاهرة ... أشفقت منها فماذا زادك الحذر)\n(استقبلوا المسقط الشرقى يحفزهم ... في السير أشوس فيه الفحش والضجر)\n(كأن ظعنهم والآل يرفعها ... نخل المشقر أو ما ربيت هجر)\n(مازلت أرمقهم في الآل مرتفقا ... حتى تقطع دون الجيرة البصر)\n(فاقر الهموم التى نابت مذكرة ... وشواشة سرحا في دفها زور)\n(تذرى الحصى رثما من تحت منسمها ... كما يرض سوادى القرى حجر)\n(تمر جثلا على الحاذين ذا خصل ... كالعذق لا كشف فيه ولا زعر)\n(كأن أوب ذراعيها إذا انحدرت ... وأحرز الظل فى أعدائه الشجر)\n(أوب ذراعى لجوج جاد واحدها ... حتى إذا ما انتهى أودى به القدر)\n(فأبلغن قومنا إن جئتهم عذرا ... عنا وهل ينفعنهم عندنا عذر)\n(إنا نذكرهم بالله واحدة ... وبالقرابة والأخرى التى وذروا)\n(حسن البلاء وإياما لنا سلفت ... يبيض منها إذا ما تذكر الشعر)\n(فلا تعدوا علينا الزورو ارتدعوا ... فإن عندكم من مسنا خبر)\n(لا تبطروا السلم واستأنوا بإخوتكم ... إن الندامة تعدو سبقها البطر)\n(وإن فينا صبوحا غير ممتزج ... يصرى الدماء عليه الصاب والصبر)\n(فينا فتو وفينا سادة حشد ... عند الصباح وفينا جامل عكر)\n(كم من رئيس فريناه بأجمعه ... بالمشرفية حتى يعدل الصعر)"},{"id":"tabaqat-shuara:892","bookId":"tabaqat-shuara","type":"section","seq":892,"chapter":"طبقات فحول الشعراء","title":"895- وقال أيضا —","page":"ج2 ص722","text":"وقال أيضا\n(نحن الفوارس يوم الشعب ضاحية ... والضاربون على ما كان من ألم)\n(والمعلمون وعظم الخيل لا حقة ... مبثوثة كعجيم تر عن جرم)\n(هلا سألت وقول الحق أصدقه ... عنا وعنكم وعن من نلق بالرقم)\n(أنا جدعنا بصغر من أنوفكم ... أنفا أشم فأمسى حق مصطلم)\n(ياعام لا تفسد الدعوى وقد تركت ... منكم عصائب بين العرج والرخم)\n(مالت عليهم لغيظ غبية بركت ... فيهم أحاديثهم فى الناس كالحلم)"},{"id":"tabaqat-shuara:893","bookId":"tabaqat-shuara","type":"section","seq":893,"chapter":"طبقات فحول الشعراء","title":"896- وقال أيضا —","page":"ج2 ص724","text":"وقال أيضا\n(ونبئت قومى ولم ألقهم ... أجدوا على ذى شويس حلولا)\n(فإنكم وعطاء الرهان ... إذا جرت الحرب جلا جليلا)\n(كثوب ابن بيض وقاهم به ... فسد على السالكين السبيلا)\n(فإما هلكت ولم آتكم ... فأبلغ أماثل سهم رسولا)\n(بأن التى سامكم قومكم ... هم جعلوها عليكم عدولا)\n(هوان الحياة وخزى الممات ... وكلا أراه طعاما وبيلا)\n(فإن لم يكن غير أحداهما ... فسيروا إلى الموت سيرا جميلا)\n(ولا تهلكوا وبكم منة ... كفى بالحوادث للمرء غولا)"},{"id":"tabaqat-shuara:894","bookId":"tabaqat-shuara","type":"section","seq":894,"chapter":"طبقات فحول الشعراء","title":"897- والثالث شبيب بن البرصاء وهو الذى يقول —","page":"ج2 ص726","text":"والثالث شبيب بن البرصاء وهو الذى يقول\n(أنا ابن برصاء بها أجيب ... هل فى هجان اللون ما تعيب)"},{"id":"tabaqat-shuara:895","bookId":"tabaqat-shuara","type":"section","seq":895,"chapter":"طبقات فحول الشعراء","title":"898- واسمه شبيب بن يزيد بن جمرة بن عوف بن أبى حارثة بن مرة بن نشبة وأمه البرصاء بنت الحارث بن ع","page":"ج2 ص726","text":"واسمه شبيب بن يزيد بن جمرة بن عوف بن أبى حارثة بن مرة بن نشبة وأمه البرصاء بنت الحارث بن عوف بن أبي حارثة"},{"id":"tabaqat-shuara:896","bookId":"tabaqat-shuara","type":"section","seq":896,"chapter":"طبقات فحول الشعراء","title":"899- وقال —","page":"ج2 ص726","text":"وقال\n(يدل علينا الجار آخر قبله ... وأحلامنا معروفة وسدادها)\n(وجاراتنا مادمن فينا بعزة ... كأروى ثبير لا يحل اصطيادها)\n(ترى إبل الجار الغريب كأنها ... بمكة بين الأخشبين مرادها)\n(يكون علينا نقصها وضمانها ... وللجار إن كانت تزيد ازديادها)"},{"id":"tabaqat-shuara:897","bookId":"tabaqat-shuara","type":"section","seq":897,"chapter":"طبقات فحول الشعراء","title":"900- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(هل عند سعدى ابنة العمرى من زاد ... أم هل لعان لديها موثق فادى)\n(قامت تراءى لنا سعدى فقلت لها ... ماذا تريدين من قتلى وإقصادى)\n(أبدت ترائب عبلات وسالفة ... وجيد مغزلة من خير أجياد)\n(حالى الترائب والذفرى عقدن به ... من لؤلؤ وجمان غير أفراد)\n(تبدو وساوس منها كلما ارتفقت ... هز الجنوب استخفت عشرق الوادى)\n(فى ضامر الكشح والأحشاء تحسبه ... مما تخضد منه طى أسناد)\n(منها إلى كفل نهد روادفه ... مرتجة كارتجاج الدعص مياد)\n(ووارد كعذوق النخل زينة ... من الجداول لا زعر ولا كادى)\n(طال اتباعى أمورا ما تجود بها ... حتى يئست فهبنى غير مزداد)\n(ثم استمرت ولم تقض التى وعدت ... لا يهنئنك إذ أخلفت ميعادى)\n(دعها لشأنك وانظر أنت كيف ترى ... شأن امرأين ذوى مال وأولاد)\n(إنى امرؤ لى رواب لا يشققها ... سيل الأتى ولا تسطاع أوتادى)\n(إن المكارم والأحساب عودها ... من آل مرة أعمامى وأجدادى)\n(أنا ابن عوفومنى إن فخرت بهم ... بنو سنان ومسعود بن شداد)"},{"id":"tabaqat-shuara:898","bookId":"tabaqat-shuara","type":"section","seq":898,"chapter":"طبقات فحول الشعراء","title":"901- وقال أيضا —","page":"ج2 ص729","text":"وقال أيضا\n(ماذا تلمس سلمى فى معرسنا ... كر الغريم لدين كان قد وجبا)\n(أوكر صاحب ذى الأوجاع مسنده ... إذا تأوه ألقى فوقه الهببا)\n(ألم تكن زعمت بالله مسلمة ... ولم تكن هى مما قضت الأربا)\n(فلا يحل لسلمى أن تؤرقنا ... بعد المنام ولو كنا لها نصبا)"},{"id":"tabaqat-shuara:899","bookId":"tabaqat-shuara","type":"section","seq":899,"chapter":"طبقات فحول الشعراء","title":"902- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(كأن ابنة العذرى يوم بدت لنا ... بواد القرى روعى الجنان سليب)\n(من الأدم ضمتها الحبال فأفلتت ... وفي الجسم منها علة وشحوب)"},{"id":"tabaqat-shuara:900","bookId":"tabaqat-shuara","type":"section","seq":900,"chapter":"طبقات فحول الشعراء","title":"903- حدثنى أبو عبيدة قال خطب شبيب بن البرصاء إلى مهر بن على بن جابر أحد بنى غيظ بن مرة فقال نعم","page":"ص0","text":"حدثنى أبو عبيدة قال خطب شبيب بن البرصاء إلى مهر بن على بن جابر أحد بنى غيظ بن مرة فقال نعم أزوجك قال شبيب أؤامر أخى فقال أتؤامر رجلا فى تزويجك والله لا أزوج رجلا لا يملك أمره فقال شبيب\n(لعمر ابنة المرى ما أنا بالذى ... له أن تنوب النائبات ضجيج)\n(وقد علمت أفناء مرة أننى ... إلى الضيف قوام السنات خروج)\n(وإنى لأغلى اللحم نيا وإننى ... لممن يهين اللحم وهو نضيج)\n(إذا المرضع العوجاء باتت يعزها ... على ثديها ذو ودعتين لهوج)"},{"id":"tabaqat-shuara:901","bookId":"tabaqat-shuara","type":"section","seq":901,"chapter":"طبقات فحول الشعراء","title":"904- والرابع قراد بن حنش بن عمرو بن عبد الله بن عبد العزى ابن صبح بن سلامة بن مرة","page":"ص0","text":"والرابع قراد بن حنش بن عمرو بن عبد الله بن عبد العزى ابن صبح بن سلامة بن مرة"},{"id":"tabaqat-shuara:902","bookId":"tabaqat-shuara","type":"section","seq":902,"chapter":"طبقات فحول الشعراء","title":"905- قال محمد بن سلام فحدثنى أبو عبيدة قال كان قراد بن حنش من شعراء غطفان وكان قليل الشعر جيده","page":"ص0","text":"قال محمد بن سلام فحدثنى أبو عبيدة قال كان قراد بن حنش من شعراء غطفان وكان قليل الشعر جيده وكانت شعراء غطفان تغير على شعره فتدعيه منهم زهير بن أبي سلمى ادعى هذه الأبيات\n(إن الرزية لا رزية مثلها ... ما تبتغى عطفان يوم أضلت)\n(إن الركاب لتبتغى ذا مرة ... بجنوب نخل إذا الشهور أحلت)\n(ولنعم حشو الدرع أنت لنا إذا ... نهلت من العلق الرماح وعلت)\n(ينعون خير الناس عند كريهة ... عظمت مصيبهم هناك وجلت)"},{"id":"tabaqat-shuara:903","bookId":"tabaqat-shuara","type":"section","seq":903,"chapter":"طبقات فحول الشعراء","title":"90 - 6","page":"ص0","text":"(فوارس كالنيران يحمون نسوة ... عقائل لم يدنسن بيض المحاجر)\n(إذا ما نسبن ينتسبن إلى الذرى ... لبدر بن عمرو أو لعمرو بن جابر)\n(وعودن أن يعبأن حصا وفارة ... ذكيا وما عودن نسج الغرائر)\n(وماهن من سعد بن ذبيان كلها ... ولا من مواليها حميس بن عامر)"},{"id":"tabaqat-shuara:904","bookId":"tabaqat-shuara","type":"section","seq":904,"chapter":"طبقات فحول الشعراء","title":"الطبقة التاسعة","page":"ج2 ص736","text":"رجاز منهم"},{"id":"tabaqat-shuara:905","bookId":"tabaqat-shuara","type":"section","seq":905,"chapter":"طبقات فحول الشعراء","title":"907- الأغلب العجلى وكان مقدما يقال إنه أول من رجز","page":"ج2 ص736","text":"الأغلب العجلى وكان مقدما يقال إنه أول من رجز"},{"id":"tabaqat-shuara:906","bookId":"tabaqat-shuara","type":"section","seq":906,"chapter":"طبقات فحول الشعراء","title":"908- وأبو النجم واسمه الفضل بن قدامة بن عبيد بن محمد بن — عبيد الله بن عبدة بن الحارث بن إياس بن","page":"ج2 ص736","text":"وأبو النجم واسمه الفضل بن قدامة بن عبيد بن محمد بن\nعبيد الله بن عبدة بن الحارث بن إياس بن عوف بن ربيعة بن مالك بن ربيعة بن عجل"},{"id":"tabaqat-shuara:907","bookId":"tabaqat-shuara","type":"section","seq":907,"chapter":"طبقات فحول الشعراء","title":"909- والعجاج واسمه عبد الله بن رؤبة بن لبيد بن صخر بن كثيف بن عمرو بن حنى بن ربيعة سعد بن مالك","page":"ص0","text":"والعجاج واسمه عبد الله بن رؤبة بن لبيد بن صخر بن كثيف بن عمرو بن حنى بن ربيعة سعد بن مالك بن سعد بن زيد مناة بن تميم"},{"id":"tabaqat-shuara:908","bookId":"tabaqat-shuara","type":"section","seq":908,"chapter":"طبقات فحول الشعراء","title":"910- ورؤبة بن العجاج","page":"ص0","text":"ورؤبة بن العجاج"},{"id":"tabaqat-shuara:909","bookId":"tabaqat-shuara","type":"section","seq":909,"chapter":"طبقات فحول الشعراء","title":"911- قال محمد بن سلام حدثنى الأصمعى قال كانت للأغلب سرحة يصعد عليها ثم يرتجز فقال —","page":"ص0","text":"قال محمد بن سلام حدثنى الأصمعى قال كانت للأغلب سرحة يصعد عليها ثم يرتجز فقال\n(قد عرفتنى سرحتى وأطت ... وقد شمطت بعدها واشمطت)\nقال فاعترض له رجل من بنى سعد ثم أحد بنى الحارث بن عمرو ابن كعب بن سعد فقال له\n(قبحت من سالفة ومن قفا ... شيخ إذا ما رسب القوم طفا)\n(كما شرار الرعى أطراف السفا ... )"},{"id":"tabaqat-shuara:910","bookId":"tabaqat-shuara","type":"section","seq":910,"chapter":"طبقات فحول الشعراء","title":"912- قال وأنشدنا للأغلب في سجاح لما تزوجت مسيلمة الكذاب —","page":"ص0","text":"قال وأنشدنا للأغلب في سجاح لما تزوجت مسيلمة الكذاب\n(قد لقيت سجاح من بعد العمى ... تاح لها بعدك حنزاب وزى)\n(ملوحا فى العين مجلوز القرا ... مثل الفنيق فى شباب قد أنى)\n(من اللجيميين أصحاب القرى ... ليس بذى واهنة ولا نسا)\n(نشا بخبز وبلحم ما اشتهى ... حتى شتا تنتح ذفراه الندى)\n(خاظى البضيع لحمه خظا بظا ... كأنما جمع من لحم الخصى)\n(إذا تمطى بين برديه صأى ... كأن عرق أيره إذا ودى)\n(حبل عجوز ضفرت سبع قوى ... يمشى على قوائم خمس خسا)\n(يرفع وسطاهن من برد الندى ... )\n(قالت متى كنت أبا الخيرمتى ... قال حديثا لم يغيرنى البلى)\n(ولم أفارق خلة لى عن قلى ... فانتشغت فيشته ذات الشوى)\n(كأن فى أجيادها سبع كلى ... مازال عنها بالحديث والمنى)\n(والحلف السفساف يردى فى الردى ... قال ألا ترينهقالت أرى)\n(قال ألا أشيمهقالت بلى ... فشام فيها مثل محراث الغضى)\n(تقول لما غاب فيها واستوى ... لمثلها كنت أحسيك الحسى)\n(يبرى لها كينا كأطراف النوى ... وقد تطلت حين هما وادنى)\n(من طيب مصان الذى كان اشترى ... تقذف عيناه بعلك المصطكى)"},{"id":"tabaqat-shuara:911","bookId":"tabaqat-shuara","type":"section","seq":911,"chapter":"طبقات فحول الشعراء","title":"913- قال وحدثنى أيضا أنه كان يقال إن هذه القصيدة فى الجاهلية لجشم بن الخزرج","page":"ج2 ص742","text":"قال وحدثنى أيضا أنه كان يقال إن هذه القصيدة فى الجاهلية لجشم بن الخزرج"},{"id":"tabaqat-shuara:912","bookId":"tabaqat-shuara","type":"section","seq":912,"chapter":"طبقات فحول الشعراء","title":"914- وقال أيضا —","page":"ج2 ص742","text":"وقال أيضا\n(نحن وردنا واديى جلاجل ... بجحفل جم الوغى من وائل)\n(عند اختلاف الأسل النواهل ... فى ديلم يزحف بالقنابل)\n(فى جذم عجل فى العديد الذائل ... ومن بنى شيبان غير خامل)\n(والخيل تعدو بالوشيج الذابل ... تحت قتام الغبر القساطل)\n(فى حسب بخ وقبص كامل ... وعدد كالدبر غير جافل)"},{"id":"tabaqat-shuara:913","bookId":"tabaqat-shuara","type":"section","seq":913,"chapter":"طبقات فحول الشعراء","title":"915- وقال أيضا —","page":"ص0","text":"وقال أيضا\n(إن لنا شابكة وعورا ... لا يملك الناس لها تغييرا)\n(نحن إذا الداعى دعا ثبورا ... ولم يجد مجاور مجيرا)\n(قمنا بجد لم يكن عثورا ... وشزب قد طويت شهورا)\n(حتى انطوت أقرابها ضمورا ... يهوين بالمستلئمين زورا)\n(فهى تبارى منهبا طحورا ... )"},{"id":"tabaqat-shuara:914","bookId":"tabaqat-shuara","type":"section","seq":914,"chapter":"طبقات فحول الشعراء","title":"916- الثانى أبو النجم فحدثنى أبى سلام قال دخل أبو النجم العجلى على هشام بن عبد الملك فقال كيف ر","page":"ص0","text":"الثانى أبو النجم فحدثنى أبى سلام قال دخل أبو النجم العجلى على هشام بن عبد الملك فقال كيف رابك يا أبا النجم فى النساء قال ما لهن عندى خير وما أنظر إليهن إلا شزرا ولا ينظرن إلى إلا\nخزرا قال فما ظنك بأمير المؤمنين قال ظني بنفسى قال لا علم لك يا أبا النجم ثم أرسل إلى جوار له فسألهن عما ظن أبو النجم فقلن يا أمير المؤمنين وما علم هذا ثم أقبلن على أبي النجم فقلن له يا أعرابي أتقول هذا لأمير المؤمنين وليس منا امرأة تصلى إلا بغسل منه فقال هشام يا أبا النجم دونك هذه الجارية لواحدة منهن فأخذ بيدها ثم أمره أن يغدو عليه بخبرها فغدا عليه ولم\nيصنع شيئا فلما رآه قال ما صنعت يا أبا النجم قال ما صنعت شيئا ولقد قلت في ذلك شعرا قال وما هو قال قلت\n(نظرت فأعجبها الذى فى درعها ... من حسنه ونظرت فى سر باليا)\n(فرأت لها كفلا ينوء بخصرها ... وعثا روادفه وأخثم ناتيا)\n(ضيقا يعض بكل عرد ناله ... كالقعب أو أصرح يرى متجافيا)\n(ورأيت منتشر العجان مقبضا ... رخوا حمائله وجلدا باليا)\n(أدنى له الركب الحليق كأنما ... أهدى إليه عقاربا وأفاعيا)\n(إن الندامة والسدامة فاعلمن ... لو قد صبرتك للمواسى خاليا)\n(ما بال رأسك من ورائي خالفا ... أظننت أن حر الفتاة ورائيا)\n(فاذهب فإنك ميت لا ترتجى ... أبد الأبيد ولو عمرت لياليا)\n(أنت الغرور إذا خبرت وربما ... كان الغرور لمن رجاه شافيا)\nقال فضحك هشام وأمر له بجائزة"},{"id":"tabaqat-shuara:915","bookId":"tabaqat-shuara","type":"section","seq":915,"chapter":"طبقات فحول الشعراء","title":"917- وقال أيضا —","page":"ج2 ص747","text":"وقال أيضا\n(الحمد لله الوهوب المجزل ... أعطى فلم يبخل ولم يبخل)\n(كوم الذرى من خول المخول ... تنقلت من أول التبقل)\n(بين رماحى مالك ونهشل ... يدفع عنها العز جهل الجهل)\nيريد مالك بن ضبيعة بن قيس بن ثعلبة ونهشل بن دارم ويروى عن أبي النجم أنه قال بين رماحى دارم وهم حى من بنى تيم الله بن ثعلبة ونهشل من بنى عجل"},{"id":"tabaqat-shuara:916","bookId":"tabaqat-shuara","type":"section","seq":916,"chapter":"طبقات فحول الشعراء","title":"918- قال وكان أبو النجم ربما قصد فأجاد ولم يكن كغيره من الرجاز الذين لم يحسنوا أن يقصدوا وكان ص","page":"ص0","text":"قال وكان أبو النجم ربما قصد فأجاد ولم يكن كغيره من الرجاز الذين لم يحسنوا أن يقصدوا وكان صاحب فخر وبذخ وهو الذى يقول\n(علق الهوى بحبائل الشعثاء ... والموت بعض حبائل الأهواء)\n(ليت الحسان إذا أصبن قلوبنا ... بالداء جدن بنعمة وشفاء)\n(لشم عندى بهجة وملاحة ... وأحب بعض ملاحة الذلفاء)\n(وأرى البياض على النساء جهارة ... والعتق تعرفه على الأدماء)\n(والقلب فيه لكلهن مودة ... إلا لكل دميمة زلاء)\n(فلئن فخرت بوائل لقد ابتنت ... يوم المكارم فوق كل بناء)\n(ولئن خصصت بنى لجيم إننى ... لأخص مكرمة وأهل غناء)\n(قوم إذا نزل الفظيع تحملوا ... حسن الثناء وأعظم الأعباء)\n(ليست مجالسنا تقر لقائل ... زيغ الحديث ولا نثا الفحشاء)"},{"id":"tabaqat-shuara:917","bookId":"tabaqat-shuara","type":"section","seq":917,"chapter":"طبقات فحول الشعراء","title":"919- محمد بن سلام عن يونس وحدثنى أبي سلام ببعض هذا الحديث قال اجتمع شعراء العرب عند سليمان بن ع","page":"ج2 ص750","text":"محمد بن سلام عن يونس وحدثنى أبي سلام ببعض هذا الحديث قال اجتمع شعراء العرب عند سليمان بن عبد الملك فأمرهم أن يقول كل رجل منهم قصيدة يذكر فيها مآثر قومه ولا يكذب\nثم جعل لمن برز عليهم جارية مولدة فأنشدوه وأنشد أبو النجم حتى أتى على قوله\n(عدوا كمن ربع الجيوش لصلبه ... عشرون وهو يعد في الأحياء)\nفقال سليمان أشهد إن كنت صادقا إنك لصاحب الجارية فقال أبو النجم سل الملأ عن ذلك يا أمير المؤمنين قال الفرزدق أما أنا فأعرف منهم ستة عشر ومن ولد ولده أربعة كلهم قد ربع فقال سليمان ولد ولده هم ولده ادفع إليه الجارية"},{"id":"tabaqat-shuara:918","bookId":"tabaqat-shuara","type":"section","seq":918,"chapter":"طبقات فحول الشعراء","title":"920- وقال أبو النجم فى نعت الفرس —","page":"ص0","text":"وقال أبو النجم فى نعت الفرس\n(فى ذى شكيم عضه يرمله ... ثم تناولنا الغلام تنزله)\n(عن متن سامى الطرف ما يعلله ... والسوط فى يمينه ما يعمله)\n(يجول فى أشطانه ويسعله ... تعمج الماء يفيض جدوله)\n(فوافت الخيل ونحن نشكله ... كل مكب الجرى أو منعثله)\n(والضرب يحشوها بربو تسعله ... والجن عكاف به تقبله)\n(وهو نشيط النفس حر طلله ... )"},{"id":"tabaqat-shuara:919","bookId":"tabaqat-shuara","type":"section","seq":919,"chapter":"طبقات فحول الشعراء","title":"921- أخبرنى أبو خليفة الفضل بن الحباب الجمحى إجازة عن محمد بن سلام قال قال أبو عمرو بن العلاء ك","page":"ص0","text":"أخبرنى أبو خليفة الفضل بن الحباب الجمحى إجازة عن محمد بن سلام قال قال أبو عمرو بن العلاء كان أبو النجم أبلغ فى النعت من العجاج"},{"id":"tabaqat-shuara:920","bookId":"tabaqat-shuara","type":"section","seq":920,"chapter":"طبقات فحول الشعراء","title":"922- أخبرنا أبو خليفة عن محمد بن سلام قال قال عامر بن عبد الملك المسعى كان رؤبة وأبو النجم يجتم","page":"ص0","text":"أخبرنا أبو خليفة عن محمد بن سلام قال قال عامر بن عبد الملك المسعى كان رؤبة وأبو النجم يجتمعان عندى فأطلب لهما النبيذ فكان أبو النجم يتسرع إلى رؤبة حتى أكفه عنه"},{"id":"tabaqat-shuara:921","bookId":"tabaqat-shuara","type":"section","seq":921,"chapter":"طبقات فحول الشعراء","title":"923- والثالث العجاج وإنما اكتفينا من نسبه لشهرة — اسمه وبعد ذكره وأنا لم نجد شاعرا له اسمه غيره و","page":"ص0","text":"والثالث العجاج وإنما اكتفينا من نسبه لشهرة\nاسمه وبعد ذكره وأنا لم نجد شاعرا له اسمه غيره وكما قال الشاعر\n(أحب من النسوان كل قصيرة ... لها نسب فى الصالحين قصير)\nيقول تعرف بأبيها الأدنى لشرف أبيها وشرفها"},{"id":"tabaqat-shuara:922","bookId":"tabaqat-shuara","type":"section","seq":922,"chapter":"طبقات فحول الشعراء","title":"924- قال محمد بن سلام الجمحى فحدثنى أبو الغراف قال لما توجه عمر بن عبيد الله بن معمر إلى أبي فد","page":"ص0","text":"قال محمد بن سلام الجمحى فحدثنى أبو الغراف قال لما توجه عمر بن عبيد الله بن معمر إلى أبي فديك الشارى امتدحه العجاج فقال\n(قد جبر الدين الإله فجبر ... وعور الرحمن من ولى العور)\nيعنى أمية بن عبد الله بن خالد بن أسيد وذاك أنه توجه إلى أبي فديك فهزمه فكتب فى ذلك إلى عبد الملك بن مروان فقال لعمر بن عبيد الله بن معمر أرأيتك لو كان بين عينى وتد أكنت تنزعه قال نعم والله يا أمير المؤمنين قال فهذا أبو فديك وتد بين عينى فاخرج إليه قال أعفنى يا أمير المؤمنين فلما أبي عليه قال ارفع إلينا ماجرى على يديك من خراج فارس فأقر له بالخروج فتلقاه العجاج وهو متوجه إلى أبي فديك فلما قال\n(هذا أوان الجد إذ جد عمر ... وصرح ابن معمر لمن ذمر)\nقال عمر لا قوة إلا بالله فلما قال\n(لا قدح إن لم تور نارا بهجر ... ذات سنا يوقدها من افتخر)\nقال عمر توكلت على الله ولن أدع جهدا فلما قال\n(شهادة فيها طهور من طهر ... )\nفكأن عمر تطير من ذلك ثم قال ماشاء الله"},{"id":"tabaqat-shuara:923","bookId":"tabaqat-shuara","type":"section","seq":923,"chapter":"طبقات فحول الشعراء","title":"925- وقال العجاج —","page":"ج2 ص755","text":"وقال العجاج\n(يارب رب البيت والمشرق ... والمرقلات كل سهب سملق)\n(إياك أدعو فيقبل ملقى ... واغفر خطاياى وثمر ورقى)\n(إنا إذا حرب غدت لا نتقى ... دينا ولا مستأخرا لم يلحق)\n(نرد حد الناب منها الأروق ... فى كل عام كاللياح الأبلق)\n(فقد علمته عصبة المروق ... ورهط شؤبوب ورهط الخندق)\n(والحمس قد تعلم يوم ملزق ... أنا نقى أحسابنا ونعتقى)\n(بالمشرفيات افتخار الأحمق ... )\nشؤبوب وخندق رجلان والحمس يعنى قريشا"},{"id":"tabaqat-shuara:924","bookId":"tabaqat-shuara","type":"section","seq":924,"chapter":"طبقات فحول الشعراء","title":"926- وقال —","page":"ج2 ص757","text":"وقال\n(الحمد لله العشى والضحى ... والحمد لله فما شاء أتى)\n(أسأل رب الناس هديا بالهدى ... هو الذى أنزل آيات التقى)\n(بل لو سألت خابرا عما أتى ... عن جمع بكر إذ حساما قد حسا)\n(وجمع عبد القيس إذ لاقى ثأى ... ضافا علينا وسعى حيث سعى)\n(لاقى جوادا فعلاه إذ جرى ... وعن فوق شأوه حتى ارعوى)\n(وبينما هم ينظرون المنقضى ... منا إذا هن أراعيل ربى)\n(مثل جراد الدبر من كل لوى ... من كل شقاء ومنشق النسا)\n(ساط إذا ابتل رقيقاه ندا ... شديد جلز الصلب معصوب الشوى)\n(كالكر لاشخت ولافيه لوى ... وطرفة نبرى له إذا انبرى)\n(جرداء سرحوب إذا باعت ردى ... نأى ولن يسبقها وإن نأى)\n(أضر بالخيل الغوار فانطوى ... منها الكشوح فهى أمثال النوى)\n(مستقدمات جحفلا جم الوغى ... كثير مجرى المقربات والحصا)\n(ذا لجب يسرح من حيث اغتدى ... حتى توارت شمسه وما انقضى)\n(ينكر ذو الحاجة منه ما ابتغى ... حيران لا يشعر من حيث أتى)\n(عن قبض من لاقى أخاس أم زكا ... غرق فى القمقام أم لاقى هوى)"},{"id":"tabaqat-shuara:925","bookId":"tabaqat-shuara","type":"section","seq":925,"chapter":"طبقات فحول الشعراء","title":"927- والرابع رؤبة بن العجاج ويكنى أبا الجحاف وهو أول من قال فى تقصير الاسم وتخفيف عدد النسب فقا","page":"ج2 ص760","text":"والرابع رؤبة بن العجاج ويكنى أبا الجحاف وهو أول من قال فى تقصير الاسم وتخفيف عدد النسب فقال\n(قد رفع العجاج ذكرى فادعنى ... باسمى إذا الأسماء طالت يكفنى)"},{"id":"tabaqat-shuara:926","bookId":"tabaqat-shuara","type":"section","seq":926,"chapter":"طبقات فحول الشعراء","title":"928- ورؤبة أكثر شعرا من أبيه وقال بعضهم إنه أفصح من أبيه ولا أحسب ذلك حقا لأن أباه قد أخذ عليه","page":"ج2 ص760","text":"ورؤبة أكثر شعرا من أبيه وقال بعضهم إنه أفصح من أبيه ولا أحسب ذلك حقا لأن أباه قد أخذ عليه فى قصيدته التى أولها\n(وقاتم الأعماق خاو المخترق ... مشتبه الأعلام لماع الخفق)\n(يكل وفد الريح من حيث انخرق ... )\nثم قال فيها\n(مضبورة قرواء هرجاب فنق ... )\nفضم وأولها مفتوح"},{"id":"tabaqat-shuara:927","bookId":"tabaqat-shuara","type":"section","seq":927,"chapter":"طبقات فحول الشعراء","title":"929- وقال أيضا يمدح سلم بن قتيبة الباهلى —","page":"ص0","text":"وقال أيضا يمدح سلم بن قتيبة الباهلى\n(ياسلم أعلى كعبك القدوس ... على عدى أوبقهم إبليس)\n(يوم بنى المهلب البئيس ... أصلاهم ما تصطلى المجوس)\n(إذ صبحتهم فيلق رجوس ... ملمومة ذفراء دردبيس)\n(وصبحت سفيانها النحوس ... جرت بذاك اللجم العطوس)\n(فصبحتهم برحا ملطيس ... فلا يحس منهم حسيس)\n(قد علم العالم والقسيس ... أن امرءا حاربكم ممسوس)\n(بئس الخليط الجرب المدسوس ... بكم يداوى الفقم الشخيس)\nوهذه طويلة"},{"id":"tabaqat-shuara:928","bookId":"tabaqat-shuara","type":"section","seq":928,"chapter":"طبقات فحول الشعراء","title":"930- وقال فيه أيضا —","page":"ج2 ص763","text":"وقال فيه أيضا\n(ياسلم قد عرفك التعريف ... حقا وأنت المسلم الحنيف)"},{"id":"tabaqat-shuara:929","bookId":"tabaqat-shuara","type":"section","seq":929,"chapter":"طبقات فحول الشعراء","title":"931- وقال أيضا —","page":"ج2 ص763","text":"وقال أيضا\n(يا سلم يا ابن الأكرمين شجرا ... حيا عروقا فى الثرى وثمرا)"},{"id":"tabaqat-shuara:930","bookId":"tabaqat-shuara","type":"section","seq":930,"chapter":"طبقات فحول الشعراء","title":"932- أخبرنى أبو خليفة في كتابه إلي عن محمد بن سلام عن أبي زيد الأنصارى والحكم بن قنبر قالا كنا","page":"ص0","text":"أخبرنى أبو خليفة في كتابه إلي عن محمد بن سلام عن أبي زيد الأنصارى والحكم بن قنبر قالا كنا نقعد إلى رؤبة يوم الجمعة فى رحبة بنى تميم فاجتمعنا يوما فقطعنا الطريق ومرت بنا عجوز فلم تقدر على أن تجوز فى طريقها فقال رؤبة\n(تنح للعجوز عن طريقها ... إذ أقبلت رائحة من سوقها)\n(دعها فما النحوى من صديقها ... )"},{"id":"tabaqat-shuara:931","bookId":"tabaqat-shuara","type":"section","seq":931,"chapter":"طبقات فحول الشعراء","title":"933- أخبرنى أبو خليفة فى كتابه عن محمد بن سلام عن يونس قال غدوت يوما أنا وإبراهيم بن محمد العطا","page":"ص0","text":"أخبرنى أبو خليفة فى كتابه عن محمد بن سلام عن يونس قال غدوت يوما أنا وإبراهيم بن محمد العطاردى على رؤبة فخرج إلينا كأنه نسر فقال له ابن نوح يا أبا الجحاف أصبحت\nوالله كقولك\n(كالكرز المشدود بين الأوتاد ... ساقط عنه الريش كر الإبراد)\nفقال له رؤبة والله يا ابن نوح ما زلت لك ماقتا فقلت بل أصبحت يا أبا الجحاف كما قال الآخر\n(فأبقين منه وأبقى الطرا ... دبطنا خميصا وصلبا سمينا)\nفضحك وقال هات حاجتك"},{"id":"tabaqat-shuara:932","bookId":"tabaqat-shuara","type":"section","seq":932,"chapter":"طبقات فحول الشعراء","title":"934- قال ابن سلام ووقف رؤبة على باب سليمان بن على بستأذن فقيل له قد أخذ الإذريطوس فقال رؤبة —","page":"ص0","text":"قال ابن سلام ووقف رؤبة على باب سليمان بن على بستأذن فقيل له قد أخذ الإذريطوس فقال رؤبة\n(يا منزل الوحى على إدريس ... ومنزل اللعن على إبليس)\n(وخالق الإثنين والخميس ... بارك له فى شرب إذريطوس)"},{"id":"tabaqat-shuara:933","bookId":"tabaqat-shuara","type":"section","seq":933,"chapter":"طبقات فحول الشعراء","title":"935- أخبرنى أبو خليفة فى كتابه إلى عن محمد بن سلام عن عبد الرحمن بن محمد بن علقمة الضبى قال خرج","page":"ص0","text":"أخبرنى أبو خليفة فى كتابه إلى عن محمد بن سلام عن عبد الرحمن بن محمد بن علقمة الضبى قال خرج شاهين بن عبد الله الثقفى برؤبة إلى أرضه فقعدوا يلعبون بالنرد فلما أتوا بالخوان قال رؤبة\n(يا أخوتى جاء الخوان فارفعوا ... حنانة كعابها تقعقع)\n(لم أدر ما ثلاثها والأربع ... )\nقال فضحكنا ورفعناها وقدم الطعام"},{"id":"tabaqat-shuara:934","bookId":"tabaqat-shuara","type":"section","seq":934,"chapter":"طبقات فحول الشعراء","title":"936- وقال ابن سلام عن يونس قال لى رؤبة حتى متى تسألنى عن هذه الأباطيل وأزوقها لك أما ترى الشيب","page":"ص0","text":"وقال ابن سلام عن يونس قال لى رؤبة حتى متى تسألنى عن هذه الأباطيل وأزوقها لك أما ترى الشيب قد بلع فى رأسك ولحيتك"},{"id":"tabaqat-shuara:935","bookId":"tabaqat-shuara","type":"section","seq":935,"chapter":"طبقات فحول الشعراء","title":"الطبقة العاشرة","page":"ص0","text":"أربعة رهط"},{"id":"tabaqat-shuara:936","bookId":"tabaqat-shuara","type":"section","seq":936,"chapter":"طبقات فحول الشعراء","title":"937- مزاحم بن الحارث العقيلى","page":"ص0","text":"مزاحم بن الحارث العقيلى"},{"id":"tabaqat-shuara:937","bookId":"tabaqat-shuara","type":"section","seq":937,"chapter":"طبقات فحول الشعراء","title":"938- ويزيد بن الطثرية والطثرية أمه وهو يزيد بن المنتشر أحد بنى عمرو بن سلمة بن قشير والطثرية نس","page":"ص0","text":"ويزيد بن الطثرية والطثرية أمه وهو يزيد بن المنتشر أحد بنى عمرو بن سلمة بن قشير والطثرية نسب إلى حى من قضاعة يقال لهم ظثرة فنسبت إليها وأبو دواد الرؤاسى أحد بنى رؤاس بن كلاب بن ربيعة ابن عامر بن صعصعة"},{"id":"tabaqat-shuara:938","bookId":"tabaqat-shuara","type":"section","seq":938,"chapter":"طبقات فحول الشعراء","title":"940- والقحيف بن سليم العقيلى","page":"ص0","text":"والقحيف بن سليم العقيلى"},{"id":"tabaqat-shuara:939","bookId":"tabaqat-shuara","type":"section","seq":939,"chapter":"طبقات فحول الشعراء","title":"941- قال محمد بن سلام فحدثنى أبو عبيدة أن مزاحم بن الحارث العقيلى كان رجلا عزلا وكان شجاعا وكان","page":"ص0","text":"قال محمد بن سلام فحدثنى أبو عبيدة أن مزاحم بن الحارث العقيلى كان رجلا عزلا وكان شجاعا وكان شديد أسر الشعر حلوه وكان مع رقة شعره صعب الشعر هجاء وصافا"},{"id":"tabaqat-shuara:940","bookId":"tabaqat-shuara","type":"section","seq":940,"chapter":"طبقات فحول الشعراء","title":"942- وقال فى يوم أغار عليهم دهر الجعفى فى قبائل مذحج وهمدان ومعه علقمة الجعفى فسبوا وغنموا وأصا","page":"ص0","text":"وقال فى يوم أغار عليهم دهر الجعفى فى قبائل مذحج وهمدان ومعه علقمة الجعفى فسبوا وغنموا وأصابوا إبلا كثيرة فاتبعتهم بنو كعب ثلاثا ثم رجع بعض القوم ومضى\nعقال بن خويلد فى بنى عقيل فجعل يندى أبعار الإبل ببوله ثم يرى أصحابه البعر نديا ويقول لأصحابه ما أقربكم منهم حتى ورد عليهم النخيل فى يوم قائظ ورأس دهر فى حجر جارية من بنى بجلة تفليه متوسدا قطيفة فكأن الجارية أحست نفسها بالطلب فجعلت تضفر شعره بهدب القطيفة فلم ينتبه إلا بالخيل فكان أول من لقى دهرا هبيرة بن التفاصة فضرب وجهة دهر بقوسه فهشم وجهه ولحقه عقال بن خويلد فطعنه فنثر بطنه فسال من بطنه البرير مطبوخا فقتلت جعفى ومن كان معها فى ذلك الجيش وهزمت\nهزيمة فاحشة فقال مزاحم بن الحارث في ذلك اليوم\n(منا الذين استنشطوا الأمر جهرة ... يقدمهم عارى الأشاجع أروع)\n(على أثر الجعفى دهر وقد أتى ... له منذ ولى يسحج السير أربع)\n(بسير طراحى ترى من نجائه ... جلود المهارى بالندى الجون تنتع)\n(فما ذاق طعم النوم حتى تفرجت ... جبال وليل والنجائب تقرع)\n(عن الحى من عليا حريم وفيهم ... سوام وسبى من سليم موزع)\n(طلوع نجاد القوم ما يستفزه ... جنان وما يغتاله الدهر يفجع)"},{"id":"tabaqat-shuara:941","bookId":"tabaqat-shuara","type":"section","seq":941,"chapter":"طبقات فحول الشعراء","title":"943- وقال أيضا —","page":"ج2 ص772","text":"وقال أيضا\n(خليلى عوجابى على الربع نسأل ... متى عهده بالظاعن المتحمل)\n(فإن تعجلانى بانصراف أهجكما ... على عبرة أو ترق عين معول)\n(فعجت وعاجا فوق صحراء غادرت ... بها الريح جولان التراب المنخل)\n(وما هاجه من دمنة بان أهلها ... وأمست قوى بين الحصير ومحبل)\n(إلا لا تذكرنى أميمة إنه ... متى ما يراجع ذكرها القلب يجهل)\n(وتعلم ريعات الهوى أن حبها ... تتبع منى كل عظم ومفصل)\n(كما تبعت صرف عقار مدامة ... مشاش المروى ثم لما تنصل)\n(ويوم تلافيت الصبا أن يفوتنى ... بصهباء تطوى نفنف البعد عنسل)\n(تلاعب حاذيها وتطرح الشذا ... بأصهب ضاف سابغ المتذيل)\n(تنيف به طورا وطورا تخاله ... مخاريق بالأيمان أو نفح مشمل)\n(لها ورك كالجوب شدت فقاره ... حبت قدما فى مكمن الخلق مكمل)"},{"id":"tabaqat-shuara:942","bookId":"tabaqat-shuara","type":"section","seq":942,"chapter":"طبقات فحول الشعراء","title":"944- وله —","page":"ج2 ص774","text":"وله\n(كأنى وعبد الله لم تسر بيننا ... أحاديث يثنى سالف الدهر لينها)\n(ولم نطلب دون الحجون ظعائنا ... تبارى بها أدم المهارى وجونها)\n(ظعائن من عليا نمير بن عامر ... مصححة الأجساد مرضى عيونها)\n(تنكرن من أنسى فلما عرفننى ... بدت كل مبهاج أغر جبينها)\n(وقلن اعجلا لاعين نخشى وأبشرا ... بليلة سعد غاب عنها ظنونها)\n(فجئنا كما انقض القرينان أشرفا ... على خلوة ناء من الحى بينها)\n(فبتنا ندامى ليلة لم نذق بها ... حراما ولم يبخل بحل ضنينها)\n(صفاحا بأيمان نرى أن مسها ... شفاء الصدى من غلة طال حينها)\n(وبتنا وأيدينا وساد وفوقنا ... رياط وعالى بركة لا نصونها)\n(فلما بدا ضوء من الصبح ساطع ... عصى خلة لم ينج إلا قرينها)\n(بدت زفرات الحب من كل وامق ... ومحجوبة لم تعط صبرا يعينها)\n(فأصبحن صرعى فى الحجال وأصبحت ... بنا العيس بالموماة جعدا لجينها)"},{"id":"tabaqat-shuara:943","bookId":"tabaqat-shuara","type":"section","seq":943,"chapter":"طبقات فحول الشعراء","title":"945- والثانى يزيد بن الطثرية قال محمد بن سلام حدثنى أبو الغراف قال كان يزيد بن الطثرية صاحب غزل","page":"ج2 ص776","text":"والثانى يزيد بن الطثرية قال محمد بن سلام حدثنى أبو الغراف قال كان يزيد بن الطثرية صاحب غزل ومحادثة للنساء وكان ظريفا جميلا ومن أحسن الناس كلهم شعرة وكان أخوه\nثور رجلا سيدا كثير المال والنخل والرقيق وكان متنسكا كثير الحج والصدقة وكان كثير الملازمة لإبله ونخله فلا يكاد يلم بالحى إلا وقعة وكانت إبله ترد مع الرعاء على أخيه يزيد بن الطثرية فتسقى على عينه فبينا يزيد مارا فى الإبل وقد صدرت عن الماء إذ مر بخباء فيه نسوة من الحاضر فلما رأينه قلن يا يزيد أطعمنا لحما قال اعطينني سكينا فأعطينه فنحر لهن ناقة من إبل أخيه وبلغ الخبر أخاه فأقبل فلما رآه أخذ بشعره وفسقه وشتمه فأنشأ يزيد يقول\n(يا ثور لا تشتمن عرضى فداك أبي ... فإنما الشتم للقوم العواوير)\n(ما عقر ناب لأمثال الدمى خرد ... عون كرام وأبكار معاصير)\n(عكفن حولى يسألن القرى أصلا ... وليس يرضين منى بالمعاذير)\n(هبهن ضيفا عراكم بعد هجعتكم ... فى قطقط من سقيط الليل منثور)\n(وليس قربكم شاء ولا لبن ... فيرحل الضيف عنكم غير محبور)\n(ما خير واردة للماء صادرة ... لا تنجلى عن عقير الرجل منحور)"},{"id":"tabaqat-shuara:944","bookId":"tabaqat-shuara","type":"section","seq":944,"chapter":"طبقات فحول الشعراء","title":"946- وقال أيضا فى امرأة كان يتحدث إليها ويعجب بها فبينا هو عندها إذا حدث لها سواه قد طلع عليها","page":"ج2 ص778","text":"وقال أيضا فى امرأة كان يتحدث إليها ويعجب بها فبينا هو عندها إذا حدث لها سواه قد طلع عليها ثم جاء آخر فلم يزالوا كذلك حتى تموا سبعة وهو الثامن فقال\n(أرى سبعة يسعون للوصل كلهم ... له عند ليلى دينة يستدينها)\n(فألقيت سهمى وسطهم حين أوخشوا ... فما صار لى من ذاك إلا ثمينها)\n(وكنت عزوف النفس أشنأ أن أرى ... على الشرك من ورهاء طوع قرينها)\n(فيوما تراها بالعهود وفية ... ويوما على دين ابن خاقان دينها)\n(يدا بيد من جاء بالعين منهم ... وإن لم يجىء بالعين حيزت رهونها)"},{"id":"tabaqat-shuara:945","bookId":"tabaqat-shuara","type":"section","seq":945,"chapter":"طبقات فحول الشعراء","title":"947- وقال فيها وقد ضارمها —","page":"ج2 ص780","text":"وقال فيها وقد ضارمها\n(ألا بأبا من قد برى الجسم حبه ... ومن هو موموق إلى حبيب)\n(ومن هو لا يزداد إلا تشوقا ... وليس يرى إلا عليه رقيب)\n(وإنى وإن أحموا على كلامها ... وحالت أعاد دونها وحروب)\n(لمثن على ريا ثناء يزينها ... قواف بأفواه الرواة تطيب)\n(أريااحذرى نقض القوى لا يزل لنا ... على النأى والهجران منك نصيب)\n(وكونى على الواشين لداء شغبة ... كما أنا للواشى ألد شغوب)\n(فإن خفت أن لا تحكمى مرة القوى ... فردى فؤادى والمرد قريب)"},{"id":"tabaqat-shuara:946","bookId":"tabaqat-shuara","type":"section","seq":946,"chapter":"طبقات فحول الشعراء","title":"948- والثالث أبو دواد الروأسى قال محمد بن سلام حدثنى يونس بن حبيب قال وقعت حرب بين عقيل بن كعب","page":"ص0","text":"والثالث أبو دواد الروأسى قال محمد بن سلام حدثنى يونس بن حبيب قال وقعت حرب بين عقيل بن كعب ونمير بن عامر فلم يقم لهم بنو عقيل وجعلت نمير تسرف عليهم فلما رأت ذلك بنو كعب وبنو كلاب وما تلقى عقيل من بنى نمير أجمعوا على قتال بنى نمير فارتحلت نمير ليلحقوا ببنى سعد بن زيد مناة فلحقتهم كلاب فردتهم وتحملوا ما كان لهم دم فى بنى كعب\nووهبوا لهم ما كان فيهم فقال أبو دواد\n(دفعنا والأحبة من دفعنا ... وكنا ملجأ لبنى نمير)\n(حوينا حجرنا لهم فحلوا ... إلينا بعد تظعان وسير)\n(وكان الرأس يوم قراص منا ... ومنا الرأس يوم أبي عمير)\n(فإن ذهب العمى وأمنتموهم ... فلا تستبدلوا أخيال طير)\n(صديق كلما كنتم بشر ... وأعداء إذا كنتم بخير)"},{"id":"tabaqat-shuara:947","bookId":"tabaqat-shuara","type":"section","seq":947,"chapter":"طبقات فحول الشعراء","title":"949- وقال أيضا فى وقعتهم بمذحج —","page":"ج2 ص783","text":"وقال أيضا فى وقعتهم بمذحج\n(ألا هل اتاك ما لقيت قنان ... وما لقيت ببلدتها صداء)\n(وما لاقت بنو الديان منا ... غداة تضج بالخبر الثناء)\n(أتانا أن بالخرماء منهم ... سوامهم ودون الفيف شاء)\n(وأن بها قراضبة غساسا ... يدبر أمر سادتها النساء)\n(فوجهنا كتائب غير ميل ... ولا كشف إذا كره اللقاء)\n(وأفلتنا المحجل فى صلاه ... طرير الحد ينهاه اللواء)\n(وغادرنا بنى الديان صرعى ... كأن رؤوس سادتها الغثاء)\n(فغودر منهم لما التقينا ... بمعترك تمور به الدماء)\n(أبو خلف وصاحبه ووهب ... ورداد وفارسهم عداء)\n(وذو الرمحين أحمر قد أتاه ... فداء ثم إن نفع الفداء)\n(تنادوا نحونا ودعوت قومى ... كلابا والأمور لها بداء)\n(فآب لنا شريك حيث أبنا ... جنيبا لايراد به الغلاء)\n(فأنعمنا هناك على شريك ... وكنا من سجيتنا الحباء)"},{"id":"tabaqat-shuara:948","bookId":"tabaqat-shuara","type":"section","seq":948,"chapter":"طبقات فحول الشعراء","title":"950- وقال أبو دواد أيضا —","page":"ج2 ص786","text":"وقال أبو دواد أيضا\n(لليلى خيال قل ما يتعرج ... يهيج من أحزاننا ما يهيج)\n(يؤرق أصحابى وبينى وبينها ... مناكب رعم فالنباج فأخرج)\n(وعهدى بها والدار تجمع أهلها ... لها مقلتا ريم وخلق خدلج)\n(تواصل أحيانا وتصرم تارة ... وشر الأخلاء الخليل الممزج)\n(كأنا توافينا مع الليل مغزل ... من الأدم جماء المدامع عوهج)\n(نظل بأجزاع المرير مربة ... وسال عليها من فجيرة أشرج)\n(فإن تك أضحت بعد ساكن غبطة ... بها العين ترعى والظايم السفنج)\n(فكل جميع صائر لتفرق ... وكل جديد لا محالة منهج)\n(ونحن منعنا بطن مج وحائل ... وأبلى من الأعداء حتى تفرجوا)\n(بحى حلال لا تكاد تجيرهم ... وضاخ ونفؤ والبطاح فمنعج)\n(نقاذف بالأسياف عبسا وطيئا ... وقد أحجمت عنا تميم ومذحج)\n(بعزو كولغ الذئب غاد ورائح ... وسير كصدر السيف لا يتعرج)\n(بكل جواد مشرف حجباتها ... تشاركت الرعشاء فيها وأعوج)\n(ونحن حبسنا الجيش عنا وقد بدا ... لهم نعم حوم بعثران محدج)\n(فما انصرفوا بقيا ولكن نهاهم ... حصيفان منهم حاسر ومدجج)\n(وقد سد فيف الريح جأواء فيلق ... وألفان أو ألف من الرجل يدرج)\n(ونحن أباه الخسف فى كل موطن ... إذا كان يوم ذو كواكب مرهج)\n(فتلك نمير ثم لم تغن نقرة ... وقالت هلا أهل إليكم مولج)\n(ولما رأينا أنما سعينا لنا ... وقد يفلح الساعى المجد ويفلج)\n(وكنا بنى أم حممنا ذمارنا ... ولم يك فينا العاجز المتزلج)\n(سيخبر عن أيامنا وبلائنا ... وشداتنا فى الحرب حدج وحندج)\nحدج وحندج ابنا البكاء بن عامر بن ربيعة بن عامر بن صعصعة"},{"id":"tabaqat-shuara:949","bookId":"tabaqat-shuara","type":"section","seq":949,"chapter":"طبقات فحول الشعراء","title":"951- والرابع القحيف قال محمد بن سلام حدثنى أبي سلام قال كان القحيف خرج زائرا لأبراهيم بن عاصم ا","page":"ج2 ص790","text":"والرابع القحيف قال محمد بن سلام حدثنى أبي سلام قال كان القحيف خرج زائرا لأبراهيم بن عاصم العقيلى فبعث الأشهب بن كليب العقيلي إلى إبراهيم بن عاصم رسولا يخبره أن القحيف قد هجاه وأساء القول فيه ليحرمه وليقصيه ففعل فقال القحيف\n(متى ما تحط خبرا بنا يا ابن عاصم ... تجد لى رجالا من بنى العم حسدا)\n(وماذاك عن ذنب إليهم جنيته ... سوى أن لى ذكرا أغار وأنجدا)"},{"id":"tabaqat-shuara:950","bookId":"tabaqat-shuara","type":"section","seq":950,"chapter":"طبقات فحول الشعراء","title":"952- وقال القحيف فى يوم الفلج حين جاءهم صريخ بنى كعب ابن ربيعة على بنى عجل —","page":"ج2 ص790","text":"وقال القحيف فى يوم الفلج حين جاءهم صريخ بنى كعب ابن ربيعة على بنى عجل\n(ديار الحى تضربها الطلال ... من الخافى بها أهل ومال)\n(وأجذم ذبها عودا وبدءا ... بدفيه تعبقرت السخال)\n(بها الفدر الرياد وكل هقل ... كبيت الرفقة احترقوا فقالوا)\n(أما ومعلم التوراة موسى ... ومن صلى وصام له بلال)\n(لقد كانت تودك أم عمرو ... بذات الصدر إذ نسى الخلال)\n(أتانا بالعقيق صريخ كعب ... فحن النبع والأسل النهال)\n(ثلاثا ثم وجهنا إليهم ... رحى للموت ليس لها ثفال)\n(وحالفنا السيوف وصافنات ... سواء هن فينا والعيال)\n(بنات بنات أعوج طامحات ... مدى الأبصار جلتها الفحال)\n(شعير زادها وفتيت قت ... ومن ماء الحديد لها نعال)\n(وكردست الحريش فعارضونا ... بخيل فى فوارسها اختيال)\n(وسالت من أباطحها قشير ... بمثل أتى بيشة حين سالوا)\n(نقود الخيل كل أشق نهد ... وكل طمرة فيها اعتدال)\n(تكاد الجن بالغدوات منا ... إذا اصطفت كتائبنا تهال)\n(فبتن على العسيلة ممسكات ... لهن غدية رهج جفال)\n(فلما شق أبيض ذو حواش ... له حال وللظلماء حال)\n(صبحناهم نواصيهن شعثا ... بهن حرارة وبنا اغتلال)\n(فلما جحدلت مئتان منهم ... وفر حنانهم عنهم فزالوا)\n(وصاروا بين ممتن عليه ... ومنصوب له جذع طوال)\n(تكفنهم حنيفة بعد حول ... وكيف يكفنون وقد أحالوا)\n(أمنكم ياحنيف نعم لعمرى ... لحى مخضوبة ودم سجال)\n(ولولا الريح أسمع أهل حجر ... صياح البيض تقرعها النصال)\n(كأن الخيل طالعة عليهم ... بفرسان الصباح قطا رعال)"},{"id":"tabaqat-shuara:951","bookId":"tabaqat-shuara","type":"section","seq":951,"chapter":"طبقات فحول الشعراء","title":"953- وقال أيضا —","page":"ج2 ص796","text":"وقال أيضا\n(وماء قد يظل على جباه ... حمام حائم وقطا وقوع)\n(جعلت عمامتى صلة لدلوى ... لتبلغ إذ تقاصرت النسوع)\n(لأسقى فتية ومنفهات ... أضر بنيها سفر رجيع)\n(ركبناها سمانتها فلما ... بدت منها السناسن والضلوع)\n(صبحناها السياط محدرجات ... فعزتها الضليعة والضليع)\nتم كتاب طبقات الشعراء والحمد لله رب العالمين كثيرا سرمدا وصلى الله على محمد النبى وآله وسلم أولا وآخرا وحسبنا الله ونعم الوكيل\nوفى هامش المخطوطة\nقوبل بالأصل فصح"}]};